const BUILD="2026-11-23.1911";
const TOWNS={"いわき市":{"pref":"福島県","cards":[{"tag":"へえ","hook":"高校生が見つけた首長竜","t":"フタバスズキリュウの化石は、1968年に当時高校生だった鈴木直さんが、いわき市大久町の川岸で発見しました。","teaser":true},{"tag":"数字","hook":"県内で面積1位","t":"面積は約1,232.3km²で、県内53市町村中1位の広さ。人口は約336,111人（2021年）です。"},{"tag":"へえ","hook":"のび太の恐竜のピー助の仲間","t":"『ドラえもん のび太の恐竜』は、主人公たちとフタバスズキリュウのピー助の交流を主軸とした物語です。"},{"tag":"出身","hook":"いわき市出身の有名人","t":"いわき市出身には、詩人の草野心平、指揮者の小林研一郎、女優の伊東美咲、元陸上競技選手の柏原竜二がいます。"},{"tag":"歴史","hook":"福島県内唯一の国宝建造物","t":"白水阿弥陀堂は、平安時代末期建立の仏堂で、福島県内唯一の国宝建造物です（2019年現在）。"},{"tag":"車窓","hook":"白亜の塩屋埼灯台","t":"塩屋埼灯台は、白亜の美しい外観から「日本の灯台50選」にも選ばれ、地元では「豊間の灯台」とも呼ばれます。"},{"tag":"へえ","hook":"いわきの石炭は植物の化石","t":"いわきの石炭は、3500万年前のメタセコイアの植物化石です。"},{"tag":"へえ","hook":"世界最大の大露天風呂","t":"ハワイアンズの「江戸情話 与市」は、浴場面積1,000平方メートル。江戸時代の雰囲気がある世界最大の大露天風呂で、ギネス認定です。"},{"tag":"歴史","hook":"いったん枯れた温泉をよみがえらせた","t":"ハワイアンズの温泉は、炭鉱跡地の鉱底をボーリングして開発したいわき湯本温泉の泉源から引かれます。一度は石炭採掘で枯渇しました。"},{"tag":"歴史","hook":"当時、日本一広かった市","t":"1966年、14の自治体が1つになってできたいわき市は、当時としては日本一広い面積の市でした。"},{"tag":"へえ","hook":"いわきナンバーは全国初","t":"いわき市に新設された「いわきナンバー」は、1979年に交付が始まった、全国初のひらがなナンバープレートでした。"},{"tag":"味","hook":"常磐ものとメヒカリ","t":"親潮と黒潮のぶつかる常磐沖は好漁場。冬のアンコウやメヒカリなどが「常磐もの」として珍重され、メヒカリは市の魚です。"},{"tag":"クイズ","q":"いわき市の「市の魚」に指定されている魚は？","a":"メヒカリ"}]},"おいらせ町":{"pref":"青森県","cards":[{"tag":"へえ","hook":"「ちょう」と読む本州最北の町","t":"おいらせ町は、「町」を「ちょう」と読む自治体として本州最北です。"},{"tag":"数字","hook":"約72.0km²に約24,407人が暮らす町","t":"面積は約72.0km²、人口は約24,407人（2021年）。1km²あたり約339人です。"},{"tag":"へえ","hook":"町なかに自由の女神がいる","t":"ニューヨークと同緯度にあることから、本物の1/4の大きさの自由の女神像が建っています。","teaser":true},{"tag":"出身","hook":"おいらせ町出身の有名人","t":"おいらせ町出身には、青森県知事の三村申吾、女子サッカー選手の伊藤美紀、社会運動家の袴田里見がいます。"},{"tag":"歴史","hook":"日本最古かもしれない大銀杏","t":"根岸の大銀杏は樹齢1100年以上で、日本最古の銀杏の木という説もある県天然記念物です。"},{"tag":"味","hook":"宮内庁御用達の「銀の鴨」","t":"おいらせ町の特産品に、宮内庁御用達の「銀の鴨」があります。"},{"tag":"味","hook":"その名も「おっぱいブランド」","t":"おいらせ町の特産に、メロンとイチゴの「おっぱいブランド」があります。"},{"tag":"車窓","hook":"ハクチョウが来る間木堤","t":"間木堤はハクチョウの飛来地として知られています。"},{"tag":"歴史","hook":"馬を祀る氣比神社","t":"氣比神社は、南部藩最大の藩営牧場があったことから、馬を祀る神社として17世紀に創建されました。"},{"tag":"ゆかり","hook":"将棋の名人の記念館","t":"大山将棋記念館には、大山康晴十五世名人に関連する資料が中心に展示されています。"},{"tag":"クイズ","q":"おいらせ町の町名の由来となった川は？","a":"奥入瀬川"},{"tag":"歴史","hook":"「おいらせ市」になるはずだった","t":"おいらせ町は、当初は「おいらせ市」になる予定でしたが、六戸町が協議から離脱し、市昇格を断念しました。"},{"tag":"車窓","hook":"県南最大級のイオンモール","t":"イオンモール下田は、県南地域最大級のショッピングセンターで、100店舗以上が出店しています。"},{"tag":"へえ","hook":"市外局番は八戸と同じ","t":"おいらせ町は上北郡ですが、市外局番は一部を除いて八戸市と同じエリアです。"}]},"つがる市":{"pref":"青森県","cards":[{"tag":"歴史","hook":"縄文遺跡が世界遺産に","t":"2021年、亀ヶ岡石器時代遺跡と田小屋野貝塚が「北海道・北東北の縄文遺跡群」として世界文化遺産に登録されました。"},{"tag":"数字","hook":"約253.6km²に約30,760人が暮らす町","t":"面積は約253.6km²、人口は約30,760人（2021年）。1km²あたり約121人です。"},{"tag":"へえ","hook":"あの遮光器土偶の出た地","t":"亀ヶ岡遺跡は、遮光器土偶が発掘された遺跡で、国の史跡です。","teaser":true},{"tag":"出身","hook":"つがる市出身の有名人","t":"つがる市出身には、天文学者の一戸直蔵、作曲家の上原げんと、第63代横綱の旭富士正也がいます。"},{"tag":"へえ","hook":"日本随一のりんごの古木","t":"桑野木田の「りんごの樹」は1878年に植栽された日本随一の古木で、県天然記念物です。"},{"tag":"へえ","hook":"イオンモールの原点","t":"イオンモールつがる柏は、イオンモールが初めて手掛けたショッピングモールです。70店舗ほどが入ります。"},{"tag":"歴史","hook":"アメリカの貨物船が座礁","t":"明治時代、七里長浜沖でアメリカ・メイン州バス市で建造された貨物船チェスボロー号が座礁しました。"},{"tag":"へえ","hook":"県内2例目のひらがな市","t":"つがる市は、青森県内の平仮名市名として、むつ市に次ぐ2例目です。"},{"tag":"歴史","hook":"1町4村が合体して誕生","t":"2005年2月11日、木造町、森田村、柏村、稲垣村、車力村の1町4村が合併して誕生しました。"},{"tag":"クイズ","q":"つがる市の亀ヶ岡遺跡で発掘された、有名な土偶は何土偶？","a":"遮光器土偶"},{"tag":"へえ","hook":"アメリカのバス市と友好","t":"つがる市は、アメリカ・メイン州のバス市と、2006年に友好都市になりました。"},{"tag":"へえ","hook":"千葉の柏市と友好都市","t":"つがる市は、旧柏村からの縁で、2005年7月23日に千葉県柏市と友好都市になりました。"},{"tag":"ゆかり","hook":"第63代横綱の旭富士","t":"第63代横綱の旭富士は、つがる市の出身です。"}]},"にかほ市":{"pref":"秋田県","cards":[{"tag":"へえ","hook":"東の松島、西の象潟","t":"象潟は今は陸地ですが、かつては島々が浮かぶ入り江（潟湖）で、「東の松島 西の象潟」と謳われた景勝地でした。","teaser":true},{"tag":"数字","hook":"約241.1km²に約22,981人が暮らす町","t":"面積は約241.1km²、人口は約22,981人（2021年）。1km²あたり約95人です。"},{"tag":"歴史","hook":"地震で湖が消えた象潟","t":"1804年の象潟地震で地盤が数メートル隆起し、水深の浅かった象潟湖は完全に干上がって消滅しました。"},{"tag":"出身","hook":"にかほ市出身の有名人","t":"にかほ市出身には、TDK創始者の齋藤憲三、南極探検家の白瀬矗、漫画家の藤本タツキがいます。"},{"tag":"クイズ","q":"象潟の島々は、何が崩れてできた？","a":"鳥海山"},{"tag":"ゆかり","hook":"芭蕉が評した松島と象潟","t":"松尾芭蕉は『おくのほそ道』で、「松島は笑ふが如く、象潟は憾（うら）むが如し」と評しました。"},{"tag":"ゆかり","hook":"南極探検家・白瀬矗の故郷","t":"南極探検家の白瀬矗は、出羽国由利郡金浦村（現在のにかほ市）の出身。浄蓮寺の住職の長男として生まれました。"},{"tag":"歴史","hook":"白瀬隊の南極初上陸","t":"1912年1月16日、白瀬隊は南極に初上陸し、その湾を「開南湾」と命名しました。"},{"tag":"車窓","hook":"ドーナツ状の南極記念館","t":"白瀬南極探検隊記念館は黒川紀章の設計。円錐型の「オーロラドーム」を、展示室がドーナツ状に取り囲みます。"},{"tag":"歴史","hook":"TDK野球部が都市対抗優勝","t":"TDK硬式野球部は、2006年の都市対抗野球で優勝。東北勢にとって悲願の初優勝を成し遂げました。"},{"tag":"へえ","hook":"ウミウの繁殖地がある海岸","t":"市の鳥ウミウは、大須郷海岸に、本州の日本海側では唯一の繁殖地があります。"},{"tag":"味","hook":"高品質の雄は「本ズワイ」","t":"にかほ市で水揚げされるズワイガニのうち高品質な雄は、「秋田 にかほ本ズワイ」に認定され、ブランド化が図られています。"},{"tag":"クイズ","q":"秋田県で唯一のひらがな自治体名は？","a":"にかほ市"}]},"むつ市":{"pref":"青森県","cards":[{"tag":"へえ","hook":"ひらがなだけの市名","t":"1960年に大湊田名部市から改称して、日本で初めての平仮名の市となりました。"},{"tag":"数字","hook":"県内で面積1位","t":"面積は約864.1km²で、県内40市町村中1位の広さ。人口は約53,767人（2021年）です。"},{"tag":"へえ","hook":"当時は日本一長かった市名","t":"1959年に誕生した大湊田名部市は、当時、日本一長い名称の市（5文字）でした。","teaser":true},{"tag":"出身","hook":"むつ市出身の有名人","t":"むつ市出身には、俳優の松山ケンイチ、タレントの細川ふみえ、映画監督の川島雄三がいます。"},{"tag":"歴史","hook":"会津藩士2800戸が下北へ","t":"1870年、会津藩は斗南藩三万石として再興を許され、2800戸が移封させられました。"},{"tag":"車窓","hook":"恐山はカルデラの中に湖","t":"恐山の中央には直径約3キロメートルのカルデラがあり、中に宇曽利湖というカルデラ湖があります。"},{"tag":"へえ","hook":"北限のサルに会える公苑","t":"猿山公苑は、国の天然記念物「北限のサル」で知られています。"},{"tag":"車窓","hook":"日本最古の石造りアーチ式ダム","t":"水源池公園は桜の名所で、旧海軍の水源地堰堤は日本最古の石造りアーチ式ダムです。"},{"tag":"歴史","hook":"軍港の町に10万人近く","t":"終戦直前の大湊は、海軍関係者も合わせて町では異例の10万人近くの人口がありました。"},{"tag":"クイズ","q":"日本で初めての平仮名の市になったのはどこ？","a":"むつ市"},{"tag":"クイズ","q":"恐山のカルデラの中にある湖の名前は？","a":"宇曽利湖"},{"tag":"車窓","hook":"日本の夜景百選の釜臥山","t":"釜臥山展望台は、日本の夜景百選に選ばれています。"},{"tag":"へえ","hook":"本州最北端のダム","t":"川内ダムは本州最北端のダムで、かわうち湖はダム湖100選に選ばれています。"},{"tag":"歴史","hook":"国の重要文化財の阿弥陀如来","t":"田名部の常念寺にある木造阿弥陀如来坐像は、平安時代末期のもので、国の重要文化財です。"},{"tag":"ゆかり","hook":"俳優の松山ケンイチさん","t":"俳優の松山ケンイチさんは、むつ市の出身です。"}]},"一戸町":{"pref":"岩手県","cards":[{"tag":"歴史","hook":"縄文の世界遺産・御所野","t":"御所野遺跡は、世界遺産「北海道・北東北の縄文遺跡群」の構成遺産です。"},{"tag":"数字","hook":"約300.0km²に約11,296人が暮らす町","t":"面積は約300.0km²、人口は約11,296人（2021年）。1km²あたり約38人です。"},{"tag":"へえ","hook":"縄文の土屋根の建物跡","t":"御所野遺跡の焼失建物は、全国的にも類例のない縄文時代の土屋根建物の痕跡だと実証されました。"},{"tag":"出身","hook":"一戸町出身の有名人","t":"一戸町出身には、彫刻家の舟越保武、作詞家の東山重雄、プロ野球選手の西舘勇陽がいます。"},{"tag":"へえ","hook":"立ったまま石になった大木","t":"根反の大珪化木は、約1700万年前に火山灰に埋もれ、立木のまま珪化木（石になった木）になった珍しいものです。","teaser":true},{"tag":"車窓","hook":"波打つ縞模様の浪打峠","t":"浪打峠の名は、貝殻を含む砂岩が切通しに露出し、波に侵食された海辺を思わせる姿に由来すると考えられています。"},{"tag":"へえ","hook":"国の天然記念物が点在","t":"一戸町には、藤島のフジ、実相寺のイチョウ、平糠のイヌブナ自然林など、国の天然記念物が点在します。"},{"tag":"車窓","hook":"支柱が一本の木製歩道橋","t":"「きききのつりはし」は、支柱が一本だけで曲線を描く木製の歩道橋。仙田満の設計です。"},{"tag":"車窓","hook":"国道4号の最高地点","t":"国道4号は、一戸町の中山跨線橋付近が最高地点で、標高458mです。"},{"tag":"歴史","hook":"お召し列車が止まった奥中山","t":"1947年8月10日、昭和天皇が戦後巡幸で奥中山駅に下車し、徒歩で奥中山開拓農場を視察しました。"},{"tag":"へえ","hook":"県北で最初の秋祭り","t":"一戸まつりは8月末に行われ、岩手県北部で最初に行われる秋祭りです。"},{"tag":"クイズ","q":"世界遺産「北海道・北東北の縄文遺跡群」の構成遺産、一戸町の遺跡は？","a":"御所野遺跡"}]},"一関市":{"pref":"岩手県","cards":[{"tag":"味","hook":"餅料理が300種類を超える","t":"一関・平泉地方は、創作料理を含めて300種類を超える餅料理がある土地です。餅を食べる日は年間60日以上といわれます。","teaser":true},{"tag":"数字","hook":"県内で面積2位","t":"面積は約1,256.4km²で、県内33市町村中2位の広さ。人口は約111,824人（2021年）です。"},{"tag":"車窓","hook":"新幹線の鉄橋は3870m","t":"一関遊水池にある東北新幹線の鉄橋「第1北上川橋梁」は、日本の鉄道橋の中では最長の3870メートルです。"},{"tag":"出身","hook":"一関市出身の有名人","t":"一関市出身には、国語学者の大槻文彦、蘭学者の大槻玄沢、歌手の藤圭子、小説家の楡周平がいます。"},{"tag":"歴史","hook":"日本刀の源流・舞草刀","t":"日本最古の刀鍛冶集団のひとつが舞草の地に住み、日本刀の源流の一つといわれる舞草刀を作りました。"},{"tag":"歴史","hook":"芭蕉ゆかりの日本の道100選","t":"一関市道金沢線などの17.5kmの道は、松尾芭蕉ゆかりの道として、1986年に「日本の道100選」に選ばれました。"},{"tag":"味","hook":"郭公の名は物真似から","t":"厳美渓の郭公だんごは、ロープで団子と代金をやり取りします。名は、創業者がカッコウの物真似が得意だったことに由来します。"},{"tag":"ゆかり","hook":"振袖火事から生まれた奇祭","t":"大東町の大原水かけ祭りは、1657年の振袖火事を受けて始まった奇祭です。毎年2月11日に開かれます。"},{"tag":"車窓","hook":"獅子の鼻に似た猊鼻渓","t":"猊鼻渓の名は、渓谷の上流部にある突き出たこぶ状の鍾乳石が、猊（獅子）の鼻に似ていることに由来します。"},{"tag":"へえ","hook":"りんどうは岩手が日本一","t":"岩手県はりんどうの生産量が日本一で、一関市室根町で多く生産されています。"},{"tag":"車窓","hook":"栗駒山の紅葉は神の絨毯","t":"栗駒山の紅葉は「神の絨毯」と称されます。秋分のころ山頂から始まり、10月上旬にかけて次第に麓へ降りてきます。"},{"tag":"クイズ","q":"一関地方で、餅を食べる日は年間何日以上といわれる?","a":"60日以上"},{"tag":"クイズ","q":"ケーブルで渓谷を渡って届く、厳美渓の名物は?","a":"郭公だんご"}]},"七ヶ宿町":{"pref":"宮城県","cards":[{"tag":"へえ","hook":"信号機が町内に1か所だけ","t":"七ヶ宿町は、人口が1500人に満たない県内最小の自治体とされ、信号機は町内に1交差点にしかないとされます。","teaser":true},{"tag":"数字","hook":"人より自然が多い町","t":"1km²あたり約5人。県内で下から1番目の人口密度です。"},{"tag":"歴史","hook":"江戸の賑わいから急な凋落へ","t":"七ヶ宿街道は江戸時代に参勤交代にも使われて賑わいましたが、1899年に奥羽南線が福島駅-米沢駅間で開業すると、急速に地位が下がりました。"},{"tag":"出身","hook":"七ヶ宿町出身の有名人","t":"七ヶ宿町出身には、住友不動産元社長の安藤太郎がいます。"},{"tag":"へえ","hook":"宮城県最大のダム、七ヶ宿ダム","t":"七ヶ宿ダムは堤高90.0mで宮城県最大のダム。釜房ダムなどと共に、東北最大の都市・仙台市の水がめの一つです。"},{"tag":"へえ","hook":"七ヶ宿ダムの水は県民の約8割へ","t":"七ヶ宿ダムの水は7市10町の上水道に届き、宮城県の全人口のおよそ77.5%をカバーします。"},{"tag":"車窓","hook":"七ヶ宿湖に高さ77mの大噴水","t":"七ヶ宿湖の中央には、高さ77mの噴射能力がある大噴水があります。毎年4月から11月に楽しめます。"},{"tag":"車窓","hook":"階段状に落ちる「二階滝」","t":"滑津大滝は高さ10m、幅30m。階段状になっていることから「二階滝」とも言われ、国道113号脇にあります。"},{"tag":"へえ","hook":"映画『ラストレター』のロケ地","t":"滑津大滝は、岩井俊二監督の映画『ラストレター』のロケ地の一つとして登場します。"},{"tag":"歴史","hook":"小さな沼から発電用の湖へ","t":"長老湖は、かつては小さな沼でしたが、発電用に拡張されて周囲2kmの湖になりました。夏は新緑、秋は紅葉でにぎわいます。"},{"tag":"へえ","hook":"水路の上で洗い物をする暮らし","t":"横川地区には、水路の上で洗い物などをする生活様式が残り、水の郷百選「水守の里・七ヶ宿」に認定されています。"},{"tag":"クイズ","q":"七ヶ宿町の名は、街道沿いに七つ置かれた何に由来する?","a":"宿場"}]},"七ヶ浜町":{"pref":"宮城県","cards":[{"tag":"へえ","hook":"北海道・東北で一番小さい町","t":"七ヶ浜町は仙台市の東側にある半島状の町で、北海道・東北地方において最小の面積の市町村です。"},{"tag":"数字","hook":"県内で小さい方の町","t":"面積は約13.2km²で、県内35市町村中35位。人口は約17,793人（2021年）です。"},{"tag":"クイズ","q":"七ヶ浜町の名は、何が7つあったことから?","a":"海沿いにあった7つの集落です。湊浜、松ヶ浜、菖蒲田浜、花渕浜、吉田浜、代ヶ崎浜、東宮浜の7つです。"},{"tag":"出身","hook":"七ヶ浜町出身の有名人","t":"七ヶ浜町出身には、プロ野球選手の大越基、プロボクサーの佐藤仁徳がいます。"},{"tag":"歴史","hook":"国際交通安全学会賞のニュータウン","t":"七ヶ浜ニュータウン汐見台の「ボンエルフ計画」は、1983年4月に国際交通安全学会賞を受賞しました。のちコミュニティ道路が採用される端緒になりました。"},{"tag":"歴史","hook":"東北初の海水浴場は菖蒲田","t":"1888年、療養施設「大東館」が完成して海水浴場と認められた菖蒲田は、国内で3番目、東北地方では初の海水浴場となりました。","teaser":true},{"tag":"ゆかり","hook":"「浜の迎賓館」大東館","t":"菖蒲田の療養施設「大東館」の宿泊者名簿には、島崎藤村、宮沢賢治、夏目漱石らの名前があったとされます。"},{"tag":"へえ","hook":"「海の高山」と呼ばれた避暑地","t":"高山外国人避暑地は、「山の軽井沢、湖の野尻湖、海の高山」と称され、日本三大外国人避暑地の一つとされました。"},{"tag":"歴史","hook":"国府の厨が置かれた浜","t":"奈良時代、七ヶ浜には国府厨（こくふのくりや）が置かれ、豊富な海産物が多賀城に送られました。"},{"tag":"歴史","hook":"北洋漁業発祥の地","t":"七ヶ浜国際村のギャラリー海物語は、北洋漁業発祥の地である七ヶ浜の漁業の歴史展示室です。"},{"tag":"味","hook":"12月13日は湯豆腐の「お歳とり」","t":"代ヶ崎浜の多聞山にある毘沙門堂では、12月13日に「お歳とり」の祭りがあり、湯豆腐が振る舞われます。"},{"tag":"歴史","hook":"縄文の貝塚、大木囲貝塚","t":"大木囲貝塚は縄文時代前期から中期の大規模な環状集落の遺跡。東西270メートル、南北280メートルの楕円状に、数十箇所の貝層が分布します。"}]},"七戸町":{"pref":"青森県","cards":[{"tag":"車窓","hook":"町内の駅は新幹線だけ","t":"町内の唯一の駅は新幹線の七戸十和田駅です。2022年時点で同じ特徴の自治体は、七戸町のほかに佐賀県嬉野市だけでした。","teaser":true},{"tag":"数字","hook":"約337.2km²に約14,217人が暮らす町","t":"面積は約337.2km²、人口は約14,217人（2021年）。1km²あたり約42人です。"},{"tag":"歴史","hook":"有数の規模の二ツ森貝塚","t":"二ツ森貝塚は、青森県内最大、国内でも有数の規模を誇る遺跡で、5,500年前から4,000年前の縄文前期から中期のものと見られています。"},{"tag":"出身","hook":"七戸町出身の有名人","t":"七戸町出身には、元関脇の魁輝薫秀、映画脚本家の小国英雄、画家の鷹山宇一、プロ野球選手の松山晋也がいます。"},{"tag":"へえ","hook":"値引きの日「まける日」","t":"「まける日」は商店等による伝統行事で、当日は幟が立ちます。「まける」は値引きの意味です。"},{"tag":"へえ","hook":"ダービー馬の像がある道の駅","t":"道の駅しちのへには、町内産でダービーを制したヒカルメイジとコマツヒカリの像があります。"},{"tag":"歴史","hook":"坂上田村麻呂が創建と伝わる","t":"千曳神社は、807年に坂上田村麻呂により創建されたと伝えられています。"},{"tag":"歴史","hook":"明治の曲屋が残る牧場","t":"旧盛田牧場では、南部地方独特の曲屋など明治時代の施設が保存・公開されています。"},{"tag":"車窓","hook":"樹齢700年の銀南木","t":"銀南木は青森県天然記念物のイチョウで、推定樹齢700年です。"},{"tag":"クイズ","q":"七戸町の「まける日」の「まける」とは、どんな意味？","a":"商品の値引き"},{"tag":"クイズ","q":"七戸町の千曳神社を創建したと伝えられる人物は？","a":"坂上田村麻呂"},{"tag":"歴史","hook":"駒饅頭は事業停止","t":"七戸町の駒饅頭は、1861年創業の「お菓子のみやきん」の銘菓でしたが、2025年2月18日付で事業を停止しました。"},{"tag":"へえ","hook":"各町内会が山車を作る秋祭り","t":"しちのへ秋祭りは毎年9月の始めに開かれ、各町内会が制作した山車が囃子とともに運行します。"},{"tag":"へえ","hook":"名馬グリーングラスの生産地","t":"七戸町の生産馬には、グリーングラスやハセパーク、タムロチェリーなどがいます。"}]},"三島町":{"pref":"福島県","cards":[{"tag":"車窓","hook":"桐の花と同じ薄紫色の橋","t":"第一只見川橋梁は、三島町特産の桐の花と同じ薄紫色に塗装されています。只見川の鉄道橋で唯一のトラス構造アーチ橋です。","teaser":true},{"tag":"数字","hook":"約90.8km²に約1,407人が暮らす町","t":"面積は約90.8km²、人口は約1,407人（2021年）。1km²あたり約15人です。"},{"tag":"歴史","hook":"「ふるさとを持たない人に」","t":"1974年に始まった「ふるさと運動」は、「ふるさとを持たない都会の人たちに理想のふるさとを」をキャッチコピーに、年会費制の「特別町民」を基軸としました。"},{"tag":"へえ","hook":"農民の工芸で全国初の指定","t":"奥会津編み組細工は、2003年に国の伝統的工芸品に指定されました。農民の工芸が指定されるのは全国初めてでした。"},{"tag":"車窓","hook":"6〜8月に川霧の霧幻峡","t":"霧幻峡の渡しは只見川の手漕ぎの渡し舟です。「霧幻峡」の名は、6〜8月の早朝・夕方を中心に川霧が多く発生することに因みます。"},{"tag":"歴史","hook":"年中行事が33地区に残る","t":"三島町の各集落には鳥追いや虫送りなどの年中行事が多く残り、13種33地区の行事が県の重要無形民俗文化財に指定されています。"},{"tag":"車窓","hook":"只見川沿いの五段の河岸段丘","t":"只見川沿いには五段の河岸段丘が形成され、西方集落は最上段、宮下集落は上から4段目に位置します。"},{"tag":"へえ","hook":"町名は三島神社から","t":"三島町の名は、旧宮下村にある「三島神社」に由来します。2012年には「日本で最も美しい村」連合に加盟しました。"},{"tag":"ゆかり","hook":"ドラマに登場した早戸駅","t":"テレビ東京のドラマ「鉄オタ道子、2万キロ」の第5話は、早戸駅の「絶景渡し船に乗れる駅」が舞台でした。"},{"tag":"味","hook":"会津桐の中心地","t":"三島町は会津桐の中心地で、明治期から桐下駄の生産が盛んです。"},{"tag":"歴史","hook":"鶴が見つけた早戸温泉","t":"早戸温泉は宝亀年間（770〜781年）に鶴によって発見されたとされ、古くは「鶴の湯」と呼ばれました。"},{"tag":"クイズ","q":"三島町の第一只見川橋梁は、町特産の何の花と同じ色に塗られている?","a":"桐の花"}]},"三川町":{"pref":"山形県","cards":[{"tag":"へえ","hook":"三つの川で「三川」","t":"三川町の名は、町内を流れる赤川、藤島川、大山川の三つの川に由来します。"},{"tag":"数字","hook":"県内で小さい方の町","t":"面積は約33.2km²で、県内35市町村中34位。人口は約7,533人（2021年）です。"},{"tag":"車窓","hook":"町の7割が水田、北に鳥海山","t":"三川町は庄内平野のほぼ中央にあり、面積の7割が水田の穀倉地帯。北に鳥海山、東南東に月山を望みます。","teaser":true},{"tag":"出身","hook":"三川町出身の有名人","t":"三川町出身には、作家の奥泉光、化学者の加藤セチ、元全日本女子バレーボール選手の大沼綾子がいます。"},{"tag":"へえ","hook":"小さな町の大きなショッピングモール","t":"イオンモール三川は、比較的小さな町ながら周辺市町村からの集客力が高く、庄内地方で唯一のシネマコンプレックスがあります。"},{"tag":"歴史","hook":"元禄の庭を持つアトク先生の館","t":"アトク先生の館は1928年完成の近代和風建築。庭園は元禄期に一千両を投じて名木や珍石を集めて築かれ、『おくりびと』のロケ地です。"},{"tag":"へえ","hook":"「アトク先生」って誰？","t":"館の名は公募で決まりました。阿部徳三郎が生前「アトク先生」と親しまれていたことに由来します。"},{"tag":"ゆかり","hook":"日本の既婚女性初の理学博士","t":"加藤セチは三川町出身の化学者で、名誉町民です。日本の既婚女性初の理学博士でした。"},{"tag":"ゆかり","hook":"コシヒカリの祖先をたどると","t":"佐藤順治は三川町出身。「東郷2号」を選抜し、コシヒカリの父方の母「森田早生」は、その変種株です。"},{"tag":"ゆかり","hook":"五輪の空に描いたブルーインパルス","t":"遠渡祐樹さんは三川町出身。ブルーインパルスの編隊長として、東京2020オリンピック・パラリンピックでカラースモークの五輪を描きました。"},{"tag":"クイズ","q":"三川町の名は、赤川、藤島川と、あと一つはどの川に由来する？","a":"大山川"},{"tag":"クイズ","q":"三川町出身の佐藤順治が選抜した稲の品種は？","a":"東郷2号"}]},"三戸町":{"pref":"青森県","cards":[{"tag":"へえ","hook":"県出身初の横綱を出した町","t":"力士の鏡里喜代治は第42代横綱で、青森県出身力士として初の横綱です。","teaser":true},{"tag":"数字","hook":"約151.8km²に約8,864人が暮らす町","t":"面積は約151.8km²、人口は約8,864人（2021年）。1km²あたり約58人です。"},{"tag":"歴史","hook":"戦国期に本城が置かれた町","t":"戦国時代に本城の三戸城が築かれ、城下町として栄えました。江戸時代に本城が盛岡城に移った後は代官所が置かれました。"},{"tag":"出身","hook":"三戸町出身の有名人","t":"三戸町出身には、力士の鏡里喜代治、漫画家の馬場のぼる、実業家の金田一国士がいます。"},{"tag":"ゆかり","hook":"「11ぴきのねこ」の作者の故郷","t":"「11ぴきのねこ」シリーズで知られる漫画家・絵本作家の馬場のぼるは、三戸町の出身です。"},{"tag":"へえ","hook":"県内に現存する最古の鉄筋コンクリート造","t":"八日町の佐滝本店は登録有形文化財で、青森県内最古の現存する鉄筋コンクリート造です。"},{"tag":"歴史","hook":"飢饉の犠牲者を弔う千人塚","t":"斗内千人塚は、天明の大飢饉の際の餓死者を弔うもので、県史跡になっています。"},{"tag":"車窓","hook":"葉タバコの主要産地","t":"葉タバコの主要産地で、コメ、リンゴ、ニンニク、サクランボ、ぶどうなどの生産も盛んです。"},{"tag":"へえ","hook":"300年の歴史「まける市」","t":"「まける市」は300年の伝統をもつ市です。"},{"tag":"クイズ","q":"三戸町が舞台の連続テレビ小説で、主人公の像が建つ作品は？","a":"繭子ひとり"},{"tag":"へえ","hook":"「ドコノ森」という山","t":"三戸町には、標高672mの「ドコノ森」という山があります。"},{"tag":"へえ","hook":"オーストラリアのタムワースと姉妹","t":"三戸町は、オーストラリアのタムワースと、2001年に姉妹都市になりました。"},{"tag":"数字","hook":"氷点下16.3℃を観測","t":"三戸町では、2021年1月8日に氷点下16.3℃を観測しました。"}]},"三春町":{"pref":"福島県","cards":[{"tag":"へえ","hook":"推定樹齢1000年超の滝桜","t":"三春滝桜は日本五大桜または三大巨桜のひとつとして知られ、2012年時点で推定樹齢1000年超、樹高12mです。","teaser":true},{"tag":"数字","hook":"約72.8km²に約17,319人が暮らす町","t":"面積は約72.8km²、人口は約17,319人（2021年）。1km²あたり約238人です。"},{"tag":"車窓","hook":"花が滝のように流れ落ちる","t":"毎年4月中・下旬、広げた枝から薄紅の花が滝のように流れ落ちるように咲くことが名の由来です。毎年全国から30万人の観光客が訪れます。"},{"tag":"出身","hook":"三春町出身の有名人","t":"三春町出身には、登山家の田部井淳子、小説家の玄侑宗久、漫画家の前川つかさがいます。"},{"tag":"へえ","hook":"滝桜の種が宇宙へ","t":"2008年から2009年にかけて、滝桜を含む14種の花の種が国際宇宙ステーションの日本実験棟「きぼう」に8か月半滞在し、地球へ戻されました。"},{"tag":"歴史","hook":"滝桜の子孫の枝垂れ桜が420本以上","t":"1960年頃の調査で、三春滝桜の半径10キロ以内に、根廻り1メートル以上の枝垂れ桜が420本以上あることがわかりました。"},{"tag":"ゆかり","hook":"伊達政宗の正室は三春の出身","t":"三春は伊達政宗の正室・愛姫の出身地です。仙台市の西公園には、2006年に「三春愛姫櫻お輿入れ準備会」が桜を植樹しました。"},{"tag":"歴史","hook":"木馬に助けられた田村麻呂伝説","t":"坂上田村麻呂が793年の蝦夷征討で苦戦していたとき、どこからともなく現れた木馬に助けられたという伝説が、三春駒の起源とされます。"},{"tag":"へえ","hook":"日本三大駒のひとつ、三春駒","t":"三春駒は、青森県の八幡馬、宮城県の木下駒と並ぶ日本三大駒のひとつとして知られています。"},{"tag":"車窓","hook":"桜の名所になった三春城跡","t":"三春城跡は標高407mの丘陵地にあり、戦国時代は田村氏、江戸時代は松下氏・加藤氏・秋田氏の居城でした。今は公園で、桜の名所です。"},{"tag":"ゆかり","hook":"三春出身の芥川賞作家と衆議院議長","t":"三春町出身者には、芥川賞を受賞した僧で小説家の玄侑宗久、自由民権運動活動家で第11代衆議院議長の河野広中がいます。"},{"tag":"クイズ","q":"三春滝桜の種は、国際宇宙ステーションの日本実験棟の何という名前の施設に滞在した？","a":"きぼう"},{"tag":"クイズ","q":"坂上田村麻呂が木馬に助けられたという伝説が起源とされる、三春の郷土玩具は？","a":"三春駒"}]},"三沢市":{"pref":"青森県","cards":[{"tag":"へえ","hook":"基地の町は約2割がアメリカ人（2007年）","t":"米軍三沢基地に関連して約1万人のアメリカ人が暮らし、人口の20%程度にあたるといえます（2007年7月末）。","teaser":true},{"tag":"数字","hook":"約119.9km²に約38,351人が暮らす町","t":"面積は約119.9km²、人口は約38,351人（2021年）。1km²あたり約320人です。"},{"tag":"歴史","hook":"ここから太平洋無着陸横断へ","t":"1931年、ミス・ビードル号が淋代海岸から太平洋無着陸横断飛行に挑み、午前7時1分に飛び立ちました。"},{"tag":"出身","hook":"三沢市出身の有名人","t":"三沢市出身には、指揮者の沖澤のどか、写真家の沢田教一、元大相撲力士の貴ノ浪貞博、詩人の寺山修司がいます。"},{"tag":"ゆかり","hook":"寺山修司のふるさと","t":"三沢市は詩人・劇作家の寺山修司の故郷で、寺山修司記念館があります。"},{"tag":"へえ","hook":"共同使用は日本で唯一だった","t":"米軍・自衛隊・民間航空が共同で使う空港は、2012年12月に岩国で民間定期便が再開されるまで、日本では三沢空港だけでした。"},{"tag":"歴史","hook":"全国高等学校野球で準優勝","t":"1969年の第51回全国高等学校野球選手権大会で、三沢高校が準優勝しました。"},{"tag":"車窓","hook":"小川原湖そばの仏沼","t":"小川原湖近くの「仏沼」はラムサール条約に指定され、絶滅が危惧されているオオセッカなどが生息しています。"},{"tag":"へえ","hook":"野鳥の声が音風景100選","t":"小川原湖畔の野鳥の声が、「日本の音風景100選」に選ばれています。湖畔で耳を澄ませたくなります。"},{"tag":"ゆかり","hook":"近代畜産の父ゆかりの町","t":"三沢ゆかりの人物に、「近代畜産の父」とされる広沢安任がいます。"},{"tag":"クイズ","q":"1931年にミス・ビードル号が太平洋無着陸横断飛行に出発した海岸は？","a":"淋代海岸"},{"tag":"へえ","hook":"アメリカンデーと航空祭の街","t":"三沢市では、6月上旬にアメリカンデー、9月上旬に航空自衛隊三沢基地航空祭が開かれます。"},{"tag":"歴史","hook":"斗南藩士の太刀「会津虎徹」","t":"先人記念館には、旧斗南藩士広澤家所蔵の太刀「会津虎徹」があります。"},{"tag":"ゆかり","hook":"指揮者の沖澤のどかさん","t":"指揮者の沖澤のどかさんは、三沢市の出身です。"},{"tag":"ゆかり","hook":"写真家の沢田教一","t":"写真家の沢田教一は、三沢市の出身です。"}]},"三種町":{"pref":"秋田県","cards":[{"tag":"味","hook":"じゅんさい日本一の産地","t":"三種町は、じゅんさいの生産が国内生産量の約90%を占める日本一の産地です。","teaser":true},{"tag":"数字","hook":"約248.0km²に約14,944人が暮らす町","t":"面積は約248.0km²、人口は約14,944人（2021年）。1km²あたり約60人です。"},{"tag":"へえ","hook":"じゅんさいの生産量の移り変わり","t":"じゅんさいの生産量は、1991年度に約1260トンの最盛期を迎え、2016年度は約440トンになりました。"},{"tag":"出身","hook":"三種町出身の有名人","t":"三種町出身には、舞踊家の石井漠、プロボクサーの三浦隆司、詩人の友川カズキがいます。"},{"tag":"歴史","hook":"三種川の名の由来","t":"三種川の名は、高僧が川の源流で出会った白髪の老翁に川の名を尋ねると、「三種川」と答えた物語に由来します。"},{"tag":"へえ","hook":"日本一高い砂山・丸山","t":"三種町の丸山は、日本一高い砂山といわれます。"},{"tag":"車窓","hook":"遠くまで見渡せる房住山","t":"房住山の山頂からは、東に森吉山、西に大潟村の広大な干拓地、男鹿半島、日本海を遠望できます。"},{"tag":"ゆかり","hook":"菅江真澄が登った房住山","t":"江戸時代の紀行家・菅江真澄は、70歳のころ房住山に登り、山岳信仰の伝説を記録しました。"},{"tag":"歴史","hook":"身長3mの長面三兄弟","t":"房住山の伝説では、長面三兄弟は身長が一丈（約3m）あったといいます。"},{"tag":"車窓","hook":"サンセットビーチ釜谷浜","t":"釜谷浜海水浴場は、夕日が見えることから「サンセットビーチ釜谷浜」とも呼ばれます。"},{"tag":"へえ","hook":"浜口は二つの地名から","t":"浜口地区の名は、「浜田」と「大口」の地名から1文字ずつ取ってつけられました。"},{"tag":"クイズ","q":"三種町は、何の生産が国内生産量の約90%を占める日本一の産地？","a":"じゅんさい"},{"tag":"クイズ","q":"三種町の丸山は、何といわれている山？","a":"日本一高い砂山"}]},"上小阿仁村":{"pref":"秋田県","cards":[{"tag":"へえ","hook":"全国初の自動運転サービス","t":"2019年11月、上小阿仁村で全国初の自動運転車によるサービスが始まりました。","teaser":true},{"tag":"数字","hook":"人より自然が多い町","t":"1km²あたり約8人。県内で下から1番目の人口密度です。"},{"tag":"車窓","hook":"山林原野が9割超の村","t":"上小阿仁村は秋田杉の産地で、総面積の92.7%が山林原野です。"},{"tag":"出身","hook":"上小阿仁村出身の有名人","t":"上小阿仁村出身には、漫画家の守村大がいます。"},{"tag":"歴史","hook":"「大阿仁」と「小阿仁」","t":"地名の伝説では、高倉長者の娘婿が治めた地は「大阿仁」、実子が治めた萩形までは「小阿仁」と呼ばれました。"},{"tag":"へえ","hook":"老翁の面のような霊木","t":"沖田面の名は、老翁の面のようになった霊木に由来するという伝承があり、菅江真澄がその絵を残しています。"},{"tag":"ゆかり","hook":"村の文化財第1号はマタギ道具","t":"2012年、八木沢マタギの狩猟用具5点が、村の有形民俗文化財第1号に指定されました。"},{"tag":"歴史","hook":"最後のマタギが鉄砲を返納","t":"八木沢では2009年春、集落ただ一人の古老マタギが鉄砲を返納し、生業とするマタギ集落は消えました。"},{"tag":"歴史","hook":"県営第1号の萩形ダム","t":"萩形ダムは、1966年に竣工した県営第1号のダムです。小阿仁川につくられました。"},{"tag":"へえ","hook":"足の形をした沼","t":"沖田面の山の上には足の形をした沼があり、もう一つの足跡は二ツ井町にあるといわれます。"},{"tag":"クイズ","q":"2019年に全国初のサービスが始まった、上小阿仁村の乗り物は？","a":"自動運転車"},{"tag":"クイズ","q":"上小阿仁村の総面積の約何%が山林原野？","a":"92.7%"}]},"上山市":{"pref":"山形県","cards":[{"tag":"へえ","hook":"城下町・宿場町・温泉街のまち","t":"上山市は、城下町・宿場町・温泉街の3つを同時に兼ね備えた都市で、全国的にも珍しいとされています。"},{"tag":"数字","hook":"約240.9km²に約29,141人が暮らす町","t":"面積は約240.9km²、人口は約29,141人（2021年）。1km²あたり約121人です。"},{"tag":"歴史","hook":"鶴が傷を癒した場所に温泉","t":"1458年、僧の月秀上人が、湯町のあたりで鶴が傷を癒しているのを見かけ、温泉の湧出を発見したのが上山温泉の起源です。","teaser":true},{"tag":"出身","hook":"上山市出身の有名人","t":"上山市出身には、歌人の斎藤茂吉、力士の出羽ヶ嶽文治郎、プロサッカー選手の半田陸がいます。"},{"tag":"クイズ","q":"上山市の「市の木」になっている、歌人・斎藤茂吉ゆかりの木は何でしょう?","a":"アララギです。イチイ科の常緑針葉高木で、市内に老樹名木が見られます。"},{"tag":"クイズ","q":"江戸時代、羽州街道の楢下宿を参勤交代で利用した東北の藩は、いくつあったでしょう?","a":"13藩です。津軽藩や庄内藩、新庄藩などが利用しました。"},{"tag":"へえ","hook":"明治の石造りの眼鏡橋","t":"楢下宿の中央を流れる金山川には、明治期では珍しい西洋の土木技術を取り入れた石造りの眼鏡橋が二つ架けられました。"},{"tag":"ゆかり","hook":"沢庵和尚が過ごした春雨庵","t":"1629年、沢庵宗彭が上山に流罪となったときに過ごした庵が、春雨庵として1953年に復元されています。"},{"tag":"へえ","hook":"冷水をかける小正月の行事","t":"2月11日の「カセ鳥」は、蓑をまとって鳥に扮した若者が町を練り歩く行事。町の人は冷水をかけ、火伏せと豊作を祈ります。"},{"tag":"味","hook":"ワイン特区のまち","t":"上山市は2016年に「かみのやまワイン特区」の認定を受け、ワイン用ブドウの生産から醸造まで行う街づくりに取り組んでいます。"},{"tag":"ゆかり","hook":"茂吉が歌を作った公園","t":"斎藤茂吉記念館は、茂吉の生家がある金瓶の南の「みゆき公園」にあります。茂吉も時折足を運び、作歌に励んだそうです。"},{"tag":"歴史","hook":"500人で4000人を迎え撃った城","t":"1600年、上山城は上杉軍4000人に攻められました。守る城兵はわずか500人でしたが、待ち伏せた最上軍が背後から襲いかかりました。"}]},"下郷町":{"pref":"福島県","cards":[{"tag":"味","hook":"箸の代わりにネギで蕎麦を","t":"大内宿では、高遠そばの名で知られる蕎麦を、箸の代わりにネギを用いて食べる風習があります。","teaser":true},{"tag":"数字","hook":"約317.0km²に約5,042人が暮らす町","t":"面積は約317.0km²、人口は約5,042人（2021年）。1km²あたり約16人です。"},{"tag":"歴史","hook":"旧宿場で全国3番目の保存地区","t":"大内宿は1981年に国の重要伝統的建造物群保存地区に選定されました。旧宿場としては妻籠宿、奈良井宿に続き、全国で3番目です。"},{"tag":"出身","hook":"下郷町出身の有名人","t":"下郷町出身には、芥川賞作家の室井光広、前福島県知事の佐藤雄平がいます。"},{"tag":"車窓","hook":"全長約450mの茅葺きの街並み","t":"大内宿は、全長約450mの往還の両側に寄棟造の民家が建ち並び、茅葺き民家の街割りが整然と並んでいます。"},{"tag":"へえ","hook":"「大内宿の自然用水」","t":"大内宿の自然用水は、1996年に日本の音風景100選に選定されました。"},{"tag":"車窓","hook":"全長200mに奇岩が並ぶ","t":"塔のへつりは1943年に国の天然記念物に指定され、全長200メートルにわたって大規模な奇岩が整列しています。"},{"tag":"車窓","hook":"標高700mのそば畑","t":"猿楽台地は標高700mに位置する面積40haのそば畑で、例年8月下旬から9月上旬頃に見頃になります。"},{"tag":"へえ","hook":"こけし形の湯巡り手形","t":"湯野上温泉の湯巡り手形はこけしの形で、3湯を入湯した後、塔のへつり近くの作業場で絵付けができます。"},{"tag":"歴史","hook":"猿が見つけた湯野上温泉","t":"湯野上温泉の開湯伝説によれば、猿が入湯しているところを発見したといい、その名は源泉名に残っています。"},{"tag":"歴史","hook":"下野街道は国の史跡","t":"下野街道は、古道約10キロメートルと一里塚などが国の史跡に指定されています。"},{"tag":"ゆかり","hook":"芥川賞作家・室井光広","t":"芥川賞作家の室井光広さんは、下郷町の出身です。"},{"tag":"クイズ","q":"塔のへつりの「へつり」とは、会津方言で何のこと?","a":"断崖あるいは急斜面"}]},"中山町":{"pref":"山形県","cards":[{"tag":"へえ","hook":"芋煮会発祥の地の一つ","t":"中山町は、江戸時代に最上川を利用した北前舟の舟運で栄えた町です。芋煮会発祥の地の一つとされています。"},{"tag":"数字","hook":"県内で小さい方の町","t":"面積は約31.1km²で、県内35市町村中35位。人口は約10,617人（2021年）です。"},{"tag":"歴史","hook":"鍋をかけた松が芋煮のルーツ","t":"中山町長崎には、里芋を煮る鍋をかけたという「鍋掛の松」が1917年まで残っていました。芋煮のルーツを伝える遺跡として復元されています。","teaser":true},{"tag":"出身","hook":"中山町出身の有名人","t":"中山町出身には、落語家の春風亭昇りん、野球選手の横山雄哉がいます。"},{"tag":"味","hook":"日本三大芋煮の中山町","t":"中山町は、島根県津和野町、愛媛県大洲市とともに「日本三大芋煮」の3地域に数えられます。船乗りが船荷の棒鱈と里芋を煮たのがはじまりとされます。"},{"tag":"クイズ","q":"中山町で、生産量が東北一とされる果物は何でしょう?","a":"すももです。"},{"tag":"歴史","hook":"国の重要文化財の旧柏倉家住宅","t":"2019年、柏倉九左衛門家（旧柏倉家住宅）が国の重要文化財に指定されました。"},{"tag":"へえ","hook":"紅花の畑を隔年で変えた柏倉家","t":"旧柏倉家住宅の柏倉家は、質の良い紅花をつくるため、連作障害を防ごうと隔年で栽培する畑を変える方法を長年続けました。"},{"tag":"歴史","hook":"町の名は旧領主の家名から","t":"中山町は1954年、長崎町と豊田村が合併して誕生しました。町名は旧領主の家名に由来します。"},{"tag":"車窓","hook":"最上川と須川に囲まれた平地","t":"中山町は山形盆地の西部にあり、町域はほぼ平地です。北は最上川で寒河江市と、東は須川で山形市や天童市との境になっています。"},{"tag":"ゆかり","hook":"落語家・昇りんさんの出身地","t":"落語家の春風亭昇りんさんは、中山町の出身です。"}]},"中島村":{"pref":"福島県","cards":[{"tag":"へえ","hook":"災害を汗で知らせる地蔵","t":"奥州汗かき地蔵尊は、災害が起こると汗をかいて村民に知らせるという言い伝えがあります。","teaser":true},{"tag":"数字","hook":"県内で小さい方の町","t":"面積は約18.9km²で、県内53市町村中52位。人口は約4,766人（2021年）です。"},{"tag":"ゆかり","hook":"小室哲哉の祖父は村の出身","t":"音楽プロデューサー小室哲哉さんの祖父が中島村出身という縁で、1997年、童里夢公園に「ヨカッペ音頭」が流れるカラクリ時計が寄贈されました。"},{"tag":"出身","hook":"中島村出身の有名人","t":"中島村出身には、フリーアナウンサーの小室早弥香がいます。"},{"tag":"へえ","hook":"善通寺のしだれ桜","t":"中島村の「善通寺しだれ桜」は、1983年に「福島県緑の文化財」に登録されました。"},{"tag":"へえ","hook":"小学校のバンドが武道館へ","t":"1987年、吉子川小学校のマーチングバンドが、日本武道館での全国大会に出場しました。"},{"tag":"ゆかり","hook":"国際口笛大会の優勝者","t":"口笛演奏家の高木満理子さんは、中島村在住と紹介されています。国際口笛大会で優勝しました。"},{"tag":"歴史","hook":"古代の東山道がにぎわった","t":"中島村の阿武隈川の西側には、古代の東山道が通っていて、にぎわっていました。"},{"tag":"車窓","hook":"村内のバス停は2か所だけ","t":"村内を通る路線バスは白河〜石川線だけで、村の南端を通ります。停留所は「向久保」「柏原」の2か所のみです。"},{"tag":"歴史","hook":"石川氏が築いた滑津舘","t":"滑津舘跡は、陸奥石川氏の二代、石川有光の子の光房が築いた城の跡です。"},{"tag":"クイズ","q":"中島村の「村の木」に決まっているのは何の木？","a":"あか松"}]},"中泊町":{"pref":"青森県","cards":[{"tag":"へえ","hook":"町が2つに分かれている","t":"中泊町は、旧中里町域と旧小泊村域の2つに分かれた飛地になっています。"},{"tag":"数字","hook":"約216.3km²に約9,750人が暮らす町","t":"面積は約216.3km²、人口は約9,750人（2021年）。1km²あたり約45人です。"},{"tag":"車窓","hook":"新幹線が通るのに駅がない","t":"町域を北海道新幹線と海峡線が通りますが、青函トンネル内の通過のため町内に利用できる駅はありません。","teaser":true},{"tag":"出身","hook":"中泊町出身の有名人","t":"中泊町出身には、元大相撲力士の宝富士大輔、元大相撲力士の阿武咲奎也、フォークシンガーの三上寛がいます。"},{"tag":"歴史","hook":"豪農の離れ「詩夢庵」","t":"豪農だった家の離れ「詩夢庵」は、18面の狩野派の襖絵やステンドグラスで知られ、公開は春秋のみです。"},{"tag":"ゆかり","hook":"関脇まで上った宝富士","t":"中泊町出身の宝富士大輔は元大相撲力士で、最高位は関脇でした。"},{"tag":"クイズ","q":"中泊町は、2005年に中里町とどこが新設合併して生まれた？","a":"小泊村"},{"tag":"へえ","hook":"「なにもささ踊り」の祭り","t":"中泊町のなかさとまつりでは、「なにもささ踊り」が踊られます。"},{"tag":"車窓","hook":"十三湖や不動の滝がある町","t":"町の観光スポットには、十三湖、不動の滝、中里城史跡公園などがあります。"},{"tag":"ゆかり","hook":"相撲取りを多く出した町","t":"中泊町出身の元大相撲力士には、最高位が関脇の源氏山と出羽の花がいます。"},{"tag":"へえ","hook":"遠い宮崎の町と交流","t":"中泊町は、宮崎県小林市と、教育や文化、産業の交流をしています。"}]},"丸森町":{"pref":"宮城県","cards":[{"tag":"へえ","hook":"宮城県の最南端、福島側に突き出す","t":"丸森町は宮城県の最南端にあり、福島県側に突出する形をしています。町域の約7割は山林で、阿武隈川が阿武隈山地を分断して流れます。"},{"tag":"数字","hook":"人より自然が多い町","t":"1km²あたり約45人。県内で下から3番目の人口密度です。"},{"tag":"歴史","hook":"「齋理」は当主の名から","t":"齋理屋敷は、七代にわたって繁栄した豪商・齋藤家の屋敷です。歴代当主が「齋藤理助」を名乗ったことから「齋理」と呼ばれます。","teaser":true},{"tag":"出身","hook":"丸森町出身の有名人","t":"丸森町出身には、日経連会長の大槻文平、衆議院議員の秋葉賢也、民謡歌手の鈴木正夫がいます。"},{"tag":"歴史","hook":"洪水対策の町場替えと同時に創業","t":"齋理は1804年、洪水対策の市街地移転事業である町場替えと同時に呉服太物商を始め、養蚕へと広げ、生糸の相場で財を成しました。"},{"tag":"車窓","hook":"蔵が並ぶ屋敷、国の登録有形文化財","t":"齋理屋敷には居宅や蔵6棟などが立ち並び、2011年1月に12の建造物が国の登録有形文化財に登録されました。"},{"tag":"歴史","hook":"屋敷内で最古は1848年の店蔵","t":"県道45号線に面した店蔵は、1848年に建てられた屋敷内で最古の建物です。"},{"tag":"車窓","hook":"日本の棚田百選、沢尻の棚田","t":"沢尻の棚田は大張川張字宗膳にあり、日本の棚田百選に選ばれています。"},{"tag":"ゆかり","hook":"紅白に5度出場した民謡歌手","t":"丸森町出身の鈴木正夫は民謡歌手で、『新相馬節』などのヒット曲を残し、NHK紅白歌合戦に5度出場しました。"},{"tag":"歴史","hook":"寄贈を受けて蔵の郷土館に","t":"1986年に齋藤家七代目当主から蔵や屋敷、収蔵品の寄贈を受けた丸森町は、1988年7月に蔵の郷土館齋理屋敷を開館しました。"},{"tag":"クイズ","q":"丸森町が1990年に姉妹都市提携をした、アメリカ・カリフォルニア州の都市は?","a":"ヘメット"}]},"久慈市":{"pref":"岩手県","cards":[{"tag":"へえ","hook":"最北の海で潜る北限の海女","t":"久慈市は、国内最北端の海で漁をする「北限の海女」の町です。"},{"tag":"数字","hook":"約623.5km²に約32,813人が暮らす町","t":"面積は約623.5km²、人口は約32,813人（2021年）。1km²あたり約53人です。"},{"tag":"へえ","hook":"国内最大の琥珀の産地","t":"久慈は、世界有数かつ国内最大の琥珀の採掘産地。鉱山と加工場と博物館を備えています。","teaser":true},{"tag":"出身","hook":"久慈市出身の有名人","t":"久慈市出身には、講道館柔道十段の三船久蔵、総合格闘家の扇久保博正、ジャズピアニストの馬場葉子がいます。"},{"tag":"歴史","hook":"流通できる最古の琥珀","t":"久慈琥珀は、流通できる最古年代の琥珀です。琥珀は新生代が主流で、中生代白亜紀の久慈のものは量が少ないのです。"},{"tag":"へえ","hook":"琥珀の中にいた新種の虫","t":"琥珀に閉じ込められた昆虫「クジコハクトガマムシ」は、2008年に発見され、後に新種と認められました。"},{"tag":"へえ","hook":"日本初の地下水族科学館","t":"久慈国家石油備蓄基地に併設された日本初の地下水族科学館「もぐらんぴあ」は、市内駅前の「まちなか水族館」として復活しました。"},{"tag":"ゆかり","hook":"あまちゃんの北三陸市","t":"2013年のNHK朝ドラ『あまちゃん』では、久慈市内各所で、架空の市「北三陸市」の場面のロケが行われました。"},{"tag":"ゆかり","hook":"柔道の神様の生誕の地","t":"久慈市は、「柔道の神様」といわれた三船久蔵柔道十段の生誕の地。柔道が盛んなまちです。"},{"tag":"へえ","hook":"日本で5番目に長い鍾乳洞","t":"山形町の内間木洞は、総延長6,350mで日本で5番目に長い鍾乳洞です。"},{"tag":"車窓","hook":"海が見えるダム","t":"滝ダムは「海が見えるダム」として知られ、観光遊覧船もあります。"},{"tag":"クイズ","q":"久慈市で採れる、虫が入ったものも多い、宝石のような樹脂の化石は？","a":"琥珀"},{"tag":"クイズ","q":"久慈市で「北限の海女」の拠点となっている海岸は？","a":"小袖海岸"}]},"九戸村":{"pref":"岩手県","cards":[{"tag":"へえ","hook":"夏に100万匹のヒメボタル","t":"折爪岳の山頂付近にはヒメボタルが多数生息し、毎年夏には100万匹以上のホタルが夜を舞います。","teaser":true},{"tag":"数字","hook":"約134.0km²に約5,256人が暮らす町","t":"面積は約134.0km²、人口は約5,256人（2021年）。1km²あたり約39人です。"},{"tag":"味","hook":"九戸村は甘茶の産地","t":"九戸村は、日本でも有数の甘茶の産地です。"},{"tag":"出身","hook":"九戸村出身の有名人","t":"九戸村出身には、戦国時代の武将の九戸政実、元プロ野球選手の風張蓮、小説家の石野晶がいます。"},{"tag":"へえ","hook":"畳の細かいゴミも掻きだす箒","t":"南部箒は、箒草の栽培から編み上げまでを職人が行う伝統の箒。畳や絨毯の間の細かいゴミまで掻きだせます。"},{"tag":"へえ","hook":"釘を1本も使わない箪笥","t":"南部箪笥は、地元に自生する欅や桐を使い、釘1本使わない伝統技術で作る家具です。漆を使うのも特徴です。"},{"tag":"ゆかり","hook":"九戸政実の生誕地とも","t":"戦国武将・九戸政実は、九戸村の長興寺で生まれたとの説があります。"},{"tag":"歴史","hook":"九戸城は、実は二戸市にある","t":"九戸城があるのは二戸市。九戸郡の要塞としては、村役場の背後の山「熊野館」が有力な候補とされます。"},{"tag":"へえ","hook":"ブロイラーの産地","t":"1999年当時、ブロイラーの総生産額日本一だった岩手県。その中で、生産量が多いのが九戸村です。"},{"tag":"へえ","hook":"ご当地キャラ「キングオブチキン」","t":"ご当地キャラクター「キングオブチキン」は、2019年に九戸村商工会青年部のアート活動から生まれました。"},{"tag":"車窓","hook":"村と二戸市の境にある折爪岳","t":"折爪岳の山頂は二戸市と九戸村の境で、標高は852.2m。展望台から岩手山や八戸市を望めます。"},{"tag":"クイズ","q":"九戸村の折爪岳の山頂付近で、毎年夏に100万匹以上が舞う虫は？","a":"ヒメボタル"}]},"二戸市":{"pref":"岩手県","cards":[{"tag":"歴史","hook":"九戸城を6万の兵が包囲","t":"豊臣秀次らの鎮圧軍は、約6万の兵で九戸城を包囲し、9月4日に降伏開城させました。"},{"tag":"数字","hook":"約420.4km²に約25,083人が暮らす町","t":"面積は約420.4km²、人口は約25,083人（2021年）。1km²あたり約60人です。"},{"tag":"へえ","hook":"東北最古の石垣がある城跡","t":"九戸城跡の本丸の一部には、東北最古の石垣があります。三方を川に囲まれた天然の要害でした。"},{"tag":"出身","hook":"二戸市出身の有名人","t":"二戸市出身には、戦国武将の九戸政実、地磁気学の祖の田中舘愛橘、映画監督の柴田清克がいます。"},{"tag":"へえ","hook":"国産漆の約7割は浄法寺","t":"浄法寺町の浄法寺漆は、日本産としては最も生産量が多く、国産の約7割を占めるとされます。"},{"tag":"ゆかり","hook":"あじさい祭りの天台寺","t":"天台寺は1987年に瀬戸内寂聴が住職となり復興。そのとき植えられたアジサイが名物で、7月にあじさい祭りが開かれます。"},{"tag":"へえ","hook":"陸上の夫婦岩は全国最大","t":"馬仙峡の男神岩（比高180m）と女神岩（比高160m）は、陸上にある夫婦岩としては全国最大の規模です。"},{"tag":"車窓","hook":"国道4号から見える大崩崖","t":"馬仙峡の大崩崖は、一枚の砂岩が山塊に露出したもの。国道4号からも一望できます。"},{"tag":"へえ","hook":"一戸から九戸、四戸だけ無い","t":"糠部郡の「一戸〜九戸」は、四戸を除いて今も地名が残ります。岩手県にあるのは一戸町・二戸市・九戸村です。","teaser":true},{"tag":"歴史","hook":"輝ける丘という名の神社","t":"九戸城松ノ丸の呑香稲荷神社は天和2年（1682年）の創建。呑香（とんこう）はアイヌ語で「輝ける丘」の意味です。"},{"tag":"ゆかり","hook":"日本式ローマ字の提唱者","t":"田中舘愛橘は、日本における地磁気学の祖。日本式ローマ字を提唱した人物で、二戸にゆかりがあります。"},{"tag":"クイズ","q":"二戸市の名は、糠部郡に敷かれた何という制に由来するでしょう？","a":"四門九戸（しもんくのへ）の制"}]},"二本松市":{"pref":"福島県","cards":[{"tag":"へえ","hook":"地名は旅人の目印の二本松","t":"二本松の地名は、旅人の目印となった二本の松があったことが由来とされます。"},{"tag":"数字","hook":"約344.4km²に約54,447人が暮らす町","t":"面積は約344.4km²、人口は約54,447人（2021年）。1km²あたり約158人です。"},{"tag":"歴史","hook":"一夜で刻んだ戒石銘碑","t":"二本松城の入口には、藩主が一夜のうちに自然石へ藩政改革の指針を刻ませた「戒石銘碑」があり、国の史跡です。"},{"tag":"出身","hook":"二本松市出身の有名人","t":"二本松市出身には、歴史学者の朝河貫一、女流洋画家の高村智恵子、ミュージシャンの遠藤ミチロウがいます。"},{"tag":"車窓","hook":"霞ケ城の石垣沿いの道","t":"霞ケ城公園入口の石垣に沿う道は、1986年に「日本の道100選」に選ばれました。"},{"tag":"へえ","hook":"7台の太鼓台に提灯300個","t":"二本松提灯祭りでは、7台の太鼓台にそれぞれ300個余りの提灯をつけて町内を曳き回します。","teaser":true},{"tag":"味","hook":"郷土料理「ざくざく」","t":"根菜や鶏肉を刻み入れた醤油ベースの汁物「ざくざく」。提灯祭りなどで多く作られます。"},{"tag":"へえ","hook":"乳白色になる「ミルキーデイ」","t":"岳温泉は普段は透明なお湯ですが、週に一度だけ乳白色のにごり湯になり、「ミルキーデイ」と呼ばれます。"},{"tag":"へえ","hook":"温泉街が独立宣言?","t":"1982年、岳温泉旅館協同組合は「ニコニコ共和国」として日本からの独立を宣言しました。"},{"tag":"車窓","hook":"杉沢の大スギ","t":"杉沢の大スギは、樹高50m〜68m。樹齢は推定600年以上、あるいは1000年以上とされる巨木です。"},{"tag":"ゆかり","hook":"『智恵子抄』の高村智恵子","t":"洋画家の高村智恵子は二本松の出身です。夫は高村光太郎で、『智恵子抄』で有名です。"},{"tag":"クイズ","q":"二本松提灯祭りで町内を曳き回される太鼓台は、全部で何台?","a":"7台"}]},"五城目町":{"pref":"秋田県","cards":[{"tag":"へえ","hook":"500年続く朝市","t":"五城目町の中心部では、500年の歴史を持つ朝市が、0・2・5・7のつく日に開かれています。","teaser":true},{"tag":"数字","hook":"約214.9km²に約8,210人が暮らす町","t":"面積は約214.9km²、人口は約8,210人（2021年）。1km²あたり約38人です。"},{"tag":"へえ","hook":"スズムシ群棲地の北限だった町","t":"五城目町は、かつて日本におけるスズムシ群棲地の北限として知られましたが、2020年に登録が解除されました。"},{"tag":"出身","hook":"五城目町出身の有名人","t":"五城目町出身には、作家の矢田津世子、劇作家の畑澤聖悟、レスリング選手の菅原弥三郎がいます。"},{"tag":"歴史","hook":"町章に込められた5つの城","t":"五城目町の町章は、中世にあった5城（浦城・岡本城・砂沢城・馬場目城・山内城）を象徴しています。"},{"tag":"味","hook":"1688年創業の酒蔵","t":"福禄寿酒造は、加賀国から秋田に逃れた渡邉家の初代彦兵衛が、1688年に創業した酒蔵です。"},{"tag":"ゆかり","hook":"酒蔵の当主は町長","t":"福禄寿酒造の当主は代々「彦兵衛」を襲名し、15代目の彦兵衛は2005年に五城目町長に就任しました。"},{"tag":"歴史","hook":"日本海沿岸の最北の古墳群","t":"岩野山古墳群は、しばしば「日本海沿岸部最北の古墳群」と称されます。"},{"tag":"車窓","hook":"馬の守護神を祀る馬場目岳","t":"馬場目岳の山頂脇には馬の守護神・相染神の石祠があり、かつて馬の守護神として信仰を集めた山です。"},{"tag":"へえ","hook":"浅見内の語源","t":"浅見内の語源は「あざみない（薊の川）」とされますが、「薊」の部分は日本語という説もあります。"},{"tag":"車窓","hook":"田んぼに立つ独立峰・森山","t":"森山は、国道7号や国道285号から、田んぼに突き立つ独立峰として望むことができます。"},{"tag":"クイズ","q":"五城目町の朝市は、何年の歴史を持つ？","a":"500年"},{"tag":"クイズ","q":"かつて日本におけるスズムシ群棲地の北限として知られた、秋田県の町は？","a":"五城目町"}]},"五戸町":{"pref":"青森県","cards":[{"tag":"へえ","hook":"四戸だけ消えた地名","t":"一戸から九戸の地名のうち、四戸だけは地名として現存しません。ただし糠部郡の時代には存在したことが判っています。","teaser":true},{"tag":"数字","hook":"約177.7km²に約15,761人が暮らす町","t":"面積は約177.7km²、人口は約15,761人（2021年）。1km²あたり約89人です。"},{"tag":"味","hook":"馬肉の里","t":"五戸町は馬肉の里として知られ、町内には馬肉料理店が点在しています。"},{"tag":"出身","hook":"五戸町出身の有名人","t":"五戸町出身には、レスリング選手の太田忍、サッカー選手・指導者の手倉森誠がいます。"},{"tag":"へえ","hook":"推定樹齢650年以上のカシワ","t":"倉石中市の「わむらのカシワの木」は県の天然記念物で、推定樹齢は650〜750年とされます。"},{"tag":"歴史","hook":"八戸と結ぶ鉄道があった","t":"かつては八戸駅と五戸駅の間を南部鉄道が走っていましたが、1968年の十勝沖地震で被災し、復旧せず廃止されました。"},{"tag":"クイズ","q":"2016リオ五輪のレスリングで銀メダルの、五戸町出身選手は？","a":"太田忍"},{"tag":"車窓","hook":"国の重要文化財の江渡家住宅","t":"荒町にある江渡家住宅は、国の重要文化財です。"},{"tag":"ゆかり","hook":"航空機設計者と新選組隊士","t":"五戸町にゆかりのある人物には、航空機設計者の木村秀政博士や、新選組隊士の斎藤一がいます。"},{"tag":"へえ","hook":"えんぶりも南部駒踊りもある町","t":"五戸町の祭りには、えんぶりや五戸まつり、南部駒踊りがあります。"},{"tag":"車窓","hook":"国道4号はあるが高速道路はない","t":"国道4号が通りますが、高速道路は通っていません。最寄りは八戸自動車道の八戸北ICなどです。"}]},"五所川原市":{"pref":"青森県","cards":[{"tag":"ゆかり","hook":"太宰治の生家は今や記念館","t":"金木町の津島邸は1907年に竣工した太宰治の生家で、いまは太宰治記念館「斜陽館」になっています。"},{"tag":"数字","hook":"約404.2km²に約50,757人が暮らす町","t":"面積は約404.2km²、人口は約50,757人（2021年）。1km²あたり約126人です。"},{"tag":"歴史","hook":"アイヌとの交易港・十三湊","t":"13世紀初頭、十三湊は豪族・安東氏の本拠地として、和人とアイヌの重要な交易拠点に栄え始めました。"},{"tag":"出身","hook":"五所川原市出身の有名人","t":"五所川原市出身には、小説家の太宰治、演歌歌手の吉幾三、大相撲力士の尊富士弥輝也がいます。"},{"tag":"歴史","hook":"十三湊を襲った大津波？","t":"1340年に大津波で十三湊が壊滅したとの伝承がありますが、発掘調査で津波の痕跡は検出されていません。","teaser":true},{"tag":"歴史","hook":"日本最古の海の法規集に登場","t":"日本最古の海洋法規集『廻船式目』は、七湊の一つとして「奥州津軽十三湊」の名を挙げています。"},{"tag":"歴史","hook":"米を運ぶ「十三小廻し」","t":"江戸時代、岩木川を下ってきた米を十三湊から鯵ヶ沢湊へ運ぶ「十三小廻し」が行われていました。"},{"tag":"へえ","hook":"ため池が百選に二つも","t":"2010年、農林水産省の「ため池百選」に境野沢ため池と藤枝ため池が選ばれました。"},{"tag":"へえ","hook":"立佞武多は8月4日〜8日","t":"五所川原立佞武多は、例年8月4日～8日に開催されます。"},{"tag":"クイズ","q":"五所川原市金木町にある、太宰治の生家は何という記念館になっている？","a":"斜陽館"},{"tag":"クイズ","q":"十三湊を本拠地として栄えた豪族は？","a":"安東氏（津軽安東氏）"},{"tag":"へえ","hook":"北海道の上ノ国町と姉妹都市","t":"五所川原市は、安藤氏とのかかわりから、北海道の上ノ国町と、1985年に姉妹都市になりました。"},{"tag":"車窓","hook":"十三湖に浮かぶ小島のパーク","t":"中の島ブリッジパークは、十三湖の西に浮かぶ小島を利用したパークで、島内から奈良時代の遺跡が発見されています。"},{"tag":"へえ","hook":"津軽錦石の玉鹿石","t":"金木町の玉鹿石は、津軽錦石の一種で、青森県指定天然記念物です。"},{"tag":"車窓","hook":"さくら名所100選の芦野公園","t":"金木町の芦野公園は、日本のさくら名所100選に選ばれています。"}]},"井川町":{"pref":"秋田県","cards":[{"tag":"へえ","hook":"人名と間違える駅名で1位","t":"井川さくら駅は、人名と勘違いしそうな駅名として、2008年と2018年のgooランキングでいずれも1位でした。","teaser":true},{"tag":"数字","hook":"県内で小さい方の町","t":"面積は約48.0km²で、県内25市町村中24位。人口は約4,482人（2021年）です。"},{"tag":"へえ","hook":"同じ名前の方を招待","t":"駅の開業後の1996年、井川町は同じ名前の「井川さくら」さんを招待しました。"},{"tag":"歴史","hook":"桜200種2,000本の国花苑","t":"1972年から2年がかりで、日本各地から集めた桜200種2,000本が植えられ、日本国花苑が開園しました。"},{"tag":"歴史","hook":"「園」を「苑」に変えた名前","t":"「日本国花園」という案に、当時の村長・鷲谷嘉兵衛が「園」を「苑」にしてはと提案した、と伝わります。"},{"tag":"クイズ","q":"日本国花苑は、秋田県から、どこの公園とともに「桜の名所百ヵ所」に選ばれた？","a":"大館市の長根山公園"},{"tag":"クイズ","q":"井川さくら駅の名前は、近くの何に由来する？","a":"桜の名所「日本国花苑」"},{"tag":"歴史","hook":"鎌倉時代の書物にも登場","t":"鎌倉時代の『吾妻鏡』にある「出羽国秋田郡湯河」が、井川にあたると考えられています。"},{"tag":"へえ","hook":"東西14kmの細長い町","t":"井川町は、東西に約14km、南北に約4kmと細長い町です。東の端に俎山があります。"},{"tag":"ゆかり","hook":"元関取の出身が三人","t":"井川町の出身者には、花乃湖健、若ノ海周治、大ノ海久光と、元関取が三人います。"},{"tag":"車窓","hook":"漫画に登場する駅と桜の園","t":"漫画『D-LIVE!!』には、井川さくら駅と日本国花苑が登場しています。"},{"tag":"歴史","hook":"日本初の認定こども園","t":"2006年11月、井川こどもセンターが日本初の認定こども園に認定されました。"}]},"亘理町":{"pref":"宮城県","cards":[{"tag":"味","hook":"ご飯が茶色い「はらこ飯」","t":"亘理町に伝わる郷土料理の「はらこ飯」は、鮭の煮汁でご飯を炊くため、ご飯の色が茶色です。"},{"tag":"数字","hook":"約73.6km²に約32,846人が暮らす町","t":"面積は約73.6km²、人口は約32,846人（2021年）。1km²あたり約446人です。"},{"tag":"味","hook":"はらこ飯は漁師のふるまいから","t":"亘理町荒浜では鮭の地引網漁が盛んで、大漁の時に漁師が振る舞ったのがはらこ飯と言われます。伊達政宗にも献上されたといわれます。"},{"tag":"出身","hook":"亘理町出身の有名人","t":"亘理町出身には、漫才師の宮城けんじ、詩人の菅原克己、元サッカー選手の鈴木淳がいます。"},{"tag":"味","hook":"イチゴの出荷量は東北地方第1位","t":"亘理町は、イチゴの出荷量が東北地方第1位で、リンゴの出荷量も宮城県第1位です。"},{"tag":"へえ","hook":"全長3kmの鳴き砂","t":"2006年、鳥の海の東南に広がる吉田浜で、全長3kmに及ぶ国内最大規模の鳴き砂が確認されました。","teaser":true},{"tag":"車窓","hook":"「鳥の海」は野鳥にちなむ名","t":"鳥の海は、渡り鳥や海鳥など野鳥の生息地で、地名の由来にもなっています。古くは仙台藩主伊達家の狩場でした。"},{"tag":"へえ","hook":"左甚五郎と天邪鬼の伝説","t":"三十三間堂官衙遺跡には、左甚五郎が一夜で建物を建てようとしたが、天邪鬼が鶏の鳴きまねをしたため礎石だけで中止になった、という伝説があります。"},{"tag":"歴史","hook":"牛が臥せた形の「臥牛城」","t":"亘理城は、地形が牛の臥せた形に似ていることから臥牛城ともいわれます。江戸時代は亘理要害と呼ばれました。"},{"tag":"歴史","hook":"仙台藩の降伏式は亘理で","t":"1868年、戊辰戦争に敗れた仙台藩の降伏式が、亘理城のあった地で行われました。"},{"tag":"歴史","hook":"北海道の伊達市へ家臣団と移住","t":"1870年、亘理伊達氏第14代当主の伊達邦成が、北海道開拓のため家臣団を率いて、有珠郡（現在の伊達市一帯）への移住を始めました。"},{"tag":"へえ","hook":"冬は晴れが多く温暖","t":"奥羽山脈などが雪雲を遮り、海風で気温が上がるため、亘理町の冬は県内でも特に晴天率が高く温暖です。"},{"tag":"クイズ","q":"亘理町が「はらこめしの日」としているのは、何月何日?","a":"10月8日"}]},"今別町":{"pref":"青森県","cards":[{"tag":"へえ","hook":"新幹線駅がある最も小さな自治体","t":"今別町は、新幹線の駅がある自治体で最も人口が少ない町とされています。","teaser":true},{"tag":"数字","hook":"約125.3km²に約2,292人が暮らす町","t":"面積は約125.3km²、人口は約2,292人（2021年）。1km²あたり約18人です。"},{"tag":"歴史","hook":"義経が名付けた町？","t":"地名は、源義経一行が川の水量の増加に驚き「今淵」と命名したという伝承に由来するとされます。のちに訛って今別になったといいます。"},{"tag":"ゆかり","hook":"荒馬まつりに大学生も参加","t":"荒馬まつりは毎年8月上旬の郷土芸能です。2000年に立命館大学の学生が参加したのを機に、県外の大学生も加わるようになりました。"},{"tag":"車窓","hook":"赤い岩はベンガラの産地","t":"赤根沢の赤岩はベンガラの産地で、県の天然記念物です。"},{"tag":"へえ","hook":"トンネル入口に神社","t":"青函トンネル入口広場の付近には、2016年の北海道新幹線開業時に「トンネル神社」が設置されました。"},{"tag":"へえ","hook":"海辺に仏舎利の代わりの石","t":"袰月舎利浜は、仏舎利の代替品である舎利石の産地です。"},{"tag":"クイズ","q":"今別町の地名は、伝承では義経一行が何と名付けたことに由来する？","a":"今淵（いまぶち）"},{"tag":"へえ","hook":"特別豪雪地帯の大陸性気候","t":"今別町は寒暖の差が大きい大陸性気候で、特別豪雪地帯に指定されています。"},{"tag":"数字","hook":"年に降る雪は503cm","t":"今別町の年平均降雪量は503cmです。"},{"tag":"車窓","hook":"津軽国定公園の袰月海岸","t":"袰月海岸は、津軽国定公園の景勝地です。"},{"tag":"へえ","hook":"廃校が宿泊施設に","t":"海峡の家「ほろづき」は、中学校の廃校を利用した町営の宿泊施設で、人工温泉もあります。"}]},"仙北市":{"pref":"秋田県","cards":[{"tag":"へえ","hook":"湖底が海面より174m下","t":"田沢湖は最大深度423.4mで日本第1位。湖面標高は249mなので、最深部の湖底は海面下174.4mです。","teaser":true},{"tag":"数字","hook":"県内で面積3位","t":"面積は約1,093.6km²で、県内25市町村中3位の広さ。人口は約24,515人（2021年）です。"},{"tag":"へえ","hook":"真冬でも凍らない湖","t":"田沢湖は、真冬でも湖面が凍り付くことはありません。"},{"tag":"出身","hook":"仙北市出身の有名人","t":"仙北市出身には、歌手の藤あや子、新潮社創業者の佐藤義亮、日本画家の平福百穂、元バレーボール選手の荒木田裕子がいます。"},{"tag":"クイズ","q":"田沢湖は、世界で最も深い湖になぞらえて、何と呼ばれる？","a":"日本のバイカル湖"},{"tag":"歴史","hook":"クニマスの最古の記述","t":"田沢湖の固有種クニマスは、1715年に最古の記述が出ており、久保田藩主の佐竹氏などへの献上品として利用されてきました。"},{"tag":"歴史","hook":"京の文化が移った角館","t":"角館に入った佐竹北家の佐竹義隣は京の公家・高倉家からの養子で、角館には多くの京文化が移入されました。"},{"tag":"車窓","hook":"火除け地で分けた城下町","t":"角館の城下町は、中央に土塁を築いた「火除け地」で火事に備え、北側を武士の内町、南側を町人の外町としました。"},{"tag":"車窓","hook":"桜まつりに百数十万人","t":"角館の桜まつりの時期は、毎年百数十万人の観光客が訪れます。"},{"tag":"へえ","hook":"高山植物は国の天然記念物","t":"秋田駒ヶ岳の山頂一帯に咲く数百種類の高山植物群は、1926年に「秋田駒ヶ岳高山植物帯」として国の天然記念物に指定されました。"},{"tag":"へえ","hook":"七つの宿からなる乳頭温泉郷","t":"乳頭温泉郷は、鶴の湯温泉から黒湯温泉までの六軒の一軒宿と、休暇村乳頭温泉郷の計7つの宿で構成されています。"},{"tag":"クイズ","q":"抱返り渓谷の名は、人がすれ違うとき何をしたことに因むといわれる？","a":"互いに抱き合って振り返った"},{"tag":"味","hook":"大きな西明寺栗","t":"西木町地区には、大きい西明寺栗があり、八津地区にはカタクリの群生があります。"}]},"仙台市":{"pref":"宮城県","cards":[{"tag":"へえ","hook":"フィギュアスケート発祥の地","t":"仙台は「フィギュアスケート発祥の地」。1897年ごろ、米国人のデブィソンが仙台城の堀である五色沼で子供たちに教えたのが始まりとされます。","teaser":true},{"tag":"数字","hook":"県内で面積3位","t":"面積は約786.4km²で、県内35市町村中3位の広さ。人口は約1,061,177人（2020年）です。"},{"tag":"歴史","hook":"日本初の地下駅は仙台駅","t":"1925年に宮城電気鉄道が開設した仙台駅とその路線は、日本初の地下駅・地下鉄とされています。東京の銀座線の開業は、その2年後の1927年です。"},{"tag":"歴史","hook":"日本初の女子大生が誕生","t":"1913年、東北帝国大学に黒田チカ、牧田らく、丹下ウメの3人が入学しました。仙台は日本初の女子大生誕生の地とされます。"},{"tag":"味","hook":"牛タンも冷やし中華も仙台発祥","t":"牛タン料理、炉端焼き、冷やし中華、せり鍋などが、仙台発祥の料理に挙げられています。"},{"tag":"味","hook":"ウイスキーの蒸留所が広瀬川上流に","t":"ニッカウヰスキーの蒸留所の一つ、宮城峡蒸溜所は、広瀬川上流の新川河畔にあります。宮城県はウィスキー消費量日本一です。"},{"tag":"へえ","hook":"仙台七夕まつりの大きな人出","t":"仙台七夕まつりは藩政時代以来の歴史を持つ祭り。東北四大夏祭りの1つで、中心部商店街は期間中200万人以上の人出です。"},{"tag":"歴史","hook":"天守のない仙台城","t":"仙台城は、天守台はあるものの天守を持たず、時代の流行に背を向けましたが、ビスカイノに「日本の最も勝れ、又最も堅固なるものの一つ」と言わしめた堅城でした。"},{"tag":"歴史","hook":"仙台城の建設費は蔵王の金から","t":"仙台城の建設費の一部は、宮鉱山（現在の蔵王町）などで採掘された金でまかなわれました。"},{"tag":"歴史","hook":"政宗が遺言した霊廟、瑞鳳殿","t":"伊達政宗は生前、ホトトギスの初音を聞き、遺骸を経ヶ峯に葬るよう遺言しました。二代藩主の忠宗が、霊廟「瑞鳳殿」を建てました。"},{"tag":"へえ","hook":"落差55mの秋保大滝","t":"秋保大滝は名取川上流にある落差55m、幅6mの滝です。国の名勝に指定され、日本の滝百選の1つに数えられます。"},{"tag":"クイズ","q":"駅弁の種類が日本で最も多い駅として知られるのは、どこの駅?","a":"仙台駅"}]},"伊達市":{"pref":"福島県","cards":[{"tag":"味","hook":"あんぽ柿は干しぶどうがヒント","t":"梁川町五十沢のあんぽ柿は大正期の開発。米国の硫黄燻蒸干しぶどうの製法をヒントに生まれました。","teaser":true},{"tag":"数字","hook":"約265.1km²に約58,232人が暮らす町","t":"面積は約265.1km²、人口は約58,232人（2021年）。1km²あたり約220人です。"},{"tag":"味","hook":"半分生のジューシーな干し柿","t":"あんぽ柿は完全に乾燥させず、半分生のようなジューシーな感触で、羊羹のように柔らかいのが特徴です。"},{"tag":"出身","hook":"伊達市出身の有名人","t":"伊達市出身には、医学者の三浦謹之助、元バレーボール選手の羽根翠、女優の小林アリスがいます。"},{"tag":"歴史","hook":"全国の蚕種の半分以上","t":"江戸時代中期には、全国の蚕種生産高の半分以上は信達地方の生産だったといいます。"},{"tag":"歴史","hook":"蚕都・梁川のにぎわい","t":"梁川町は蚕都と呼ばれ、全国から生糸の買い付け人が集まりました。戦後まで旅館街や歌舞伎座がありました。"},{"tag":"へえ","hook":"梁川の歌舞伎座は福島市に","t":"梁川町の歌舞伎座「広瀬座」は福島市に寄贈され、文化財として移築保存されています。"},{"tag":"ゆかり","hook":"伊達氏は伊達郡が発祥","t":"仙台藩主の伊達家は、鎌倉時代に伊達郡の領地を与えられて伊達氏と改姓したのが発祥です。"},{"tag":"歴史","hook":"南朝方の拠点・霊山城","t":"南北朝時代の1337年、北畠顕家が霊山に城を築き、陸奥国の国府を置くなど南朝方の一大拠点になりました。"},{"tag":"車窓","hook":"奇岩の山・霊山","t":"霊山は標高825メートルの岩山。国の名勝で、日本百景、うつくしま百名山にも指定されています。"},{"tag":"へえ","hook":"農業協同組合発祥の地","t":"霊山町上小国は「農業協同組合発祥の地」とされます。1898年、佐藤忠望が小国信用組合を設立しました。"},{"tag":"クイズ","q":"伊達市は全国で2例目の何になった?(北海道にも伊達市があるため)","a":"「同一名称の市」"},{"tag":"クイズ","q":"あんぽ柿が開発された時期は?","a":"大正期"}]},"会津坂下町":{"pref":"福島県","cards":[{"tag":"へえ","hook":"一木造で日本最大級の観音像","t":"恵隆寺の木造千手観音立像は、一木造で総高8.5m。一木造としては日本最大級の仏像です。","teaser":true},{"tag":"数字","hook":"約91.6km²に約14,906人が暮らす町","t":"面積は約91.6km²、人口は約14,906人（2021年）。1km²あたり約163人です。"},{"tag":"歴史","hook":"亀ヶ森古墳は福島県で最大","t":"亀ヶ森古墳は4世紀後半頃の築造と推定され、福島県では最大、東北地方では第2位の規模の古墳です。"},{"tag":"出身","hook":"会津坂下町出身の有名人","t":"会津坂下町出身には、演歌歌手の春日八郎、木版画家の斎藤清、たこ焼きを発明した料理人の遠藤留吉、武道家の武田惣角がいます。"},{"tag":"へえ","hook":"「坂下のバカ三里」","t":"江戸時代、坂下では毎月旧暦の14日に市が立ちました。若松・喜多方・高田から三里だったため、「坂下のバカ三里」とも呼ばれました。"},{"tag":"歴史","hook":"地震でできた山科湖","t":"1611年の会津大地震の山崩れで阿賀川がせき止められ、山科湖ができました。広瀬地区の地名は、この湖に水没していたことに由来します。"},{"tag":"歴史","hook":"丈介橋の名の由来","t":"阿賀川の荷揚げ場を整備した民間人の佐藤丈介は、橋も整備しました。その名が今も丈介橋として残っています。"},{"tag":"車窓","hook":"沼田街道の起点","t":"かつて沼田街道の起点が町にあり、七折峠から奥会津、尾瀬が原、片品を通って群馬県沼田市へ至る主要街道でした。"},{"tag":"へえ","hook":"5トンの米俵を引き合う","t":"初市大俵引きは1月、重さ約5トンの米俵を引き合う伝統行事です。"},{"tag":"味","hook":"蕎麦の実の中心だけを使う","t":"名産品の「極上の蕎麦」は、蕎麦の実の中心だけから採った蕎麦粉を使う独自のスタイルの発祥地とされます。"},{"tag":"ゆかり","hook":"たこ焼きを開発した遠藤留吉","t":"会津屋の創業者・遠藤留吉は、1907年に会津坂下町の農家に生まれ、1935年にたこ焼きを開発したことで知られます。"},{"tag":"クイズ","q":"江戸時代、坂下で市が立ったのは、毎月旧暦の何日?","a":"14日"},{"tag":"クイズ","q":"恵隆寺の木造千手観音立像の総高は、約何m?","a":"8.5m"}]},"会津美里町":{"pref":"福島県","cards":[{"tag":"へえ","hook":"「会津」は行き会ったから？","t":"「会津」という地名は、北陸道と東海道を進んだ二人の将軍が会津で行き会ったことに由来するといわれます。","teaser":true},{"tag":"数字","hook":"約276.3km²に約19,078人が暮らす町","t":"面積は約276.3km²、人口は約19,078人（2021年）。1km²あたり約69人です。"},{"tag":"歴史","hook":"日本三大田植の御田植祭","t":"伊佐須美神社の御田植祭は7月12日に行われ、「日本三大田植」の1つに挙げられます。"},{"tag":"出身","hook":"会津美里町出身の有名人","t":"会津美里町出身には、天台宗の僧侶の天海、女優の水戸光子、民俗学者の山口弥一郎がいます。"},{"tag":"へえ","hook":"35m以上に伸びる「飛竜の藤」","t":"伊佐須美神社の境内には、35メートル以上の高さまで伸びる「飛竜の藤」があります。福島県指定の天然記念物です。"},{"tag":"車窓","hook":"あやめ苑は10万株","t":"伊佐須美神社の神苑「あやめ苑」には約150種・10万株のあやめがあり、6月15日から7月5日にあやめ祭りが催されます。"},{"tag":"歴史","hook":"日本最大級の山城、向羽黒山城","t":"向羽黒山城は、蘆名盛氏が1568年に築いた「日本最大級の山城」で、城跡は国の史跡です。"},{"tag":"歴史","hook":"窯元は100超から12に","t":"会津本郷焼の窯元は、明治の最盛期には100を超えましたが、2026年時点では12です。"},{"tag":"味","hook":"にしんの山椒漬け専用の鉢","t":"会津本郷焼の代表的な陶器「にしん鉢」は、古くからにしんの山椒漬け専用として使われてきました。"},{"tag":"味","hook":"実の重みで木が折れる身不知柿","t":"身不知柿は、柿の木が重みで折れてしまうほど実を付けることから名付けられたとされます。"},{"tag":"ゆかり","hook":"観光大使はお笑いコンビ","t":"お笑いコンビ「スゲーニョ」のメンバー、金成裕也さんは会津美里町の観光大使です。"},{"tag":"車窓","hook":"博士峠は冬季閉鎖","t":"国道401号の博士峠は、冬季閉鎖されます。"},{"tag":"クイズ","q":"伊佐須美神社の御田植祭は、何月何日に行われる?","a":"7月12日"}]},"会津若松市":{"pref":"福島県","cards":[{"tag":"車窓","hook":"すれ違わない二重らせんの堂","t":"会津さざえ堂は二重らせんの斜路。右回りで上り、左回りで下りるので、他の人とすれ違わずに出口へ出られます。","teaser":true},{"tag":"数字","hook":"県内で人口4位","t":"人口は約117,924人（2021年）で、県内53市町村中4位。面積は約383.0km²です。"},{"tag":"歴史","hook":"「若松」の名は神社の杜から","t":"蒲生氏郷が町の名を黒川から「若松」に改めました。「若松」の名は、出身地に近い神社の参道にあった「若松の杜」に由来します。"},{"tag":"出身","hook":"会津若松市出身の有名人","t":"会津若松市出身には、東京帝国大学総長の山川健次郎、社会学者の小室直樹、天文学者の渡部潤一、声優の保志総一朗がいます。"},{"tag":"へえ","hook":"鶴ヶ城のしゃちほこの瞳はダイヤ","t":"鶴ヶ城の鯱は寄贈品。全身の鱗は銀箔、牙は金製で、瞳の中心に2カラットのダイヤモンドが埋め込まれています。"},{"tag":"歴史","hook":"御三階は阿弥陀寺に現存","t":"鶴ヶ城の本丸にあった櫓「御三階」は、1870年に阿弥陀寺（七日町）へ移築され、現存します。"},{"tag":"へえ","hook":"赤べこの黒い斑点は痘の印","t":"赤べこは赤い牛に似せた張子。黒い斑点は痘を表し、病にかかっても重くならないよう子どもに贈る風習がありました。"},{"tag":"へえ","hook":"小法師は家族より1個多く","t":"起き上がり小法師は、家族の人数より1個多く買う慣習があります。「家族が増えますように」という願いからです。"},{"tag":"歴史","hook":"先に市になったのに改名","t":"1955年、市名を「若松市」から「会津若松市」に変更。福岡県の若松市との混同を避けるため、先に市制を敷いた市が改名した唯一の例です。"},{"tag":"へえ","hook":"内視鏡は世界の7割がここ製","t":"会津オリンパスの会津工場は世界最大級の内視鏡関連製品の生産拠点で、消化器向けは世界の7割が同工場製といわれます。"},{"tag":"車窓","hook":"約400種の薬草が育つ庭","t":"御薬園の北側にある薬用植物標本園では、会津産薬草約200種を含む約400種の薬草が栽培されています。"},{"tag":"クイズ","q":"赤べこの「べこ」は、東北地方の方言で何のこと?","a":"牛"},{"tag":"クイズ","q":"鶴ヶ城の鯱の瞳の中心には、何カラットのダイヤが埋め込まれている?","a":"2カラット"}]},"住田町":{"pref":"岩手県","cards":[{"tag":"へえ","hook":"「森林・林業日本一の町」を目指す","t":"豊富な森林資源と木材加工施設を活かして、住田町は「森林・林業日本一の町」を目指しています。"},{"tag":"数字","hook":"約334.8km²に約4,997人が暮らす町","t":"面積は約334.8km²、人口は約4,997人（2021年）。1km²あたり約15人です。"},{"tag":"歴史","hook":"住田は三つの地名の合成","t":"住田は、上有住村・下有住村・世田米町から一文字ずつとった地名です。当初は成瀬町になる予定でした。"},{"tag":"出身","hook":"住田町出身の有名人","t":"住田町出身には、歌手の早瀬ひとみ、俳優の及川達郎、歌人の佐藤霊峰がいます。"},{"tag":"へえ","hook":"洞窟の中に落差29mの滝","t":"滝観洞の天の岩戸の滝は、洞窟内の滝として日本最大級の落差（高さ29m）です。映画「八つ墓村」のロケ地でもあります。","teaser":true},{"tag":"車窓","hook":"気仙川のめがね橋","t":"葉山めがね橋は、1931年に気仙川にかけられた農地かんがい専用の水路橋です。アーチの形から名がつきました。"},{"tag":"車窓","hook":"流されても復元される橋","t":"気仙川の松日橋は木製の流れ橋です。増水で橋材が流されることを前提にしていて、その都度復元されています。"},{"tag":"歴史","hook":"伊達藩の火縄は五葉山産","t":"伊達藩の火縄銃に使う火縄が五葉山で作られていたことから、五葉山火縄銃鉄砲隊が結成されました。"},{"tag":"ゆかり","hook":"賢治ゆかりの種山ヶ原","t":"宮沢賢治にゆかりの深い種山ヶ原では、かつて毎年8月上旬に約1000人が集まる星空イベントがありました。2005年が最後です。"},{"tag":"車窓","hook":"三陸沿岸の最高峰・五葉山","t":"五葉山は標高1,351mで、三陸沿岸の最高峰です。日本三百名山にも選ばれています。"},{"tag":"歴史","hook":"木の家を産地から直送","t":"1982年に第三セクターの住田住宅産業を設立し、他の木材産地に先駆けて産直住宅の販売を始めました。"},{"tag":"クイズ","q":"住田町の名は、三つの旧町村から何をとってできた?","a":"それぞれ一文字ずつ"},{"tag":"クイズ","q":"洞窟内の滝として日本最大級の落差をもつ、滝観洞の滝は?","a":"天の岩戸の滝"}]},"佐井村":{"pref":"青森県","cards":[{"tag":"車窓","hook":"仏像のような白緑色の奇岩","t":"仏ヶ浦は約2kmにわたる海岸沿いに、仏像を思わせる白緑色の奇岩が連なる国の名勝です。","teaser":true},{"tag":"数字","hook":"人より自然が多い町","t":"1km²あたり約13人。県内で下から2番目の人口密度です。"},{"tag":"へえ","hook":"漁村に100年続く歌舞伎","t":"福浦歌舞伎は明治20年頃に伝わり、100年以上受け継がれる青森県の無形民俗文化財です。"},{"tag":"ゆかり","hook":"抱き合う男女に見える岩","t":"願掛岩は男女が抱き合っているように見える岩で、古くより縁結びの岩として信仰されています。"},{"tag":"歴史","hook":"佐井と函館が海峡のメイン航路","t":"享和3年、江戸幕府は佐井と函館を結ぶ航路を海峡航路のメインルートと定めました。"},{"tag":"へえ","hook":"本州最後のへき地5級校","t":"牛滝小学校は、かつて本州最後のへき地5級校でした。"},{"tag":"ゆかり","hook":"手製の赤十字旗で兵を救う","t":"医師の三上剛太郎は日露戦争で、ロシア兵に囲まれても手製の赤十字旗を掲げて負傷兵を救いました。"},{"tag":"ゆかり","hook":"円空作の十一面観音","t":"長福寺には円空作の木彫十一面観音立像があり、県重宝に指定されています。"},{"tag":"クイズ","q":"仏ヶ浦の国の名勝としての指定名称は？","a":"仏宇多"},{"tag":"クイズ","q":"下北半島をまさかりに見立てると、佐井村はどの部分？","a":"刃の部分"},{"tag":"へえ","hook":"「日本で最も美しい村」の連合に加盟","t":"佐井村は「日本で最も美しい村」連合に加盟していて、仏ヶ浦の眺望と福浦の漁村歌舞伎が登録されています。"},{"tag":"歴史","hook":"青森と結んだシィライン","t":"青森港から佐井港までを結んだシィラインは、2023年3月31日に廃止されました。"},{"tag":"へえ","hook":"祇園祭の流れを汲む例大祭","t":"箭根森八幡宮の例大祭は、京都祇園祭の流れを汲んでいます。"}]},"八峰町":{"pref":"秋田県","cards":[{"tag":"へえ","hook":"滝壺に入る神輿","t":"白瀑神社の例大祭「みこしの滝浴び」は毎年8月1日。神輿を担いだまま滝壺に入る珍しい神事です。","teaser":true},{"tag":"数字","hook":"約234.1km²に約6,437人が暮らす町","t":"面積は約234.1km²、人口は約6,437人（2021年）。1km²あたり約27人です。"},{"tag":"歴史","hook":"桃源郷と讃えられた手這坂","t":"手這坂は、1807年に菅江真澄が「桃源郷の様だ」と賞賛した集落で、茅葺屋根の民家が複数現存しています。"},{"tag":"出身","hook":"八峰町出身の有名人","t":"八峰町出身には、オフコースの松尾一彦、広告クリエイターのクドウナオヤがいます。"},{"tag":"車窓","hook":"漁師の目印だったピラミッド山","t":"真瀬岳は端正なピラミッド形の山で、日本海からも確認が容易なため、漁師たちの寄港の目印になっていました。"},{"tag":"味","hook":"秋田音頭の八森ハタハタ","t":"八峰町は、秋田音頭の最初に歌われる八森ハタハタで知られ、ハタハタ寿司やしょっつるも名物です。"},{"tag":"味","hook":"ハタハタは県魚、卵はブリコ","t":"ハタハタは秋田県の県魚です。魚卵は「ブリコ」と呼ばれます。"},{"tag":"車窓","hook":"沖に浮かぶ無人島・雄島","t":"雄島は周囲約500mの無人島。「雄じま」と「雌じま」と呼ばれる2つの小高い岩山があります。"},{"tag":"へえ","hook":"山肌に浮かぶ「八」の字","t":"国道101号に面した標高208mの糠森山では、お盆と正月をはさんだ各1か月程度、「八」の字のライトアップが行われます。"},{"tag":"へえ","hook":"町名は合成地名","t":"町名の候補には「南白神町」「あきた白神町」もありましたが、合成地名の「八峰町」になりました。"},{"tag":"歴史","hook":"ジオパークのテーマ","t":"八峰白神ジオパークのテーマは「白神山地の恵みに生きる」。2012年9月に日本ジオパークに認定されました。"},{"tag":"クイズ","q":"八峰町の白瀑神社で、神輿を担いだまま滝壺に入る神事は？","a":"みこしの滝浴び"},{"tag":"クイズ","q":"八峰町で知られる、秋田音頭の最初に歌われる魚は？","a":"ハタハタ"}]},"八幡平市":{"pref":"岩手県","cards":[{"tag":"へえ","hook":"竜の目に見える「ドラゴンアイ」","t":"5月下旬から6月上旬、八幡平頂上付近の鏡沼の雪解けが竜の目のように見え、「八幡平ドラゴンアイ」と呼ばれています。","teaser":true},{"tag":"数字","hook":"約862.3km²に約23,742人が暮らす町","t":"面積は約862.3km²、人口は約23,742人（2021年）。1km²あたり約28人です。"},{"tag":"歴史","hook":"一時は東洋一の硫黄鉱山","t":"松尾鉱山は1969年まで松尾村にあった鉱山で、一時は東洋一の硫黄鉱山でした。鉱山労働者の鉄筋アパート群が廃墟として残っています。"},{"tag":"出身","hook":"八幡平市出身の有名人","t":"八幡平市出身には、考古学者の工藤雅樹、漫画家の菅野修、スキージャンプの小林陵侑がいます。"},{"tag":"へえ","hook":"日本初の商業地熱発電所","t":"八幡平市の松川地熱発電所は、日本初の商業ベースの地熱発電所として1966年に運転を開始しました。"},{"tag":"歴史","hook":"真っ赤に流れた「焼走り」","t":"焼走り熔岩流の名は、真っ赤な熔岩流が斜面を急速に流れ下るのを見た当時の人々が「焼走り」と呼んだことによるといわれます。"},{"tag":"車窓","hook":"日本百名山の八幡平","t":"八幡平は、秋田県と岩手県にまたがる標高1,614mの山と高原台地で、日本百名山に挙げられています。"},{"tag":"ゆかり","hook":"北京五輪の金メダリスト","t":"八幡平市松尾生まれの小林陵侑選手は、2022年北京オリンピックのノーマルヒルで金メダルを取りました。"},{"tag":"ゆかり","hook":"宮古市・名護市とつながる市","t":"八幡平市は宮古市と2006年に姉妹都市、沖縄県の名護市と2007年に友好都市の提携を結んでいます。"},{"tag":"車窓","hook":"県内最大規模のスキーリゾート","t":"八幡平市には複数のスキー場があり、安比高原や八幡平のリゾートエリアは県内最大規模を誇ります。"},{"tag":"へえ","hook":"日本初の英国式全寮制の学校","t":"2022年8月、八幡平市に、日本初の英国式全寮制インターナショナルスクール「ハロウ安比校」が開校しました。"},{"tag":"クイズ","q":"八幡平市で東北自動車道から分かれる高速道路は、何自動車道？","a":"八戸自動車道"}]},"八戸市":{"pref":"青森県","cards":[{"tag":"へえ","hook":"B-1グランプリの生まれた町","t":"八戸市はB-1グランプリ発祥の地です。ご当地の味を食べ歩く旅も楽しそうです。","teaser":true},{"tag":"数字","hook":"県内で人口2位","t":"人口は約222,799人（2021年）で、県内40市町村中2位。面積は約305.6km²です。"},{"tag":"味","hook":"お盆に食べる「背中あて」","t":"八戸ではお盆に「背中あて」を食べる慣習が根付いています。どんな味か、気になりませんか。"},{"tag":"出身","hook":"八戸市出身の有名人","t":"八戸市出身には、アマチュアレスリング選手の伊調馨、音楽家の内澤崇仁、歌人の梅内美華子がいます。"},{"tag":"へえ","hook":"八戸は「氷都」","t":"八戸は「氷都八戸」と呼ばれ、その歴史は1947年の第1回冬季国体から始まったとされています。"},{"tag":"車窓","hook":"ウミネコの島が天然記念物","t":"蕪島は日本の音風景100選にも選ばれたウミネコの繁殖地で、国の天然記念物です。"},{"tag":"歴史","hook":"盛岡藩に引きずられなかった","t":"八戸藩は「盛岡藩には引きずられない」という意識から、不戦に徹したとされます。"},{"tag":"歴史","hook":"縄文の国宝、合掌土偶","t":"風張遺跡から出土した合掌土偶は国宝です。縄文時代後期の米粒も見つかっています。"},{"tag":"クイズ","q":"八戸が「氷都」と呼ばれる理由の一つ、スケートと並んで盛んな競技は？","a":"アイスホッケー"},{"tag":"クイズ","q":"八戸でお盆に食べる慣習がある食べ物は何？","a":"背中あて"},{"tag":"へえ","hook":"ユネスコ遺産の八戸三社大祭","t":"八戸三社大祭は、重要無形民俗文化財でユネスコ無形文化遺産です。7月末から8月上旬に行われます。"},{"tag":"車窓","hook":"朝市と八食センターの街","t":"八戸には、陸奥湊駅前朝市、八食センター、八戸屋台村みろく横丁などがあります。"},{"tag":"へえ","hook":"遊泳禁止でも鳴り砂の海岸","t":"大須賀海岸は、離岸流のため遊泳はできませんが、鳴り砂で知られています。"},{"tag":"へえ","hook":"南部裂織や南部菱刺し","t":"八戸市内の青森県指定伝統工芸品には、南部裂織、南部菱刺し、八戸焼、八幡馬、南部姫鞠、えんぶり烏帽子があります。"}]},"八郎潟町":{"pref":"秋田県","cards":[{"tag":"へえ","hook":"死者の姿で踊る盆踊","t":"一日市の盆踊は、もとは死者を弔うため死者の姿に仮装して踊られ、今はさまざまな姿の仮装が通りにあふれます。","teaser":true},{"tag":"数字","hook":"県内で小さい方の町","t":"面積は約17.0km²で、県内25市町村中25位。人口は約5,445人（2021年）です。"},{"tag":"歴史","hook":"最北の式内社をめぐって","t":"副川神社は、現在の所在地では日本最北の式内社ですが、本来の所在地としては岩手県の志賀理和気神社が最北とされます。"},{"tag":"出身","hook":"八郎潟町出身の有名人","t":"八郎潟町出身には、元プロ野球選手の後藤光尊、歌手の順弘子、バドミントン選手の志田千陽がいます。"},{"tag":"車窓","hook":"船の灯台だった石灯籠","t":"副川神社の山腹の石灯籠は高さ約2.5mの永久常夜灯で、かつては八郎潟を往来する船の灯台の役割を果たしました。"},{"tag":"歴史","hook":"琵琶湖に次ぐ第2位だった湖","t":"八郎潟はかつて面積220km2で、日本の湖沼では琵琶湖に次ぐ第2位でしたが、干拓で大部分が陸地になりました。"},{"tag":"へえ","hook":"北緯40度線と東経140度線の交点","t":"八郎潟の干拓地には、北緯40度線と東経140度線の交会点があります。陸地にあるのは日本唯一の地点です。"},{"tag":"へえ","hook":"県内で一番小さな町","t":"八郎潟町は、面積17.0km2で、秋田県内では一番小さな自治体です。"},{"tag":"ゆかり","hook":"野球部から名選手が","t":"八郎潟中学校の野球部は、石井浩郎さんや後藤光尊さんなどを輩出しています。"},{"tag":"へえ","hook":"三倉鼻の名の由来","t":"三倉鼻の名は、八郎太郎に助けられた夫殿が長者になり、3つの倉を建てたことに由来するという伝承があります。"},{"tag":"へえ","hook":"サンズイを足した寺の名","t":"清源寺の名は、火災による焼失が相次いだため、験を担いで「青原寺」にサンズイを入れたものと伝わります。"},{"tag":"クイズ","q":"八郎潟町は、秋田県内で何が一番小さい自治体？","a":"面積"},{"tag":"クイズ","q":"毛馬内、西馬音内とともに三大盆踊りと称される、八郎潟町の盆踊りは？","a":"一日市の盆踊"}]},"六ヶ所村":{"pref":"青森県","cards":[{"tag":"へえ","hook":"50音順で最後の村","t":"日本の村を50音順に並べると、六ヶ所村は最後になるとされます。","teaser":true},{"tag":"数字","hook":"約252.7km²に約10,099人が暮らす町","t":"面積は約252.7km²、人口は約10,099人（2021年）。1km²あたり約40人です。"},{"tag":"へえ","hook":"エネルギーが勢ぞろいの村","t":"原子力施設、国家石油備蓄基地、やませを利用した風力発電基地など、エネルギー関連施設が集中しています。"},{"tag":"出身","hook":"六ヶ所村出身の有名人","t":"六ヶ所村出身には、演歌歌手の林あさ美、フリーキャスターの遠田恵子がいます。"},{"tag":"歴史","hook":"歌枕「尾駮の駒」","t":"「尾駮の駒」は歌枕として何度もうたわれ、1793年には菅江真澄が大雪の中、尾駮村を訪ねて感激を歌にしました。"},{"tag":"へえ","hook":"とまりのトトロ","t":"泊地区には、トトロにそっくりの岩穴があり「とまりのトトロ」と呼ばれています。"},{"tag":"車窓","hook":"冷害に強い根菜の村","t":"やませによる冷害が起きやすいため、ナガイモなど冷害に強い根菜類が多く作られています。"},{"tag":"味","hook":"ナガイモの焼酎「六趣」","t":"ナガイモで造った焼酎「六趣」があります。"},{"tag":"へえ","hook":"財政力指数が全国2位（2023年度）","t":"2023年度の財政力指数は1.61で、全国で2番目に高い値でした。"},{"tag":"クイズ","q":"六ヶ所村を走る鉄道路線はある？","a":"ない"},{"tag":"へえ","hook":"ドイツのヴァーレン市と友好","t":"六ヶ所村は、ドイツのヴァーレン市と、1994年に友好都市になりました。"},{"tag":"数字","hook":"石油備蓄は約570万kl","t":"むつ小川原国家石油備蓄基地は、1985年9月に完成し、最大備蓄量は約570万klです。"},{"tag":"数字","hook":"風車34基の二又風力発電所","t":"二又風力発電所は、1500kWの風車34基で、設備能力は51000kWです。2008年5月に運転を始めました。"}]},"六戸町":{"pref":"青森県","cards":[{"tag":"へえ","hook":"一戸から九戸は兄弟のまち","t":"六戸町は、一戸町、二戸市、三戸町、五戸町、七戸町、八戸市、九戸村と、1994年に「戸の兄弟のまち」を宣言しました。","teaser":true},{"tag":"数字","hook":"約83.9km²に約10,473人が暮らす町","t":"面積は約83.9km²、人口は約10,473人（2021年）。1km²あたり約125人です。"},{"tag":"車窓","hook":"県南地方随一の桜の名所","t":"舘野公園は県南地方随一の桜の名所として有名で、主にヤマザクラが植えられています。"},{"tag":"出身","hook":"六戸町出身の有名人","t":"六戸町出身には、大相撲立行司の37代木村庄之助がいます。"},{"tag":"味","hook":"「日本一の大玉ニンニク」を名乗る","t":"六戸町のニンニクは「日本一の大玉ニンニク」と紹介されています。"},{"tag":"へえ","hook":"三沢駅の大字は六戸町と同じ","t":"三沢駅周辺の古間木地区はもと旧六戸村で、駅の所在地は六戸町と同じ「大字犬落瀬」です。"},{"tag":"へえ","hook":"星野リゾートの半分は六戸町","t":"星野リゾート青森屋（古牧温泉）は、敷地の約半分が六戸町に属しています。"},{"tag":"歴史","hook":"熊野神社は844年の創建","t":"熊野神社は、文室綿麻呂の家臣・笹野尚盛により844年に創建されました。"},{"tag":"ゆかり","hook":"騎馬武者の野馬取りを舞う踊り","t":"上吉田南部駒踊りは、騎馬武者による野馬取りになぞらえて舞踊化された、上吉田地区に古くから伝わる踊りです。"},{"tag":"クイズ","q":"六戸町を東西に流れる、十和田湖が源流の川は？","a":"奥入瀬川"},{"tag":"クイズ","q":"六戸町の熊野神社が創建されたのは何年？","a":"844年"},{"tag":"へえ","hook":"投票は電子パネルだった","t":"六戸町は、平成19年、23年、27年の町議会選挙で電子パネル方式を採用し、平成31年に自署式へ戻りました。"},{"tag":"数字","hook":"人口が増えた県内2町のひとつ","t":"令和2年の国勢調査で人口が増えた青森県の市町村は、六戸町とおいらせ町だけでした。"},{"tag":"歴史","hook":"350年続く今熊神楽","t":"今熊神楽は、350年の歴史がある六戸町の神楽です。"}]},"利府町":{"pref":"宮城県","cards":[{"tag":"味","hook":"利府のナシは苗木150本から","t":"利府のナシ栽培は1884年、日野藤吉が2反歩の水田を畑に転換し、ナシの苗木150本を植えたことから始まりました。"},{"tag":"数字","hook":"約44.9km²に約35,521人が暮らす町","t":"面積は約44.9km²、人口は約35,521人（2021年）。1km²あたり約791人です。"},{"tag":"ゆかり","hook":"ナシの恩人をたたえる碑","t":"ナシ栽培の普及と改良に努めた日野藤吉を称える頌徳碑が、利府駅の近くにあります。"},{"tag":"出身","hook":"利府町出身の有名人","t":"利府町出身には、元フィギュアスケート選手の荒川静香、女子プロレスラーの藤本つかさがいます。"},{"tag":"歴史","hook":"利府に築かれた勿来の関","t":"利府の森郷地区には勿来の関が築かれたとされ、白河の関や鼠ヶ関と共に奥州三関の一つとする説があります。"},{"tag":"へえ","hook":"運動施設が集まる、県庁のない町","t":"利府町は県庁所在地ではないのに、県と町が別々に運営するほぼ同じ種類の運動施設が、半径1キロメートル程度に集中しています。","teaser":true},{"tag":"クイズ","q":"東京オリンピックのサッカー競技が行われた、利府町の競技場は?","a":"宮城スタジアム（キューアンドエースタジアムみやぎ）です。2002年のワールドカップの会場にもなりました。"},{"tag":"へえ","hook":"オリンピックのサッカー10試合","t":"2021年の東京オリンピックでは、利府町の宮城スタジアムがサッカー競技会場となり、6日間で計10試合が行われました。"},{"tag":"車窓","hook":"東北最大級のイオンモール","t":"2021年の南館オープンで、南館・北館を合わせた、東北最大級で国内3番目の規模のイオンモールが誕生しました。"},{"tag":"車窓","hook":"全新幹線が通う車両基地","t":"利府町の新幹線車両基地には、JR東日本が保有するすべての新幹線車両が、検査や修繕を受けるため定期的に入場します。"},{"tag":"へえ","hook":"楽天二軍のホーム、利府球場","t":"利府町中央公園野球場は「楽天イーグルス利府球場」で、2009年から東北楽天ゴールデンイーグルス二軍の本拠地の1つです。"},{"tag":"味","hook":"浜田漁港のカキ焼き処","t":"利府町はカキの養殖が盛んです。浜田漁港の「カキ焼き処」では、新鮮な蒸し牡蠣が堪能できます。"}]},"加美町":{"pref":"宮城県","cards":[{"tag":"へえ","hook":"田んぼの中のコンサートホール","t":"中新田バッハホールは、都会から離れた田舎町に建てられた音楽ホール。「田んぼの中のコンサートホール」として注目されました。","teaser":true},{"tag":"数字","hook":"約460.7km²に約21,666人が暮らす町","t":"面積は約460.7km²、人口は約21,666人（2021年）。1km²あたり約47人です。"},{"tag":"車窓","hook":"壁で残響を変えるホール","t":"バッハホールの大ホールは684席。様々な楽器や曲目に最適な残響時間が得られる残響可変壁があり、パイプオルガンがホールの象徴です。"},{"tag":"出身","hook":"加美町出身の有名人","t":"加美町出身には、漫画家のいがらしみきお、俳優の菅原大吉、衆議院議長の伊藤宗一郎がいます。"},{"tag":"ゆかり","hook":"「土左衛門」の語源になった力士","t":"江戸時代の大相撲の力士・成瀬川土左衛門は加美町の出身で、「土左衛門」という隠語の語源とされています。"},{"tag":"車窓","hook":"加美富士・薬萊山","t":"薬萊山は、加美町のほぼ中央にそびえる標高553mの独立峰で、「加美富士」とも呼ばれます。東北百名山の1つです。"},{"tag":"車窓","hook":"麓からずれて咲く桜並木","t":"薬萊山には、500mほど続くソメイヨシノの約300本の桜並木があり、標高差があるため麓から時期がずれて咲き始めます。"},{"tag":"歴史","hook":"再興された切込焼","t":"切込焼は伊万里焼の技術を導入した加美町の焼き物。明治10年代に一度廃窯になりましたが、1990年に復興が行われるようになりました。"},{"tag":"歴史","hook":"奈良時代の城柵・城生柵跡","t":"城生柵跡は奈良時代の城柵遺跡で、東西350メートル・南北370メートルの規模でした。どの官衙に当たるかは、諸説あります。"},{"tag":"ゆかり","hook":"漫画家いがらしみきおさん","t":"漫画家のいがらしみきおさんは、加美町の出身です。"},{"tag":"クイズ","q":"加美町の薬萊山で、東側登山道の大半を占める丸太階段は、何段に及ぶでしょう?","a":"700段に及びます。"},{"tag":"クイズ","q":"加美町の切込焼は、どこの焼き物の技術を導入したものでしょう?","a":"伊万里焼です。"}]},"北上市":{"pref":"岩手県","cards":[{"tag":"へえ","hook":"鬼剣舞の「鬼」には角がない","t":"北上の伝統芸能・鬼剣舞の面は五色です。鬼ではなく仏の化身なので、面には角がありません。","teaser":true},{"tag":"数字","hook":"約437.6km²に約92,348人が暮らす町","t":"面積は約437.6km²、人口は約92,348人（2021年）。1km²あたり約211人です。"},{"tag":"車窓","hook":"約2kmつづく桜並木の展勝地","t":"展勝地は北上川沿いの公園で、日本さくら名所100選。約1万本の桜があり、ソメイヨシノの並木が約2kmも続きます。"},{"tag":"出身","hook":"北上市出身の有名人","t":"北上市出身には、漫画家の三田紀房、プロレスラーの藤原喜明、プロボクサーの八重樫東がいます。"},{"tag":"歴史","hook":"夏油温泉は江戸の湯番付で東の大関","t":"夏油温泉は、江戸時代の寛永年間に京都で出された全国湯番付で、東の大関とされました。"},{"tag":"へえ","hook":"北上は「東北の十字路」","t":"北上市は、首都圏と2時間30分、日本海とは1時間30分で結ばれる「東北の十字路」です。"},{"tag":"味","hook":"赤い茎の二子さといも","t":"岩手県内では芋煮を「いものこ汁」と呼びます。北上の「二子さといも」は赤い茎の品種で、GI登録もされています。"},{"tag":"味","hook":"4つの食材の北上コロッケ","t":"北上コロッケは、北上牛・二子いものこ・しらゆりポーク・和賀のアスパラの4食材を使い、店ごとに独自のレシピで売られています。"},{"tag":"歴史","hook":"南部と伊達の藩境の地","t":"江戸時代の北上は、北が盛岡藩領、南が仙台藩領の藩境でした。町はなく、南部・伊達双方の交流が密だったといいます。"},{"tag":"ゆかり","hook":"平泉へ金を運んだ秀衡街道","t":"秀衡街道は、三代秀衡が鷲ノ巣鉱山から平泉まで金を運んだ街道と伝わり、北上市に残されています。"},{"tag":"歴史","hook":"北上のストーンサークル","t":"樺山遺跡は上下2段にわたり、下段にストーンサークル、上段には竪穴建物の集落がありました。"},{"tag":"クイズ","q":"北上の鬼剣舞のお面の色は、いくつある?","a":"五色"},{"tag":"クイズ","q":"岩手県内で、芋煮のことを何と呼ぶ?","a":"いものこ汁"}]},"北塩原村":{"pref":"福島県","cards":[{"tag":"へえ","hook":"「天にとどく磐の梯」","t":"磐梯山は「天にとどく磐（いわ）の梯（はしご）」と称され、元は「いわはしやま」と読みました。","teaser":true},{"tag":"数字","hook":"約234.1km²に約2,508人が暮らす町","t":"面積は約234.1km²、人口は約2,508人（2021年）。1km²あたり約11人です。"},{"tag":"車窓","hook":"会津富士は北から見ると別の顔","t":"磐梯山は、南の表磐梯からは一つのピークで「会津富士」と称されますが、北の裏磐梯からは山頂部が大きくえぐられた姿です。"},{"tag":"へえ","hook":"磐梯山の標高は測り直された","t":"磐梯山の標高は、三角点が侵食で消失したため2010年に計測し直され、1,818.61mから1,816.29mに改められました。"},{"tag":"車窓","hook":"日本で最も大きい火山性の堰止湖","t":"桧原湖は、1888年の磐梯山の山体崩壊で谷が埋まってできた堰止湖。日本で最も大きい火山性の堰止湖です。"},{"tag":"味","hook":"凍る湖でワカサギ釣り","t":"桧原湖は、冬は氷結した湖上でのワカサギ釣り、夏はバスフィッシングなどでにぎわっています。"},{"tag":"車窓","hook":"ニッコウキスゲの大群落","t":"雄国沼は標高1,090mにあり、6月末から7月初めには、沼の南の湿原でニッコウキスゲの大群落が咲き誇ります。"},{"tag":"へえ","hook":"猫魔ヶ岳の名は化け猫から?","t":"猫魔ヶ岳の名の由来には、化け猫が住み付いた伝説による説のほか、慧日寺の僧がネズミ退治のため猫王を山に祀った説があります。"},{"tag":"歴史","hook":"山の中の塩づくり","t":"北塩原村の大塩では、江戸時代以前から大塩裏磐梯温泉で塩が取られ、会津藩の御用塩になっていました。"},{"tag":"ゆかり","hook":"芸名の由来は村の「小椋」姓","t":"小椋佳さんは大学時代にこの地に滞在し、周辺住民の苗字の大半が「小椋」姓だったことが芸名の由来になりました。"},{"tag":"クイズ","q":"磐梯山の南側は「表磐梯」。北側は何と呼ばれる?","a":"裏磐梯"},{"tag":"クイズ","q":"雄国沼で6月末から7月初めに大群落をつくる花は?","a":"ニッコウキスゲ"}]},"北秋田市":{"pref":"秋田県","cards":[{"tag":"へえ","hook":"4つの環状列石が見つかった","t":"伊勢堂岱遺跡は、国内で唯一、4つの環状列石（ストーンサークル）が発見された縄文時代の遺跡です。"},{"tag":"数字","hook":"県内で面積2位","t":"面積は約1,152.8km²で、県内25市町村中2位の広さ。人口は約29,696人（2021年）です。"},{"tag":"へえ","hook":"牛の一枚皮の大太鼓","t":"綴子の大太鼓の一つは、牛の一枚皮で作られた世界一の和太鼓として、ギネス世界記録に認定されています。","teaser":true},{"tag":"出身","hook":"北秋田市出身の有名人","t":"北秋田市出身には、直木賞作家の渡辺喜恵子、作曲家の成田為三、元プロ野球選手の中嶋聡がいます。"},{"tag":"歴史","hook":"670年続いた阿仁鉱山","t":"阿仁鉱山は約670年操業を続け、1978年に閉山しました。旧外国人官舎（異人館）は国の重要文化財です。"},{"tag":"ゆかり","hook":"国の文化財になったマタギ道具","t":"阿仁マタギの狩猟用具は、2013年に国の重要有形民俗文化財に指定されました。"},{"tag":"へえ","hook":"上下2段の安の滝","t":"安の滝は標高約800mにあり、上段約60m、下段約30mの2段に分かれた滝です。"},{"tag":"へえ","hook":"33歳女性は黒留袖で参拝","t":"北秋田市では女性の33歳を大厄とし、2月1日に黒留袖と丸髷姿で参拝する習慣が残ります。"},{"tag":"へえ","hook":"雪の上で田植えを占う","t":"雪中田植えは、雪の上に稲わらや豆がらを植え、稲の倒れ方で作柄を占う小正月の伝統行事です。"},{"tag":"ゆかり","hook":"「浜辺の歌」の作曲者の故郷","t":"森吉地区は、唱歌「浜辺の歌」の作曲者・成田為三の出身地として知られます。"},{"tag":"車窓","hook":"三大樹氷の森吉山","t":"森吉山は、八甲田山・蔵王連峰と並ぶ、日本を代表する三大樹氷形成地とされます。"},{"tag":"味","hook":"バター餅のグランプリ","t":"2012年4月21日、北秋田市で第1回「BM-1グランプリ」（バター餅）が開かれました。"},{"tag":"クイズ","q":"北秋田市の伊勢堂岱遺跡で、国内で唯一発見された環状列石の数は？","a":"4つ"}]},"十和田市":{"pref":"青森県","cards":[{"tag":"へえ","hook":"湖の県境が決まるまで137年","t":"十和田湖の湖面の県境は1871年から未確定でした。2008年に青森県6：秋田県4で決まり、137年目の決着でした。","teaser":true},{"tag":"数字","hook":"県内で面積3位","t":"面積は約725.6km²で、県内40市町村中3位の広さ。人口は約60,063人（2021年）です。"},{"tag":"味","hook":"ニンニクの生産量は日本一","t":"十和田市は、ニンニクの市町村別の生産量が日本一です。"},{"tag":"出身","hook":"十和田市出身の有名人","t":"十和田市出身には、作家の川上健一、作家の高橋弘希、歌手の菅原都々子がいます。"},{"tag":"歴史","hook":"「無益の荒野」に川を通した人","t":"荒野だった三本木原を、新渡戸稲造の祖父・新渡戸傳らが開拓。1859年に人工河川の稲生川を完成させました。"},{"tag":"車窓","hook":"桜と赤松の「日本の道100選」","t":"桜と赤松並木が調和した道として、「日本の道100選」に選ばれています。"},{"tag":"歴史","hook":"あきたこまちの先祖は藤坂5号","t":"十和田で開発された冷害に強い稲「藤坂5号」の遺伝子は、ひとめぼれやあきたこまちにも受け継がれています。"},{"tag":"歴史","hook":"雪中行軍を導いた7人の猟師","t":"1902年の八甲田の雪中行軍で、行軍を完遂した弘前隊の道案内をしたのは、十和田市域の若い猟師7人でした。"},{"tag":"へえ","hook":"「十和田」は岩の多い湖の意味","t":"「十和田」は、アイヌ語で「岩の多い湖」を意味する「トーワタㇻ」が由来とされています。"},{"tag":"へえ","hook":"県内10市で唯一、駅がない市","t":"十和田観光電鉄線が2012年に廃線となって以降、青森県内10市で唯一、鉄道駅がない市です。"},{"tag":"クイズ","q":"十和田湖の水が唯一流れ出る川は何川？","a":"奥入瀬川"},{"tag":"車窓","hook":"高村光太郎最後の作品、乙女の像","t":"十和田湖畔の乙女の像は、彫刻家・高村光太郎の最後の作品です。"},{"tag":"歴史","hook":"スイスの建築家が設計した教会","t":"カトリック十和田教会は1932年に完成し、設計は上智大学1号館を手がけたスイスの建築家マックス・ヒンデルです。"},{"tag":"ゆかり","hook":"紅白第1回のトップバッター","t":"歌手の菅原都々子さんは、第1回NHK紅白歌合戦でトップバッターを務めました。"},{"tag":"ゆかり","hook":"SUPERCARのメンバーの故郷","t":"ロックバンドSUPERCARの中村弘二さん、いしわたり淳治さん、田沢公大さんは、十和田市の出身です。"}]},"南三陸町":{"pref":"宮城県","cards":[{"tag":"へえ","hook":"志津川にモアイがやって来た","t":"津波の被災地という縁でチリと交流を始めた志津川は、1991年、志津川湾に面する公園にモアイのレプリカを設置しました。","teaser":true},{"tag":"数字","hook":"約163.4km²に約10,896人が暮らす町","t":"面積は約163.4km²、人口は約10,896人（2021年）。1km²あたり約67人です。"},{"tag":"へえ","hook":"イースター島から届いたモアイ","t":"2013年5月、イースター島の石工が現地産の石材で加工したモアイ像が届き、「南三陸さんさん商店街」に置かれました。"},{"tag":"出身","hook":"南三陸町出身の有名人","t":"南三陸町出身には、作曲家の佐藤英敏、歌謡歌手のまきのめぐみがいます。"},{"tag":"へえ","hook":"歌津の化石は世界最古の魚竜","t":"1970年に歌津町で脊椎動物化石が発見され、研究の結果、1978年に世界最古の新種の魚竜、ウタツギョリュウとして公表されました。"},{"tag":"へえ","hook":"志津川湾はラムサール条約湿地","t":"2018年、志津川湾がラムサール条約湿地に登録されました。海藻藻場としては日本初の登録地です。"},{"tag":"車窓","hook":"5万本のツツジが咲く田束山","t":"田束山は標高512mで三陸海岸を一望でき、5月に開花する5万本のツツジでも名高い山です。"},{"tag":"歴史","hook":"田束山に七堂伽藍・七十余房","t":"平安時代末期、平泉の藤原秀衡が田束山に7堂伽藍・70余房を造営しました。田束山は古くから仏教徒の修行の場でした。"},{"tag":"歴史","hook":"生糸づくりの中心地だった入谷","t":"入谷地区は江戸時代以降、養蚕が盛んで、仙台藩における養蚕・生糸生産の中心地になりました。今、生糸生産はほとんど行われていません。"},{"tag":"味","hook":"ギンザケ養殖と志津川湾","t":"志津川湾では1975年にギンザケ養殖が始まり、全盛期には水揚げ高が35億円に上りました。"},{"tag":"車窓","hook":"堤防の通路で渡れる荒島","t":"志津川湾の荒島は面積0.02km2の小さな島で、本土側から堤防通路を通じて渡れます。島の頂に荒嶋神社があります。"},{"tag":"クイズ","q":"南三陸町の防災行政無線の時報に使われている、作曲家・佐藤英敏さんの代表曲は何でしょう?","a":"佐藤英敏さんの代表曲『残酷な天使のテーゼ』です。"},{"tag":"クイズ","q":"荒澤神社の境内にある杉の巨木「太郎坊杉」の推定樹齢は、何年くらいでしょう?","a":"約800年です。樹高は約42mで、宮城県指定天然記念物です。"}]},"南会津町":{"pref":"福島県","cards":[{"tag":"へえ","hook":"本州の町村で3番目の広さ","t":"南会津町は本州の町村では3番目に広く、福島県内ではいわき市に次ぐ2位です。その約92％が森林です。"},{"tag":"数字","hook":"県内で面積2位","t":"面積は約886.5km²で、県内53市町村中2位の広さ。人口は約14,204人（2021年）です。"},{"tag":"歴史","hook":"日本三大祇園祭の一つ","t":"会津田島祇園祭は7月22日から24日に行われ、日本三大祇園祭の一つとされています。1981年に国の重要無形民俗文化財に指定されました。","teaser":true},{"tag":"出身","hook":"南会津町出身の有名人","t":"南会津町出身には、衆議院議員の渡部恒三、俳優の青柳文太郎がいます。"},{"tag":"歴史","hook":"祭りを担う「お党屋」","t":"会津田島祇園祭は「お党屋」という組が運営し、現在は12組が1年ずつ当番を交替していきます。"},{"tag":"味","hook":"祇園祭は「蕗祭り」","t":"会津田島祇園祭は「蕗祭り」とも言われ、蕗料理が多い祭りです。蕗を「富貴」にかけて縁起を担ぐ意味もあります。"},{"tag":"歴史","hook":"村の舞台は国の文化財","t":"大桃の舞台は農村舞台で、隣の檜枝岐村の舞台とともに、1976年に国の重要有形民俗文化財に指定されました。"},{"tag":"へえ","hook":"約23,000点の民俗文化財","t":"奥会津博物館は、国指定の重要有形民俗文化財を含む約23,000点の郷土の民俗文化財を収蔵しています。"},{"tag":"車窓","hook":"3つの湿原の駒止湿原","t":"駒止湿原は大谷地、白樺谷地、水無谷地の3湿原でできた標高1,100mのブナ林地帯で、冬の積雪は3～4mに達します。"},{"tag":"へえ","hook":"冬は氷点下20℃付近まで","t":"南会津町の田島では、冬は近年でも-20℃付近の気温が観測されています。"},{"tag":"車窓","hook":"曲り家が残る前沢","t":"前沢は国の重要伝統的建造物群保存地区で、曲り家が数多く残る集落です。"},{"tag":"クイズ","q":"南会津町の会津田島祇園祭で、祭事を担当して運営する組を何という?","a":"お党屋"},{"tag":"クイズ","q":"南会津町の面積は、本州の町村で何番目に広い?","a":"3番目"}]},"南相馬市":{"pref":"福島県","cards":[{"tag":"へえ","hook":"関東大震災を世界に伝えた塔","t":"関東大震災を最初に世界に伝えた原町無線塔。当時アジアで最も高い約200mの塔で、今は1/10の記念塔が立ちます。","teaser":true},{"tag":"数字","hook":"約398.6km²に約52,619人が暮らす町","t":"面積は約398.6km²、人口は約52,619人（2021年）。1km²あたり約132人です。"},{"tag":"歴史","hook":"東京タワーが超えた無線塔","t":"1958年、建設途中の東京タワーが、原町無線塔の高さを上回りました。"},{"tag":"出身","hook":"南相馬市出身の有名人","t":"南相馬市出身には、評論家の埴谷雄高、映画監督の亀井文夫、陸上競技選手の今井正人がいます。"},{"tag":"歴史","hook":"当時は最北・最大の桜井古墳","t":"桜井古墳は、1955年の測量調査の当時としては、日本列島で最も北にあり東北地方最大の規模の前方後方墳でした。現在は東北地方第4位です。"},{"tag":"歴史","hook":"福島県初の本格的な史跡公園","t":"2003年、原町市は桜井古墳を、福島県初の本格的史跡公園として整備し、開園しました。"},{"tag":"車窓","hook":"北泉海岸は波が立つサーフスポット","t":"北泉海岸は、発電所の防波堤の反射波と直達波が合成されて大きな波が生まれる、サーフスポットとして知られます。"},{"tag":"車窓","hook":"馬と騎手が一般道を歩く","t":"相馬野馬追のための馬は200頭弱。直前には、朝方に馬と騎手が一般道を歩く光景も珍しくありません。"},{"tag":"へえ","hook":"『戦国自衛隊』に野馬追","t":"南相馬市(旧原町市)はSF映画『戦国自衛隊』の撮影に使われ、相馬野馬追が劇中で使用されました。"},{"tag":"へえ","hook":"小型恐竜の足跡化石","t":"鹿島区小山田では、体長2m程度の小型恐竜の足跡の化石が見つかっています。中生代ジュラ紀後期の地層です。"},{"tag":"歴史","hook":"地元で日本三大磨崖仏","t":"小高区の大悲山の石仏は、地元では大谷磨崖仏、臼杵磨崖仏とともに「日本三大磨崖仏」に数えられています。"},{"tag":"クイズ","q":"関東大震災を最初に世界に伝えた、原町区にあった塔は?","a":"原町無線塔"},{"tag":"クイズ","q":"南相馬市が撮影に使われ、相馬野馬追が劇中で使われたSF映画は?","a":"戦国自衛隊"}]},"南部町":{"pref":"青森県","cards":[{"tag":"歴史","hook":"南部藩発祥の地","t":"南部町は南部藩発祥の地で、町内には南部氏に縁の史跡が多数あります。","teaser":true},{"tag":"数字","hook":"約153.1km²に約16,449人が暮らす町","t":"面積は約153.1km²、人口は約16,449人（2021年）。1km²あたり約107人です。"},{"tag":"味","hook":"全国で唯一の町営青果市場","t":"リンゴやサクランボなどを育てる町で、全国で唯一の町営青果市場が運営されています。"},{"tag":"出身","hook":"南部町出身の有名人","t":"南部町出身には、歌手の坂本サトル、児童文学者の白木茂、競輪選手の坂本勉がいます。"},{"tag":"車窓","hook":"8000本の牡丹の園","t":"長谷ぼたん園には、3.3haの敷地に130種8000本の牡丹が植えられています。"},{"tag":"歴史","hook":"200年続いた南部氏の本城","t":"南部氏24代晴政の時代に家臣の放火で焼失するまでの200年間、南部氏の本城とされた城館があったと伝わります。"},{"tag":"ゆかり","hook":"推定樹齢1000年の爺杉","t":"法光寺の爺杉は推定樹齢1000年。法光寺開山の後、間もなく植えられたものとされています。"},{"tag":"クイズ","q":"南部町にある、全国で唯一とされる町営の市場は何の市場？","a":"青果市場"},{"tag":"クイズ","q":"長谷ぼたん園には何本の牡丹が植えられている？","a":"8000本"},{"tag":"へえ","hook":"町の花はぼたん、鳥はうぐいす","t":"南部町は、町の木を赤松、町の花をぼたん、町の鳥をうぐいすと定めています。"},{"tag":"ゆかり","hook":"ロス五輪の銅メダリスト","t":"競輪選手の坂本勉さんは、ロサンゼルスオリンピックの自転車競技で銅メダルを獲得しました。"},{"tag":"へえ","hook":"市外局番が二つある町","t":"南部町は旧町村で市外局番が異なり、旧南部町域は0179、旧名川町・旧福地村域は0178です。"},{"tag":"車窓","hook":"標高615mの名久井岳","t":"南部町の南部には標高615mの名久井岳があり、町の中心部を馬淵川が東西に流れています。"}]},"南陽市":{"pref":"山形県","cards":[{"tag":"へえ","hook":"世界最大の木造コンサートホール","t":"2015年に完成した南陽市文化会館は、世界最大の木造コンサートホールとしてギネスに認定されました。","teaser":true},{"tag":"数字","hook":"約160.5km²に約30,235人が暮らす町","t":"面積は約160.5km²、人口は約30,235人（2021年）。1km²あたり約188人です。"},{"tag":"歴史","hook":"市名は「南陽の菊水」から","t":"合併のとき宮内町と赤湯町が市名で譲らず、県知事が中国の故事「南陽の菊水」から命名しました。"},{"tag":"出身","hook":"南陽市出身の有名人","t":"南陽市出身には、刀工の水心子正秀、プロレスラーの井上京子、作家の深町秋生がいます。"},{"tag":"車窓","hook":"一本石の大鳥居","t":"烏帽子山八幡宮の鳥居(高さ10.75m、幅12.7m)は、継ぎ目のない一本石のものとしては日本一の大きさとされています。"},{"tag":"歴史","hook":"山形県最大の前方後円墳","t":"稲荷森古墳は4世紀末ごろの前方後円墳。山形県では最大、東北地方では第7位の規模です。"},{"tag":"へえ","hook":"置賜の王が築いた古墳?","t":"稲荷森古墳は、米沢・川西・南陽の3地域を統合した首長(置賜地方の王)が築いたと想定されています。"},{"tag":"ゆかり","hook":"夕鶴の里のまゆ蔵","t":"夕鶴の里資料館の建物は、養蚕で使われていた3階建てのまゆ蔵を利用しています。鶴の恩返しの民話を伝える施設です。"},{"tag":"ゆかり","hook":"鶴の恩返しを伝える珍蔵寺","t":"漆山地区の珍蔵寺は、民話「鶴の恩返し」を開山縁起として伝え、鶴巻田・羽付など鶴を思わせる地名も残ります。"},{"tag":"歴史","hook":"日本三熊野の一つ、熊野大社","t":"南陽市の熊野神社は、通称「熊野大社」。日本三熊野の一つとされています。"},{"tag":"ゆかり","hook":"『ないしょ話』の童謡詩人","t":"代表作『ないしょ話』で知られる童謡詩人・結城よしをは、南陽市の出身です。"},{"tag":"クイズ","q":"2016年、南陽市役所に日本初で設置された課は?","a":"ラーメン課"},{"tag":"クイズ","q":"岩部山の岩に彫られた磨崖仏の観音像は、何体?","a":"33体"}]},"双葉町":{"pref":"福島県","cards":[{"tag":"へえ","hook":"壁画は彩色壁画の北限","t":"1967年に発見された清戸迫横穴の壁画は、現在判明している彩色壁画のうちの北限にあたります。","teaser":true},{"tag":"車窓","hook":"7重の渦巻と馬と兜の人","t":"清戸迫横穴の壁画には、7重の渦巻文のほか、兜をかぶった人物や馬、イノシシ、鹿、犬が描かれています。"},{"tag":"出身","hook":"双葉町出身の有名人","t":"双葉町出身には、競輪選手の渡邉一成、プロキックボクサーの竹原太がいます。"},{"tag":"車窓","hook":"前田の大スギと稲荷大明神","t":"前田の大スギは樹高が約21メートル。722年に稲荷大明神を勧請した時、御神木として植えられたとされます。"},{"tag":"歴史","hook":"ダルマ市が12年ぶりに復活","t":"双葉町ダルマ市は、避難先のいわき市で町民有志が続け、2023年1月7日に12年ぶりに双葉町で復活しました。"},{"tag":"へえ","hook":"「双葉」は郡の合併から","t":"「双葉」の町名は、標葉郡と楢葉郡の合併にちなんだもの。町は旧標葉郡の区域にあります。"},{"tag":"歴史","hook":"新山城は1331年の築城","t":"1331年、標葉隆連が新山城を築城。合併前の新山町は、この城にちなんだ名称です。"},{"tag":"歴史","hook":"旅芸人に身を変えた逃走","t":"霊山が落城した際、追っ手を欺くため旅芸人の装束で踊りながら逃げた伝承が、宝財踊りの元とされます。"},{"tag":"ゆかり","hook":"田村麻呂が安置した観世音菩薩像","t":"長迫観音堂の十一面観世音菩薩像は、坂上田村麻呂が征伐後の807年に堂を建立し安置したものです。"},{"tag":"へえ","hook":"全国初のバスとタクシーの路線","t":"2003年、全国初のバスとタクシーの複合型生活路線である双葉町交通システムの運行が始まりました。"},{"tag":"クイズ","q":"清戸迫横穴の壁画は、現在判明している彩色壁画のうち何にあたる?","a":"北限"},{"tag":"クイズ","q":"「双葉」という町名は、標葉郡と何郡の合併にちなむ?","a":"楢葉郡"}]},"古殿町":{"pref":"福島県","cards":[{"tag":"味","hook":"味噌かんぷらの発祥地、古殿町","t":"味噌かんぷらの発祥は古殿町です。海軍の烹炊員だった鈴木勝美が考案したとの説があり、復員後に地元で振る舞ったことで少しずつ広まったとされます。","teaser":true},{"tag":"数字","hook":"約163.3km²に約4,600人が暮らす町","t":"面積は約163.3km²、人口は約4,600人（2021年）。1km²あたり約28人です。"},{"tag":"味","hook":"売り物にならない小さな芋から","t":"味噌かんぷらは、食糧難の頃に生まれたとされます。収穫時に出る売り物にならない小さな芋を使い、甘じょっぱく味付けしたものがおやつなどとして人気になりました。"},{"tag":"出身","hook":"古殿町出身の有名人","t":"古殿町出身には、総料理長の野崎洋光、自転車競技選手の窪木一茂がいます。"},{"tag":"へえ","hook":"「かんぷら」の語源はオランダ語？","t":"「かんぷら」は福島県の方言でジャガイモのことです。オランダ語でジャガイモを意味する言葉が変化したという説が有力とされています。"},{"tag":"へえ","hook":"樹齢400年の越代の桜","t":"越代の桜（こしだいのさくら）は、林野庁『森の巨人たち百選』に選ばれたヤマザクラの大木です。樹齢は400年で、福島県の天然記念物です。"},{"tag":"へえ","hook":"映画『フラガール』のロケ地","t":"2006年9月公開の映画『フラガール』の、常磐音楽舞踊学院のシーンは、古殿町公民館敷地内の旧古殿中学校寄宿舎でロケが行われました。"},{"tag":"歴史","hook":"800年前から続く流鏑馬・笠懸","t":"古殿八幡神社では、およそ800年前の鎌倉時代から伝わる笠懸・流鏑馬が、10月第2日曜日とその前日の例大祭で行われています。福島県重要無形民俗文化財です。"},{"tag":"車窓","hook":"最高峰は三株山","t":"古殿町は阿武隈山系の標高300m〜500mにあり、三株山が最高峰です。いわき市から太平洋に注ぐ鮫川が、町を東西に横断しています。"},{"tag":"ゆかり","hook":"南極観測隊に7度参加した地質学者","t":"古殿町出身の矢内桂三さんは地質学の研究者で、1967年から89年まで7度の南極観測隊に参加しました。"},{"tag":"ゆかり","hook":"古殿町出身の元大相撲力士","t":"古殿町出身の常錦利豪さんは、元大相撲力士で、最高位は西前頭筆頭です。"},{"tag":"クイズ","q":"福島県の方言で「かんぷら」とは何のこと？","a":"ジャガイモ"},{"tag":"クイズ","q":"古殿町にある『森の巨人たち百選』のヤマザクラ「越代の桜」の樹齢は何年？","a":"400年"}]},"只見町":{"pref":"福島県","cards":[{"tag":"へえ","hook":"セメントを積むと富士山311個分","t":"田子倉ダムの建設に使われたセメントは、袋に換算して積み重ねると、富士山の約311倍の高さになります。","teaser":true},{"tag":"数字","hook":"人より自然が多い町","t":"1km²あたり約5人。県内で下から2番目の人口密度です。"},{"tag":"歴史","hook":"ダム建設で人口が3万人を超えた","t":"田子倉ダムを建設中の昭和30年代前半、ダム建設作業員や飲食店関係の人々を含めた人口は3万人を超え、市制施行への機運が盛り上がりました。"},{"tag":"出身","hook":"只見町出身の有名人","t":"只見町出身には、落語家の登龍亭門助、NHKアナウンサーの三瓶宏志がいます。"},{"tag":"へえ","hook":"キャッチフレーズは「自然首都」","t":"只見町は福島県の最西端にある日本有数の豪雪地帯で、日本の原風景を残し、「自然首都」をキャッチフレーズにしています。"},{"tag":"車窓","hook":"国道252号は冬に閉鎖","t":"国道252号は例年11月下旬から4月下旬まで積雪で閉鎖され、只見町から新潟県魚沼市までは通行できなくなります。"},{"tag":"歴史","hook":"豪雨から復旧した只見線","t":"2011年7月の集中豪雨で営業休止となった只見線は、2022年10月1日に会津川口駅と只見駅の間が復旧し、全線で運転を再開しました。"},{"tag":"車窓","hook":"人力の転車台が残る只見駅","t":"只見線では昭和40年代後半頃まで蒸気機関車C11の貨物列車が走り、只見駅の構内には人力の転車台が残されています。"},{"tag":"へえ","hook":"ブナ林とユビソヤナギ","t":"只見ユネスコエコパークのブナの天然林400平方キロメートルと、50kmに及ぶユビソヤナギの河畔林は、国内最大規模とされます。"},{"tag":"歴史","hook":"福島県で最も古い農家住宅","t":"旧五十嵐家住宅は、1718年に建てられた農家の住宅です。福島県で最も古い農家住宅の建物で、国の重要文化財です。"},{"tag":"ゆかり","hook":"天童よしみさんと只見町","t":"演歌歌手の天童よしみさんは、母方の祖母が只見町の出身です。"},{"tag":"車窓","hook":"「会津のマッターホルン」蒲生岳","t":"蒲生岳は標高828mの尖った山で、登山家の田部井淳子さんが「会津のマッターホルン」と名付けました。"},{"tag":"クイズ","q":"只見町がキャッチフレーズにしている言葉は?","a":"自然首都"}]},"名取市":{"pref":"宮城県","cards":[{"tag":"へえ","hook":"東北地方では最大の古墳","t":"雷神山古墳の墳丘長は168メートルで東北地方最大。第2位以下は120メートル以下で、突出した規模です。"},{"tag":"数字","hook":"県内で人口4位","t":"人口は約79,250人（2021年）で、県内35市町村中4位。面積は約98.2km²です。"},{"tag":"へえ","hook":"「閖」は門の中に水の字","t":"閖上の「閖」は、1697年に仙台藩主・伊達綱村が「門の中に水と書いて閖上と呼ぶように」と言って出来た仙台藩専用の字です。","teaser":true},{"tag":"出身","hook":"名取市出身の有名人","t":"名取市出身には、映画監督の橋浦方人、元宝塚歌劇団花組トップ娘役の仙名彩世、コラムニストの犬山紙子がいます。"},{"tag":"歴史","hook":"熊野三山を引き写した名取","t":"平安時代、名取に熊野の本宮・新宮・那智社が別々に設けられ、名取熊野三山に。三社を合祀しない例は全国的にも珍しいそうです。"},{"tag":"ゆかり","hook":"実方中将の墓と西行・芭蕉","t":"実方中将の墓のそばには西行の歌碑と松尾芭蕉の句碑があります。実方は道祖神の前で落馬して亡くなったと伝わります。"},{"tag":"歴史","hook":"仙台空港のはじまりは陸軍の飛行場","t":"1940年、下増田村に日本陸軍の空港「名取飛行場」が開港しました。これがのちの仙台飛行場、仙台空港です。"},{"tag":"クイズ","q":"名取市の貞山堀(貞山運河)。名前は誰にちなんだもの?","a":"伊達政宗です。江戸時代初めに政宗が作った運河が始まりで、政宗の法名にちなんで命名されました。"},{"tag":"ゆかり","hook":"山形の上山市と同じ北緯38度線","t":"名取市は山形県の上山市と姉妹都市です。上山市は名取市と同じ北緯38度線上に位置します。"},{"tag":"味","hook":"ビール酵母のカステラ","t":"名取には、市内のビール工場のビール酵母を使ったカステラ「ビーテラ」があり、ビールの香りがするそうです。"},{"tag":"味","hook":"閖上の鰈を焼いて仙台へ","t":"その昔、閖上で採れた鰈に塩をふって焼き、日持ちのする状態にして仙台方面へ出荷したそうです。"},{"tag":"歴史","hook":"「北限のシラス」の閖上","t":"閖上産のシラスは「北限のシラス」として、2017年から「閖上しらす祭り」が開かれるようになりました。"}]},"喜多方市":{"pref":"福島県","cards":[{"tag":"味","hook":"人口37,000人にラーメン店120軒","t":"2006年の合併前の旧喜多方市では、人口37,000人あまりにラーメン店が120軒ほど。対人口比の店舗数は日本一でした。","teaser":true},{"tag":"数字","hook":"約554.6km²に約45,590人が暮らす町","t":"面積は約554.6km²、人口は約45,590人（2021年）。1km²あたり約82人です。"},{"tag":"車窓","hook":"市内に蔵が4,200","t":"喜多方市内には、市街地から農村部まで4,200の蔵があります。小田付、小荒井、菅原町を中心に数多くの蔵が分布します。"},{"tag":"出身","hook":"喜多方市出身の有名人","t":"喜多方市出身には、棋士の戸辺誠、歌手の佐藤隆紀、女優の野路ももこがいます。"},{"tag":"歴史","hook":"ラーメンの原点は屋台の支那そば","t":"喜多方ラーメンの原点は、1924年に「源来軒」創業者の潘欽星が、「支那そば」を打って屋台を引いたことです。"},{"tag":"ゆかり","hook":"蔵の写真500枚で「蔵のまち」に","t":"写真館の金田実が四季を通して蔵の写真を500枚ほど撮り、東京で写真展を開いたことで「蔵のまち喜多方」が浸透しました。"},{"tag":"へえ","hook":"2300万年前は深い海だった","t":"喜多方市高郷町は、2300万年前は深い海でした。入り江や汽水湖を経て、800万年前ころに陸地化したとみられます。"},{"tag":"車窓","hook":"樹齢600年の大イチョウ","t":"新宮熊野神社の長床前にある大イチョウは高さ30m、根本周り8.1m。樹齢は600年といわれ、喜多方市の天然記念物です。"},{"tag":"へえ","hook":"「日中走らぬ日中線」","t":"1938年に開業した日中線は、廃止時点で1日3往復の朝夕のみの運行で、「日中走らぬ日中線」とも揶揄されました。"},{"tag":"へえ","hook":"全国で唯一、十日間続く行事","t":"願成寺の廿五菩薩来迎行道は、十日十夜の間、1日6回念仏を唱える浄土宗の行事。全国で唯一、十日間実施しています。"},{"tag":"へえ","hook":"田植神事の北限","t":"毎年「半夏生」の日（7月2日頃）に行われる慶徳稲荷神社のお田植祭りは、日本の田植神事の北限です。"},{"tag":"クイズ","q":"喜多方市内にある蔵は、市街地から農村部まで合わせていくつ?","a":"4,200"},{"tag":"クイズ","q":"日中線の路線名は、どこの温泉に由来する?","a":"日中温泉"}]},"国見町":{"pref":"福島県","cards":[{"tag":"歴史","hook":"二重の堀と三重の土塁","t":"阿津賀志山防塁は、二重の堀と三重の土塁でできていることから「阿津賀志山二重堀」とも呼ばれます。","teaser":true},{"tag":"数字","hook":"約38.0km²に約8,643人が暮らす町","t":"面積は約38.0km²、人口は約8,643人（2021年）。1km²あたり約228人です。"},{"tag":"歴史","hook":"源頼朝に備えた約4キロの防塁","t":"防塁は阿津賀志山の中腹から阿武隈川まで約4キロメートル。源頼朝の軍勢に備えて奥州藤原氏が築いたと思われます。"},{"tag":"出身","hook":"国見町出身の有名人","t":"国見町出身には、フリーアナウンサーの阿部重典、東北電力会長の樋口康二郎がいます。"},{"tag":"車窓","hook":"高速・国道・線路が束に","t":"厚樫山のふもとを、東北自動車道、国道4号、東北本線が束になって通っています。"},{"tag":"車窓","hook":"厚樫山は桃の花の名所","t":"厚樫山の山頂には展望台があり、福島盆地を望めます。盆地一帯に桃の花が咲く春の景色は美しいといいます。"},{"tag":"車窓","hook":"道の駅の名は厚樫山から","t":"道の駅国見「あつかしの郷」は、厚樫山が名前の由来になった道の駅です。"},{"tag":"歴史","hook":"「蒙古の碑」とも呼ばれる板碑","t":"石母田供養石塔は「蒙古の碑」とも呼ばれる板碑。鎌倉時代の1308年、僧が先祖の追善供養に建てました。"},{"tag":"歴史","hook":"呉服店から興った奥山家","t":"奥山家住宅は、呉服店を興した奥山家の迎賓館として1921年に竣工した建物で、国の登録有形文化財です。"},{"tag":"へえ","hook":"かつて「国見町」だった町と交流","t":"国見町は、かつて同じ「国見町」だった長崎県と大分県の旧町(現在は市)と交流を続けています。"},{"tag":"クイズ","q":"阿津賀志山防塁は、何重の堀と何重の土塁でできている?","a":"二重の堀と三重の土塁"},{"tag":"クイズ","q":"阿津賀志山防塁があった国見町の山、厚樫山の標高はおよそ何m?","a":"289.4m"}]},"塙町":{"pref":"福島県","cards":[{"tag":"へえ","hook":"鹿が傷を治した湯が始まり","t":"湯岐温泉は、和泉屋旅館の創業者が、鹿が湯で傷を治しているのを発見したのが始まりといわれます。","teaser":true},{"tag":"数字","hook":"約211.4km²に約8,209人が暮らす町","t":"面積は約211.4km²、人口は約8,209人（2021年）。1km²あたり約39人です。"},{"tag":"ゆかり","hook":"藤田東湖も湯治に訪れた","t":"1853年、水戸藩の学者の藤田東湖が、湯岐温泉に湯治に訪れています。"},{"tag":"出身","hook":"塙町出身の有名人","t":"塙町出身には、競輪選手の佐藤慎太郎、シンガーソングライターのつのだ☆ひろがいます。"},{"tag":"車窓","hook":"標高500mの山中の温泉","t":"湯岐温泉は標高500mの山中にあり、2軒の旅館と、日帰り入浴施設を兼ねた「湯遊ランドはなわ」が点在します。"},{"tag":"歴史","hook":"名代官・寺西封元","t":"江戸時代の塙代官・寺西封元は、儒教の教えをやさしく説いた「寺西八ヶ条」を広め、人口減少に歯止めをかけて、周辺の藩からも注目されました。"},{"tag":"歴史","hook":"江戸時代は幕府の天領","t":"塙町は江戸時代、幕府の天領で、塙代官所が置かれていました。"},{"tag":"へえ","hook":"富永一朗の漫画廊が町に","t":"漫画家・富永一朗さんの作品を展示する施設は9か所あり、その一つ「富永一朗はなわ漫画廊」が塙町にあります。"},{"tag":"ゆかり","hook":"つのだ☆ひろさんの出身地","t":"シンガーソングライター、ドラマーのつのだ☆ひろさんは、塙町の出身です。"},{"tag":"車窓","hook":"久慈川が町の中央を流れる","t":"塙町は福島県の南端にあり、東に阿武隈山系、西に八溝山系があります。久慈川が町の中央を南北に流れます。"},{"tag":"クイズ","q":"塙町で、近年でも冬に観測される気温は、どれくらいの低さ？","a":"-15℃付近"}]},"塩竈市":{"pref":"宮城県","cards":[{"tag":"へえ","hook":"生マグロの水揚げは日本一","t":"塩竈市は水産業が盛んで、生マグロの水揚げと、蒲鉾など魚肉練り製品の生産が日本一です。"},{"tag":"数字","hook":"県内で小さい方の町","t":"面積は約17.4km²で、県内35市町村中34位。人口は約51,999人（2021年）です。"},{"tag":"味","hook":"寿司屋の多さも日本一","t":"1平方キロメートルあたりの寿司屋の店舗数も、人口あたりの寿司屋の店舗数も、日本一多い町です。","teaser":true},{"tag":"出身","hook":"塩竈市出身の有名人","t":"塩竈市出身には、声優の山寺宏一、将棋棋士の中原誠、ミュージシャンの大友康平がいます。"},{"tag":"歴史","hook":"市名は「釜」でなく「竈」の字","t":"「釜」はナベカマ、「竈」は釜を乗せるかまどの意味です。市は1941年から「塩竈」の表記に統一しました。"},{"tag":"ゆかり","hook":"日本人初の世界一周は浦戸の人","t":"寒風沢島の津太夫は49歳で嵐に遭い、アリューシャン列島に漂流。ロシア初の世界一周航海に同行し、日本人初の世界一周を果たしました。"},{"tag":"ゆかり","hook":"光源氏のモデルが写した景色","t":"光源氏のモデルとされる源融は、京都の自宅の庭園に、塩釜の風景（千賀の浦）を模した庭園を造ったことで有名です。"},{"tag":"へえ","hook":"国の天然記念物「塩竈桜」","t":"鹽竈神社の境内には、国の天然記念物に指定されている塩竈桜（シオガマザクラ）があります。"},{"tag":"歴史","hook":"全国の鹽竈神社の総本社","t":"鹽竈神社は、全国にある鹽竈（塩竈・塩釜など）神社の総本社です。陸奥国一宮でもあります。"},{"tag":"へえ","hook":"海の上を神輿が渡る船祭り","t":"塩竈みなと祭は、宮島の管絃祭、真鶴の貴船まつりとあわせて、日本三大船祭りとされています。"},{"tag":"クイズ","q":"塩竈市の「浦戸諸島」。「浦戸」と呼ばれたのは、どんな場所にあるから?","a":"松島浦の戸口にあることから、浦戸と呼ばれたそうです。"},{"tag":"ゆかり","hook":"『ガロ』の長井勝一の故郷","t":"長井勝一の故郷が塩竈市。1999年1月に市内に「長井勝一漫画美術館」が開かれ、経歴や『ガロ』の原稿などが展示されています。"}]},"外ヶ浜町":{"pref":"青森県","cards":[{"tag":"へえ","hook":"青函トンネルで北海道と隣り合う","t":"外ヶ浜町は、青函隧道内で北海道の福島町と隣接しています。上の津軽海峡中央部は公海です。","teaser":true},{"tag":"数字","hook":"約230.3km²に約5,233人が暮らす町","t":"面積は約230.3km²、人口は約5,233人（2021年）。1km²あたり約23人です。"},{"tag":"歴史","hook":"幻の町名は竜飛町","t":"新町名を決める際の住民アンケートでは「竜飛」が最多得票で竜飛町が提案されましたが、平舘村が難色を示し、「外ヶ浜」になりました。"},{"tag":"出身","hook":"外ヶ浜町出身の有名人","t":"外ヶ浜町出身には、プロボクサーのジャッカル丸山、女優の新高恵子、ノンフィクション作家の田澤拓也がいます。"},{"tag":"車窓","hook":"観光入込の筆頭は階段国道","t":"2013年の観光入込客数で、最も多かったのは階段国道でした。"},{"tag":"へえ","hook":"町の一部が飛地になっている","t":"外ヶ浜町は、旧三厩村域が飛地になっている町です。"},{"tag":"ゆかり","hook":"工藤静香さんの父の故郷","t":"歌手の工藤静香さんは東京都羽村市の出身ですが、父が蟹田町の出身で、幼少期を蟹田町で過ごしました。"},{"tag":"車窓","hook":"青函トンネル記念館駅がある","t":"青函トンネル竜飛斜坑線には、青函トンネル記念館駅と体験坑道駅があります。"},{"tag":"クイズ","q":"外ヶ浜町の新町名を決める際、住民アンケートで最多得票だった新町名の候補は？","a":"竜飛（竜飛町）"},{"tag":"数字","hook":"氷点下15.4℃を観測","t":"外ヶ浜町では、2014年1月18日に氷点下15.4℃を観測しました。"},{"tag":"歴史","hook":"北海道へ渡った三厩のフェリー","t":"三厩と北海道福島町を結んだ東日本フェリーは、1998年以降、運航を休止しています。"},{"tag":"ゆかり","hook":"初代チャンピオンのボクサー","t":"プロボクサーのジャッカル丸山は、ジュニアバンタム級の初代チャンピオンで、外ヶ浜町の出身です。"},{"tag":"ゆかり","hook":"松坂大輔さんの母の故郷","t":"プロ野球選手の松坂大輔さんは、母が旧蟹田町の出身です。"}]},"多賀城市":{"pref":"宮城県","cards":[{"tag":"歴史","hook":"国宝の石碑、多賀城碑","t":"多賀城碑は奈良時代の石碑で国宝。724年の創建と762年の改修を伝え、日本三古碑の1つとされます。"},{"tag":"数字","hook":"県内で小さい方の町","t":"面積は約19.7km²で、県内35市町村中33位。人口は約61,937人（2021年）です。"},{"tag":"へえ","hook":"国宝の碑にかけられた偽作の疑い","t":"多賀城碑には、江戸時代末期から「後世の偽作ではないか」との疑いがかけられました。現在は真作説が有力です。","teaser":true},{"tag":"出身","hook":"多賀城市出身の有名人","t":"多賀城市出身には、俳優の千葉雄大、ヴァイオリニストの郷古廉、プロレスラーの石森太二、プロ野球選手の平沢大河がいます。"},{"tag":"クイズ","q":"多賀城碑の上部に、大きく刻まれている漢字は何?","a":"「西」です。京の天皇へのアピールを示すとされ、碑自体も西に向かって立っています。"},{"tag":"歴史","hook":"多賀城は東の大宰府","t":"古代の多賀城は、東北地方の政治・軍事の中心でした。西の大宰府に対応する、東の政治都市として重要な位置にありました。"},{"tag":"歴史","hook":"780年に焼かれ、すぐ再建","t":"多賀城は宝亀11年（780年）、伊治呰麻呂の反乱で攻め寄せた軍勢に略奪放火されましたが、すぐに再建されました。"},{"tag":"歴史","hook":"百人一首にも登場する末の松山","t":"「末の松山」は古今和歌集に収録された後も多くの歌人に詠まれ、13世紀前半に成立した『小倉百人一首』にも歌が選ばれました。"},{"tag":"ゆかり","hook":"芭蕉も訪れた末の松山","t":"末の松山には、元禄2年（1689年）に松尾芭蕉らも訪れ、『奥の細道』に書き残しています。"},{"tag":"へえ","hook":"土器の籾跡が生んだ論文","t":"枡型囲貝塚で見つかった籾の痕跡のある土器から、山内清男の論文「石器時代にも稲あり」が生まれ、考古学史上著名です。"},{"tag":"歴史","hook":"縄文の海辺で塩作り","t":"縄文時代の晩期、松島湾に近い橋本囲貝塚などで、製塩土器を使った塩作りが盛んに行われました。"},{"tag":"車窓","hook":"中心部のない、ロードサイドの町","t":"多賀城市は国道45号沿いに発展した町です。ロードサイド店が多く、市の中心部が存在しないという特徴があります。"}]},"大仙市":{"pref":"秋田県","cards":[{"tag":"へえ","hook":"笑顔やアニメの花火の発祥","t":"笑顔やアニメキャラクター、ヒマワリの形の花火。こうした創作花火は、大曲の全国花火競技大会が発祥とされます。","teaser":true},{"tag":"数字","hook":"県内で人口3位","t":"人口は約76,164人（2021年）で、県内25市町村中3位。面積は約866.8km²です。"},{"tag":"クイズ","q":"大曲の花火の「大会提供花火」は、幅は何メートル？","a":"900メートル"},{"tag":"出身","hook":"大仙市出身の有名人","t":"大仙市出身には、漫画原作者の小池一夫、アニメーション美術監督の男鹿和雄、俳優の柳葉敏郎、芸人の鳥居みゆきがいます。"},{"tag":"へえ","hook":"山に反射する音が自慢","t":"大曲の花火の会場対岸には姫神山などがあり、山に反射する音と、観覧の邪魔になる光がないことも自慢の一つです。"},{"tag":"へえ","hook":"日本で唯一の昼花火の競技","t":"大曲の花火には、日本で唯一の昼花火の競技大会もあります。"},{"tag":"歴史","hook":"文献にない「幻の柵」","t":"払田柵跡は、文献資料にその名がないため「幻の柵」とも呼ばれる、古代の城柵遺跡です。国の史跡に指定されています。"},{"tag":"へえ","hook":"発見された柵木は下駄に","t":"1902年頃、水田から200本余の柵木が見つかりましたが、燃料にされたり、下駄に加工されて売られたりしたそうです。"},{"tag":"歴史","hook":"東北三大地主の池田家","t":"旧池田氏庭園の池田家は、山形県庄内地方の本間家、宮城県石巻市の齋藤家とともに「東北三大地主」と称されました。"},{"tag":"車窓","hook":"約4万2000平方メートルの庭園","t":"旧池田氏庭園は、明治時代末から大正時代につくられた日本庭園。面積は約4万2000平方メートルで、国の名勝です。"},{"tag":"へえ","hook":"国宝の鏡像がある水神社","t":"中仙地域の水神社は、国宝の線刻千手観音等鏡像を所有しています。"},{"tag":"ゆかり","hook":"黒澤明の父は大仙市の出身","t":"映画監督の黒澤明は、父が大仙市の出身です。"},{"tag":"クイズ","q":"「大仙市」の名前は、何と何の頭文字からできている？","a":"大曲市と仙北郡"}]},"大和町":{"pref":"宮城県","cards":[{"tag":"歴史","hook":"宿場を救った、1000両の利息","t":"吉岡宿の商人・穀田屋十三郎たち9名は、1000両を8年かけて捻出して仙台藩に貸し付け、毎年の利子で宿場を運営しました。"},{"tag":"数字","hook":"約225.5km²に約28,307人が暮らす町","t":"面積は約225.5km²、人口は約28,307人（2021年）。1km²あたり約126人です。"},{"tag":"歴史","hook":"毎年暮れに利息100両","t":"毎年暮れに利息の100両を手にできるようになった吉岡宿は、幕末に至るまで人口が減りませんでした。"},{"tag":"出身","hook":"大和町出身の有名人","t":"大和町出身には、彫刻家の佐藤忠良、歌人の原阿佐緒、演歌歌手の太田あかりがいます。"},{"tag":"へえ","hook":"吉岡宿が映画『殿、利息でござる!』に","t":"およそ240年ほど前の吉岡宿を舞台にした映画『殿、利息でござる!』が、2016年5月14日に公開されました。","teaser":true},{"tag":"ゆかり","hook":"今も吉岡で営業する「酒の穀田屋」","t":"穀田屋は「酒の穀田屋」として現在も吉岡で営業しています。2003年には有志が九品寺に国恩記顕彰碑を建立しました。"},{"tag":"へえ","hook":"七ツ森をつくったのは朝比奈三郎","t":"七ツ森の民話では、朝比奈三郎が土を運ぶことで七ツ森ができたとされています。伝承は色々ですが、この点は共通です。"},{"tag":"歴史","hook":"七ツ森の「7つ」は入れ替わった","t":"現在は笹倉山を含めて七ツ森と呼びますが、かつては笹倉山を含めず、たがら森を含めた7山を七ツ森としていました。"},{"tag":"クイズ","q":"七ツ森の山の名に共通して入る「倉」の字は、何を意味する?","a":"岩を意味しています。"},{"tag":"へえ","hook":"ブルーレットは大和町で作られる","t":"仙台北部中核工業団地の仙台小林製薬は、グループで東日本側最大の製造拠点です。ブルーレットシリーズはすべて、同社での製造です。"},{"tag":"へえ","hook":"マスコットは伝説の大男","t":"町の公式イメージキャラクター「アサヒナサブロー」は、伝説の大男「朝比奈三郎」がモチーフ。1993年に道路標識用のキャラクターとして誕生しました。"}]},"大崎市":{"pref":"宮城県","cards":[{"tag":"へえ","hook":"日本人技術者だけで造ったダム","t":"鳴子ダムは、外国の技術者を招かずに日本の技術者だけで建設した、日本初の100m級アーチ式コンクリートダムです。","teaser":true},{"tag":"数字","hook":"県内で面積2位","t":"面積は約796.8km²で、県内35市町村中2位の広さ。人口は約127,135人（2021年）です。"},{"tag":"歴史","hook":"日本最古の学問所建築・有備館","t":"岩出山の旧有備館は、茅葺きの書院造の建物が現存する、日本最古の学問所建築です。庭園とともに国の史跡および名勝に指定されています。"},{"tag":"歴史","hook":"東北最大級の前方後円墳","t":"古墳時代の4世紀前後に築造された古川の青塚古墳は、東北地方最大級の前方後円墳です。"},{"tag":"へえ","hook":"5つの温泉地域それぞれの泉質","t":"鳴子温泉郷は、鳴子、東鳴子、川渡、中山平、鬼首の5つの温泉地域に分けられ、それぞれ異なる泉質を持つ個性的なエリアです。"},{"tag":"車窓","hook":"断崖が4km続く鳴子峡","t":"鳴子峡は、深さ80-100mの断崖が長さ4kmにわたって続く峡谷です。狭いところは幅10mのV字谷、広いところは幅100mのU字谷です。"},{"tag":"へえ","hook":"東北で初の世界農業遺産","t":"2017年12月、大崎市を中心とする「大崎耕土」が、国連食糧農業機関が認定する世界農業遺産に、東北地方として初めて認定されました。"},{"tag":"味","hook":"銘柄米の発祥地","t":"大崎市は、ササニシキ、ひとめぼれ、ささ結（東北194号の大崎市独自ブランド名）など、銘柄米の発祥地です。"},{"tag":"車窓","hook":"マガンが飛来する化女沼と蕪栗沼","t":"ラムサール条約に登録されている化女沼や蕪栗沼は国際的に重要な湿地で、国内有数のマガンの飛来地です。"},{"tag":"歴史","hook":"市名の「大崎」は豪族の名","t":"市名の「大崎」は、中世に関東からこの一帯に移住した豪族・大崎氏に由来します。大崎氏は室町時代に奥州探題に任ぜられました。"},{"tag":"クイズ","q":"中山平や北宮沢で、ゲンジボタルと共生している国の天然記念物のホタルは何でしょう?","a":"ヘイケボタルです。ゲンジボタルと共生するのは全国的にも珍しい場所です。"},{"tag":"クイズ","q":"春の鳴子ダムで風物詩になっている放流は何でしょう?","a":"「すだれ放流」です。"}]},"大槌町":{"pref":"岩手県","cards":[{"tag":"へえ","hook":"昼のチャイムはひょうたん島","t":"大槌町の蓬莱島は人形劇『ひょっこりひょうたん島』のモデルといわれ、昼のチャイムにはそのテーマソングが使われています。","teaser":true},{"tag":"数字","hook":"約200.4km²に約10,719人が暮らす町","t":"面積は約200.4km²、人口は約10,719人（2021年）。1km²あたり約53人です。"},{"tag":"へえ","hook":"町が「吉里吉里国」で独立宣言","t":"1982年、大槌町は町おこしの一環で「吉里吉里国」として独立宣言をし、1980年代のミニ独立国ブームのきっかけになりました。"},{"tag":"出身","hook":"大槌町出身の有名人","t":"大槌町出身には、歌手の臼澤みさき、漫画家のこしたてつひろ、シンガーソングライターの佐藤ひろ美がいます。"},{"tag":"歴史","hook":"新巻鮭を考えた大槌城主","t":"安土桃山時代の末ごろ、大槌城主の大槌孫八郎政貞は、特産の鮭を新巻（塩鮭）に加工する方法を開発し、江戸と取引して富を得ました。"},{"tag":"へえ","hook":"湧水の町・大槌","t":"大槌町の町方地区には自噴井が約180か所あり、生活用水のほか、水産加工や酒造、豆腐作りにも活用されていました。"},{"tag":"へえ","hook":"岩手県内唯一のイトヨの生息地","t":"大槌川の湧水域に生息するイトヨは、岩手県内では唯一の生息地となっています。"},{"tag":"歴史","hook":"大虎退治に感動した虎舞","t":"大槌の虎舞は、豪商・前川善兵衛の船の乗組員が、浄瑠璃『国姓爺合戦』の大虎退治に感動し、故郷で舞にして奉納したと伝えられます。"},{"tag":"車窓","hook":"初夏に咲く新山つつじ","t":"新山高原は標高約1,000mの高原で、初夏にかけて町の花「新山つつじ」が咲きます。"},{"tag":"歴史","hook":"義経一行をしのぶ判官堂","t":"宮ノ口判官堂は、源義経一行が頼朝の追手から逃れたことを偲び、地元の人が建てたとされる祠です。"},{"tag":"ゆかり","hook":"民謡から歌手デビューの臼澤みさき","t":"大槌町出身の臼澤みさきさんは、民謡を歌う慰問活動がテレビに映ったのがきっかけで、2012年7月に歌手デビューしました。"},{"tag":"歴史","hook":"想いを伝える「風の電話」","t":"風の電話は、電話線のつながっていない黒電話とノートが置かれた電話ボックスで、来訪者は亡き人への思いを伝えられます。"},{"tag":"クイズ","q":"大槌町の蓬莱島は、NHKのどの人形劇のモデルといわれる？","a":"ひょっこりひょうたん島"}]},"大江町":{"pref":"山形県","cards":[{"tag":"へえ","hook":"小学生が見つけた海牛の化石","t":"1978年、渇水で露出した最上川の河床で、左沢小学校6年生の2人が約800万年前の海牛の化石を発見。「ヤマガタダイカイギュウ」と命名されました。","teaser":true},{"tag":"数字","hook":"約154.1km²に約7,522人が暮らす町","t":"面積は約154.1km²、人口は約7,522人（2021年）。1km²あたり約49人です。"},{"tag":"へえ","hook":"山形県最古の花火大会","t":"水郷おおえ夏まつり花火大会(8月15日)は、1922年にスタートした山形県最古の花火大会です。"},{"tag":"出身","hook":"大江町出身の有名人","t":"大江町出身には、女医の志田周子、シベール創業者の熊谷眞一、山形県知事の吉村美栄子がいます。"},{"tag":"車窓","hook":"樹齢約1,500年の神代カヤ","t":"神代カヤは根周り9m、高さ19m。樹齢約1,500年で、東北地方最古のカヤの木といわれます。"},{"tag":"車窓","hook":"山形県で最古といわれる大杉","t":"松保の大杉は根周り14.7m、高さ約26m。樹齢約1100年で、山形県で最古の杉の木といわれます。"},{"tag":"歴史","hook":"最上川舟運の中継地・大江","t":"大江町(左沢)は、元禄年間から大正初期にかけて、最上川舟運の中継地として大いに栄えました。"},{"tag":"へえ","hook":"「おしん」のロケ地・最上川","t":"NHK朝の連続TV小説「おしん」で、おしんがいかだで最上川を下り母親と別れる場面が、大江町で撮影されました。"},{"tag":"へえ","hook":"左沢の地名は「あちらの沢」?","t":"「左沢」の地名には諸説あり、最上川の右岸を「こちらの沢」、左岸を「あちらの沢」と呼んだことからとする説があります。"},{"tag":"ゆかり","hook":"宝蔵寺の招魂碑","t":"月布の宝蔵寺にある招魂碑は、元内閣総理大臣・佐藤榮作の御染筆によるものです。"},{"tag":"クイズ","q":"大江町の難読地名「左沢」。何と読む?","a":"あてらざわ"},{"tag":"クイズ","q":"大江町が作ったヤマガタダイカイギュウの復元模型の愛称は?","a":"プクちゃん"}]},"大河原町":{"pref":"宮城県","cards":[{"tag":"歴史","hook":"「一目千本桜」は寄贈から始まった","t":"白石川の治水工事が完了する半年前、大河原出身の高山開治郎がソメイヨシノ1000本余りを町に寄贈。これが「一目千本桜」の起源です。","teaser":true},{"tag":"数字","hook":"県内で小さい方の町","t":"面積は約25.0km²で、県内35市町村中32位。人口は約23,586人（2021年）です。"},{"tag":"車窓","hook":"桜の季節は列車も徐行運転","t":"白石川の両岸には約8km、約1200本の桜並木が続きます。桜の季節には、すぐ横を走るJR東北本線の列車も徐行運転をします。"},{"tag":"出身","hook":"大河原町出身の有名人","t":"大河原町出身には、詩人の尾形亀之助、歌人の佐藤佐太郎、漫画家の一條裕子がいます。"},{"tag":"へえ","hook":"「大河原」は「逢河原」から","t":"「大河原」は大きな川のある原ではなく、多くの河が合流する（逢う）原の意味。「逢河原」から変化しました。"},{"tag":"歴史","hook":"仙台の東八番丁も「大河原町」","t":"伊達政宗に従った大河原村出身の鉄砲組足軽が仙台城下の東八番丁に住んだため、東八番丁は「大河原町」の別称でも呼ばれました。"},{"tag":"車窓","hook":"白石川に渡り鳥がやってくる","t":"白石川には毎年、カモ類やコハクチョウ・オオハクチョウなど、多くの渡り鳥が飛来します。"},{"tag":"へえ","hook":"仙南で一番古い花火大会","t":"8月中旬ごろの「おおがわら夏まつり」の花火大会は、仙南地域では一番歴史が古いそうです。"},{"tag":"味","hook":"「和豚もちぶた」のブランド豚","t":"「一目千本桜」の名で日本酒、味噌、醤油などが売られ、「和豚もちぶた」というブランド豚も飼育されています。"},{"tag":"味","hook":"「萩の月」の菓匠三全の工場","t":"大河原町には、仙台銘菓「萩の月」で知られる菓匠三全の工場があります。"},{"tag":"歴史","hook":"奥州街道の宿場町、仙南の商都","t":"大河原町は奥州街道の宿場町として栄え、「仙南の商都」として発展してきました。"},{"tag":"へえ","hook":"神社の名は「白鷹社」から","t":"大高山神社の名称は、「白鷹社」が「大鷹社」に変化したものが元であるといいます。"},{"tag":"クイズ","q":"大河原町から柴田町にかけて白石川沿いに約8km続く、桜並木の名前は?","a":"一目千本桜"}]},"大潟村":{"pref":"秋田県","cards":[{"tag":"へえ","hook":"標高0mの山・大潟富士","t":"大潟富士は、富士山の1,000分の1の3.776mで、山頂の標高が0mになるよう造られた人工の山です。","teaser":true},{"tag":"数字","hook":"約170.1km²に約2,992人が暮らす町","t":"面積は約170.1km²、人口は約2,992人（2021年）。1km²あたり約18人です。"},{"tag":"へえ","hook":"北緯40度と東経140度の交点","t":"村の中央部に北緯40度と東経140度の交点があります。10の倍数の緯線と経線が交わる日本の陸地は、ここだけです。"},{"tag":"出身","hook":"大潟村出身の有名人","t":"大潟村出身には、タレントの鈴木絢音がいます。"},{"tag":"クイズ","q":"もとは湖だった大潟村。自然にできた川は何本ある？","a":"1本もない"},{"tag":"歴史","hook":"開村時は6世帯14人","t":"1964年10月1日に発足した大潟村は、発足時の人口がわずか6世帯14人の新しい村でした。"},{"tag":"クイズ","q":"大潟村の入植者が、いちばん多く来た県はどこ？","a":"秋田県（323名）"},{"tag":"歴史","hook":"合併も分割もない新設自治体","t":"大潟村は、既存自治体の合併や分割を伴わずに新設された自治体としては、日本最後です。"},{"tag":"へえ","hook":"琵琶湖に次ぐ第2位だった湖","t":"八郎潟はかつて面積220km2で、琵琶湖に次ぎ、日本の湖沼面積では第2位でした。大部分が干拓で陸地になり、大潟村になりました。"},{"tag":"へえ","hook":"龍になった八郎太郎の伝説","t":"八郎潟の名は、人から龍に姿を変えられた八郎太郎が、放浪の末に棲家に選んだという伝説が語り伝えられています。"},{"tag":"車窓","hook":"大潟富士の登頂証明書","t":"大潟富士の山頂には階段があり、登頂証明書は道の駅おおがた隣の大潟村干拓博物館で受け取れます。"},{"tag":"車窓","hook":"電池自動車専用の道路","t":"1994年、次世代電池自動車専用道路「ソーラースポーツライン」が開通し、ワールド・ソーラーカー・ラリーの第2回大会が開かれました。"},{"tag":"ゆかり","hook":"オランダの町と友好都市","t":"オランダのドロンテンとは1992年に友好都市宣言を調印。八郎潟開発がゾイデル海開発を元に行われた縁です。"}]},"大熊町":{"pref":"福島県","cards":[{"tag":"へえ","hook":"大熊は「苦麻の村」だった","t":"7世紀前半、大熊は「苦麻（くま）の村」と呼ばれました。助川が「道口岐閉」と呼ばれたのに対し、こちらは「道尻岐閉」でした。","teaser":true},{"tag":"数字","hook":"約78.7km²に約10,004人が暮らす町","t":"面積は約78.7km²、人口は約10,004人（2023年）。1km²あたり約127人です。"},{"tag":"歴史","hook":"国道6号沿いの熊川宿","t":"江戸時代の熊川は中村藩の領内で、浜街道（現在の国道6号）の宿場町が整備され、熊川宿として栄えました。"},{"tag":"へえ","hook":"大名の境は夜ノ森","t":"戦国時代の相馬氏と岩城氏の境、江戸時代の相馬中村藩と磐城平藩の境は、いまの大熊町と富岡町の境にある夜ノ森でした。"},{"tag":"歴史","hook":"国道288号は戦国のルート","t":"戦国時代末期、相馬氏は岩城氏とともに熊川から西進して田村氏の領土へ侵攻。このルートが今の国道288号です。"},{"tag":"歴史","hook":"水が足りない好条件の地","t":"熊川流域は福島県内で最も営農上好条件でしたが、水量の少なさが課題で、地元はダム建設を度々陳情しました。"},{"tag":"車窓","hook":"避難先で復活した稚児鹿舞","t":"毎年8月の熊川稚児鹿舞は、震災後も避難先で復活しました。"},{"tag":"歴史","hook":"脱炭素で東京都中央区とつながる","t":"大熊町は2024年1月18日、町内で作った太陽光発電の電力を東京都中央区へ送る脱炭素連携協定を結びました。"},{"tag":"クイズ","q":"大熊町は、1954年に大野村とどの村が合併してできた?","a":"熊町村"},{"tag":"クイズ","q":"戦国時代に相馬氏と岩城氏の境だった、大熊町と富岡町の境にある地名は?","a":"夜ノ森"}]},"大玉村":{"pref":"福島県","cards":[{"tag":"ゆかり","hook":"マチュピチュ村の初代村長","t":"大玉村出身の野内与吉は、ペルーのマチュピチュ村の初代村長を務めました。"},{"tag":"数字","hook":"約79.4km²に約8,932人が暮らす町","t":"面積は約79.4km²、人口は約8,932人（2021年）。1km²あたり約112人です。"},{"tag":"歴史","hook":"村初の本格的ホテルを開業","t":"野内与吉はマチュピチュ村で、村初の本格的ホテル「ホテル・ノウチ」を開業し、水力発電所も作って村の発展に尽力しました。"},{"tag":"へえ","hook":"マチュピチュ村の初の友好都市","t":"マチュピチュ村にとって初の友好都市は、野内与吉の故郷・大玉村。2015年に協定を結びました。","teaser":true},{"tag":"車窓","hook":"推定樹齢1000年超の馬場ザクラ","t":"大玉村の馬場ザクラは、国の天然記念物に指定されたエドヒガンの老桜。推定樹齢は1000年超といわれます。"},{"tag":"歴史","hook":"「駒止め桜」「義家桜」とも","t":"馬場ザクラの名は、源義家が軍馬を訓練した馬場がこの桜の周囲にあったという言い伝えから。「駒止め桜」とも呼ばれます。"},{"tag":"へえ","hook":"「日本で最も美しい村」連合に加盟","t":"大玉村は2014年10月に、「日本で最も美しい村」連合に加盟しました。"},{"tag":"歴史","hook":"村議選で電子投票","t":"大玉村は2003年8月の村議選で、電子投票を実施しました。6例目の実施でした。"},{"tag":"車窓","hook":"村内にICのない東北自動車道","t":"東北自動車道は大玉村の東部を貫通していますが、村内にインターチェンジはありません。最寄りは二本松ICと本宮ICです。"},{"tag":"クイズ","q":"大玉村出身の野内与吉が、初代村長を務めたペルーの村は?","a":"マチュピチュ村"},{"tag":"クイズ","q":"大玉村の馬場ザクラは、何という種類の桜?","a":"エドヒガン"}]},"大石田町":{"pref":"山形県","cards":[{"tag":"歴史","hook":"最上川で最大の物資の港","t":"大石田の南には最上川の三難所があり、大型の川舟は小型の舟に積み替える必要がありました。そのため大石田は、最上川の港としては最大の物資の集積地として栄えました。"},{"tag":"数字","hook":"約79.5km²に約6,417人が暮らす町","t":"面積は約79.5km²、人口は約6,417人（2021年）。1km²あたり約81人です。"},{"tag":"歴史","hook":"最上川の荷は仙台城下まで","t":"大石田河港の物資は、村山や置賜だけでなく奥羽山脈を越えて仙台藩にまで運ばれ、仙台城下に上方の物資をもたらしました。"},{"tag":"出身","hook":"大石田町出身の有名人","t":"大石田町出身には、日本画家の小松均、紀文食品創業者の保芦邦人がいます。"},{"tag":"へえ","hook":"幻の「野後駅」が見つかった？","t":"『延喜式』にある「野後駅」の場所は長年わかりませんでした。近年、町北部の駒籠楯跡で遺構が見つかり、野後駅だった可能性が高いとされています。","teaser":true},{"tag":"ゆかり","hook":"茂吉が暮らした聴禽書屋","t":"斎藤茂吉は疎開中の1946年1月から2年間、大石田に住みました。その建物「聴禽書屋」が、歴史民俗資料館の中にあります。"},{"tag":"ゆかり","hook":"最上川を描き続けた日本画家","t":"大石田町出身の日本画家・小松均は、1969年から故郷の最上川を題材にした作品を数多く残しました。"},{"tag":"クイズ","q":"大石田町の地名「次年子」は、何と読むでしょう?","a":"「じねんご」です。"},{"tag":"車窓","hook":"積雪3mを超える次年子","t":"大石田町の次年子は、根雪期間が例年12月から4月までの5か月。平均積雪量は3mから3.5mにもなる豪雪地帯です。"},{"tag":"ゆかり","hook":"紀文食品の創業者の出身地","t":"紀文食品の創業者・保芦邦人は、大石田町の出身です。"},{"tag":"へえ","hook":"北村山郡で唯一の町","t":"大石田町は、北村山郡に属する唯一の自治体です。"}]},"大船渡市":{"pref":"岩手県","cards":[{"tag":"ゆかり","hook":"モスバーガー創業者のふるさと","t":"モスバーガーを創業した実業家の櫻田慧さんは、大船渡市の出身です。","teaser":true},{"tag":"数字","hook":"約322.5km²に約34,558人が暮らす町","t":"面積は約322.5km²、人口は約34,558人（2021年）。1km²あたり約107人です。"},{"tag":"へえ","hook":"沖合いは世界三大漁場のひとつ","t":"大船渡市の沖合いは、世界三大漁場のひとつに数えられる北西太平洋海域（三陸漁場）です。"},{"tag":"出身","hook":"大船渡市出身の有名人","t":"大船渡市出身には、モスバーガー創業者の櫻田慧、演歌歌手の新沼謙治、ゲームクリエイターの鈴木裕がいます。"},{"tag":"歴史","hook":"スペイン人が名づけたサン・アンドレス湾","t":"1611年、スペインの探検家ビスカイノが大船渡湾の景観をたたえ、「サン・アンドレス湾」と命名しました。"},{"tag":"車窓","hook":"音と渚で選ばれた碁石海岸","t":"碁石海岸は、「日本の音風景100選」と「日本の渚百選」に選ばれています。"},{"tag":"へえ","hook":"方言を「ケセン語」と呼んだ医師","t":"気仙地方の方言を「ケセン語」と呼んだ医師の山浦玄嗣さんは、聖書のケセン語訳を出版しました。"},{"tag":"ゆかり","hook":"アワビ殻を下げたスネカ","t":"吉浜のスネカは、奇怪なお面に蓑をまとい、アワビの殻を腰に下げて各家をまわり、怠けている者への戒めを行います。"},{"tag":"歴史","hook":"気仙地方は仙台弁の地域","t":"気仙地方は江戸時代に仙台藩領で、1876年までは宮城県でした。そのため仙台弁が話される地域に含まれます。"},{"tag":"歴史","hook":"岩手で初の釜山航路","t":"2007年4月下旬、岩手県で初めて、大船渡港と韓国の釜山港を結ぶ外国貿易コンテナ船の定期航路が開設されました。"},{"tag":"ゆかり","hook":"大船渡高校の卒業生","t":"プロ野球選手の佐々木朗希さんは、岩手県立大船渡高等学校の卒業生です。"},{"tag":"クイズ","q":"大船渡湾を「サン・アンドレス湾」と名づけたスペインの探検家は?","a":"ビスカイノ"},{"tag":"クイズ","q":"大船渡市の沖合いは、世界三大漁場のひとつ。何漁場?","a":"三陸漁場"}]},"大蔵村":{"pref":"山形県","cards":[{"tag":"へえ","hook":"日本で最も美しい村連合の一員","t":"大蔵村は「日本で最も美しい村」連合に加盟しています。"},{"tag":"数字","hook":"人より自然が多い町","t":"1km²あたり約14人。県内で下から3番目の人口密度です。"},{"tag":"へえ","hook":"巨大雪だるま「おおくら君」","t":"3月中旬の歩くスキー大会を盛り上げるため、村の有志がギネスブックにも登録されたことのある巨大雪だるま「おおくら君」を作ります。"},{"tag":"へえ","hook":"日本最大規模の「歩くスキー」大会","t":"全日本ラングラウフ月山大蔵大会は日本最大規模の歩くスキーの大会で、毎年3000人以上が参加。順位ではなく完走が目的です。"},{"tag":"車窓","hook":"肘折以南は悪路の国道","t":"村を縦断する銅山川沿いの国道458号は、肘折以南が悪路の国道として知られています。"},{"tag":"歴史","hook":"最上川舟運の積出港・清水","t":"清水地区は最上川の舟運の積出港として大きな規模を誇り、中世には「清水城」が築かれ、最上地方南部の領国経営の中心でした。"},{"tag":"車窓","hook":"日本の棚田百選「四ヶ村」","t":"大蔵村の「四ヶ村」の棚田は、日本の棚田百選に選ばれています。"},{"tag":"へえ","hook":"積雪445cm、宿泊無料の「ドカ雪割」","t":"2018年2月、肘折温泉で積雪深445cmを観測し、最高記録を更新。「積雪最大記録を更新したら宿泊無料」の“ドカ雪割”が初めて適用されました。","teaser":true},{"tag":"歴史","hook":"肘が折れた地蔵が教えた湯","t":"肘折温泉は807年、行者の源翁が発見したとされます。伝承では、地蔵の化身の老僧が「ここの湯に浸かるとたちどころに治った」と教えたといいます。"},{"tag":"車窓","hook":"旅館に売店がない温泉街","t":"肘折温泉では、明治期の「肘折温泉村則」の名残りで、各旅館は売店を置かず、温泉街に商店が軒を連ねています。"},{"tag":"へえ","hook":"湯座神社の「火禾葉山」","t":"肘折温泉では江戸時代中期に大火が頻発。火防の御利益がある石碑には、村民有志の願いで「火禾葉山」と書いてもらったそうです。"},{"tag":"クイズ","q":"大蔵村が加盟している連合は、「日本で最も何な村」連合？","a":"美しい"}]},"大衡村":{"pref":"宮城県","cards":[{"tag":"クイズ","q":"宮城県でただ一つの「村」はどこ?","a":"大衡村です。県下唯一の村です。"},{"tag":"数字","hook":"約60.3km²に約5,739人が暮らす町","t":"面積は約60.3km²、人口は約5,739人（2021年）。1km²あたり約95人です。"},{"tag":"へえ","hook":"2021年まで郵便局がなかった村","t":"2021年3月8日に大衡村役場前郵便局が開局するまで、大衡村は全国で唯一、直営の郵便局がない自治体でした。","teaser":true},{"tag":"へえ","hook":"万葉集の草木を歩く森","t":"昭和万葉の森には『万葉集』の歌に詠まれる草木が植えられ、「ひさかたの道」など11通りの遊歩道があります。総延長は約5.6キロメートルです。"},{"tag":"歴史","hook":"植樹祭の松林に隣り合う森","t":"昭和万葉の森は、1955年の第6回全国植樹祭の会場だった松林に隣接する森林を含めて造成され、1989年に開園しました。"},{"tag":"車窓","hook":"船形山を見渡す高台の大衡城","t":"大衡城跡は国道4号と善川沿いの東側の高台にあり、船形山や大衡村・大和町の市街地を見渡せる絶景スポットだそうです。"},{"tag":"歴史","hook":"大衡城は1544年の築城","t":"大衡城は1544年（天文13年）、黒川氏開祖の次子で治部大輔の大衡宗氏が築きました。別名は越路舘です。"},{"tag":"へえ","hook":"宮城県で一番長いすべり台","t":"万葉クリエートパークには、宮城県で一番長いローラーすべり台（115m）があります。"},{"tag":"車窓","hook":"桜・キャンプ・紅葉の牛野ダム","t":"牛野ダムの湖畔は、桜の名所でもあります。春の桜、夏のキャンプ、秋の紅葉と3シーズン、行楽客が集まります。"},{"tag":"へえ","hook":"トヨタ自動車東日本の本社","t":"2012年7月に発足したトヨタ自動車東日本の本社は大衡村に置かれ、岩手県金ヶ崎町の工場とともに小型車の一大生産拠点を形成しています。"}]},"大郷町":{"pref":"宮城県","cards":[{"tag":"歴史","hook":"消えた湖、品井沼","t":"大郷町の水田地帯には、仙台藩領内で最大の湖だった品井沼が広がっていました。江戸時代からの干拓により消滅しました。","teaser":true},{"tag":"数字","hook":"約82.0km²に約7,760人が暮らす町","t":"面積は約82.0km²、人口は約7,760人（2021年）。1km²あたり約95人です。"},{"tag":"歴史","hook":"消えた湖のほとりの貝塚","t":"旧品井沼の北岸の丘陵にある大松沢貝塚では、ヤマトシジミを主体とする貝殻や縄文時代中期の土器などが発見されました。"},{"tag":"クイズ","q":"大郷町の諏訪古墳は、多賀城ができる何年ほど前の墓?","a":"300年ほど前の墓です。5世紀から6世紀に作られたとみられる円墳です。"},{"tag":"ゆかり","hook":"常長の墓所と伝わる場所","t":"支倉常長の墓所と伝わる場所は複数あり、そのひとつが大郷町です。「支倉常長メモリアルパーク」として整備されています。"},{"tag":"味","hook":"ベガルタ仙台と作った「大郷みそカレー」","t":"大郷みそカレーは、ベガルタ仙台と共同開発されました。「カレーは飲み物」イベントで販売され、小学校の給食にも出ます。"},{"tag":"味","hook":"町おこしのモロヘイヤ","t":"大郷町は、町おこしとしてモロヘイヤ栽培に力を入れています。モロヘイヤソフトクリームや、モロヘイヤ餃子、蕎麦などがあります。"},{"tag":"車窓","hook":"仙台地区で唯一の道の駅","t":"道の駅おおさと（大郷ふるさとプラザ）は、2026年現在、仙台地区で唯一の道の駅です。"},{"tag":"歴史","hook":"明治まで城で暮らした大松沢氏","t":"大松沢内地区には大窪城址公園があり、大松沢氏は明治まで大窪城で暮らしました。"}]},"大間町":{"pref":"青森県","cards":[{"tag":"車窓","hook":"灯台は海に浮かぶ島の上","t":"大間崎の『こゝ本州最北端の地』の碑の先、約600mの弁天島に大間埼灯台が建っています。"},{"tag":"数字","hook":"約52.1km²に約4,612人が暮らす町","t":"面積は約52.1km²、人口は約4,612人（2021年）。1km²あたり約89人です。"},{"tag":"へえ","hook":"北海道まで17.5km","t":"大間町から対岸の汐首岬までは17.5kmです。北海道が目の前の町です。"},{"tag":"出身","hook":"大間町出身の有名人","t":"大間町出身には、彫刻家の向井勝實、落語家の三遊亭大楽がいます。"},{"tag":"へえ","hook":"北海道のテレビが映る町","t":"函館市まで約20kmしか離れていないため、北海道のテレビ局の電波が受信できます。"},{"tag":"味","hook":"こいのぼりならぬマグロのぼり","t":"映画『魚影の群れ』で大間マグロの知名度が上がり、町では『マグロのぼり』も作っています。","teaser":true},{"tag":"車窓","hook":"断崖に咲くスカシユリ","t":"津鼻崎はスカシユリの群生地で、10m程の切り立った断崖が約1kmほど続きます。"},{"tag":"歴史","hook":"北前船の影響が濃い町","t":"南部藩でありながら、文化的にも血縁的にも北回り航路の影響が濃い町です。"},{"tag":"歴史","hook":"幻に終わった国鉄大間線","t":"大畑駅から風間浦村を経て奥戸駅まで結ぶ国鉄大間線の計画がありましたが、実現しませんでした。"},{"tag":"クイズ","q":"大間町にある、本州最北の温泉は？","a":"大間温泉"},{"tag":"クイズ","q":"大間町で『マグロ』の知名度を上げた映画は？","a":"魚影の群れ"},{"tag":"数字","hook":"町の7割以上が国有林","t":"大間町は、町域の70%以上を国有林が占め、宅地はすべて合わせても1%に満たない面積です。"},{"tag":"へえ","hook":"ドラマで本物のマグロを仕留めた","t":"2007年のドラマ「マグロ」のロケでは、渡哲也さんが220kgの本マグロを実際に仕留めるシーンもありました。"},{"tag":"ゆかり","hook":"アテネ五輪の銀メダリスト","t":"泉浩さんは大間町の出身で、アテネオリンピックの柔道男子90kg級で銀メダルを獲得しました。"},{"tag":"車窓","hook":"本州最北の海水浴場","t":"赤石海岸は、本州最北の海水浴場です。"}]},"大館市":{"pref":"秋田県","cards":[{"tag":"ゆかり","hook":"ハチ公の生まれた町","t":"大館は忠犬ハチ公の生誕地。大館駅前にはハチ公の銅像があります。","teaser":true},{"tag":"数字","hook":"県内で面積4位","t":"面積は約913.2km²で、県内25市町村中4位の広さ。人口は約68,593人（2021年）です。"},{"tag":"車窓","hook":"世界最長とされる木造ドーム","t":"大館樹海ドームは、長径の差し渡しが178mで世界最長とされる木造のドームです。"},{"tag":"出身","hook":"大館市出身の有名人","t":"大館市出身には、思想家の安藤昌益、シンガーソングライターの因幡晃、小説家の小林多喜二がいます。"},{"tag":"味","hook":"きりたんぽの始まり","t":"きりたんぽは、もとは冷や飯の利用法として工夫されたものだといわれています。"},{"tag":"へえ","hook":"大館の5大名産品","t":"大館の5大名産品は、秋田犬、比内鶏、きりたんぽ、大館曲げわっぱ、天然鮎です。"},{"tag":"歴史","hook":"曲げわっぱは内職から","t":"大館曲げわっぱは17世紀後半、佐竹西家が下級武士に内職として奨励し、産業になりました。"},{"tag":"へえ","hook":"国の天然記念物の比内鶏","t":"比内鶏は野鶏に近い貴重な存在で、1942年に国の天然記念物に指定されました。"},{"tag":"へえ","hook":"唯一の大型の日本犬","t":"秋田犬は、日本犬種のうち唯一の大型犬種で、国の天然記念物です。"},{"tag":"車窓","hook":"雲の上の高層湿原","t":"田代岳の9合目付近には、「雲上のアラスカ庭園」と呼ばれる高層湿原が広がっています。"},{"tag":"歴史","hook":"大文字まつりの始まり","t":"大文字まつりは、市長の発案で始まった旧盆の送り火行事で、8月16日に初めて開かれました。"},{"tag":"クイズ","q":"日本犬種のうち唯一の大型犬種で、大館が故郷の犬は？","a":"秋田犬"},{"tag":"クイズ","q":"大館市で作られる、おひつや弁当箱になる秋田杉の曲物は？","a":"大館曲げわっぱ"}]},"大鰐町":{"pref":"青森県","cards":[{"tag":"へえ","hook":"競技スキーの聖地","t":"阿闍羅山を擁する大鰐町は、オリンピック選手を多数輩出してきたスキーの町です。"},{"tag":"数字","hook":"約163.4km²に約8,442人が暮らす町","t":"面積は約163.4km²、人口は約8,442人（2021年）。1km²あたり約52人です。"},{"tag":"へえ","hook":"国際コースがあるスキー場","t":"大鰐温泉スキー場には、FIS（国際スキー連盟）公認の雨池国際コースがあります。"},{"tag":"出身","hook":"大鰐町出身の有名人","t":"大鰐町出身には、第56代横綱の2代目若乃花幹士、女優の横山結衣、俳人の増田手古奈がいます。"},{"tag":"歴史","hook":"2010年までに五輪代表9人","t":"大鰐町では、2010年までに9人の冬季オリンピック代表選手を輩出しています。"},{"tag":"車窓","hook":"駅名が違う共同使用駅","t":"大鰐温泉駅と大鰐駅は、JRと弘南鉄道で駅名が異なる共同使用駅です。","teaser":true},{"tag":"ゆかり","hook":"第56代横綱の出身地","t":"第56代横綱の2代目若乃花幹士は、大鰐町出身です。"},{"tag":"歴史","hook":"鎌倉時代の阿弥陀如来","t":"大円寺の木造阿弥陀如来坐像は鎌倉時代前半のもので、国の重要文化財です。"},{"tag":"歴史","hook":"全日本スキー選手権を初開催","t":"大鰐町は1925年に、全日本スキー選手権を初めて開催しました。"},{"tag":"クイズ","q":"1925年に大鰐町が初めて開催した、スキーの大会は？","a":"全日本スキー選手権"},{"tag":"クイズ","q":"大鰐町のスキーの聖地とされる山は？","a":"阿闍羅山"},{"tag":"数字","hook":"五輪に3大会連続で出場","t":"大鰐町出身の福田修子さんは、2002年から2010年まで、ソルトレークシティ、トリノ、バンクーバーの3大会に連続出場しました。"},{"tag":"ゆかり","hook":"元アイドルの横山結衣さん","t":"元AKB48 Team8の横山結衣さんは大鰐町の出身で、現在は「相馬結衣」として知られています。"}]},"天栄村":{"pref":"福島県","cards":[{"tag":"味","hook":"9年連続金賞のブランド米","t":"天栄村の米は、米・食味分析鑑定コンクール国際大会で、日本で唯一9年連続の金賞受賞を誇るブランド米とされています。","teaser":true},{"tag":"数字","hook":"約225.5km²に約5,120人が暮らす町","t":"面積は約225.5km²、人口は約5,120人（2021年）。1km²あたり約23人です。"},{"tag":"歴史","hook":"村名は村の中央の天栄山から","t":"天栄村の村名は、1955年の合併の際、村の中央にそびえる天栄山から採られました。"},{"tag":"出身","hook":"天栄村出身の有名人","t":"天栄村出身には、俳優の和田聰宏、演歌歌手の星ゆうこがいます。"},{"tag":"車窓","hook":"奥羽山脈の分水嶺をまたぐ村","t":"天栄村は奥羽山脈の分水嶺をはさみ、太平洋側と日本海側にまたがります。東西の距離は約36kmで、古くから会津と中通りを結ぶ交通の要衝でした。"},{"tag":"へえ","hook":"日本海側の水を太平洋側の白河へ","t":"阿賀野川水系の羽鳥ダムは、農業用水が不足しがちな阿武隈川流域の白河地域に農業用水を供給しています。アースダムとして全国屈指の規模を誇ります。"},{"tag":"へえ","hook":"イギリスの街並みを再現","t":"ブリティッシュヒルズは、約24万m2の敷地内に、看板や道路標識なども含めてイギリスの街並みが再現された語学研修施設です。"},{"tag":"歴史","hook":"開湯は969年の二岐温泉","t":"二岐温泉の開湯は969年といわれ、江戸時代には隠し湯として、一般の人の入浴が制限されていました。"},{"tag":"ゆかり","hook":"漫画『二岐渓谷』の舞台","t":"つげ義春の漫画『二岐渓谷』は、実在する湯小屋温泉をモデルに創作されました。昭和40年代の二岐温泉の佇まいがリアルに描かれています。"},{"tag":"ゆかり","hook":"作中の宿泊費は600円","t":"つげ義春が泊まった「湯小屋温泉」は、当時5軒あった宿のなかでも貧しそうな爺さん婆さんの宿でした。1967年当時の宿泊費は、作品では600円と記されています。"},{"tag":"ゆかり","hook":"つげ義春が絶賛した湯本温泉","t":"湯本温泉は、昭和40年代につげ義春が訪れ、これまでに来た最高の場所だと絶賛した温泉です。"},{"tag":"クイズ","q":"天栄村の村名は、村の中央にそびえる何という山から採られた？","a":"天栄山"},{"tag":"クイズ","q":"天栄村の羽鳥ダムは、どんな形式のダムとして全国屈指の規模を誇る？","a":"アースダム"}]},"天童市":{"pref":"山形県","cards":[{"tag":"へえ","hook":"馬の字が逆さの縁起物","t":"天童の縁起物「左馬」は、馬の字が左右反転した置物の駒です。「ウマ」を逆さに読むと「マウ」で、「舞う」がお祝い事に通じるためです。","teaser":true},{"tag":"数字","hook":"ぎゅっと人が集まる町","t":"1km²あたり約548人。県内35市町村中2位の人口密度です。"},{"tag":"へえ","hook":"市役所にある隕石のレプリカ","t":"天童市役所には、1910年頃に貫津地区の土中から見つかった約10kgの鉄隕石のレプリカが展示されています。実物は国立科学博物館にあります。"},{"tag":"出身","hook":"天童市出身の有名人","t":"天童市出身には、歌手の佐藤千夜子、アニメーション監督の平田敏夫、プロ野球選手の中野拓夢、お笑い芸人のともしげがいます。"},{"tag":"クイズ","q":"天童の人間将棋で、駒役のうち女性しか務められないのはどの駒?","a":"歩兵です。"},{"tag":"へえ","hook":"藤井聡太五冠に1万人超が応募","t":"2022年の天童人間将棋に藤井聡太五冠が出演したときは、観覧者600人の応募枠に1万人超の応募が殺到しました。"},{"tag":"歴史","hook":"江戸時代から続く駒づくり","t":"天童は江戸時代から将棋駒の生産で知られ、近年でも将棋駒の約95%がこの地域で生産されています。"},{"tag":"車窓","hook":"橋の名前が将棋の駒","t":"天童の市街地を流れる倉津川には、王将橋、金将橋、銀将橋など、将棋の駒の名前がついた橋がかかっています。"},{"tag":"歴史","hook":"天童の名前は天から来た？","t":"「天童」の地名は、天から童子が舞い降りたという伝説や、中世に北畠天童丸が住んでいたことに由来するとの説があります。"},{"tag":"ゆかり","hook":"人間将棋が結んだイタリアとの縁","t":"天童市は1989年、イタリアのマロスティカ市と姉妹都市になりました。天童の人間将棋と、マロスティカの人間チェスの縁によります。"},{"tag":"ゆかり","hook":"織田家が治めた天童藩","t":"江戸時代後期から約100年間、織田家が天童藩主を務めた縁で、天童市は織田信長ゆかりの市町が集う「織田信長サミット」に参加しています。"},{"tag":"へえ","hook":"出雲と並ぶ縁結びの観音","t":"天童の若松寺は、「西の出雲、東の若松」と、出雲大社と並び称される縁結びの観音として知られています。"},{"tag":"歴史","hook":"桜の名所は天童城の跡","t":"標高242.1mの舞鶴山一帯は天童城址で、桜の名所として知られます。毎年4月には人間将棋が開かれます。"}]},"奥州市":{"pref":"岩手県","cards":[{"tag":"へえ","hook":"日本最大級の胆沢扇状地","t":"胆沢川がつくった胆沢扇状地は、広さ約2万ヘクタールで日本最大級の扇状地です。"},{"tag":"数字","hook":"県内で面積3位","t":"面積は約993.3km²で、県内33市町村中3位の広さ。人口は約112,531人（2021年）です。"},{"tag":"ゆかり","hook":"水沢三偉人","t":"水沢からは多くの偉人が出ました。高野長英・後藤新平・斎藤実は「水沢三偉人」と呼ばれ、生家などの史跡が残ります。"},{"tag":"出身","hook":"奥州市出身の有名人","t":"奥州市出身には、蘭学者の高野長英、台湾総督府民政長官の後藤新平、海軍大将の斎藤実、プロ野球選手の大谷翔平がいます。"},{"tag":"歴史","hook":"水沢にあった緯度観測所","t":"1899年、水沢に緯度観測所が開設されました。初代所長の木村栄博士がZ項を発見し、国際極運動観測の中央局となりました。"},{"tag":"歴史","hook":"岩手で唯一の前方後円墳","t":"角塚古墳は、岩手県では唯一の前方後円墳で、日本の最北端に位置する前方後円墳です。"},{"tag":"歴史","hook":"東北初の寺院・黒石寺","t":"729年、行基が東北地方初の寺院として東光山薬師寺（後の黒石寺）を建てました。"},{"tag":"歴史","hook":"穀倉地帯をつくった用水堰","t":"後藤寿庵は私財を投じて胆沢川の水を引く用水堰づくりに尽力しました。遺志を継いだ人々が寿庵堰を完成させました。"},{"tag":"へえ","hook":"日本初の公民館","t":"水沢にある後藤伯記念公民館は、日本初の公民館とされています。","teaser":true},{"tag":"味","hook":"三大和牛のひとつ・前沢牛","t":"前沢牛は、奥州市前沢で肥育された黒毛和種のブランド牛肉で、三大和牛の一つとされています。"},{"tag":"味","hook":"南部鉄器は中国で人気","t":"伝統産業の南部鉄器は、中国の富裕層に人気で、中国市場からの発注が伸びています。"},{"tag":"クイズ","q":"水沢三偉人は、高野長英、斎藤実と、もう一人は誰?","a":"後藤新平"},{"tag":"クイズ","q":"胆沢扇状地の広さは、約何ヘクタール?","a":"約2万ヘクタール"}]},"女川町":{"pref":"宮城県","cards":[{"tag":"へえ","hook":"大漁を祈る「サンマdeサンバ」","t":"女川では、大漁を祈る「サンマdeサンバ」という曲が、地域の祭りや運動会で踊られることもあります。","teaser":true},{"tag":"数字","hook":"約65.3km²に約5,662人が暮らす町","t":"面積は約65.3km²、人口は約5,662人（2021年）。1km²あたり約87人です。"},{"tag":"歴史","hook":"「女川」の名の由来は小川","t":"伝承では、前九年の役のとき安倍貞任の一族の婦女子が避難した安野平から流れる小川を、「女川」と呼ぶようになったといいます。"},{"tag":"出身","hook":"女川町出身の有名人","t":"女川町出身には、歌手の中村雅俊、元・プロ野球選手の中条善伸がいます。"},{"tag":"味","hook":"ギンザケとサンマの港","t":"女川はギンザケの養殖やサンマの沿岸漁業が盛んで、ギンザケとサンマの水揚げ量は全国でも有数です。"},{"tag":"味","hook":"ワカメ養殖は女川湾から","t":"戦後、女川湾の小乗浜でワカメ養殖が成功し、これが宮城県内各地に広まりました。"},{"tag":"車窓","hook":"ウミネコの繁殖地・足島","t":"足島は女川港の南東約14キロメートルにある無人島。ウミネコとウトウの繁殖地として、国の天然記念物に指定されています。"},{"tag":"車窓","hook":"新しい女川駅が再開","t":"2015年3月、建築家・坂茂さん設計の新しい女川駅が再開し、JR石巻線が全線復旧。翌日には町営の「女川温泉ゆぽっぽ」が併設でオープンしました。"},{"tag":"ゆかり","hook":"ももクロが女川を訪れ続ける","t":"ももいろクローバーZは震災直後から定期的に女川町を訪問し、町のお祭りでライブを行って約7000人を集めたこともあります。"},{"tag":"ゆかり","hook":"中村雅俊さんは女川の出身","t":"歌手で俳優の中村雅俊さんは、女川町の出身です。"},{"tag":"へえ","hook":"住宅は高台、商業は低地に","t":"女川は復興にあたり、住宅は津波が遡上しにくい高台に、商業施設などを低地に整備する街づくりを進めています。"},{"tag":"クイズ","q":"女川町の公式マスコットの名前は何でしょう?","a":"「シーパルちゃん」です。"},{"tag":"クイズ","q":"2024年12月19日、女川の本土と結ばれた島の名前は何でしょう?","a":"出島です。出島大橋が開通しました。"}]},"宮古市":{"pref":"岩手県","cards":[{"tag":"へえ","hook":"最東端の岬は車道が通じない","t":"魹ヶ崎は、本州の東西南北の端のうち、唯一近くまで車道が通じていません。徒歩で片道約1時間かかります。","teaser":true},{"tag":"数字","hook":"県内で面積1位","t":"面積は約1,259.2km²で、県内33市町村中1位の広さ。人口は約50,855人（2021年）です。"},{"tag":"へえ","hook":"「最東端の市」の訪問証明書","t":"重茂地区の魹ヶ崎は本州の最東端。観光協会は「本州最東端訪問証明書」を発行し、「最東端の市」として観光に力を入れています。"},{"tag":"出身","hook":"宮古市出身の有名人","t":"宮古市出身には、演歌歌手の鳥取春陽、ジャズピアニストの本田竹広、キックボクサーの藤原敏男、漫画家の卯月妙子がいます。"},{"tag":"歴史","hook":"「極楽浄土のごとし」で浄土ヶ浜","t":"浄土ヶ浜の名は、天和年間に常安寺の霊鏡竜湖が「さながら極楽浄土のごとし」と感嘆したことから付いたとする説があります。"},{"tag":"ゆかり","hook":"賢治が詠んだ浄土ヶ浜","t":"宮沢賢治は1917年7月に浄土ヶ浜を訪れ、「うるはしの海のビロード昆布らは寂光のはまに敷かれひかりぬ」と詠みました。"},{"tag":"歴史","hook":"国道106号のもとになった街道","t":"僧・牧庵鞭牛が開いた宮古街道は総延長109km。現在の国道106号線は、この街道を元に整備されています。"},{"tag":"へえ","hook":"巨岩を熱して冷水で割る","t":"鞭牛は、道をふさぐ巨岩を薪で熱して冷水をかけ、もろくして壊すという画期的な方法で、難所を切り開きました。"},{"tag":"歴史","hook":"宮古湾で起きた海戦","t":"1869年、宮古湾で箱館戦争の海戦が起き、旧幕府軍が新政府軍の主力艦・甲鉄の奪取を図りましたが、失敗に終わりました。"},{"tag":"車窓","hook":"北上山地の最高峰・早池峰山","t":"早池峰山は標高1917mで、北上山地の最高峰です。日本百名山にも選ばれています。"},{"tag":"味","hook":"東京の目黒にサンマを無償提供","t":"宮古市は、東京都品川区の「目黒のさんま祭り」に、1999年以降、水揚げされたサンマ数千匹を無償提供しています。"},{"tag":"車窓","hook":"高さ250mのラサの煙突","t":"ラサの煙突は高さ160mで、標高90mの山上に建ち、合わせて250mの高さです。1939年の操業開始以来、宮古のランドマークです。"},{"tag":"クイズ","q":"宮古市の重茂半島にある魹ヶ崎は、本州のどの方角の端にある？","a":"東"}]},"富岡町":{"pref":"福島県","cards":[{"tag":"へえ","hook":"6,000株のツツジの駅","t":"夜ノ森駅は、ホームの両側1キロほどに約6,000株のツツジが植えられた駅。5月には線路両側の斜面が花で覆われました。","teaser":true},{"tag":"ゆかり","hook":"「夜ノ森」を「花の森」に","t":"半谷六郎が「夜ノ森」の暗いイメージを「花の森」にしたいと、1939年からツツジを移植したのが始まりです。"},{"tag":"出身","hook":"富岡町出身の有名人","t":"富岡町出身には、プロレスラーの宮本和志、空手家の三瓶啓二がいます。"},{"tag":"車窓","hook":"桜並木は2.2km続く","t":"夜ノ森公園には2.2km続く桜並木があり、2022年1月26日からは全域に立ち入れるようになりました。"},{"tag":"車窓","hook":"旧駅舎を再現した待合室","t":"夜ノ森駅は2020年3月14日に営業を再開。同年11月30日には、旧駅舎を再現した待合室が完成しました。"},{"tag":"へえ","hook":"福島県で最東端の駅","t":"富岡駅は、福島県で最東端に位置する、JR常磐線の駅です。"},{"tag":"歴史","hook":"かつて別の「双葉町」があった","t":"1950年、上岡村が町になり双葉町に。1955年に富岡町と合併して、改めて富岡町が発足しました。"},{"tag":"歴史","hook":"7〜8世紀の役所跡","t":"富岡町には、7〜8世紀頃の役所跡と見られる小浜代遺跡など、古くから人が暮らした痕跡が残っています。"},{"tag":"へえ","hook":"崖を切り崩した漁港","t":"富岡漁港は1993年に富岡川の河口に建設。それまで使った断崖を切り崩した小良ヶ浜漁港は、2000年に廃港になりました。"},{"tag":"へえ","hook":"姉妹都市の関係は今も","t":"富岡町は1983年にワントリーヒル市と姉妹都市に。市がオークランド市の一部になった後も、関係は続いています。"},{"tag":"クイズ","q":"夜ノ森駅は、何の花の名所として有名?","a":"ツツジ"},{"tag":"クイズ","q":"夜ノ森公園の桜並木は、何km続く?","a":"2.2km"}]},"富谷市":{"pref":"宮城県","cards":[{"tag":"へえ","hook":"45年で人口が10倍以上に","t":"富谷の人口は、1970年の4,912人から2015年の51,591人へ、45年間で10倍以上に増えました。"},{"tag":"数字","hook":"約49.2km²に約51,859人が暮らす町","t":"面積は約49.2km²、人口は約51,859人（2021年）。1km²あたり約1,054人です。"},{"tag":"歴史","hook":"「富谷」は「十宮」から?","t":"伝説では、大蛇の死骸を十ヶ所に葬って宮を建て、その10の神社を「十宮」と呼んでいたのが「富谷」と書かれるようになったといわれます。","teaser":true},{"tag":"出身","hook":"富谷市出身の有名人","t":"富谷市出身には、女優の久保史緒里、水泳選手の森田智己、演歌歌手の美里里美がいます。"},{"tag":"クイズ","q":"江戸時代、富谷宿は奥州街道の何番目の宿場だった?","a":"72番目の宿場です。元和4年（1618年）に設置されました。"},{"tag":"歴史","hook":"13戸から始まった宿場","t":"1618年に生まれた富谷宿は、当時の戸数がわずか13戸でした。しかし、2年ほどで戸数が倍くらいになりました。"},{"tag":"ゆかり","hook":"大名が泊まる本陣は内ヶ崎家","t":"参勤交代をする奥州諸藩や松前藩の大名の宿泊所となる本陣を務めたのは、内ヶ崎家でした。"},{"tag":"歴史","hook":"25業種75軒が並んだ富谷宿","t":"天保13年（1842年）には、宿屋、呉服屋、酒屋、醤油屋など25業種、75軒もの店が街道沿いに軒を連ねていました。"},{"tag":"味","hook":"宮城県最古の現役酒蔵","t":"寛文元年（1661年）、仙台藩主から酒の醸造を許され、現役の酒蔵としては宮城県最古の内ヶ崎酒造店が創業しました。"},{"tag":"歴史","hook":"山を掘り抜いた用水路","t":"1736年に千坂半左衛門が着工した志戸田用水隧道は、1786年頃に完工。160町歩（160ha）の水田が良田になりました。"},{"tag":"へえ","hook":"政宗の鷹を葬った「甕杉」","t":"伊達政宗が可愛がっていた鷹が鷹狩中に死んだため、甕に入れて丁重に埋葬したという言い伝えのある『甕杉』が残っています。"},{"tag":"味","hook":"ブルーベリーは1983年から","t":"1983年にブルーベリーの生産組合が組成され、のちに富谷市の特産物となりました。"},{"tag":"車窓","hook":"鉄道が通らない市","t":"現時点で、富谷市は宮城県内で鉄軌道線が通っていない唯一の市です。"}]},"寒河江市":{"pref":"山形県","cards":[{"tag":"へえ","hook":"昔は大きな湖があった？","t":"古代、寒河江市や中山町、天童市などにまたがる「藻が湖」という湖があり、そこに注ぐ寒川の入り江から「寒河江」の名が生まれたともいいます。","teaser":true},{"tag":"数字","hook":"約139.0km²に約39,854人が暮らす町","t":"面積は約139.0km²、人口は約39,854人（2021年）。1km²あたり約287人です。"},{"tag":"味","hook":"日本一さくらんぼの里","t":"寒河江市は「日本一さくらんぼの里さがえ」を標榜しています。市内には国内最大規模の観光さくらんぼ園があります。"},{"tag":"出身","hook":"寒河江市出身の有名人","t":"寒河江市出身には、写真家の鬼海弘雄、詩人の黒田喜夫、作家の中村晃がいます。"},{"tag":"歴史","hook":"724年に行基が開いた慈恩寺","t":"慈恩寺は、724年に行基が開いたと伝わる古いお寺です。2014年10月に国の史跡に指定されました。"},{"tag":"へえ","hook":"寒河江川で砂金が採れた","t":"寒河江川は古くから砂金が採れることで知られ、川に流れ出たものを拾い上げて採っていました。"},{"tag":"歴史","hook":"番付に載った西瓜とアラレ","t":"1864年の『最上名所名産名物番付』には、寒河江の皿沼の西瓜や白岩のアラレが特産品として載っていました。"},{"tag":"ゆかり","hook":"初代郡長は会津藩の家老だった","t":"1878年、寒河江に西村山郡役所が置かれました。初代郡長は、かつて会津藩の家老だった海老名季昌でした。"},{"tag":"へえ","hook":"塩の湧く地「平塩」","t":"平塩地区には塩泉が湧き出し、かつて製塩が行われました。それが「平塩」という地名の由来になったそうです。"},{"tag":"味","hook":"ラーメン店の多い山形県","t":"平成23年の調べで、山形県は人口10万人あたりのラーメン店が全国1位。寒河江市も71.28軒と多くなっています。"},{"tag":"車窓","hook":"最上川の出口にある町","t":"寒河江市は、最上川が五百川峡谷を抜けて山形盆地に注ぐ出口にあたります。最上川最大の支流・寒河江川も、市の東で合流します。"},{"tag":"クイズ","q":"寒河江市の長岡山一帯にある寒河江公園には、東北最大級の何の園がある?","a":"つつじ園です。"}]},"小国町":{"pref":"山形県","cards":[{"tag":"へえ","hook":"総落差270mの梅花皮の滝","t":"梅花皮の滝は7段の段瀑で、総落差270m。称名滝に続き、日本の滝で二番目に大きいとされます。","teaser":true},{"tag":"数字","hook":"県内で面積2位","t":"面積は約737.6km²で、県内35市町村中2位の広さ。人口は約6,939人（2021年）です。"},{"tag":"へえ","hook":"「幻の大滝」と呼ばれる理由","t":"梅花皮の滝は、車で行ける樽口峠の展望台からも8km離れ、安易に近づけないことから「幻の大滝」とされます。"},{"tag":"出身","hook":"小国町出身の有名人","t":"小国町出身には、翻訳家の岡部史、文学博士の新野直吉がいます。"},{"tag":"へえ","hook":"東北のマッターホルン","t":"祝瓶山は標高1500mに満たないものの、岩が発達した険しい山容から、俗に「東北のマッターホルン」と呼ばれます。"},{"tag":"車窓","hook":"「日本の赤壁」赤芝峡","t":"赤芝峡は、ヤマモミジが紅葉で真っ赤に色づき「日本の赤壁」と呼ばれたことが名前の由来です。"},{"tag":"歴史","hook":"へその緒のような飯豊山の県境","t":"飯豊山の「へその緒」にたとえられる特異な形の県境は、山岳信仰の山の帰属をめぐる明治時代の紛争を収めるため生まれました。"},{"tag":"ゆかり","hook":"平野歩夢が練習した横根スキー場","t":"小国町の横根スキー場は、平野歩夢選手が幼いころスノーボードの練習をした場所です。"},{"tag":"車窓","hook":"積雪2m超の豪雪地帯","t":"冬、小国町の中心部でも積雪が2mを超えることがあります。沼沢地区は日本有数の豪雪地帯として知られます。"},{"tag":"へえ","hook":"日本初の観光わらび園","t":"小国町には、日本初の観光わらび園を含め、町内23箇所に観光わらび園があります。"},{"tag":"ゆかり","hook":"イザベラ・バードの宿","t":"イザベラ・バードは明治11年7月12日、小国の市野々宿の岩船屋に宿泊したと伝わります。"},{"tag":"クイズ","q":"小国町の滝「梅花皮の滝」。何と読む?","a":"かいらぎのたき"},{"tag":"クイズ","q":"小国町は面積が山形県内で何番目に大きい?","a":"2番目"}]},"小坂町":{"pref":"秋田県","cards":[{"tag":"車窓","hook":"7つの滝で落ちる七滝","t":"七滝は、その名のとおり7つの滝で約60mを落ちる滝です。道の駅こさか七滝のすぐそばにあります。","teaser":true},{"tag":"数字","hook":"約201.7km²に約4,686人が暮らす町","t":"面積は約201.7km²、人口は約4,686人（2021年）。1km²あたり約23人です。"},{"tag":"歴史","hook":"東北唯一の廻り舞台だった","t":"1910年に開館した康楽館は、開館当初から廻り舞台を持ち、東北地方では唯一の廻り舞台でした。"},{"tag":"出身","hook":"小坂町出身の有名人","t":"小坂町出身には、画家の福田豊四郎、ミュージシャンの大間ジロー、陸上競技選手の佐々木吉蔵がいます。"},{"tag":"へえ","hook":"三大銅山と並んだ小坂","t":"小坂鉱山の銅は、別子銅山・足尾銅山と並び三大銅山と称される産出をほこりました。"},{"tag":"へえ","hook":"町の花アカシアの由来","t":"町の花アカシアは、1902年ごろ深刻化した鉱山の煙害への対策として、植林されたものです。"},{"tag":"ゆかり","hook":"町の魚はヒメマス","t":"小坂町の魚はヒメマス。和井内貞行が十和田湖で養殖した魚です。"},{"tag":"車窓","hook":"十和田湖の西側は小坂町","t":"十和田湖の西側は、2008年9月に十和田市との境界が決まり、正式に小坂町の町域となりました。"},{"tag":"歴史","hook":"1905年築の鉱山事務所","t":"小坂鉱山事務所は1905年に本部事務所として建てられ、1997年まで事務所として使われました。"},{"tag":"歴史","hook":"小坂鉱山を支えた小坂線","t":"小坂線は大館駅と小坂駅を結んだ鉄道。旅客営業は1994年まで行い、2009年に廃止されました。"},{"tag":"車窓","hook":"かおり風景100選の通り","t":"明治百年通りは、かおり風景100選に選定されている通りです。"},{"tag":"クイズ","q":"小坂町の花で、鉱山の煙害対策に植林された花は？","a":"アカシア"},{"tag":"クイズ","q":"七滝は、いくつの滝で約60mを落下している？","a":"7つ"}]},"小野町":{"pref":"福島県","cards":[{"tag":"ゆかり","hook":"小野小町の生誕伝説の町","t":"小野町は、小野小町の生誕伝説がある町として知られています。"},{"tag":"数字","hook":"約125.2km²に約9,453人が暮らす町","t":"面積は約125.2km²、人口は約9,453人（2021年）。1km²あたり約76人です。"},{"tag":"ゆかり","hook":"比古姫が小野小町という伝承","t":"小野小町の生誕地には各地に伝承があります。福島県小野町とする説では、小野篁と愛子（珍敷御前）の娘の比古姫が小野小町だという伝承があります。"},{"tag":"出身","hook":"小野町出身の有名人","t":"小野町出身には、農学者の小泉武夫、作詞家の丘灯至夫、落語家の林家彦三がいます。"},{"tag":"へえ","hook":"リカちゃんの工場と展示施設","t":"小野町のリカちゃんキャッスルは、リカちゃんの工場および展示施設です。1967年発売の初代以来の歴代製品を展示するミュージアムがあります。","teaser":true},{"tag":"へえ","hook":"リカちゃんの製造がガラス越しに見える","t":"リカちゃんキャッスルでは、リカちゃんやジェニーを生産している様子を、ガラス張りの通路から見学できます。"},{"tag":"歴史","hook":"並んで立つ翁スギと媼スギ","t":"諏訪神社の翁スギ・媼スギは、ほぼ同じ大きさ・高さで相対して並ぶ珍しい巨木です。樹齢は1,100年とも1,200年とも伝わります。"},{"tag":"車窓","hook":"注連縄で結ばれた2本のスギ","t":"諏訪神社の石段の両側に、翁スギ媼スギが相対して立ち、2つの主幹同士は互いを結ぶように注連縄が渡されています。"},{"tag":"車窓","hook":"四方を700m超の山に囲まれた町","t":"小野町は四方を標高700メートルを越える山々に囲まれ、町の中央を夏井川が流れ、これに沿って平坦地が広がっています。"},{"tag":"へえ","hook":"町内3カ所が福島緑の百景","t":"阿武隈高原中部県立自然公園に囲まれた小野町では、高柴山、矢大臣山を含む町内3カ所が「福島緑の百景」に選ばれています。"},{"tag":"へえ","hook":"508体の羅漢像が並ぶ満福寺","t":"満福寺の境内には、1985年に小野町制30周年記念として羅漢像を奉納した「昭和羅漢」があります。2021年時点で508体が奉納されています。"},{"tag":"クイズ","q":"諏訪神社の国の天然記念物のスギ2株は、「翁（じじ）」と何と呼ばれる？","a":"媼（ばば）"},{"tag":"クイズ","q":"リカちゃんキャッスルに展示されている初代リカちゃんは、何年に発売された？","a":"1967年"}]},"尾花沢市":{"pref":"山形県","cards":[{"tag":"へえ","hook":"花笠音頭は堤づくりの唄から","t":"徳良湖は、約230haの水田のため1920年に築堤が完成した貯水池。この工事で歌われた土搗唄が、花笠音頭の起源といわれます。","teaser":true},{"tag":"数字","hook":"約372.5km²に約14,760人が暮らす町","t":"面積は約372.5km²、人口は約14,760人（2021年）。1km²あたり約40人です。"},{"tag":"歴史","hook":"人口20万〜30万を数えた銀山","t":"延沢銀山は、江戸時代の寛永期（1624年〜1644年）には人口20万から30万を数えるほど栄えたといいます。"},{"tag":"出身","hook":"尾花沢市出身の有名人","t":"尾花沢市出身には、元大相撲力士の琴ノ若晴將、スキー選手の太田渉子、脚本家の阿部美佳がいます。"},{"tag":"車窓","hook":"大正ロマンの木造旅館街","t":"銀山温泉では、大正から昭和初期の三層・四層の木造旅館が銀山川の両岸に並びます。石畳の歩道にはガス灯が並んでいます。"},{"tag":"へえ","hook":"銀山温泉は車を手前に停める","t":"銀山温泉の通路は、人がすれ違うのがやっとの幅です。観光客の車は手前の大正ろまん館に駐車し、そこからバスで温泉街に入ります。"},{"tag":"ゆかり","hook":"芭蕉が10日滞在した町","t":"松尾芭蕉は『おくのほそ道』の旅で尾花沢の鈴木清風を訪ね、10日滞在しました。資料館にその資料が展示されています。"},{"tag":"歴史","hook":"お告げで見つかった鉱石","t":"1456年、旅の儀賀市郎左衛門が白山神社でお告げにより鉱石を発見したと伝わります。翌1457年、30人の鉱夫で採掘が始まりました。"},{"tag":"クイズ","q":"銀山温泉が1983年のヒットで全国的に認知されるきっかけになったドラマは何でしょう?","a":"「おしん」です。"},{"tag":"へえ","hook":"年に948cm降る雪","t":"尾花沢市は全域が特別豪雪地帯です。年平均降雪量は948cmにもなります。"},{"tag":"ゆかり","hook":"久保史緒里さんの母の故郷","t":"女優の久保史緒里さんは、母親が尾花沢市の出身で、幼いころから何度も母親の実家や徳良湖を訪れていました。"},{"tag":"ゆかり","hook":"なでしこ元監督は尾花沢の出身","t":"なでしこジャパンの元監督・佐々木則夫さんは、尾花沢市の出身です。"}]},"山元町":{"pref":"宮城県","cards":[{"tag":"ゆかり","hook":"赤痢菌の発見者は山元町の名誉町民","t":"赤痢菌の発見者・志賀潔は山元町の名誉町民で、晩年を磯浜の貴洋翠荘で過ごしました。","teaser":true},{"tag":"数字","hook":"約64.6km²に約11,736人が暮らす町","t":"面積は約64.6km²、人口は約11,736人（2021年）。1km²あたり約182人です。"},{"tag":"歴史","hook":"蓑首城とも呼ばれた坂元城","t":"坂元城は蓑首城（みのくびじょう）とも呼ばれた山元町の城で、1572年に坂本俊久によって築かれました。町指定史跡です。"},{"tag":"出身","hook":"山元町出身の有名人","t":"山元町出身には、元プロ野球選手の小坂誠、声優の佐藤拓也、イラストレーターのニコ・ニコルソンがいます。"},{"tag":"歴史","hook":"戊辰戦争の本営が坂元城に","t":"1868年の戊辰戦争では、駒ヶ嶺城の陥落後、奥羽越列藩同盟の浜通り方面軍の本営が坂元城に置かれました。"},{"tag":"歴史","hook":"幕末まで坂元を治めた大條氏","t":"1616年に大條宗綱が坂元城に入ってから幕末まで、大條氏が坂元本郷ほか4,000石を領しました。"},{"tag":"車窓","hook":"山・台地・低地と東へ移る地形","t":"山元町は、西部が山地、中部が台地（畑・果樹園）、太平洋に面した東部が低地（水田）と、西から東へ地形が移り変わります。"},{"tag":"歴史","hook":"町域が史料に現れた最初の記述","t":"『和名類聚抄』に「曰理（わたり）郡に四郷を置く、すなわち坂本・菱沼・亘理・望多」とあります。これが山元町域が史料上に現れた最初です。"},{"tag":"歴史","hook":"藤原経清ゆかりの中嶋館","t":"1056年ごろ、藤原経清が亘理郡に入り、町内の中嶋館が経清かその一族の居館と推定されています。"},{"tag":"味","hook":"ホッキ祭りとふれあい市","t":"山元町には、2月下旬のホッキ祭り、6月上旬のストロベリーラインふれあい市、11月下旬のアップルラインふれあい市があります。"},{"tag":"クイズ","q":"2016年12月10日、町内の区間が運転を再開した山元町の鉄道は?","a":"常磐線"}]},"山形市":{"pref":"山形県","cards":[{"tag":"へえ","hook":"山寺にあった巨大な滑り台","t":"1950年、立石寺（山寺）に参拝客が楽しく麓まで下れるよう、全長約300mの滑り台が造られました。1970年代の初めに廃止されたといわれます。","teaser":true},{"tag":"数字","hook":"県内で人口1位","t":"人口は約247,234人（2021年）で、県内35市町村中1位。面積は約381.3km²です。"},{"tag":"クイズ","q":"1933年7月25日に山形市で観測され、74年間も日本の最高気温記録だった気温は何℃?","a":"40.8℃です。2007年に熊谷市と多治見市が40.9℃を観測するまで、74年間記録でした。"},{"tag":"出身","hook":"山形市出身の有名人","t":"山形市出身には、女優の橋本マナミ、教育者の無着成恭、劇作家の渡辺えりがいます。"},{"tag":"味","hook":"芋煮会でギネス達成","t":"2018年の芋煮会フェスティバルでは3万食の芋煮を調理。「8時間以内で提供されるスープの数」のギネスに挑戦し、4時間半で1万2695食を振る舞って達成しました。"},{"tag":"車窓","hook":"県庁所在地どうしが隣り合う","t":"山形市は、宮城県の県庁所在地・仙台市と隣り合っています。都道府県庁所在地の自治体が隣接しているのは、ここを含めて4例だけです。"},{"tag":"歴史","hook":"山形と上山は同じ「山方」から","t":"山形の地名は、蔵王連峰の麓にあることから「山方」と呼ばれたことに由来します。その南部は「上山方」と呼ばれ、後に「上山」となりました。"},{"tag":"歴史","hook":"村の名前が「蔵王」に変わった","t":"1950年、「新日本観光地百選」で蔵王連峰が山岳部門1位に。地元は熱狂し、堀田村は蔵王村に、高湯は蔵王温泉に名前を改めました。"},{"tag":"クイズ","q":"山寺（立石寺）の石段は、全部で何段あるでしょう?","a":"1015段です。"},{"tag":"歴史","hook":"奥羽地方で最大の城だった","t":"山形城は、三の丸の内側が235haあり、日本国内では5番目の広さで、奥羽地方では最大の城でした。"},{"tag":"ゆかり","hook":"芭蕉が山寺で詠んだ蝉の句","t":"松尾芭蕉は1689年に立石寺を訪れ、「閑さや 巖にしみ入る 蝉の声」を詠みました。参道に句碑と「せみ塚」があります。"},{"tag":"へえ","hook":"全国三大植木市の薬師祭","t":"5月8日から10日、薬師寺周辺で行われる薬師祭植木市は、全国三大植木市に数えられています。"},{"tag":"車窓","hook":"鬼滅の刃の列車と同じ型のSL","t":"山形駅から徒歩約10分の第二公園には、映画「鬼滅の刃」無限列車編の車両と同型のSL機関車（8620形）のオブジェがあります。"}]},"山田町":{"pref":"岩手県","cards":[{"tag":"へえ","hook":"体長17.6mのマッコウクジラ","t":"鯨と海の科学館は、1987年に三陸沖で捕獲された体長17.6メートルの巨大なマッコウクジラを後世に伝えるため、1992年に開館しました。","teaser":true},{"tag":"数字","hook":"約262.8km²に約14,388人が暮らす町","t":"面積は約262.8km²、人口は約14,388人（2021年）。1km²あたり約55人です。"},{"tag":"へえ","hook":"オランダ船にちなむ島の名","t":"山田町のオランダ島は、江戸時代の1643年にオランダ船が漂着したことから、1964年にその名が付けられました。"},{"tag":"出身","hook":"山田町出身の有名人","t":"山田町出身には、第70代内閣総理大臣の鈴木善幸、本草学者の阿部将翁がいます。"},{"tag":"車窓","hook":"東北唯一の無人島の海水浴場","t":"オランダ島は「東北唯一の無人島の海水浴場」です。夏の海水浴シーズンには、山田町と島を結ぶ連絡船が運航されます。"},{"tag":"歴史","hook":"オランダ船の乗組員が上陸","t":"1643年、オランダ船ブレスケンス号の乗組員が盛岡藩領に上陸して捕縛される事件があり、完全に解決したのは1650年でした。"},{"tag":"ゆかり","hook":"山田町出身の総理大臣","t":"1980年7月17日、山田町出身の鈴木善幸が第70代内閣総理大臣に就任しました。"},{"tag":"へえ","hook":"祭りには帰ってくる町","t":"山田町の人は、「正月やお盆には帰らなくても祭りには帰ってくる」と言われるほどの祭り好きです。"},{"tag":"歴史","hook":"海に入る暴れ神輿","t":"山田祭の大杉神社の神輿は、暴れ神輿として知られ、海に入る「おしおごり」を行います。"},{"tag":"味","hook":"カキ・ホタテ・ホヤの湾","t":"山田湾では、カキ・ホタテ・ホヤなどの養殖が盛んです。"},{"tag":"車窓","hook":"湾を一望できる山田八幡宮","t":"山田八幡宮は、山田湾を一望できる高台にある神社です。"},{"tag":"クイズ","q":"山田町の鯨と海の科学館が後世に伝えようとしている、1987年に三陸沖で捕獲された巨大な鯨は何クジラ？","a":"マッコウクジラ"}]},"山辺町":{"pref":"山形県","cards":[{"tag":"クイズ","q":"山辺町にある安国寺は、どの国で唯一現存している安国寺でしょう?","a":"出羽国です。"},{"tag":"数字","hook":"県内で小さい方の町","t":"面積は約61.5km²で、県内35市町村中32位。人口は約13,610人（2021年）です。"},{"tag":"味","hook":"かき氷に酢醤油をかける","t":"山辺町の名物「すだまり氷」は、シロップをかけたかき氷に、さらに酢醤油をかけて食べます。","teaser":true},{"tag":"出身","hook":"山辺町出身の有名人","t":"山辺町出身には、ミュージシャンの峯田和伸、小説家の後藤紀一、細菌学者の遠山椿吉がいます。"},{"tag":"ゆかり","hook":"茶席で英仏を和解させた人","t":"山辺町生まれの安達峰一郎は、1929年の対独賠償会議で、意見が対立した仏国と英国の調停を頼まれ、日本流の茶席に招いて和解させたといいます。"},{"tag":"歴史","hook":"四重の濠を持つ山野辺城","t":"山辺城址は1600年の慶長出羽合戦の戦場のひとつ。翌1601年に山野辺義忠が入城して四重の濠を持つ城を再建しましたが、1622年に廃棄されました。"},{"tag":"へえ","hook":"急いで掘った全国でも珍しい堀","t":"畑谷城の空堀は、上杉軍侵攻の知らせを受けて急いで掘られたもの。西方の三重堀は全国でも珍しいものです。"},{"tag":"車窓","hook":"日本の棚田百選・大蕨の棚田","t":"大蕨の棚田は、1999年に「日本の棚田百選」に選ばれました。山形県内ではほかに、朝日町の平の棚田と大蔵村の四ヶ村の棚田が選ばれています。"},{"tag":"へえ","hook":"どこでも乗り降りできる町営バス","t":"山辺町の町営バスには、畑谷農村婦人停留所から北垣停留所までの間、停留所によらず乗り降りできるフリーストップ区間があります。"},{"tag":"歴史","hook":"豪商の蔵が資料館に","t":"山辺町ふるさと資料館は、江戸時代の豪商の蔵を利用した資料館。町の歴史資料や、繊維・染物・織物関係の資料が展示されています。"},{"tag":"ゆかり","hook":"芥川賞作家は山辺の出身","t":"小説家の後藤紀一は山辺町の出身で、芥川賞を受賞しています。"}]},"岩手町":{"pref":"岩手県","cards":[{"tag":"へえ","hook":"弓の先で突いたら泉が湧いた","t":"正覚院の「弓弭の泉」は北上川の源として知られ、源義家が弓の弓弭で岩を突くと清水が湧いたと伝えられます。","teaser":true},{"tag":"数字","hook":"約360.5km²に約12,078人が暮らす町","t":"面積は約360.5km²、人口は約12,078人（2021年）。1km²あたり約34人です。"},{"tag":"歴史","hook":"樹齢1200年の大杉","t":"正覚院の本堂脇にある大杉は、樹齢1200年といわれています。"},{"tag":"出身","hook":"岩手町出身の有名人","t":"岩手町出身には、南部藩中興の祖の南部信直、女子プロゴルファーの日蔭温子、バレリーナの岩井優花がいます。"},{"tag":"車窓","hook":"町の中央を北上川が南下","t":"岩手町は、東に北上山地、西に奥羽山脈があり、北上川が町の中央を南へ流れています。"},{"tag":"へえ","hook":"ホッケーと彫刻の町","t":"岩手町は、人工芝ホッケー競技場を中心にしたホッケーと、石神の丘美術館を中心にした彫刻に力を入れています。"},{"tag":"ゆかり","hook":"南部藩中興の祖は町の出身","t":"南部藩中興の祖といわれる南部信直は、岩手町の出身です。"},{"tag":"ゆかり","hook":"川口で育った女優・園井恵子","t":"女優・園井恵子は、岩手町川口（当時は川口村）に移り、しばらくそこで育ちました。"},{"tag":"歴史","hook":"新幹線でいわて沼宮内駅に","t":"2002年12月、東北新幹線の八戸延伸で新幹線の駅になったのに伴い、沼宮内駅は「いわて沼宮内駅」に改称されました。"},{"tag":"クイズ","q":"正覚院の本堂右奥にある、北上川の源として古くから知られている泉の名前は？","a":"弓弭（ゆはず）の泉"}]},"岩沼市":{"pref":"宮城県","cards":[{"tag":"へえ","hook":"竹駒神社は日本三大稲荷の一つ","t":"竹駒神社（竹駒稲荷）は日本三大稲荷の一つとされることがあり、正月三が日は東北地方で一、二を争うほどの初詣客が訪れます。","teaser":true},{"tag":"数字","hook":"約60.5km²に約44,340人が暮らす町","t":"面積は約60.5km²、人口は約44,340人（2021年）。1km²あたり約733人です。"},{"tag":"へえ","hook":"「竹駒」は阿武隈川が由来","t":"「竹駒」という社名は、岩沼の旧称「武隈」が転じたもので、もともとは市内を流れる阿武隈川に由来します。"},{"tag":"出身","hook":"岩沼市出身の有名人","t":"岩沼市出身には、シンガーソングライターの大友裕子、プロレスラーの田口隆祐、バレーボール選手の菅山かおるがいます。"},{"tag":"歴史","hook":"岩沼の名は城の前の沼から","t":"1361年までに泉田氏が岩沼城に入りました。岩沼の呼称は、この城の前面に広がる沼から採られたと伝えられています。"},{"tag":"クイズ","q":"岩沼は、かつて何と呼ばれていた?","a":"「武隈」です。阿武隈川の河口に位置し、のちに奥州街道と陸前浜街道の分岐点の宿場として栄えました。"},{"tag":"歴史","hook":"東山道と東海道が出会う地点","t":"岩沼は、東山道と東海道の双方が初めて合流する地点。2本の幹線が分岐・合流する交通の要衝に、竹駒神社が創建されました。"},{"tag":"歴史","hook":"刀匠が奉納した金蛇","t":"刀匠・小鍛冶宗近が名水を求めて三色吉を訪れ、宝刀を鍛えられた感謝に金蛇を奉納した。それが金蛇水神社の社名の縁起です。"},{"tag":"へえ","hook":"金運円満の神さま、金蛇水神社","t":"金蛇水神社は、古来から商売繁盛・金運円満の神として特に崇敬されています。海上安全や大漁祈願の神としても信仰されています。"},{"tag":"歴史","hook":"竹駒神社は842年の創建と伝わる","t":"社伝では、承和9年（842年）6月に小野篁が陸奥国司として赴任した際、伏見稲荷を勧請して竹駒神社を創建したと伝えます。"},{"tag":"へえ","hook":"アニメ『バクテン!!』の舞台","t":"岩沼市は、アニメ『バクテン!!』の舞台となっています。"},{"tag":"車窓","hook":"市の東に仙台空港","t":"岩沼市の東部、名取市との境に、仙台空港があります。"}]},"岩泉町":{"pref":"岩手県","cards":[{"tag":"へえ","hook":"本州でいちばん広い町","t":"岩泉町は、本州で最も面積の広い町です。"},{"tag":"数字","hook":"県内で面積4位","t":"面積は約992.4km²で、県内33市町村中4位の広さ。人口は約8,549人（2021年）です。"},{"tag":"へえ","hook":"東京の都区部より広い町域","t":"岩泉町の面積は992.36km²。東京都区部の627.57km²をはるかに上回ります。"},{"tag":"出身","hook":"岩泉町出身の有名人","t":"岩泉町出身には、女優の三浦リカ、漫画家のみながわまさゆき、詩人の北畑光男がいます。"},{"tag":"へえ","hook":"水道水にも龍泉洞の水","t":"岩泉町は「水の郷百選」に選ばれ、日本三大鍾乳洞の龍泉洞の水は、町の中心地区の水道水にも使われています。"},{"tag":"へえ","hook":"地底湖が全部で7つ","t":"龍泉洞には、水深98メートルの第3地底湖など、全部で7つの地底湖があります。"},{"tag":"へえ","hook":"日本一長い洞窟・安家洞","t":"安家洞は日本一長い洞窟で、総延長は約23,702mあります。"},{"tag":"歴史","hook":"日本で初めて確定した恐竜化石","t":"1978年、岩泉町の茂師で、日本で初めてとなる恐竜化石「モシリュウ」が発見されました。","teaser":true},{"tag":"へえ","hook":"町名がついた小惑星","t":"小惑星「(4712) Iwaizumi」は、岩泉町にちなんで命名されました。"},{"tag":"味","hook":"短角牛とマツタケの町","t":"岩泉町は肉牛の日本短角種の産地で、マツタケも全国有数の産地です。「岩泉ヨーグルト」「龍泉洞の水」も名産です。"},{"tag":"車窓","hook":"鉄道トンネルが国道に","t":"押角峠道路は、旧岩泉線の押角トンネルを道路用に広げ、2020年12月13日に開通しました。"},{"tag":"へえ","hook":"ブルートレインに泊まれる","t":"岩泉CYMBALSには、ブルートレイン「日本海」「あけぼの」で使われた客車3両が保存され、列車ホテルとして有料で泊まれます。"},{"tag":"クイズ","q":"日本最長の洞窟として知られる、岩泉町の鍾乳洞は？","a":"安家洞"}]},"川俣町":{"pref":"福島県","cards":[{"tag":"へえ","hook":"世界一長い川俣シャモの丸焼き","t":"川俣シャモまつりでは、過去に「世界一長い焼き鳥」に挑戦。現在は「世界一長い川俣シャモの丸焼き」がメインイベントです。","teaser":true},{"tag":"数字","hook":"約127.7km²に約12,537人が暮らす町","t":"面積は約127.7km²、人口は約12,537人（2021年）。1km²あたり約98人です。"},{"tag":"味","hook":"絹長者が広めたシャモ","t":"江戸時代末期、絹織物で栄えた川俣町の「絹長者」たちが闘鶏用のシャモを広め、食べ方もいろいろ試したといいます。"},{"tag":"味","hook":"脂っぽくないのに深いコク","t":"川俣シャモは、脂っぽくないのに深いコクがあり、適度な弾力が人気です。首都圏でも高級食材として認知されています。"},{"tag":"歴史","hook":"絹の里と小手姫伝説","t":"川俣町は平安時代から続く養蚕・絹織物で「絹の里」として知られ、養蚕を伝え広めたとされる小手姫伝説が残ります。"},{"tag":"へえ","hook":"国内最大の中南米音楽祭","t":"川俣町のコスキン・エン・ハポンは、国内最大のフォルクローレ・フェスティバル。町をあげて開かれています。"},{"tag":"車窓","hook":"富士山が見える北限・花塚山","t":"川俣町と飯舘村の境にある花塚山は、標高918.5m。富士山が見える北限です。"},{"tag":"ゆかり","hook":"古関裕而と川俣銀行","t":"古関裕而は1928年から2年間、伯父の経営する川俣銀行に勤務。川俣音頭や川俣町民の歌も作曲しました。"},{"tag":"歴史","hook":"松川駅と結ばれた川俣線","t":"1972年まで、国鉄川俣線が東北本線の松川駅と岩代川俣駅の間、約12キロを結んでいました。"},{"tag":"クイズ","q":"コスキン・エン・ハポンの名前は、どこの音楽祭に由来する?","a":"アルゼンチンのコスキン音楽祭"},{"tag":"クイズ","q":"川俣町の特産の食用鶏は?(闘鶏用のシャモが由来)","a":"川俣シャモ"}]},"川内村":{"pref":"福島県","cards":[{"tag":"へえ","hook":"「無税川内村」と呼ばれた村","t":"1927年、村有林の利益で全国でも希な村税の廃止を行い、「無税川内村」の名が広く知られました。","teaser":true},{"tag":"数字","hook":"約197.3km²に約1,809人が暮らす町","t":"面積は約197.3km²、人口は約1,809人（2021年）。1km²あたり約9人です。"},{"tag":"歴史","hook":"五十万俵の木炭、日本一","t":"大正から昭和への時代、川内村は五十万俵もの木炭を生産し、日本一の生産地になりました。"},{"tag":"ゆかり","hook":"“カエルの詩人”が訪れた村","t":"“カエルの詩人”草野心平が1953年の夏に長福寺を訪れたことで、川内村は全国に名を知られるようになりました。"},{"tag":"ゆかり","hook":"天山文庫は村人の手づくり","t":"天山文庫は村人たちの手で建設が進められ、1966年7月16日に落成。草野心平の蔵書3000冊が始まりです。"},{"tag":"車窓","hook":"茅葺き屋根の天山文庫","t":"天山文庫は木造・真壁造りの茅葺き屋根の日本建築。毎年7月には、草野心平を偲ぶ天山祭りが行われます。"},{"tag":"車窓","hook":"阿武隈高地の最高峰のふもと","t":"川内村は阿武隈高地の最高峰・大滝根山の東斜面にあり、標高500〜600mの高原が村の大部分を占めます。"},{"tag":"へえ","hook":"モリアオガエルの沼は天然記念物","t":"平伏沼は、モリアオガエルの生息地として天然記念物に指定されています。"},{"tag":"へえ","hook":"ニッコウナツグミの北限","t":"ニッコウナツグミは大滝根山が北限地とされ、川内村の高塚山・平伏森の断崖に自生します。"},{"tag":"歴史","hook":"山林を取り戻した村民","t":"村民一丸の山林引戻運動は、1910年と1911年の判決で勝訴。公有林の経営で村の収入が大幅に潤いました。"},{"tag":"クイズ","q":"1927年、川内村が廃止して「無税川内村」と呼ばれるようになったのは何?","a":"村税"},{"tag":"クイズ","q":"川内村を訪れた“カエルの詩人”といえば誰?","a":"草野心平"}]},"川崎町":{"pref":"宮城県","cards":[{"tag":"ゆかり","hook":"支倉常長が青年期を過ごした地","t":"支倉常長は、7歳から川崎町支倉地区にある上楯城で、長い青年期を過ごしました。"},{"tag":"数字","hook":"人より自然が多い町","t":"1km²あたり約31人。県内で下から2番目の人口密度です。"},{"tag":"ゆかり","hook":"使節の支倉常長の墓がある円福寺","t":"ヨーロッパに渡った慶長遣欧使節の支倉常長の墓がある円福寺が、釜房湖の周辺にあります。"},{"tag":"出身","hook":"川崎町出身の有名人","t":"川崎町出身には、ローカルタレントの鈴木順子がいます。"},{"tag":"車窓","hook":"釜房湖畔の東北地方初の国営公園","t":"国営みちのく杜の湖畔公園は、釜房ダム湖畔にある東北地方初の国営公園で、仙台・山形・福島の県庁所在地から50キロメートル圏内にあります。"},{"tag":"へえ","hook":"東北の古い民家が建ち並ぶ「ふるさと村」","t":"公園の南地区の「ふるさと村」には、津軽、遠野、本荘由利、月山山麓、南会津など東北各地の特徴ある古い民家が移築されています。"},{"tag":"歴史","hook":"青根温泉は伊達氏の御殿湯","t":"青根温泉には江戸時代、仙台藩伊達氏の御殿湯が置かれました。伊達氏の御殿湯は東鳴子温泉にも置かれていました。"},{"tag":"へえ","hook":"名曲「影を慕いて」は青根温泉で","t":"10月の「影を慕いて」歌謡コンクール全国大会は、古賀政男が青根温泉でこの曲を着想したことにちなんでいます。","teaser":true},{"tag":"へえ","hook":"マスコットはカモシカ、町の獣も","t":"みちのく公園のマスコット「シカボー」「モシカ」はカモシカがモデルです。カモシカは川崎町の「町の獣」に指定されています。"},{"tag":"へえ","hook":"ARABAKI ROCK FEST.の会場","t":"ARABAKI ROCK FEST.は、2006年からエコキャンプみちのくを拠点に毎年春に開かれています。東北でも最大規模の音楽イベントになりつつあるそうです。"},{"tag":"歴史","hook":"川崎城と川崎伊達氏","t":"1610年に砂金実常が川崎城を築き、1722年には伊達村詮が川崎城を拝領して2,000石を領し、川崎伊達氏となりました。"},{"tag":"クイズ","q":"仙台市の水源の六つのダムのうち、最大のシェアを占める釜房ダムは、需要量の何%を占める?","a":"35%"}]},"川西町":{"pref":"山形県","cards":[{"tag":"ゆかり","hook":"イザベラ・バードが泊まった小松","t":"1878年、旅行家イザベラ・バードが小松の金子十三衛門家に宿泊。町の住民の半数が外国人を見物に集まったといいます。","teaser":true},{"tag":"数字","hook":"約166.6km²に約14,196人が暮らす町","t":"面積は約166.6km²、人口は約14,196人（2021年）。1km²あたり約85人です。"},{"tag":"ゆかり","hook":"井上ひさしの蔵書が集まる文庫","t":"井上ひさしが故郷の川西町に蔵書を寄贈し、1987年に図書館「遅筆堂文庫」が開設されました。"},{"tag":"出身","hook":"川西町出身の有名人","t":"川西町出身には、小説家の井上ひさし、唯物論の哲学者の船山信一、プロボクサーの伊藤まみがいます。"},{"tag":"歴史","hook":"県内の前方後円墳が集まる古墳群","t":"下小松古墳群は古墳の総数が202基。山形県内の半数以上の前方後円墳が集中しています。"},{"tag":"へえ","hook":"川西の名は鬼面川の西から","t":"川西町の名は、最上川の支流・鬼面川の西側を「川西」と呼んでいたことに由来します。"},{"tag":"歴史","hook":"小松豊年獅子踊の文化賞","t":"小松豊年獅子踊は山形県指定の無形民俗文化財。2021年度に第67回斎藤茂吉文化賞を受賞しました。"},{"tag":"車窓","hook":"羽前小松駅そばの鉛筆工場","t":"羽前小松駅の近くには、三菱鉛筆の山形工場があります。"},{"tag":"歴史","hook":"リゾートからメガソーラーへ","t":"1988年に玉庭地区にできたサンマリーナ玉庭は、2014年頃までにリゾート事業が全て停止し、いまは太陽光パネルが並びます。"},{"tag":"へえ","hook":"陶磁の名品を集めた掬粋巧芸館","t":"掬粋巧芸館は1932年開館の私立美術館。元代の青花磁器の世界的名品が知られます。現在は休館中です。"},{"tag":"クイズ","q":"川西町出身の井上ひさしが、自分につけた戯号は?","a":"遅筆堂"},{"tag":"クイズ","q":"道伝遺跡から出土した、東日本最古と言われるものは?","a":"墨書きの絵馬"}]},"平内町":{"pref":"青森県","cards":[{"tag":"へえ","hook":"養殖ホタテは日本一","t":"平内町の養殖ホタテの生産量は日本一とされます。"},{"tag":"数字","hook":"約217.1km²に約9,964人が暮らす町","t":"面積は約217.1km²、人口は約9,964人（2021年）。1km²あたり約46人です。"},{"tag":"歴史","hook":"北海道と大陸へ向かう幻の鉄道","t":"茂浦では漁港ができる前に、北海道や大陸と結ぶ計画の茂浦鉄道が建設されましたが、未成線に終わりました。","teaser":true},{"tag":"出身","hook":"平内町出身の有名人","t":"平内町出身には、津軽三味線奏者の高橋竹山、プロ野球選手の細川亨、お笑いタレントの大水洋介がいます。"},{"tag":"へえ","hook":"椿の自生は北限","t":"椿山はツバキ自生の北限地帯で、国の天然記念物です。"},{"tag":"車窓","hook":"夏泊半島に白鳥が舞い降りる","t":"小湊のハクチョウとその渡来地は、国の特別天然記念物です。渡来地は夏泊半島全体にわたります。"},{"tag":"歴史","hook":"小湊から函館へ船が出ていた","t":"小湊港からは、1946年7月から1949年7月まで函館港との間で青函連絡船の補助航路が開設されていました。"},{"tag":"へえ","hook":"地名はアイヌ語で崖と川","t":"平内の地名は、アイヌ語の「ピラ・ナイ」（崖・川）からとされています。峡谷を流れる川という意味があります。"},{"tag":"クイズ","q":"平内町で生産量が日本一とされる養殖の貝は？","a":"ホタテ"},{"tag":"へえ","hook":"白鳥・椿・ほたての祭り","t":"平内町では、2月に白鳥まつり、5月に椿とサボテン祭り、10月にほたての祭典が開かれます。"},{"tag":"ゆかり","hook":"津軽三味線の高橋竹山","t":"津軽三味線奏者の高橋竹山は、平内町の出身です。"},{"tag":"へえ","hook":"スキー場でロックフェス","t":"夜越山スキー場の特設ステージでは、2012年から毎年夏にAOMORI ROCK FESTIVALが開かれています。"},{"tag":"歴史","hook":"茂浦の浅瀬に貨物船が座礁","t":"1970年3月17日、低気圧の影響で、茂浦の浅瀬に貨物船「第52共和丸」が吹き寄せられて座礁しました。"}]},"平川市":{"pref":"青森県","cards":[{"tag":"へえ","hook":"市の一部が実質飛地","t":"碇ヶ関地区は、境界の山地に道路が通じておらず、実質上の飛地です。","teaser":true},{"tag":"数字","hook":"約346.0km²に約30,326人が暮らす町","t":"面積は約346.0km²、人口は約30,326人（2021年）。1km²あたり約88人です。"},{"tag":"へえ","hook":"市名は川の名前から","t":"平川市の名は、旧3町村を流れる岩木川の支流・平川に由来します。"},{"tag":"出身","hook":"平川市出身の有名人","t":"平川市出身には、民謡歌手の岸千恵子、女優の駒井蓮、作曲家の桜田誠一がいます。"},{"tag":"へえ","hook":"名水百選の渾神の清水","t":"平川市には、名水百選に選ばれた「渾神の清水」があります。"},{"tag":"車窓","hook":"庭園と洋館の盛美園","t":"盛美園は回遊式日本庭園で、擬洋風建築の盛美館もあります。"},{"tag":"歴史","hook":"関所を再現した碇ヶ関","t":"碇ヶ関御関所は、かつて弘前藩が設けていた関所を再現したものです。"},{"tag":"歴史","hook":"縄文晩期の八幡崎遺跡","t":"八幡崎遺跡は縄文時代晩期の遺跡で、青森県史跡になっています。"},{"tag":"へえ","hook":"高校は秋田の学校も受験可","t":"平川市内の受験生は、秋田県の大館、能代、鹿角、北秋田、小坂の公立高も受験できます。"},{"tag":"クイズ","q":"平川市の名前の由来になった川は？","a":"平川"},{"tag":"クイズ","q":"平川ねぷた祭りは毎年何月に開催される？","a":"8月（2日から3日）"},{"tag":"車窓","hook":"碇ヶ関の温泉郷","t":"旧碇ヶ関村には、碇ヶ関温泉郷と秋元温泉があります。"},{"tag":"へえ","hook":"舞台になった作品","t":"「じいさんばあさん若返る」は、平川市が舞台の作品です。"},{"tag":"ゆかり","hook":"女優の駒井蓮さん","t":"平川市ゆかりの人に、女優の駒井蓮さんがいます。"}]},"平泉町":{"pref":"岩手県","cards":[{"tag":"へえ","hook":"岩手県でいちばん小さな町","t":"平泉町は、岩手県内で最も面積が小さい自治体です。東西16.15km、南北8.51kmの細長い町域です。"},{"tag":"数字","hook":"県内で小さい方の町","t":"面積は約63.4km²で、県内33市町村中33位。人口は約7,178人（2021年）です。"},{"tag":"歴史","hook":"金色堂は清衡みずからの廟堂","t":"金色堂は藤原清衡が自身の廟堂として建てた堂で、内部には清衡・基衡・秀衡の3代の遺体が安置されています。"},{"tag":"出身","hook":"平泉町出身の有名人","t":"平泉町出身には、設計建築家の葛西萬司、実業家の西村専次がいます。"},{"tag":"へえ","hook":"桶の中の種から咲いたハス","t":"泰衡の首級桶から見つかった種が発芽し、1998年に開花。その蓮が「中尊寺ハス」として境内に植えられています。","teaser":true},{"tag":"車窓","hook":"一晩で築いたという金鶏山","t":"金鶏山は、秀衡が一晩で築かせたとの伝説が残る山です。山頂に雄雌一対の金の鶏を埋めたことが名の由来と伝わります。"},{"tag":"歴史","hook":"断崖の下に建つ達谷窟","t":"達谷窟は、東西約150m、最大標高差約35mの岸壁の下の岩屋に、懸造の窟毘沙門堂が建つ史跡です。"},{"tag":"ゆかり","hook":"芭蕉が見た夏草の平泉","t":"1689年、松尾芭蕉は平泉を訪れ、藤原氏の居館があった場所が田野になっているのを見て、俳句を詠みました。"},{"tag":"へえ","hook":"毛越寺は堂塔四十余宇","t":"『吾妻鏡』によれば、毛越寺には「堂塔四十余宇、禅房五百余宇」があったといいます。"},{"tag":"歴史","hook":"金と名馬で北宋とも交易","t":"藤原秀衡は名馬や金をたびたび朝廷に献上し、十三湊や蝦夷を介して北宋や沿海州とも交易していました。"},{"tag":"へえ","hook":"庭園へ水を送る照井堰用水","t":"照井堰用水は疎水百選に選ばれ、毛越寺庭園へ給水しています。"},{"tag":"クイズ","q":"岩手県内で最も面積が小さい自治体は?","a":"平泉町"},{"tag":"クイズ","q":"金鶏山の名は、山頂に何を埋めたことにちなむと伝わる?","a":"雄雌一対の金の鶏"}]},"平田村":{"pref":"福島県","cards":[{"tag":"歴史","hook":"羊200頭が村を救った","t":"平田村では羊肉料理がご馳走とされています。1934〜1935年の冷害凶作の飢饉のとき、出身の実業家が羊200頭を寄付し、村民が飢えをしのいだ歴史があります。","teaser":true},{"tag":"数字","hook":"約93.4km²に約5,822人が暮らす町","t":"面積は約93.4km²、人口は約5,822人（2021年）。1km²あたり約62人です。"},{"tag":"味","hook":"村の名物はジンギスカン","t":"村民の羊肉料理への愛情は深く、この村で出されるジンギスカンがとても美味しいと評判になり、いまでは村の名物になっています。"},{"tag":"車窓","hook":"いわきと郡山のほぼ中間","t":"平田村は福島県の南部、いわき市と郡山市のほぼ中間にあります。標高500mから700mのなだらかな山間地帯です。"},{"tag":"車窓","hook":"独立峰のような「平田富士」","t":"蓬田岳は、山の周りがなだらかで山自体も標高が高いため、独立峰のような姿です。そのため「平田富士」とも呼ばれます。"},{"tag":"へえ","hook":"登山口の展望デッキはスカイツリーと同じ高さ","t":"蓬田岳の探検コースの登山口にある展望デッキは、東京スカイツリーと同じ標高のため、「ジュピアランドひらた634」という愛称があります。"},{"tag":"へえ","hook":"蓬田岳の山頂から富士山も","t":"蓬田岳の山頂からは、吾妻連峰、安達太良山、磐梯山、太平洋のほか、天候や気候次第で富士山の山頂部も見ることができます。"},{"tag":"歴史","hook":"文明年間の城跡、蓬田舘址","t":"蓬田舘址は、文明年間（1469～86）に石川城主の次男の秀光が築いた城跡です。"},{"tag":"へえ","hook":"古くから伝わるじゃんがら念仏踊","t":"駒形地区には、駒形じゃんがら念仏踊という伝統芸能が古くから伝わっています。"},{"tag":"へえ","hook":"村と特産ハバネロを歌った曲","t":"「けっぱって東北」のシングル「激辛ife」は、平田村と特産のハバネロを歌った曲です。"},{"tag":"クイズ","q":"1934年からの飢饉のとき、実業家が200頭を寄付して村民を救った動物は？","a":"羊"},{"tag":"クイズ","q":"平田村の蓬田岳は、独立峰のような姿から何と呼ばれる？","a":"平田富士"}]},"広野町":{"pref":"福島県","cards":[{"tag":"へえ","hook":"唱歌「汽車」は広野駅？","t":"唱歌「汽車」は広野駅が舞台と誤解され、広野駅構内に碑があります。","teaser":true},{"tag":"数字","hook":"約58.7km²に約3,881人が暮らす町","t":"面積は約58.7km²、人口は約3,881人（2021年）。1km²あたり約66人です。"},{"tag":"へえ","hook":"日本サッカー界初の合宿施設","t":"Jヴィレッジは、広野町と楢葉町にまたがる、日本サッカー界初のナショナルトレーニングセンターです。1997年に開設されました。"},{"tag":"歴史","hook":"聖火リレーの出発地","t":"2021年3月25日、東京オリンピックの聖火ランナーのスタート地点になりました。"},{"tag":"歴史","hook":"アルゼンチン代表のキャンプ地","t":"2002年のサッカーワールドカップの際、アルゼンチン代表が広野をキャンプ地に構えました。"},{"tag":"へえ","hook":"日本三大松の奥州日の出の松","t":"奥州日の出の松は「日本三大松」の一つに数えられ、「安寿と厨子王」に関する伝説の舞台でもあります。"},{"tag":"へえ","hook":"春を告げる浜下り神事","t":"広野町では4月に、浜下り神事「たんたんぺろぺろ」が行われます。"},{"tag":"車窓","hook":"東北に春を告げる町","t":"広野町は冬でも雪の少ない温暖な気候で、キャッチフレーズは「東北に春を告げる町」です。"},{"tag":"歴史","hook":"鶴岡八幡宮から5里ごとの八幡","t":"楢葉八幡神社は、源頼義・義家父子が前九年の役で出征の折、鶴岡八幡宮から5里ごとに設けた「五里八幡」の一つです。"},{"tag":"ゆかり","hook":"作家・富沢有為男の住まい","t":"作家の富沢有為男は、戦後から晩年まで広野町に住居を構えました。"},{"tag":"クイズ","q":"Jヴィレッジの名を命名した、元イングランド代表の人物は？","a":"ボビー・チャールトン"}]},"庄内町":{"pref":"山形県","cards":[{"tag":"へえ","hook":"町名の候補は「天の川町」","t":"庄内町の町名の最終候補の一つは「天の川町」。余目と立川をつなぐことを、彦星と織姫の出会いに例えた案でした。","teaser":true},{"tag":"数字","hook":"約249.2km²に約19,977人が暮らす町","t":"面積は約249.2km²、人口は約19,977人（2021年）。1km²あたり約80人です。"},{"tag":"へえ","hook":"都市ガスに地元の天然ガス","t":"1960年に余目油田の試掘が成功し、石油と天然ガスが噴出。町内の都市ガスには、余目油田の天然ガスが混合されています。"},{"tag":"出身","hook":"庄内町出身の有名人","t":"庄内町出身には、幕末の志士の清河八郎、プロ野球選手の石川直也、総合格闘家の田澤聡がいます。"},{"tag":"車窓","hook":"清川だしで風力発電の町おこし","t":"旧立川町（現庄内町）では、春から秋にかけての清川だしなど、年間を通じて平均した風向・風速を生かし、風力発電による町おこしが行われています。"},{"tag":"ゆかり","hook":"浪士組を結成した清河八郎","t":"清河八郎は庄内町の出身。幕末の志士で、浪士組を結成しました。"},{"tag":"歴史","hook":"庄内地方で初の駅開業は清川駅","t":"1914年に古口－清川間が開通し、清川駅が新設されました。庄内地方で初めての駅開業でした。"},{"tag":"歴史","hook":"「亀ノ尾」発祥の立谷沢","t":"立谷沢地区は、明治時代後期から昭和初期に広く栽培されたイネ品種「亀ノ尾」の発祥地です。"},{"tag":"車窓","hook":"最上川舟運で栄えた清川","t":"清川地区は立谷沢川と最上川の合流する所にあり、江戸時代には最上川舟運の中継地として栄えました。"},{"tag":"歴史","hook":"4か月で10キロの水路を掘った北楯大堰","t":"北楯大堰は、1日7400人を動員してわずか4ヶ月で約10キロの水路を完成させたと伝わります。後に総延長32kmとなりました。"},{"tag":"へえ","hook":"砂金採り体験から生まれた縁","t":"1993年、歌津町の小学生が立川町を訪れて砂金採り体験をしたことから交流が始まり、1999年に友好町盟約を結びました。"},{"tag":"クイズ","q":"庄内町の立谷沢地区が発祥地の、明治時代後期から昭和初期に広く栽培されたイネ品種は？","a":"亀ノ尾"},{"tag":"クイズ","q":"庄内地方で初めての駅開業となった、庄内町の駅は？","a":"清川駅"}]},"弘前市":{"pref":"青森県","cards":[{"tag":"歴史","hook":"天守が大爆発した城","t":"1627年、落雷で鷹岡城の天守が炎上し、内部の火薬に引火して大爆発。5層6階の天守などを焼失しました。","teaser":true},{"tag":"数字","hook":"県内で面積4位","t":"面積は約524.2km²で、県内40市町村中4位の広さ。人口は約167,803人（2021年）です。"},{"tag":"へえ","hook":"日本最古のソメイヨシノ","t":"弘前公園には「日本最古のソメイヨシノ」があります。"},{"tag":"出身","hook":"弘前市出身の有名人","t":"弘前市出身には、作家の石坂洋次郎、劇作家の寺山修司、美術家の奈良美智、女性タレントの王林がいます。"},{"tag":"へえ","hook":"りんごの生産量が全国一","t":"弘前市はりんごの生産量が全国一で約25%を占めるとされ、「りんご色のまちHIROSAKI」をうたっています。"},{"tag":"歴史","hook":"大正に東北初のデパート","t":"大正時代、東北地方初のデパート「かくは宮川」が土手町に開店し、近代的な都市文化が花開きました。"},{"tag":"車窓","hook":"ねぷたに100万人超が集まる","t":"弘前ねぷたまつりは、例年100万人以上の人出がある国の重要無形民俗文化財の夏祭りです。"},{"tag":"味","hook":"嶽地区名産のトウモロコシ","t":"嶽地区の名産として「嶽きみ」と呼ばれるトウモロコシがあります。"},{"tag":"歴史","hook":"東日本最古の水田跡が出た","t":"1988年、砂沢遺跡で東日本最古（弥生時代前期）の水田跡が発見されました。"},{"tag":"クイズ","q":"鷹岡から「弘前」に改称されたのは何年？","a":"1628年"},{"tag":"車窓","hook":"武家屋敷が残る仲町","t":"弘前市の仲町は、重要伝統的建造物群保存地区に選ばれています。"},{"tag":"へえ","hook":"市民が生んだ巨大ロボ","t":"弘前市が企画した市民参加型プロジェクトから、巨大ロボットキャラクター「超城合体タメノブーンV」が2016年に誕生しました。"},{"tag":"へえ","hook":"冬はイルミネーションの街","t":"弘前エレクトリカルファンタジーは、12月1日から2月末まで、イルミネーションと洋館のライトアップが行われます。"},{"tag":"へえ","hook":"津軽打刃物や津軽桐下駄","t":"弘前市内の青森県指定伝統工芸品には、津軽打刃物、津軽桐下駄、こぎん刺しなどがあります。"}]},"戸沢村":{"pref":"山形県","cards":[{"tag":"へえ","hook":"村の中なのに市外局番から","t":"戸沢村の中心部は、最上地方で唯一、酒田市・飽海郡の市外局番です。同じ村内への電話も市外局番から押す必要があります。","teaser":true},{"tag":"数字","hook":"約261.3km²に約4,089人が暮らす町","t":"面積は約261.3km²、人口は約4,089人（2021年）。1km²あたり約16人です。"},{"tag":"歴史","hook":"国保発祥の地・角川村","t":"1936年、角川村は相互扶助の保健組合を発足。2年後に国の認可第1号の国民健康保険組合となり、石碑「国保発祥の地」が建っています。"},{"tag":"出身","hook":"戸沢村出身の有名人","t":"戸沢村出身には、プロレスラーの最上九、俳優の荒川清がいます。"},{"tag":"へえ","hook":"最上峡が阻む電柱の敷設","t":"村の中心部と、西部の高屋・草薙集落の間は最上峡にさえぎられ、電柱が敷設されていません。"},{"tag":"へえ","hook":"原油ではなく温泉が出た野口集落","t":"昭和時代、野口集落で油田の掘削をしたところ、温泉と原油の混合物が噴出。その温泉で日帰り温泉施設「ぽんぽ館」が作られました。"},{"tag":"車窓","hook":"樹齢1200年あまりの長倉の大杉","t":"今熊野神社の社殿の傍らにある長倉の大杉は、幹周り9.5m、高さ42m、樹齢は1200年あまり。山形県の天然記念物です。"},{"tag":"車窓","hook":"樹齢千年超の巨木群・幻想の森","t":"最上峡左岸の山中にある「幻想の森」は、樹齢千年を超えると思われる巨木の群生地です。2024年7月の豪雨で林道が被災し、2026年に利用が再開されました。"},{"tag":"車窓","hook":"全長15kmの最上峡","t":"最上峡は、戸沢村の古口地区から庄内町の清川地区までの全長15kmの峡谷。最上川県立自然公園の中核です。"},{"tag":"車窓","hook":"最上四十八滝で最大の白糸の滝","t":"最上峡には最上四十八滝という滝群があり、西端にある白糸の滝はその中でも最大です。日本の滝百選の一つです。"},{"tag":"ゆかり","hook":"芭蕉が記した白糸の滝と仙人堂","t":"松尾芭蕉は『おくのほそ道』で「白糸の滝は青葉の隙々に落ちて、仙人堂、岸に臨みて立つ。水みなぎつて舟危し」と記しました。"},{"tag":"クイズ","q":"戸沢村の石碑に刻まれている、日本で初めて国民健康保険のシステムを整えた村の呼び名は？","a":"国保発祥の地"},{"tag":"クイズ","q":"最上峡の最上四十八滝の中で最大の、日本の滝百選にも選ばれている滝は？","a":"白糸の滝"}]},"新地町":{"pref":"福島県","cards":[{"tag":"歴史","hook":"県内で唯一の仙台藩領","t":"新地町は、福島県内で唯一の仙台藩領でした。相馬野馬追には参加せず、方言は仙台弁地域に分類されます。","teaser":true},{"tag":"数字","hook":"約46.5km²に約8,051人が暮らす町","t":"面積は約46.5km²、人口は約8,051人（2021年）。1km²あたり約173人です。"},{"tag":"車窓","hook":"海を見ながら登れる鹿狼山","t":"鹿狼山は標高429.3m。周囲に高い山がなく、「海を見ながら登れる山」として知られます。"},{"tag":"出身","hook":"新地町出身の有名人","t":"新地町出身には、漫画家の横山孝雄、建築家の遠藤新、作曲家の荒芳樹がいます。"},{"tag":"へえ","hook":"日本一早い山開き式","t":"鹿狼山では毎年元旦に、「日本一早い山開き式」と称した元旦登山が行われます。"},{"tag":"へえ","hook":"手長明神と新地貝塚","t":"鹿狼山には、手長明神が太平洋から貝を捕って食べ、その貝殻を麓に捨てたために新地貝塚が生まれたという言い伝えがあります。"},{"tag":"車窓","hook":"相馬港を相馬市と共有","t":"新地町は相馬市と重要港湾の相馬港を共有し、港の北半分ほどにあたる埠頭部分が町域に含まれます。"},{"tag":"へえ","hook":"仙台の放送局も受信できる","t":"新地町では、福島の放送局だけでなく仙台の放送局の受信も可能です。仙台市のベッドタウンと見なされることもあります。"},{"tag":"車窓","hook":"名水の右近清水","t":"鹿狼山の周辺にある右近清水は、平成の名水百選に選ばれています。"},{"tag":"歴史","hook":"「相馬の旧封の人民と異なる」","t":"明治12年、初代宇多・行方郡長の大須賀次郎は宇多郡内を巡察し、仙台藩に属する地の「習慣の風俗」は相馬の人々と異なると記しました。"},{"tag":"クイズ","q":"新地町は福島県内で唯一、どの藩の領地だった?","a":"仙台藩"},{"tag":"クイズ","q":"鹿狼山は、どんな山として知られる?","a":"海を見ながら登れる山"}]},"新庄市":{"pref":"山形県","cards":[{"tag":"へえ","hook":"市町村単位で日本一日照時間が短い","t":"新庄は豪雪地域で四方を山に囲まれているため、市町村単位では日本一日照時間が短い町とされています。","teaser":true},{"tag":"数字","hook":"約222.8km²に約34,284人が暮らす町","t":"面積は約222.8km²、人口は約34,284人（2021年）。1km²あたり約154人です。"},{"tag":"車窓","hook":"雪害救済運動発祥の地","t":"新庄は雪害救済運動発祥の地。雪についての学習施設「雪の里情報館」があり、雪崩の発生メカニズムの解明などが行われています。"},{"tag":"出身","hook":"新庄市出身の有名人","t":"新庄市出身には、漫画家の冨樫義博、俳優の竜星涼、シンガーソングライターの林部智史、陸軍大将の小磯國昭がいます。"},{"tag":"へえ","hook":"遠野と並ぶ民話の宝庫","t":"新庄は、岩手県遠野市と並ぶ東北地方随一の民話の宝庫。毎年「みちのく民話まつり」が開かれます。"},{"tag":"味","hook":"春を告げる「カド焼きまつり」","t":"豪雪の冬は鮮魚が手に入りにくく、雪解けと共に入荷するカドを焼いて酒を酌み交わし、桜を眺めて春の到来を喜びます。"},{"tag":"ゆかり","hook":"マスコット「かむてん」は天狗","t":"新庄市のマスコット「かむてん」は、神室山に住む神通力を持った天狗。新庄市出身の漫画家・冨樫義博さんのデザインです。"},{"tag":"車窓","hook":"諸藩が植えた泉田の松並木","t":"国道13号沿いの泉田の松並木は、参勤交代をする東北諸藩の手で植えられたものです。"},{"tag":"味","hook":"新庄発祥ともいわれるくぢらもち","t":"くぢらもちは、江戸時代に新庄藩の第3代藩主・戸沢正庸の治世で兵糧食として作られていたという説が有力で、新庄市が発祥ではといわれます。"},{"tag":"歴史","hook":"新庄祭の始まり","t":"1756年、前年の大凶作に苦しんだ新庄藩は、領民に活気と希望を持たせるため祭典を行いました。これが新庄祭の始まりと伝えられます。"},{"tag":"車窓","hook":"山車の左側は豪華絢爛","t":"新庄まつりの山車は、山・桜・牡丹・松・滝を必ず飾る以外は自由。進行方向左側が豪華絢爛に飾り付けられます。"},{"tag":"へえ","hook":"山車を守る「電線上げ」","t":"新庄まつりの山車が電線や脇木に引っかからないよう、左右に4mほどの棒を持った「電線上げ」の人が常に付き添います。"},{"tag":"クイズ","q":"新庄市のマスコット「かむてん」は、神室山に住む何？","a":"天狗"}]},"新郷村":{"pref":"青森県","cards":[{"tag":"へえ","hook":"村にあるキリストの墓伝説","t":"『竹内文書』で知られる竹内巨麿らが1935年に笹に埋もれた塚をキリストの墓と主張し、伝説が生まれました。","teaser":true},{"tag":"数字","hook":"人より自然が多い町","t":"1km²あたり約14人。県内で下から3番目の人口密度です。"},{"tag":"ゆかり","hook":"エルサレムに向かって乾杯","t":"キリスト祭のフィナーレは、出席者全員がエルサレムの方角を向き、ナニャドヤラワインで乾杯します。"},{"tag":"へえ","hook":"「へらい」はヘブライ？","t":"村の「へらい」という名は、「ヘブライ」が訛ったものといわれています。"},{"tag":"味","hook":"その名も「ジーザスひっつみ」","t":"新郷村には「ジーザスひっつみ」という名の品があります。"},{"tag":"車窓","hook":"十和田湖の外輪山に面する村","t":"新郷村は、十和田湖外輪山の一つである戸来岳（大駒ヶ岳、三ッ岳）に面しています。"},{"tag":"へえ","hook":"謎の大石神ピラミッド","t":"大石神ピラミッドは、太陽石、星座石、方位石、鏡石で構成されています。"},{"tag":"クイズ","q":"新郷村のキリスト祭は、いつ行われる？","a":"6月の第一日曜日"},{"tag":"クイズ","q":"新郷村の「へらい」は何が訛ったといわれる？","a":"ヘブライ"},{"tag":"味","hook":"キリストの名がつく特産品","t":"新郷村の特産品には、キリストラーメンやキリストおでん、キリストのハッカ飴、ドラキュラアイスなどがあります。"},{"tag":"歴史","hook":"自治体を越えた商工会の合併","t":"2008年4月1日、新郷村商工会が五戸町商工会に編入されました。自治体の合併を越えての合併は、まれだと報じられました。"},{"tag":"へえ","hook":"8月19日に金ヶ沢鶏舞","t":"戸来三嶽神社大祭の8月19日には、県指定無形民俗文化財の金ヶ沢鶏舞が行われます。"}]},"昭和村":{"pref":"福島県","cards":[{"tag":"へえ","hook":"「昭和村」は2つだけ","t":"2025年時点で、「昭和村」を名乗る自治体は、日本国内ではこの村と群馬県の昭和村の二つだけです。"},{"tag":"数字","hook":"人より自然が多い町","t":"1km²あたり約6人。県内で下から3番目の人口密度です。"},{"tag":"へえ","hook":"カラムシは本州で唯一ここだけ","t":"昭和村は、カラムシの本州唯一の生産地です。夏は冷涼で、カスミソウの栽培にも適しています。"},{"tag":"へえ","hook":"カスミソウは夏秋の量が日本一","t":"2021年現在、52戸がカスミソウを栽培しており、夏秋期の生産量は日本一です。"},{"tag":"へえ","hook":"「空港まで125km」の標識","t":"福島空港までの距離を示す標識のうち、記者の自主調査で最も遠かったのは、昭和村の「空港まで125km」だったそうです。","teaser":true},{"tag":"ゆかり","hook":"からむし織の「織姫」制度","t":"1994年に始まった「織姫」制度では、2014年までに97名が修了し、30名以上が修了後も村に残っています。"},{"tag":"歴史","hook":"からむしは室町時代から","t":"昭和村のからむし栽培は室町時代にはすでに始まっていたとされ、会津領主・蘆名盛政の時代に奨励されたと言われます。"},{"tag":"車窓","hook":"標高1,100mの駒止湿原","t":"駒止湿原は、大半が昭和村にある標高1,100mの高層湿原で、国の天然記念物です。"},{"tag":"車窓","hook":"1,000m級の山に囲まれた村","t":"昭和村は標高1,000メートル級の山々に囲まれた農山村で、冬の最高積雪は2メートルに達することもあります。"},{"tag":"クイズ","q":"昭和村では、夏秋期の生産量が日本一(2021年現在)とされる花は?","a":"カスミソウ"},{"tag":"クイズ","q":"昭和村の「昭和」は、何にあやかって付けられた名前?","a":"村が生まれた年の年号(昭和)"}]},"普代村":{"pref":"岩手県","cards":[{"tag":"へえ","hook":"北緯40度線上の最東端","t":"普代村は、北緯40度線上の世界最東端の地です。","teaser":true},{"tag":"数字","hook":"県内で小さい方の町","t":"面積は約69.7km²で、県内33市町村中31位。人口は約2,489人（2021年）です。"},{"tag":"ゆかり","hook":"同じ北緯40度の三種町と友好","t":"普代村は、同じ北緯40度線上の秋田県三種町と、1985年から友好都市の関係にあります。"},{"tag":"出身","hook":"普代村出身の有名人","t":"普代村出身には、プロ野球選手の銀次、元村長の和村幸得がいます。"},{"tag":"車窓","hook":"男鹿と対をなす黒埼灯台","t":"陸中黒埼灯台は北緯40度線上の灯台で、秋田県男鹿半島の入道埼灯台と対をなします。日本の灯台50選にも選ばれています。"},{"tag":"車窓","hook":"断崖が続く普代の海岸","t":"普代村の海岸は、比高100mを越える断崖絶壁がほとんどで、砂浜は少ないのが特徴です。"},{"tag":"歴史","hook":"高すぎると言われた水門","t":"普代水門の高さ15.5メートルは、計画時に「高すぎる」と非難されましたが、村長の和村幸得が「15メートル以上」と譲りませんでした。"},{"tag":"歴史","hook":"先人の備えが集落を守った","t":"高さ15.5mの普代水門と太田名部防潮堤は、2011年の津波を大幅に減衰させ、集落への浸水被害を最小限に抑えました。"},{"tag":"へえ","hook":"鎌倉時代から続く鵜鳥神楽","t":"鵜鳥神社の鵜鳥神楽は、鎌倉時代から続く山伏神楽の一種で、2015年に重要無形民俗文化財に指定されました。"},{"tag":"ゆかり","hook":"義経北行伝説の神社","t":"鵜鳥神社は義経北行伝説のコースの一つ。平泉を脱出した義経主従が、この地で七日七夜、海上安全などを祈ったと伝わります。"},{"tag":"へえ","hook":"天にそびえる夫婦杉","t":"鵜鳥神社の参道の夫婦杉は、樹齢約400年、樹高45m。地面から4〜5mで幹が二つに分かれています。"},{"tag":"クイズ","q":"普代村は、北緯何度の線上にあるでしょう？","a":"40度"},{"tag":"クイズ","q":"普代村にある、高さ15.5メートルの津波対策の施設は？","a":"普代水門"}]},"最上町":{"pref":"山形県","cards":[{"tag":"ゆかり","hook":"カカが食べたカレーが名物に","t":"ブラジルのサッカー選手カカは、11歳のころに交流試合で最上町を訪れ、ジャガイモ入りのカレーをよく食べたそうです。","teaser":true},{"tag":"数字","hook":"約330.4km²に約7,832人が暮らす町","t":"面積は約330.4km²、人口は約7,832人（2021年）。1km²あたり約24人です。"},{"tag":"味","hook":"アスパラ入りの「カカカレー」","t":"カカがよく食べた町内産ジャガイモのカレーに、アスパラガスを加えた「カカカレー」というご当地グルメが登場しました。"},{"tag":"出身","hook":"最上町出身の有名人","t":"最上町出身には、タレントのケーシー高峰、タレントのビートきよし、冒険家の大場満郎、映画監督の岸善幸がいます。"},{"tag":"へえ","hook":"「最上」町なのに最上川は流れない","t":"最上町の名がありますが、最上川は町域を流れていません。流れているのは最上小国川などです。"},{"tag":"歴史","hook":"名馬の産地「小国駒」","t":"最上町は、かつて「小国駒」と呼ばれた名馬の産地。馬市が開かれて東北一円に商われ、軍馬としても用いられました。"},{"tag":"歴史","hook":"日本最大だったアカマツ","t":"東法田には、幹回り8.56メートル、推定樹齢600年の日本最大のアカマツがありましたが、2021年までに枯死して伐採されました。"},{"tag":"へえ","hook":"熱闘盆野球","t":"毎年お盆の8月14日と15日には、町内の集落ごとに分かれて戦う町内野球大会「熱闘盆野球」が行われます。"},{"tag":"歴史","hook":"芭蕉が2泊した「封人の家」","t":"旧有路家住宅は『おくのほそ道』の「封人の家」。芭蕉と曽良は雨のため2泊3日滞在し、「蚤虱 馬の尿する 枕もと」と詠んだといわれます。"},{"tag":"へえ","hook":"堺田分水嶺は水が二つの海へ","t":"堺田分水嶺では、水路の水が太平洋と日本海に分かれて流れます。"},{"tag":"ゆかり","hook":"弁慶が見つけた瀬見温泉","t":"瀬見温泉は、武蔵坊弁慶が義経の子・亀若丸の産湯を探し、小国川の岩を薙刀で砕いて温泉を見つけたと伝わります。"},{"tag":"へえ","hook":"赤倉温泉の「お柴灯」","t":"赤倉温泉では、1月中旬に、たいまつを掲げてふんどし姿の男たちが走る伝統行事「お柴灯」が行われます。"},{"tag":"クイズ","q":"最上町の旧有路家住宅は、『おくのほそ道』で何の家と綴られた？","a":"封人の家（国境を守る役人の家）"}]},"朝日町":{"pref":"山形県","cards":[{"tag":"車窓","hook":"湖面に浮かぶ30余りの島","t":"大沼の浮島は、湖面に大小30余りの浮島が浮遊するのが特徴。島が浮遊する神秘の沼として古来より注目されてきました。","teaser":true},{"tag":"数字","hook":"約196.8km²に約6,210人が暮らす町","t":"面積は約196.8km²、人口は約6,210人（2021年）。1km²あたり約32人です。"},{"tag":"歴史","hook":"60余りから十数個に減った浮島","t":"戦後、60余りあった大沼の浮島は十数個に減りました。1987年に浮島を守る会が結成され、保存に取り組んでいます。"},{"tag":"出身","hook":"朝日町出身の有名人","t":"朝日町出身には、漫画家の長岡良子、声優の遠藤綾、児童文学作家の最上一平がいます。"},{"tag":"ゆかり","hook":"行基が名づけた浮島の国名","t":"739年に僧の行基が訪れ、大小66個の浮島に日本各地の国名を名付けたという伝承があります。"},{"tag":"車窓","hook":"山頂から見渡す棚田百選","t":"日本の棚田百選の棚田は、1942年から1946年にかけて作られました。山頂の一本松公園から一望できます。"},{"tag":"味","hook":"無袋ふじの主産地","t":"朝日町は無袋ふじの主産地。2004年からは台湾を中心にアジア諸国へのりんご輸出も行われています。"},{"tag":"味","hook":"アケビの主産地","t":"朝日町はアケビの主産地。2009年頃の時点で、全国生産量の8.5%にあたる年間15トンが出荷されていました。"},{"tag":"歴史","hook":"朝日町ワインは軍需物資が始まり","t":"朝日町ワインは1944年創業。ワインの酒石酸から軍需物資のロッシェル塩を取り出すため、政府が産地に工場を造らせたのが始まりとされます。"},{"tag":"へえ","hook":"町全体がエコミュージアム","t":"朝日町は町全体がエコミュージアムとして整備されています。1995年にはフランスや全国から約200人が参加する国際会議が開かれました。"},{"tag":"歴史","hook":"幻に終わった左荒線","t":"朝日町に鉄道駅はありません。昭和初期に着工が閣議決定された左荒線は、戦争で建設中止になりました。"},{"tag":"クイズ","q":"朝日町のキャッチフレーズは「りんごと何の里」?","a":"ワイン"},{"tag":"クイズ","q":"朝日町の棚田百選の棚田「椹平」。何と読む?","a":"くぬぎだいら"}]},"本宮市":{"pref":"福島県","cards":[{"tag":"へえ","hook":"とろろ芋は「白沢産」","t":"とろろ芋は旧白沢村の特産で「本宮市白沢産」と表記されます。ただし本宮市白沢という地名は存在しません。","teaser":true},{"tag":"数字","hook":"約88.0km²に約30,253人が暮らす町","t":"面積は約88.0km²、人口は約30,253人（2021年）。1km²あたり約344人です。"},{"tag":"歴史","hook":"「本宮」は総鎮守の名から","t":"近隣に点在する安達太良神社の総本宮にあたることから、鎮座地が本宮村となり「本宮」の地名になったとされます。"},{"tag":"出身","hook":"本宮市出身の有名人","t":"本宮市出身には、歌手の伊藤久男、女子マラソン選手の橋本康子、アニメーション監督の押山清高がいます。"},{"tag":"ゆかり","hook":"野口英世が上京した駅","t":"猪苗代町出身の医学者・野口英世は、上京の際に馬車で本宮まで出て、本宮駅から列車に乗ったといいます。"},{"tag":"歴史","hook":"街道が交わる宿場町","t":"本宮は古くから会津街道・相馬街道・三春街道の交点で、交通の中心地でした。宿場町としても有名でした。"},{"tag":"車窓","hook":"アサヒビール福島工場","t":"東北道と磐越道が交差する本宮市は工業団地が広がります。アサヒビール福島工場へは浄水場から専用管が設けられています。"},{"tag":"車窓","hook":"太鼓台が三台出る秋祭り","t":"安達太良神社の10月の秋祭りでは、太鼓台が三台出て、神輿渡御に先立って町を練り歩きます。"},{"tag":"歴史","hook":"人取橋の戦いは4倍以上の差","t":"人取橋の戦いで、伊達軍の兵力は7,000、連合軍は30,000。4倍以上の差がありました。"},{"tag":"へえ","hook":"会津街道の起点の石碑","t":"会津街道起点の石碑は、本宮市歴史民俗資料館に移されて保存され、だれでも見ることができます。"},{"tag":"クイズ","q":"野口英世が上京するとき、馬車で出て列車に乗った本宮の駅は?","a":"本宮駅"},{"tag":"クイズ","q":"会津街道起点の石碑は、いま本宮市のどこに保存されている?","a":"本宮市歴史民俗資料館"}]},"村山市":{"pref":"山形県","cards":[{"tag":"へえ","hook":"徳内を偲んで建てたアイヌの住居","t":"最上徳内記念館の敷地には、徳内がアイヌの人々と交流したことを偲び、アイヌの住居が復元されています。"},{"tag":"数字","hook":"約197.0km²に約22,222人が暮らす町","t":"面積は約197.0km²、人口は約22,222人（2021年）。1km²あたり約113人です。"},{"tag":"歴史","hook":"蝦夷地へ9回渡った探検家","t":"最上徳内は蝦夷地に9回渡り、当時随一の「蝦夷通」として知られました。シーボルトが最も信頼した日本人ともいわれます。"},{"tag":"出身","hook":"村山市出身の有名人","t":"村山市出身には、居合の始祖の林崎甚助、北方探検家の最上徳内、映画監督の村川透がいます。"},{"tag":"味","hook":"炭焼きが生んだひっぱりうどん","t":"ひっぱりうどんの発祥は村山市戸沢地域。山にこもる炭焼き職人が、茹でた乾麺を鍋からひっぱり出し、納豆入りのタレで食べたといいます。","teaser":true},{"tag":"歴史","hook":"最上川の三難所が集まる市","t":"最上川は昔、舟運の道でした。当時「三難所」と呼ばれた碁点・三ケ瀬・隼は、すべて村山市内にあります。"},{"tag":"ゆかり","hook":"居合の始祖は村山市の出身","t":"居合の始祖といわれる林崎甚助は、村山市の出身です。"},{"tag":"へえ","hook":"東日本一のバラ公園","t":"東沢バラ公園は面積7haで東日本一。約750品種、およそ2万株が植えられ、全国のバラ園で唯一「かおり風景100選」に認定されました。"},{"tag":"味","hook":"最上川三難所そば街道","t":"村山市の西部には、最上川を挟んで「最上川三難所そば街道」があります。田舎蕎麦として知られる板そばの店が多い道です。"},{"tag":"クイズ","q":"山形新幹線の村山駅は、1999年に何という駅名から改称されたでしょう?","a":"楯岡駅です。山形・新庄間の開通に合わせて改称されました。"}]},"村田町":{"pref":"宮城県","cards":[{"tag":"車窓","hook":"なまこ壁の「店蔵」が並ぶ町並み","t":"村田の中心市街地には「なまこ壁」の「店蔵（たなぐら）」が並ぶ町並みが残り、2014年に国の重要伝統的建造物群保存地区に選ばれました。"},{"tag":"数字","hook":"約78.4km²に約10,506人が暮らす町","t":"面積は約78.4km²、人口は約10,506人（2021年）。1km²あたり約134人です。"},{"tag":"へえ","hook":"京都に似た地形の小京都","t":"村田町の中心部は、三方を山に囲まれた盆地で東部を川が流れる、京都に類似した地形。小京都と言われる所以の一つです。"},{"tag":"歴史","hook":"紅花の集積地から繭の中心地へ","t":"江戸時代の村田は水運を生かして仙南地方の紅花の集積地となり、明治時代にはカイコの繭を集めて各地へ出荷する中心地として栄えました。","teaser":true},{"tag":"へえ","hook":"京都から来た公家が16代","t":"地誌によると、京都から下向した公家が村田に暮らし、「お館様」と呼ばれて16代を数えた後に、村田氏が城に入ったとされます。"},{"tag":"歴史","hook":"伊達稙宗の九男を迎えた村田氏","t":"村田氏は6代目の近重に男子がなく、永禄8年（1565年）に伊達稙宗の九男宗殖を後嗣ぎに迎え、伊達氏の係累に入りました。"},{"tag":"へえ","hook":"「SUGOには魔物が棲む」","t":"SUGOは標高差73mのアップダウンに富んだコース。アクシデントが起きやすく、「SUGOには魔物が棲む」と表現されることがあります。"},{"tag":"へえ","hook":"SUGOで開かれるレース","t":"SUGOでは、全日本ロードレース選手権などのオートバイレースや、スーパーフォーミュラ、SUPER GTなどのカーレースが開かれています。"},{"tag":"へえ","hook":"「陸前の小京都」村田","t":"村田町は、「陸前の小京都「村田」」として全国京都会議に加盟しています。"},{"tag":"クイズ","q":"村田町の「菅生（SUGO）」は、モータースポーツ界で、どこのサーキットと並ぶ知名度?","a":"鈴鹿"}]},"東北町":{"pref":"青森県","cards":[{"tag":"へえ","hook":"名前に方角が二つある唯一の町","t":"「東北町」は、郡名を除いた名称の中に方角が二つ含まれる全国唯一の町です。","teaser":true},{"tag":"数字","hook":"約326.5km²に約16,322人が暮らす町","t":"面積は約326.5km²、人口は約16,322人（2021年）。1km²あたり約50人です。"},{"tag":"歴史","hook":"「日本中央」と刻まれた石碑","t":"1949年に「日本中央」と刻まれた石碑が見つかりました。坂上田村麻呂が作ったともいわれますが、定かではありません。"},{"tag":"出身","hook":"東北町出身の有名人","t":"東北町出身には、俳優の吹越満、騎手の柴田善臣、大相撲力士の陸奥嵐幸雄がいます。"},{"tag":"味","hook":"シラウオの漁獲高は全国1位","t":"東北町のシラウオは、全国第1位の漁獲高とされています。"},{"tag":"味","hook":"ワカサギを酢みそ和えで生食","t":"ワカサギは一般的には天ぷらやフライですが、東北町では酢みそ和えとして生食することも好まれます。"},{"tag":"へえ","hook":"県民駅伝で13連覇の駅伝の町","t":"1991年に町長が「駅伝の町」を宣言。青森県民駅伝では13連覇を含む20回の町の部優勝を果たしています。"},{"tag":"へえ","hook":"皇室行事のアワを育てた町","t":"東北町では、1993年と2020年の皇室行事の新嘗祭に使うアワの栽培がおこなわれました。"},{"tag":"歴史","hook":"ナウマンゾウの歯が見られる","t":"東北町歴史民俗資料館では、ナウマンゾウ臼歯、トラ顎骨、縄文人骨などが展示されています。"},{"tag":"ゆかり","hook":"世界歴代6位の騎手ゆかりの町","t":"ゆかりの騎手・佐々木竹見は、国内最多の通算7151勝（世界歴代6位）をあげ、2001年に引退しました。"},{"tag":"クイズ","q":"東北町が全国第1位の漁獲高とされる魚は？","a":"シラウオ"},{"tag":"数字","hook":"長芋は青森県トップの産地","t":"青森県は長芋の生産量が都道府県別で日本一で、東北町は青森県の市町村別でトップです。"},{"tag":"車窓","hook":"樹齢800年と650年の銀杏","t":"東北町には、樹齢800年と樹齢650年の2本の銀杏があり、ともに町文化財に指定されています。"},{"tag":"ゆかり","hook":"横浜流星さんの父の故郷","t":"俳優の横浜流星さんは、父親が東北町の出身です。"}]},"東成瀬村":{"pref":"秋田県","cards":[{"tag":"へえ","hook":"4本まとまって出た大形の石斧","t":"上掵遺跡では4本まとまって出土した大形の磨製石斧のうち最長のものが、これまで日本で出土した磨製石斧の中では最大です。","teaser":true},{"tag":"数字","hook":"人より自然が多い町","t":"1km²あたり約12人。県内で下から3番目の人口密度です。"},{"tag":"歴史","hook":"石斧は祭祀に使われた？","t":"上掵遺跡の大形の石斧は、大きさや出土状態から、実用ではなく当時の祭祀にかかわって使用されたものと考えられています。"},{"tag":"出身","hook":"東成瀬村出身の有名人","t":"東成瀬村出身には、漫画家の高橋よしひろ、俳優の高田稔、詩人の佐々木桂がいます。"},{"tag":"へえ","hook":"学力日本一の村","t":"東成瀬村は、学力調査結果から「学力日本一の村」として知られ、秋田県の学習法が注目をあびるきっかけとなりました。"},{"tag":"へえ","hook":"滝行や断食の仙人修行","t":"仙人修行は例年8月上旬に開催。滝行、断食、写経などの修行をやり遂げると、「仙人認定証」が授与されます。"},{"tag":"へえ","hook":"観測史上最高の積雪4.2m","t":"1974年2月14日、田子内地区の観測地点で4.2mの積雪を記録しました。これが観測史上最高積雪となっています。"},{"tag":"クイズ","q":"栗駒山の名は、初夏に山頂西側に現れる何の雪形に由来する？","a":"馬（駒姿）"},{"tag":"車窓","hook":"三つの名を持つ栗駒山","t":"栗駒山は、岩手県では須川岳、秋田県では大日岳、宮城県では駒ヶ岳の別名で呼ばれることもあります。"},{"tag":"へえ","hook":"毎分6000Lの白濁の湯","t":"須川温泉の源泉は自然湧出で、毎分6000Lの湧出量を誇ります。温泉は白濁した、加水加温なしの源泉掛け流しです。"},{"tag":"車窓","hook":"冬の村は国道342号だけ","t":"村の内外を結ぶ道の大半は冬期通行止めとなり、冬の間のアクセスルートは十文字方面からの国道342号のみです。"},{"tag":"へえ","hook":"「日本で最も美しい村」連合","t":"東成瀬村は、2009年10月に「日本で最も美しい村」連合に加盟しました。"},{"tag":"車窓","hook":"砂れきで造るCSGダム","t":"成瀬ダムは、セメントで固めた砂れきで造るCSG構造で、堤高114.5m。完成予定は2027年度とされています。"}]},"東松島市":{"pref":"宮城県","cards":[{"tag":"歴史","hook":"幻の港・野蒜築港","t":"野蒜築港は日本初の近代港湾の建設でしたが、完成から3年後に台風で突堤が崩壊し、施設は放棄されました。「幻の港」とも呼ばれます。","teaser":true},{"tag":"数字","hook":"約101.3km²に約38,880人が暮らす町","t":"面積は約101.3km²、人口は約38,880人（2021年）。1km²あたり約384人です。"},{"tag":"車窓","hook":"松島を望む宮戸島の大高森","t":"宮戸島の最高峰・大高森は、古くから日本三景・松島を眺望する地として知られ、その眺望は「壮観」として松島四大観の1つに数えられます。"},{"tag":"出身","hook":"東松島市出身の有名人","t":"東松島市出身には、お笑い芸人の尾形貴弘、映画監督の阿部豊がいます。"},{"tag":"車窓","hook":"奇岩が連なる嵯峨渓","t":"宮戸島の東南端にある嵯峨渓は、「めがね島」や「かえる島」など多数の名岩や奇岩が連なる景勝地。「日本三大渓」の1つです。"},{"tag":"へえ","hook":"国内最大級の里浜貝塚","t":"松島湾岸と湾内の島々には貝塚群が59カ所あり、里浜貝塚は日本国内でも最大規模をもつ代表的貝塚の一つです。"},{"tag":"歴史","hook":"岩山に避難階段を作った人","t":"野蒜地区の佐藤善文さんは、会社近くの岩山に10年かけて避難階段と避難小屋を作っていました。約70人が津波被害を免れました。"},{"tag":"ゆかり","hook":"種痘所をつくった大槻俊斎","t":"仙台藩医・幕府医の大槻俊斎は東松島の出身で、お玉が池種痘所を設立しました。東京大学医学部の初代総長とみなされています。"},{"tag":"ゆかり","hook":"世界一周した船乗り太十郎","t":"太十郎さんは東松島の出身で、日本人として初めて、漂流も含め世界一周をした4名の船乗りのうちの1人です。"},{"tag":"クイズ","q":"松島湾で最大の島で、東松島市にあるのは何島でしょう?","a":"宮戸島です。周囲約12キロメートル、面積約8平方キロメートルです。"},{"tag":"クイズ","q":"東松島市の航空自衛隊松島基地が所属基地になっている、曲技飛行隊の名前は何でしょう?","a":"ブルーインパルスです。"}]},"東根市":{"pref":"山形県","cards":[{"tag":"味","hook":"サクランボは全国の市町村で1位","t":"東根市は、サクランボの生産量が全国の市町村で1位です。焼き麩の生産量も日本最多です。"},{"tag":"数字","hook":"約206.9km²に約47,747人が暮らす町","t":"面積は約206.9km²、人口は約47,747人（2021年）。1km²あたり約231人です。"},{"tag":"へえ","hook":"校庭にそびえる日本一の巨樹","t":"東根小学校の校庭にある大ケヤキは、樹齢1000年以上とも1500年以上ともいわれ、ケヤキとしては日本一の巨樹といわれています。"},{"tag":"出身","hook":"東根市出身の有名人","t":"東根市出身には、小説家の阿部和重、児童文学者の国分一太郎、プロレスラーの本間朋晃がいます。"},{"tag":"歴史","hook":"大ケヤキはもう1本あった","t":"明治の初めごろ、大ケヤキにはもう1本あり、「雌槻（ははケヤキ）」「雄槻（ちちケヤキ）」と呼ばれました。1885年に雄槻が枯れ、いまの木が残りました。","teaser":true},{"tag":"クイズ","q":"国の特別天然記念物「東根の大ケヤキ」は、どこの校庭に立っているでしょう?","a":"東根市立東根小学校の校庭です。"},{"tag":"へえ","hook":"幹の空洞をくぐると子宝に","t":"大ケヤキの根元の幹には、畳2枚分ほどの空洞があります。この空洞を潜り抜けると、子宝に恵まれるとの言い伝えがあります。"},{"tag":"車窓","hook":"国道48号沿いの関山大滝","t":"関山大滝は、山形と宮城をつなぐ国道48号沿いにあります。乱川上流で、落差10m、幅15mで流れ落ちます。"},{"tag":"歴史","hook":"湖のほとりが「東根」の由来","t":"大昔、村山盆地の真ん中に「藻が湖」という大きな湖があり、東の麓で最も早く拓けた所が東根といわれます。対岸の寒河江市には西根もあります。"},{"tag":"へえ","hook":"県内最古の磨崖仏","t":"大森山の南麓にある、大きな岩に彫られた仏様は、鎌倉時代末期（1300年頃）の作と推定され、山形県内では最古の磨崖仏です。"},{"tag":"味","hook":"宿場町の名残の麩の店","t":"東根市の六田には、羽州街道の宿場町・六田宿の名残をとどめ、伝統を誇る麩の名店が軒を連ねています。"},{"tag":"ゆかり","hook":"小説『シンセミア』の舞台","t":"阿部和重の小説『シンセミア』は、東根市が舞台となっている作品です。"}]},"東通村":{"pref":"青森県","cards":[{"tag":"へえ","hook":"村役場が村の外にあった","t":"道路が未整備だったことから、東通村の役場は1988年に村内へ移るまでむつ市に置かれていました。","teaser":true},{"tag":"数字","hook":"約295.3km²に約5,809人が暮らす町","t":"面積は約295.3km²、人口は約5,809人（2021年）。1km²あたり約20人です。"},{"tag":"車窓","hook":"本州最北東端の尻屋崎","t":"尻屋崎は本州最北東端の岬で、白亜の尻屋埼灯台と寒立馬（かんだちめ）が有名です。"},{"tag":"へえ","hook":"灯台の明るさは53万カンデラ","t":"尻屋埼灯台の光度は、日本最大級の53万カンデラです。"},{"tag":"へえ","hook":"天然記念物のマリモの沼","t":"猿ヶ森にはヒバの埋没林が、左京沼には天然記念物のマリモがあります。"},{"tag":"歴史","hook":"アワビを食べた中世の貝塚","t":"浜尻屋貝塚は、アワビを主体とする中世の貝塚で、国の史跡です。"},{"tag":"へえ","hook":"村に公営の学習塾がある","t":"平成17年10月、全国でも珍しい公営の学習塾『東通村学習塾』が開講しました。"},{"tag":"味","hook":"端境期を狙ったイチゴ","t":"端境期を狙ったイチゴ栽培が盛んです。"},{"tag":"クイズ","q":"尻屋崎で有名な馬『寒立馬』の読みは？","a":"かんだちめ"},{"tag":"クイズ","q":"浜尻屋貝塚は何を主体とする貝塚？","a":"アワビ"},{"tag":"数字","hook":"村の最高地点は桑畑山","t":"尻屋崎の5キロメートル南にある桑畑山は、標高402メートルで、村の最高地点です。"},{"tag":"数字","hook":"氷点下15.4℃を観測","t":"東通村では、2018年2月22日に氷点下15.4℃を観測しました。"},{"tag":"車窓","hook":"ヒバの埋没林とツツジの山","t":"東通村には、猿ヶ森のヒバの埋没林や、桑畑山のツツジがあります。"}]},"松島町":{"pref":"宮城県","cards":[{"tag":"歴史","hook":"日本三景のはじまりは1643年","t":"1643年、儒学者の林鵞峰が松島を天橋立・厳島と並べて「三処奇観」と評しました。これが日本三景の端緒とされます。"},{"tag":"数字","hook":"約53.6km²に約13,151人が暮らす町","t":"面積は約53.6km²、人口は約13,151人（2021年）。1km²あたり約246人です。"},{"tag":"ゆかり","hook":"アインシュタインも月見に来た","t":"1922年12月3日、来日中のアルベルト・アインシュタインが、月見をするために松島を訪れました。","teaser":true},{"tag":"歴史","hook":"五大堂は東北地方最古の桃山建築","t":"五大堂は1604年に伊達政宗が再建した堂です。東北地方最古の桃山建築と言われ、国の重要文化財に指定されています。"},{"tag":"へえ","hook":"足元に気を引き締める「すかし橋」","t":"五大堂がある小島に架かる「すかし橋」は、橋げたの隙間から海が見えます。足元を見て気を引き締めるために造られたと言われます。"},{"tag":"へえ","hook":"33年に1度だけ開く秘仏","t":"五大堂の本尊・五大明王像は、33年に1回開扉の秘仏です。五大堂のある島とは、本州から橋で繋がっています。"},{"tag":"歴史","hook":"瑞巌寺は政宗の造営","t":"瑞巌寺の桃山建築の本堂などの国宝建築を含む伽藍は、伊達政宗の造営によるもの。1604年から1609年の全面改築で完成しました。"},{"tag":"ゆかり","hook":"政宗が手植えした梅と伝わる","t":"瑞巌寺の境内には、「臥龍梅」と呼ばれる紅白2本の梅の木があり、伊達政宗の手植えと伝えられています。"},{"tag":"ゆかり","hook":"『どんぐりころころ』の作詞者は松島出身","t":"童謡『どんぐりころころ』の作詞者・青木存義は、松島町の出身です。"},{"tag":"味","hook":"松島の名産はカキ","t":"松島町は観光と水産業によって立つ町で、特にカキ（牡蠣）は名産とされます。"},{"tag":"クイズ","q":"日本三景の松島は、およそ何個の島々からなる?","a":"約260の島々です。"}]},"板柳町":{"pref":"青森県","cards":[{"tag":"車窓","hook":"竣工時は東洋一の高さ","t":"板柳町配水場は高さ57.2mで、竣工時は東洋一の高さを誇った町のランドマークです。","teaser":true},{"tag":"数字","hook":"県内で小さい方の町","t":"面積は約41.9km²で、県内40市町村中38位。人口は約12,681人（2021年）です。"},{"tag":"へえ","hook":"樹齢600〜700年のイチイ","t":"横沢の無量庵には、推定樹齢600年〜700年の県天然記念物イチイがあります。諏訪氏の屋敷跡と伝えられています。"},{"tag":"出身","hook":"板柳町出身の有名人","t":"板柳町出身には、元小結力士の高見盛精彦、陸上選手の福士加代子、元関脇力士の追風海直飛人がいます。"},{"tag":"歴史","hook":"川の水運で栄えた町","t":"岩木川の水運で発展し、弘前藩の代官所が置かれました。町の構造に枡形が残っています。"},{"tag":"歴史","hook":"リンゴ出荷で駅が大にぎわい","t":"昭和中期まではリンゴの出荷が鉄道頼みだったため、板柳駅は大いに賑わいました。"},{"tag":"歴史","hook":"昔の名は「板屋野木村」","t":"1895年に板屋野木村が改称して、板柳村となりました。"},{"tag":"クイズ","q":"板柳町が1972年に提携したアメリカの市は？","a":"ワシントン州ヤキマ市"},{"tag":"味","hook":"ニンニクやマコモダケも作る","t":"板柳町では、リンゴや米のほか、ときわにんにくやマコモダケも作られています。"},{"tag":"車窓","hook":"三つの温泉がある町","t":"板柳町には、板柳温泉、あすなろ温泉、高増温泉があります。"},{"tag":"ゆかり","hook":"高見盛と福士加代子の町","t":"板柳町出身の有名人には、元小結の高見盛や、陸上選手の福士加代子がいます。"},{"tag":"歴史","hook":"町民歌は「知恵と大和」","t":"1975年に、板柳町民憲章と町民歌「知恵と大和」が制定されました。"}]},"柳津町":{"pref":"福島県","cards":[{"tag":"歴史","hook":"柳津に伝わる赤べこの伝説","t":"会津地震で被害を受けた虚空藏堂の再建で、資材運びを赤毛の牛の群れが助けました。人々はこの牛を「赤べこ」と呼んだといいます。","teaser":true},{"tag":"数字","hook":"約175.8km²に約3,065人が暮らす町","t":"面積は約175.8km²、人口は約3,065人（2021年）。1km²あたり約17人です。"},{"tag":"へえ","hook":"赤べこの黒い斑点は痘の印","t":"赤べこの赤い体色には魔除けの効果があるとされ、黒い斑点は痘を表します。病が重くならないよう、子どもに贈る風習がありました。"},{"tag":"車窓","hook":"あかべこ通り商店街","t":"圓蔵寺の門前町には粟饅頭屋が軒を連ね、「あかべこ通り商店街」が形成されています。"},{"tag":"車窓","hook":"只見川の「魚淵」","t":"只見川と銀山川の合流点にあるウグイの生息地「魚淵」は、「柳津ウグイ生息地」として国の天然記念物になっています。"},{"tag":"歴史","hook":"水を運んで稲作地帯になった郷戸原","t":"只見川の水面から100mほどの高さにある郷戸原は、もとは稲作が困難でした。西山地区からトンネルで水を運ぶ用水路が昭和20年代にでき、稲作地帯になりました。"},{"tag":"へえ","hook":"硫化水素も出荷する地熱発電所","t":"柳津西山地熱発電所は、発電の際に噴き出す硫化水素等を回収し、肥料や火薬の原料として企業に出荷しています。"},{"tag":"へえ","hook":"0.2cmの小さな仏像","t":"柳津町の微細彫刻は、大きさ0.2〜3.5cmほどの小さな仏像です。2024年現在、技術を持つのは町内に1人のみです。"},{"tag":"味","hook":"卵焼きが敷かれたソースカツ丼","t":"柳津のソースカツ丼は、カツの下に卵焼きが敷かれるのが特徴です。"},{"tag":"歴史","hook":"日本三大虚空蔵尊の円蔵寺","t":"柳津温泉には、日本三大虚空蔵尊の福満虚空蔵尊がある円蔵寺があり、源泉も境内にあります。"},{"tag":"ゆかり","hook":"作品『ジヌよさらば』","t":"『ジヌよさらば〜かむろば村へ〜』は、柳津町がメインのロケ地となった作品です。"},{"tag":"クイズ","q":"赤べこの「べこ」とは、東北地方の方言で何のこと?","a":"牛"}]},"柴田町":{"pref":"宮城県","cards":[{"tag":"車窓","hook":"城跡の桜約1000本と白石川","t":"船岡城址公園には約1000本の桜があり、春には白石川堤防沿いの桜並木と一体になって、美しい桜の景観をつくります。"},{"tag":"数字","hook":"約54.0km²に約38,638人が暮らす町","t":"面積は約54.0km²、人口は約38,638人（2021年）。1km²あたり約715人です。"},{"tag":"へえ","hook":"城跡にある「樅ノ木」のモデル","t":"船岡城址公園には、山本周五郎作「樅ノ木は残った」のモデルになった樅木があります。もみの木は町の木です。","teaser":true},{"tag":"出身","hook":"柴田町出身の有名人","t":"柴田町出身には、小説家の大池唯雄、歌人の小池光、漫画家の安孫子三和がいます。"},{"tag":"歴史","hook":"大河ドラマで城跡が注目に","t":"1970年、NHK大河ドラマ『樅ノ木は残った』の放送で船岡城が注目を浴び、第1回「しばた菊人形まつり」が開かれました。"},{"tag":"歴史","hook":"悪人から忠臣に描かれた原田甲斐","t":"『樅ノ木は残った』は、従来は悪人とされてきた原田甲斐を、取り潰しから藩を守るために尽力した忠臣として描いた小説です。"},{"tag":"へえ","hook":"船岡平和観音の建立","t":"船岡城址公園の「船岡平和観音」は、1975年に柴田町出身の個人が7500万円をかけて建立しました。"},{"tag":"ゆかり","hook":"U字工事・福田薫さんの母方の実家","t":"漫才コンビU字工事の福田薫さんは、母方の実家が柴田町船岡中央にある和菓子屋・仙台屋菓子本舗です。"},{"tag":"ゆかり","hook":"直木賞作家・大池唯雄","t":"大池唯雄は柴田町出身の小説家で、第8回直木賞を受賞しました。"},{"tag":"クイズ","q":"船岡城址公園と白石川堤一目千本桜が宮城県で唯一選ばれた「日本さくら名所○○選」。○○に入る数字は?","a":"100"}]},"栗原市":{"pref":"宮城県","cards":[{"tag":"へえ","hook":"馬の雪形が名前の由来","t":"栗駒山の名は、初夏になると山頂西側に現れる「駒姿」と呼ばれる馬の雪形に由来します。","teaser":true},{"tag":"数字","hook":"県内で面積1位","t":"面積は約805.0km²で、県内35市町村中1位の広さ。人口は約63,689人（2021年）です。"},{"tag":"車窓","hook":"栗駒山の紅葉は「神の絨毯」","t":"栗駒山の紅葉は「神の絨毯」と称され、秋分のころ山頂から始まり、10月上旬にかけて次第に麓に降りてきます。"},{"tag":"出身","hook":"栗原市出身の有名人","t":"栗原市出身には、俳優の菅原文太、脚本家の宮藤官九郎、お笑いタレントの狩野英孝、タレントの高橋ジョージがいます。"},{"tag":"へえ","hook":"成立時、宮城県最大の面積に","t":"栗原市は、2005年4月1日の成立で、宮城県最大の面積を持つ地方自治体になりました。"},{"tag":"クイズ","q":"栗原市の最高地点は栗駒山の標高1,627.4mです。では、最低地点の標高は何メートルでしょう?","a":"1.8mです。市内には大きな高低差があります。"},{"tag":"歴史","hook":"大名が泊まった有壁宿本陣","t":"旧有壁宿本陣は1619年に創設され、参勤交代制度の確立後は、松前・八戸・盛岡・一関の各藩主や藩重臣が宿泊所として使いました。"},{"tag":"歴史","hook":"鉛の生産量で日本一に","t":"1895年、栗原市の細倉鉱山が鉛の生産量で日本一になりました。"},{"tag":"へえ","hook":"鉱山で使われた地方貨幣","t":"江戸時代末、細倉鉱山で産出された鉛から、鉱山で使用するための地方貨幣「細倉当百」が発行されました。"},{"tag":"歴史","hook":"秋田との境の関所・寒湯番所","t":"仙台藩の寒湯番所は秋田へ通じる街道の関所です。慶長年間からの200余年間、往来する人と荷物の検問を行っていました。"},{"tag":"車窓","hook":"縄文の暮らしを復元した公園","t":"山王囲遺跡の一部は史跡公園で、復元された竪穴建物や資料館（山王ろまん館）があります。隣接するアヤメ園は初夏に花を咲かせます。"},{"tag":"ゆかり","hook":"文太さんもらんぼうさんも","t":"俳優の菅原文太さんは旧一迫町、シンガーソングライターのみなみらんぼうさんは旧志波姫町の生まれです。"},{"tag":"クイズ","q":"栗駒山の別名のうち、宮城県側で呼ばれる名前は何でしょう?","a":"駒ヶ岳です。岩手県では須川岳、秋田県では大日岳とも呼ばれます。"}]},"桑折町":{"pref":"福島県","cards":[{"tag":"へえ","hook":"桑折の名は郡衙と養蚕から?","t":"郡司が政務を執る郡衙があったため「郡(こおり)」と呼ばれ、それが桑折となったのは養蚕が盛んなためともいわれます。","teaser":true},{"tag":"数字","hook":"約43.0km²に約11,425人が暮らす町","t":"面積は約43.0km²、人口は約11,425人（2021年）。1km²あたり約266人です。"},{"tag":"味","hook":"献上桃の郷","t":"桑折町の桃は、記事の時点で20年以上連続して皇室・宮家への献上桃に選ばれ、町は「献上桃の郷」と呼んでいます。"},{"tag":"出身","hook":"桑折町出身の有名人","t":"桑折町出身には、アニメ演出家の新房昭之、歴史研究者の角田文衞、哲学者の野村隈畔がいます。"},{"tag":"味","hook":"リンゴ「王林」発祥の地","t":"桑折町は、リンゴの品種「王林」発祥の地です。リンゴの生産も盛んです。"},{"tag":"歴史","hook":"羽州街道の分かれ道・桑折宿","t":"江戸時代の桑折は、羽州街道が奥州街道から分かれる追分でした。江戸と出羽国を行き来するには桑折宿を経由するのが普通でした。"},{"tag":"歴史","hook":"郡役所を誘致した桑折町","t":"伊達郡の郡役所は保原町に設置されましたが、桑折町の有志の誘致運動で、1883年に桑折町へ移されました。"},{"tag":"車窓","hook":"旧伊達郡役所は擬洋風建築","t":"旧伊達郡役所は、地元大工の手による擬洋風建築。残っている郡役所の建物の中では最大規模です。"},{"tag":"歴史","hook":"伊達稙宗が移った桑折西山城","t":"1532年、伊達稙宗は居城を梁川城から桑折西山城に移しました。西山城は文字通り陸奥国守護の府城となりました。"},{"tag":"車窓","hook":"東西1キロの桑折西山城","t":"桑折西山城は、高舘・中舘・西舘の3か所を中心に、東西1キロメートル、南北500メートルの規模をもつ山城です。"},{"tag":"ゆかり","hook":"ハワイ州選出の米上院議員","t":"アメリカ合衆国上院議員(ハワイ州選出)のメイジー・ヒロノさんは、桑折町の出身です。"},{"tag":"クイズ","q":"桑折西山城で1536年に制定された、伊達氏の分国法は?","a":"塵芥集"},{"tag":"クイズ","q":"桑折町が発祥の地とされるリンゴの品種は?","a":"王林"}]},"棚倉町":{"pref":"福島県","cards":[{"tag":"へえ","hook":"亀ヶ城、大亀が出ると転封？","t":"棚倉城の別名は「亀ヶ城」。濠に大亀が棲み、浮かび上がると決まって殿様が転封になるという言い伝えによります。","teaser":true},{"tag":"数字","hook":"約159.9km²に約13,264人が暮らす町","t":"面積は約159.9km²、人口は約13,264人（2021年）。1km²あたり約83人です。"},{"tag":"歴史","hook":"神社を遷して築いた棚倉城","t":"棚倉城は寛永2年、丹羽長重が築きました。棚倉盆地の中央にあった都都古別神社を遷宮し、その跡地に建てられました。"},{"tag":"出身","hook":"棚倉町出身の有名人","t":"棚倉町出身には、作家の稲川方人、歴史学者の青木美智男がいます。"},{"tag":"車窓","hook":"茨城県最高峰、八溝山","t":"八溝山は、棚倉町と茨城県の境にある標高1,021.8mの山で、茨城県最高峰です。"},{"tag":"へえ","hook":"山頂に城の形の展望台","t":"八溝山の山頂には、日本の城を模した展望台があります。気象条件に恵まれれば、筑波山や富士山が見えることもあります。"},{"tag":"歴史","hook":"同じ名の神社が町に2社","t":"棚倉町には都々古別神社が2社あります。どちらが『延喜式』に載る神社かは古来論争があり、現在もはっきりしていません。"},{"tag":"へえ","hook":"八槻の地名は8本の矢から","t":"八槻の地名には伝承があり、日本武尊が放った8本の矢がいずれも槻の木になったので「八槻」になったともいわれます。"},{"tag":"へえ","hook":"ギリシャのスパルタと友好都市","t":"棚倉町はギリシャのスパルタと国際友好都市です。同じ北緯37度にあることなどから、町が提携を提案しました。"},{"tag":"歴史","hook":"川越市と友好都市の縁","t":"埼玉県の川越市と友好都市です。1866年に棚倉藩主の松平康英が川越に転封された縁によります。"},{"tag":"ゆかり","hook":"唱歌の作詞者は棚倉出身","t":"国学者・唱歌作詞者の稲垣千穎は、棚倉町の出身です。"},{"tag":"へえ","hook":"八槻の御田植は国の文化財","t":"八槻都都古別神社の御田植は、国の重要無形民俗文化財に指定されています。"},{"tag":"クイズ","q":"棚倉町の町名は「たなぐら」。駅名「磐城棚倉」の読みは「いわき」の後が？","a":"たなくら(濁らない)"}]},"楢葉町":{"pref":"福島県","cards":[{"tag":"車窓","hook":"水戸と仙台のちょうど真ん中","t":"道の駅ならはは、水戸市と仙台市の中間点で、両市まで123kmです。","teaser":true},{"tag":"歴史","hook":"8000年以上前から人が住んだ","t":"楢葉町では、北向遺跡や天神原遺跡の発掘調査から、8000～13000年前の先土器時代から人が住んでいたとされます。"},{"tag":"出身","hook":"楢葉町出身の有名人","t":"楢葉町出身には、プロ野球選手の赤間謙、料理研究家の永山久夫がいます。"},{"tag":"歴史","hook":"楢葉一族が300年支配","t":"平安末期、岩城氏の一族の楢葉太郎隆祐が楢葉郡を支配し、以降300年、楢葉一族が支配しました。"},{"tag":"歴史","hook":"楢葉郡の中心だった町","t":"古代、現在の広野町から大熊町あたりは楢葉郷と呼ばれていたらしく、楢葉町は平安末期にできた楢葉郡の中心地域でした。"},{"tag":"車窓","hook":"海寄りの2割が平地","t":"楢葉町は浜通りのほぼ中央にあり、海寄りの約2割が平地で、中央部・西部は阿武隈高地の山地です。"},{"tag":"味","hook":"特産の柚子を使った品","t":"道の駅ならはの売店では、特産の柚子を使った製品などが販売されています。"},{"tag":"ゆかり","hook":"食文化史研究家の名誉町民","t":"料理研究家・食文化史研究家の永山久夫さんは、楢葉町の出身で、名誉町民です。"},{"tag":"へえ","hook":"会津美里町と姉妹都市","t":"楢葉町は、会津美里町と姉妹都市です。アメリカ・オハイオ州のユークリッド市とも姉妹都市です。"},{"tag":"歴史","hook":"2015年に避難指示が解除","t":"楢葉町では2015年4月6日に準備宿泊が始まり、9月5日に避難指示が解除されました。"},{"tag":"クイズ","q":"2013年に楢葉町の沖合で実証試験が始まった発電施設は？","a":"浮体式洋上風力発電"}]},"横手市":{"pref":"秋田県","cards":[{"tag":"へえ","hook":"横手の雪像は札幌より古い","t":"横手の雪像展示は1939年に始まりました。さっぽろ雪まつりの初回は1950年で、横手の方が長い歴史があります。","teaser":true},{"tag":"数字","hook":"県内で人口2位","t":"人口は約84,556人（2021年）で、県内25市町村中2位。面積は約692.8km²です。"},{"tag":"へえ","hook":"約450年続くかまくら","t":"横手のかまくらは約450年の歴史がある小正月行事。雪洞に水神を祀り、子どもたちが甘酒やお餅を振る舞います。"},{"tag":"味","hook":"黄身を崩すのが横手流","t":"横手やきそばは、目玉焼きの黄身を崩してソースと絡めて食べるのが横手流。麺は茹でた角麺で、付け合せは福神漬けです。"},{"tag":"クイズ","q":"2009年のB-1グランプリで優勝した、横手のご当地グルメは？","a":"横手やきそば"},{"tag":"味","hook":"ホルモン焼きそばの発祥","t":"ホルモン焼きそばの発祥は駅西の「まいど」。お客が、注文したホルモン焼きの残りを焼きそばに入れてほしいと頼んだのがきっかけとされます。"},{"tag":"歴史","hook":"漫画の原画を守る美術館","t":"増田まんが美術館は、矢口高雄の偉業を記念して1995年10月に開館。日本で初めて「漫画の原画」をテーマにした美術館です。"},{"tag":"ゆかり","hook":"『山と川のある町』の舞台","t":"小説家の石坂洋次郎は、横手で13年間、教鞭をとりました。横手は、彼の多くの作品の舞台になっています。"},{"tag":"車窓","hook":"城に天守はなく展望台が建つ","t":"横手城に本来、天守はありません。1965年に二の丸跡に建てられた模擬天守の頂上から、鳥海山と横手盆地を一望できます。"},{"tag":"車窓","hook":"蔵が奥に隠れる増田の町並み","t":"増田の町並みは国の重要伝統的建造物群保存地区。主屋の背後に設けられた「内蔵」と呼ばれる鞘付き土蔵が特徴です。"},{"tag":"へえ","hook":"ホップの生産は全国トップ","t":"大雄地域で盛んなホップは、市町村別の生産数で全国トップに躍り出ました（2021年～2023年）。"},{"tag":"クイズ","q":"横手城は、急斜面に何を植えたことから別名「韮城」と呼ばれた？","a":"韮（ニラ）"}]},"横浜町":{"pref":"青森県","cards":[{"tag":"へえ","hook":"横浜は神奈川より先輩","t":"青森の横浜町は、神奈川県横浜市よりも先に誕生したそうです。","teaser":true},{"tag":"数字","hook":"約126.4km²に約4,133人が暮らす町","t":"面積は約126.4km²、人口は約4,133人（2021年）。1km²あたり約33人です。"},{"tag":"車窓","hook":"菜の花の作付面積は全国トップ級","t":"菜の花の作付面積は、2012年に128ヘクタールで全国一位になりました。"},{"tag":"出身","hook":"横浜町出身の有名人","t":"横浜町出身には、女優の木野花、ロックバンドの秋田ひろむがいます。"},{"tag":"へえ","hook":"北限のゲンジボタル","t":"ゲンジボタルの生息地の北限とされ、県の天然記念物です。吹越地区のよこはまホタル村では、毎年7月にまつりがあります。"},{"tag":"歴史","hook":"ヒノキ板が木綿に化けた","t":"ヒノキ板四枚と大阪木綿一反を交換していました。地元ではそのヒノキ板を「寸法」、木綿を「寸模」と呼びました。"},{"tag":"歴史","hook":"軽石を神体にしたという八幡","t":"源義家が波を射つつ祈ると時化がおさまり、その波が後に軽石となって浜に上がったと言われます。その軽石を神体とする八幡神社を勧進したといいます。"},{"tag":"味","hook":"やわらかい横浜ナマコ","t":"「横浜ナマコ」は町の魚に指定され、他の地域のナマコよりやわらかく食感もよいそうです。地域団体商標にも登録されています。"},{"tag":"味","hook":"酒粕を食べる豚","t":"ブランド豚「ほろよい豚」は、飼料に酒粕を加えているのが特徴です。"},{"tag":"歴史","hook":"半島を横断する運河計画","t":"南部藩では1673年に下北半島を横断する運河の計画が持ち上がり、そのうちの一つが横浜と六ヶ所村泊を結ぶ案でしたが、計画のみで終わりました。"},{"tag":"クイズ","q":"横浜町は2012年に、菜の花の作付面積で全国何位を奪還した？","a":"全国一位"},{"tag":"歴史","hook":"菜の花栽培は凶作がきっかけ","t":"横浜町の菜の花栽培は、1932年に農業経済更生指定村に指定されたとき、ナタネを導入したのが始まりです。"},{"tag":"へえ","hook":"約2000発の花火","t":"よこはま夏まつり花火大会は毎年8月14日で、夜には約2000発の花火が横浜漁港で打ち上げられます。"},{"tag":"数字","hook":"ホタテ養殖は青森県第2位","t":"横浜町のホタテ養殖(耳づり)は、平内町に次いで青森県第2位です。"}]},"檜枝岐村":{"pref":"福島県","cards":[{"tag":"へえ","hook":"住所は「檜枝岐村燧ヶ岳」","t":"「福島県南会津郡檜枝岐村燧ヶ岳」の住所は、日本郵便から交通困難地に指定されていて、郵便は届きません。","teaser":true},{"tag":"数字","hook":"人より自然が多い町","t":"1km²あたり約1人。県内で下から1番目の人口密度です。"},{"tag":"へえ","hook":"福島県で最も人口が少ない村","t":"檜枝岐村は福島県内で人口が最も少なく、日本一人口密度の低い村です。"},{"tag":"歴史","hook":"夏は山の「出作り小屋」で","t":"昭和30年頃まで、夏は山間の「出作り小屋」で暮らして焼畑をしました。小屋は多いときで60軒ほどあったといいます。"},{"tag":"車窓","hook":"屋根は赤錆色にそろえて","t":"檜枝岐村では1979年に、景観保全のため家々の屋根を赤錆色に統一しました。"},{"tag":"ゆかり","hook":"村の名字は星・平野・橘","t":"村民の大多数の名字は「星」「平野」「橘」の3つに大別されます。「星」姓は藤原氏の落人の系譜につながるとされます。"},{"tag":"味","hook":"薄く重ねて切る裁ち蕎麦","t":"裁ち蕎麦は、つなぎを使わず薄く伸ばした生地を何層にも重ね、布を裁つ要領で切って作ります。"},{"tag":"車窓","hook":"東北で最も高い燧ケ岳","t":"燧ケ岳(2,356m)は、東北地方で最も標高が高い山です。"},{"tag":"へえ","hook":"燧ヶ岳の名は「火打ちばさみ」","t":"燧ヶ岳の名は、麓から見える残雪が火打ちばさみに似ていることに由来します。"},{"tag":"ゆかり","hook":"尾瀬を拓いた平野長蔵","t":"平野長蔵は檜枝岐村出身の自然保護活動家で、尾瀬を拓いた先駆者です。山小屋・長蔵小屋の初代主人でした。"},{"tag":"車窓","hook":"三条の滝は落差100m","t":"三条の滝は日本の滝百選に定められ、日本三大名瀑に選ばれることもあります。落差100m、幅30m（諸説あり）の直瀑です。"},{"tag":"クイズ","q":"檜枝岐村の村民に多い名字は「星」「平野」と、もう一つは何?","a":"橘"}]},"気仙沼市":{"pref":"宮城県","cards":[{"tag":"へえ","hook":"朝6時は『恋はみずいろ』","t":"気仙沼の防災無線は1日4回鳴ります。6時は『恋はみずいろ』、18時は『新世界より』の「家路」が流れます。","teaser":true},{"tag":"数字","hook":"約332.4km²に約59,341人が暮らす町","t":"面積は約332.4km²、人口は約59,341人（2021年）。1km²あたり約179人です。"},{"tag":"歴史","hook":"ビスカイノがたたえた港","t":"1611年、セバスティアン・ビスカイノが気仙沼を測量し、仙台藩領内最良の港湾とたたえました。"},{"tag":"出身","hook":"気仙沼市出身の有名人","t":"気仙沼市出身には、フリーアナウンサーの生島ヒロシ、シンガーソングライターの畠山美由紀、走り幅跳び選手の谷真海、第9代横綱の秀ノ山雷五郎がいます。"},{"tag":"へえ","hook":"カツオもサンマも行き交う港","t":"気仙沼には、カツオを追って北上する漁船や、サンマを追って南下する北海道などの漁船に乗った漁民が行き交います。"},{"tag":"味","hook":"味噌ニンニクだれのホルモン","t":"気仙沼ホルモンは、味噌ニンニクだれに漬け込み、千切りキャベツにウスターソースをかけて一緒に食べる豚のホルモン焼きです。"},{"tag":"ゆかり","hook":"糸井重里さんと気仙沼","t":"ほぼ日刊イトイ新聞が気仙沼に支社を設け、糸井重里さんの助言を受けてセーター製造会社が起業されるなど、新しい動きが見られます。"},{"tag":"車窓","hook":"ツツジの名山・徳仙丈山","t":"徳仙丈山は、ツツジの名山として知られる、日本最大級のツツジの群生地です。標高は711メートルです。"},{"tag":"車窓","hook":"カモシカが暮らす安波山","t":"市街地の北にある安波山には、国の天然記念物のニホンカモシカが多数生息し、市街地に姿を現して市民を驚かせることもあります。"},{"tag":"へえ","hook":"氷の中の魚を見る水族館","t":"気仙沼の「氷の水族館」は、魚介類が生きているかのように氷の中に展示する施設で、館内はマイナス20℃に保たれています。"},{"tag":"車窓","hook":"大島は「気仙沼の防波堤」","t":"気仙沼湾の入口にある大島のおかげで湾内は常に穏やかです。気仙沼漁港は天然の良港で、大島は「気仙沼の防波堤」とも呼ばれます。"},{"tag":"クイズ","q":"気仙沼で水揚げ量が日本一の食材といえば何でしょう?","a":"ふかひれです。マグロ、カツオ、サンマも全国有数の水揚げ高です。"},{"tag":"クイズ","q":"「気仙沼」の地名の由来で最も有力とされる、アイヌ語の言葉は何でしょう?","a":"「ケセ・モイ」です。「終端の湾」を意味するという説です。"}]},"河北町":{"pref":"山形県","cards":[{"tag":"味","hook":"氷なしで「冷たい」肉そば","t":"河北町谷地の名物「冷たい肉そば」は、氷は入れず常温で提供されます。具は鶏肉とネギで、つゆは鶏骨だしで冷たくしてあります。","teaser":true},{"tag":"数字","hook":"県内で小さい方の町","t":"面積は約52.5km²で、県内35市町村中33位。人口は約17,435人（2021年）です。"},{"tag":"味","hook":"冷たい肉そば、誕生の説いろいろ","t":"冷たい肉そばの誕生は定かではありません。「温かい汁だとそばが伸びてしまうから」など、いくつかの説があります。"},{"tag":"出身","hook":"河北町出身の有名人","t":"河北町出身には、演歌歌手の大泉逸郎、落語家の桂南治、ドイツ文学者の新関良三がいます。"},{"tag":"へえ","hook":"全国唯一のベニバナの資料館","t":"河北町の紅花資料館は、ベニバナの資料や享保雛などを展示する、全国唯一のベニバナの資料館です。"},{"tag":"歴史","hook":"紅花と舟運で栄えた谷地","t":"河北町は、かつて紅花・青苧の集積地、最上川舟運の船着場として栄えました。町でありながらアーケード街があるのも、その残影です。"},{"tag":"クイズ","q":"山形県の中で唯一、「町」を「ちょう」と読む自治体はどこでしょう?","a":"河北町（かほくちょう）です。"},{"tag":"ゆかり","hook":"世界卓球の優勝選手の出身町","t":"河北町は卓球の町。1971年の世界卓球選手権で優勝した女子団体チーム4人のうち、小和田敏子さんと大場恵美子さんが河北町の出身です。"},{"tag":"へえ","hook":"サクランボとスリッパの町","t":"河北町は、サクランボの生産量が町村で日本一。スリッパの生産は、全国生産額の4分の1を占めます。"},{"tag":"歴史","hook":"かつて走った谷地軌道","t":"河北町に鉄道を延ばす計画は、農家の反対で白紙になりました。ただ、神町駅と谷地を結ぶ谷地軌道が、1915年から1935年まで走っていました。"},{"tag":"へえ","hook":"日本四大舞楽の一つが残る","t":"谷地八幡宮の9月の例祭で奉納される「谷地の舞楽」は、林家が一子相伝で伝承。日本四大舞楽の一つとされ、重要無形民俗文化財です。"},{"tag":"ゆかり","hook":"染め物がつないだ友好都市","t":"河北町は、藍染めと紅染めの染め物つながりで徳島県藍住町と、同じ町名が縁で宮城県石巻市（旧河北町）と友好都市になっています。"}]},"泉崎村":{"pref":"福島県","cards":[{"tag":"へえ","hook":"初めて国際規格を満たした競技場","t":"泉崎国際サイクルスタジアムは、日本の自転車競技場として初めて国際自転車競技連合の設計基準を満たした施設で、開設当時は日本で唯一でした。","teaser":true},{"tag":"数字","hook":"県内で小さい方の町","t":"面積は約35.4km²で、県内53市町村中50位。人口は約6,171人（2021年）です。"},{"tag":"歴史","hook":"壁に朱色で描かれた騎馬人","t":"泉崎横穴の石室の壁には、鹿を追う騎馬人や手をつなぐ4人の人物が朱色で描かれています。7世紀前半の古墳です。"},{"tag":"出身","hook":"泉崎村出身の有名人","t":"泉崎村出身には、外交官の石射猪太郎、アニメーターのパロ穂積がいます。"},{"tag":"歴史","hook":"県道工事で見つかった横穴","t":"泉崎横穴は1933年の県道工事中に発見されました。翌年、装飾のある古墳の珍しい例として国の史跡に指定されました。"},{"tag":"歴史","hook":"古代の白河郡の郡家跡","t":"関和久官衙遺跡は、陸奥国白河郡の郡家跡と推定される遺跡です。白河関を統括する施設とする説もあります。"},{"tag":"歴史","hook":"白河地方の中心だった一帯","t":"6世紀後半から8世紀初めまで、白河地方の中心は泉崎村南部と白河市北部のあたりだったと推定されています。"},{"tag":"ゆかり","hook":"元関脇・玉乃島は泉崎村出身","t":"大相撲の元関脇・玉乃島（岡部新）は、泉崎村の出身です。"},{"tag":"ゆかり","hook":"マンスフィールドの記念館","t":"泉崎村には、大正大学の教授が開いた、作家キャサリン・マンスフィールドの記念館があります。"},{"tag":"車窓","hook":"烏峠の秋のイベント","t":"秋には村内の烏峠でオータムフェスティバルがあり、県外からも人が訪れます。ウォーキングなどの行事が行われます。"},{"tag":"クイズ","q":"泉崎国際サイクルスタジアムのバンクは、1周何m？","a":"333.3m"}]},"洋野町":{"pref":"岩手県","cards":[{"tag":"へえ","hook":"岩手の沿岸でいちばん北の町","t":"洋野町は岩手県沿岸部最北端の町で、三陸地方の北部に位置します。"},{"tag":"数字","hook":"約302.9km²に約14,757人が暮らす町","t":"面積は約302.9km²、人口は約14,757人（2021年）。1km²あたり約49人です。"},{"tag":"へえ","hook":"海の畑「増殖溝」","t":"洋野町の海岸には平坦な岩盤が沖合150メートルほどまで張り出し、ウニやアワビの繁殖を助ける「増殖溝」が掘られています。","teaser":true},{"tag":"出身","hook":"洋野町出身の有名人","t":"洋野町出身には、小説家の河崎愛美、円盤投げ選手の大井利江がいます。"},{"tag":"へえ","hook":"漁協が掘った総延長18キロ","t":"増殖溝は漁協が総延長18キロメートルほど掘ったもの。満潮時の海水が残り、海藻が干上がるのを防ぎます。"},{"tag":"味","hook":"ウニとホヤの種市","t":"旧種市町は漁業が盛んで、ウニとホヤが特産物です。"},{"tag":"へえ","hook":"シンボルは南部もぐりの潜水士","t":"洋野町のシンボルキャラクター「ダイちゃん」は、南部もぐりの潜水士です。"},{"tag":"歴史","hook":"潜水夫を育てる高校","t":"洋野町種市では1952年に潜水科が設置され、国内で潜水夫を養成する唯一の高校として続いているとされます。"},{"tag":"車窓","hook":"列車に大漁旗で手を振る","t":"観光列車「TOHOKU EMOTION」の町内通過時に、手や大漁旗を振って歓迎する「洋野エモーション」が行われてきました。"},{"tag":"歴史","hook":"町名は一般公募で決まった","t":"洋野町の町名は一般公募で決まった瑞祥地名（めでたい意味の地名）。「洋野」の「野」は大野の「野」とは無関係です。"},{"tag":"車窓","hook":"ツツジ咲く階上岳","t":"青森県境の階上岳は臥牛山とも呼ばれ、ツツジの群生地があって観光客が多数訪れます。"},{"tag":"クイズ","q":"洋野町の町名は、どのように決まったでしょう？","a":"一般公募で決まった"},{"tag":"クイズ","q":"洋野町と青森県階上町の境にある、標高739.6mの山は？","a":"階上岳"}]},"浅川町":{"pref":"福島県","cards":[{"tag":"歴史","hook":"福島県で最も歴史のある花火","t":"毎年8月に浅川町花火大会が行われます。福島県で最も歴史のある花火とされ、浅川町は「花火の里」として知られています。","teaser":true},{"tag":"数字","hook":"約37.4km²に約6,018人が暮らす町","t":"面積は約37.4km²、人口は約6,018人（2021年）。1km²あたり約161人です。"},{"tag":"へえ","hook":"山頂で爆発させる大地雷火","t":"花火大会には約3万人が訪れ、数千発が打ち上げられます。城山の山頂で爆発させる「大地雷火」は圧巻です。"},{"tag":"出身","hook":"浅川町出身の有名人","t":"浅川町出身には、病理学者の吉田富三、漫画家の江田二三夫、プロボクサーの矢吹純がいます。"},{"tag":"ゆかり","hook":"三波春夫が名を上げた芝居小屋","t":"かつてあった芝居小屋・映画館の浅川座で、浪曲師の三波春夫は名を上げました。興行主の貝山実吉を「第二の父」と慕いました。"},{"tag":"ゆかり","hook":"文化勲章の病理学者は浅川町出身","t":"吉田富三は浅川町出身の病理学者で、文化勲章を受けました。浅川町の名誉町民です。"},{"tag":"歴史","hook":"1329年建立の板碑がある永昌寺","t":"永昌寺は曹洞宗の寺院です。嘉暦4年（1329年）に建立された板碑は、浅川町指定文化財です。"},{"tag":"車窓","hook":"戦国時代の山城、浅川城跡","t":"浅川城跡は戦国時代の山城です。中腹には白山比咩神社があります。"},{"tag":"歴史","hook":"越後高田藩領時代の浅川","t":"浅川には、越後高田藩領時代の百姓一揆「浅川騒動」や、その時代に置かれた「浅川陣屋」の歴史があります。"},{"tag":"クイズ","q":"福島県で最も歴史のある花火とされる浅川町は、何の里として知られる？","a":"花火の里"},{"tag":"クイズ","q":"浪曲師の三波春夫が名を上げた、浅川町にかつてあった芝居小屋・映画館は？","a":"浅川座"}]},"浪江町":{"pref":"福島県","cards":[{"tag":"へえ","hook":"冷めにくい湯呑みの秘密","t":"大堀相馬焼の湯呑みは冷めにくいといわれます。外側と内側を別に作って被せる二重焼の技術は、他ではまず見られません。","teaser":true},{"tag":"歴史","hook":"馬の家紋が器の図柄に","t":"大堀相馬焼は、藩主・相馬氏の家紋から繋ぎ駒や走り駒が意匠になっており、縁起物として好まれます。"},{"tag":"出身","hook":"浪江町出身の有名人","t":"浪江町出身には、作曲家の佐々木俊一、歌人の三原由起子、ピアニストの添田哲平がいます。"},{"tag":"歴史","hook":"窯元が100軒近くに","t":"大堀相馬焼は江戸時代末期に100軒近い窯元が誕生。戊辰戦争後に衰微しましたが、戦後に再興し、1978年に国の伝統的工芸品の指定を受けました。"},{"tag":"味","hook":"太麺・モヤシ・豚肉・ラード","t":"なみえ焼そばは太めの麺が特徴。具はモヤシと豚肉で、ラードで炒め、一味唐辛子を振りかけて食べるのが通な食べ方です。"},{"tag":"車窓","hook":"島に祀られていた神社","t":"苕野神社は昔、請戸地区の沖にあった「苕野小島」に鎮座。波浪で島が崩壊し、今の地へ遷座したといいます。"},{"tag":"へえ","hook":"ロケット発射場に立候補","t":"1969年、宇宙開発事業団がロケット発射場の候補地を探していた際、浪江町は自ら手を挙げましたが、実現しませんでした。"},{"tag":"へえ","hook":"「DASH村」は浪江町にあった","t":"2000年、バラエティ番組『ザ!鉄腕!DASH!!』の企画で「DASH村」が浪江町の西部に作られました。当時は非公表でした。"},{"tag":"歴史","hook":"漁船の出初式が7年ぶりに","t":"請戸漁港では2018年1月7日に漁船の出初式が7年ぶりに行われ、2020年4月8日には地方卸売市場の競りが再開されました。"},{"tag":"クイズ","q":"浪江町の請戸漁港は、福島県のどこにあたる?","a":"最東端"},{"tag":"クイズ","q":"なみえ焼そばの具は、モヤシと何?","a":"豚肉"}]},"涌谷町":{"pref":"宮城県","cards":[{"tag":"へえ","hook":"日本で初めて金が出た町","t":"749年、涌谷で日本で初めて金が産出しました。金は聖武天皇に献上され、奈良の東大寺の大仏に当てられたことで知られます。","teaser":true},{"tag":"数字","hook":"約82.2km²に約15,177人が暮らす町","t":"面積は約82.2km²、人口は約15,177人（2021年）。1km²あたり約185人です。"},{"tag":"歴史","hook":"矢が逆さ竹になった「箟」","t":"箟峯寺の「箟（のだけ）」の由来は、坂上田村麻呂が地面に矢を刺したところ、矢が根葉を生じて逆さ竹「のだけ」となったという伝承です。"},{"tag":"出身","hook":"涌谷町出身の有名人","t":"涌谷町出身には、評論家の扇谷正造、映画監督の若松孝二、声優の安野希世乃がいます。"},{"tag":"車窓","hook":"霧が山号の由来・箟峯寺","t":"箟峯寺は創建当初、霧岳山正福寺と称しました。当地の深い霧が山号の由来とされ、気象条件が揃うと雲海を観測できます。"},{"tag":"車窓","hook":"桜の名所・涌谷城跡","t":"涌谷城は現在、城山公園になっていて、春は桜の名所として知られます。城内には隅櫓（太鼓堂）が現存しています。"},{"tag":"歴史","hook":"幕末まで続いた涌谷伊達氏","t":"1591年、亘理重宗が涌谷城主となりました。以後、幕末に至るまで亘理氏（涌谷伊達氏）が涌谷を治めました。"},{"tag":"味","hook":"稲作と、ほうれん草・小ネギ","t":"涌谷町は「金のいぶき」など稲作が中心で、近年はほうれん草・小ネギの栽培が盛んな、国の指定産地です。"},{"tag":"味","hook":"独自品種「黄金レモン」","t":"涌谷町では、2021年から涌谷園芸ファームで、独自品種の「黄金レモン」も栽培されています。"},{"tag":"ゆかり","hook":"涌谷出身の力士たち","t":"涌谷町の出身者には、元大関の駒ヶ嶽國力、元前頭の伊達ノ花静、元十両の伊達錦一成と、力士の名が並びます。"},{"tag":"クイズ","q":"涌谷城に現存し、県内で唯一の城郭遺構になっている建物は何でしょう?","a":"隅櫓（太鼓堂）です。"},{"tag":"クイズ","q":"749年に涌谷で採れ、東大寺の大仏建立のために献上された金は、約何キログラムでしょう?","a":"金900両、約13kgです。"}]},"深浦町":{"pref":"青森県","cards":[{"tag":"車窓","hook":"日本最大のイチョウ","t":"北金ヶ沢には、日本最大のイチョウがあり、国の天然記念物になっています。"},{"tag":"数字","hook":"約488.9km²に約7,191人が暮らす町","t":"面積は約488.9km²、人口は約7,191人（2021年）。1km²あたり約15人です。"},{"tag":"へえ","hook":"十二湖なのに湖は33","t":"十二湖は、ブナの自然林に囲まれた33の湖沼群です。"},{"tag":"出身","hook":"深浦町出身の有名人","t":"深浦町出身には、元大相撲力士の安美錦竜児、放送作家の佐藤かんじ、漫画家のとみさわ千夏がいます。"},{"tag":"へえ","hook":"樹齢1,000年の関の甕杉","t":"関の甕杉は県天然記念物で、推定樹齢1,000年です。"},{"tag":"へえ","hook":"町の約90%が森林と原野","t":"深浦町は青森県下で5番目の大きさで、森林・原野の割合が約90%にのぼります。"},{"tag":"へえ","hook":"一時は関取4人で全国最多","t":"一時は、現役の関取が1つの市町村出身として全国最多の4人いました。"},{"tag":"へえ","hook":"全国初のたばこ自販機規制","t":"深浦町は全国初となる自動販売機の条例を施行し、たばこの自販機を新規設置できなくなりました。","teaser":true},{"tag":"歴史","hook":"北前船の資料館","t":"風待ち舘は北前船の展示資料館で、深浦町総合観光案内所でもあります。"},{"tag":"クイズ","q":"十二湖には、湖沼がいくつある？","a":"33"},{"tag":"クイズ","q":"北金ヶ沢にある、日本最大といわれる木は？","a":"イチョウ"},{"tag":"歴史","hook":"澗口観音と呼ばれる円覚寺","t":"円覚寺は「澗口観音」と呼ばれ、薬師堂内の厨子や船絵馬などが国の重要文化財です。"},{"tag":"車窓","hook":"太宰治ゆかりの文学館","t":"ふかうら文学館は、太宰治などゆかりの文人の資料を展示しています。"},{"tag":"ゆかり","hook":"俳優夫妻が観光特使に","t":"俳優の草野とおるさんは、妻の山田まりやさんとともに、深浦町の観光特使に委嘱されました。"}]},"湯川村":{"pref":"福島県","cards":[{"tag":"へえ","hook":"東北の仏像で初めて国宝に","t":"勝常寺の木造薬師如来及び両脇侍像は、1996年に東北地方の仏像では初めて国宝に指定されました。","teaser":true},{"tag":"数字","hook":"県内で小さい方の町","t":"面積は約16.4km²で、県内53市町村中53位。人口は約3,031人（2021年）です。"},{"tag":"歴史","hook":"平安初期の仏像が12体","t":"勝常寺には30余体の仏像があり、うち12体は平安時代初期のものです。これだけ多数残る寺は、畿内を除けば非常にまれです。"},{"tag":"出身","hook":"湯川村出身の有名人","t":"湯川村出身には、映画カメラマンの高羽哲夫、元日本ハムファイターズ投手の平松省二がいます。"},{"tag":"歴史","hook":"810年、徳一が開いた勝常寺","t":"810年（弘仁元年）に、学僧の徳一が勝常寺を開いたとされます。"},{"tag":"ゆかり","hook":"最澄と論争した僧・徳一","t":"勝常寺を開いたといわれる徳一は、会津地方を拠点に活動しました。最澄と論争したことでも知られます。"},{"tag":"歴史","hook":"会津の中央にある薬師堂","t":"勝常寺は会津五薬師の中心として、「会津中央薬師」と呼ばれるようになりました。"},{"tag":"歴史","hook":"室町時代の薬師堂","t":"勝常寺の薬師堂は、室町時代初期に蘆名氏家臣の富田祐持が再建したもので、国の重要文化財です。"},{"tag":"車窓","hook":"福島県で最も狭い村","t":"湯川村は会津盆地のほぼ中央にあり、平成の大合併で伊達町がなくなったことで、福島県で最も狭い市町村になりました。"},{"tag":"味","hook":"「米と文化の里」","t":"湯川村のスローガンは「米と文化の里」。主な産業は農業で、コシヒカリの会津湯川米を特産物とします。"},{"tag":"へえ","hook":"毎年4月28日は念仏踊り","t":"勝常寺では毎年4月28日に、薬師如来の祭礼として念仏踊りが催されます。"},{"tag":"クイズ","q":"湯川村の勝常寺の木造薬師如来及び両脇侍像が、国宝に指定されたのは何年?","a":"1996年（平成8年）"},{"tag":"クイズ","q":"湯川村で毎年4月28日に行われる念仏踊りは、どの仏様の祭礼?","a":"薬師如来"}]},"湯沢市":{"pref":"秋田県","cards":[{"tag":"へえ","hook":"世界に3つの強酸性温泉","t":"川原毛大湯滝の源泉は、世界に3つしかない強酸性温泉です。飛沫を浴びると、目がかすかにしみるような刺激があります。","teaser":true},{"tag":"数字","hook":"約790.9km²に約41,601人が暮らす町","t":"面積は約790.9km²、人口は約41,601人（2021年）。1km²あたり約53人です。"},{"tag":"へえ","hook":"滝つぼが天然の露天風呂","t":"川原毛大湯滝は、温泉が沢水と合流して高さ約20mから流れ落ちる、全国でも珍しい「滝の湯」。滝つぼは天然の露天風呂です。"},{"tag":"出身","hook":"湯沢市出身の有名人","t":"湯沢市出身には、第99代内閣総理大臣の菅義偉、元大相撲横綱の照國万藏、小説家の豊島ミホ、俳優の山崎裕太がいます。"},{"tag":"車窓","hook":"蒸気が噴き出す小安峡","t":"小安峡では、絶壁の岩間から98度にも達する蒸気が噴出する大噴湯が見られます。峡谷のハイライトになっています。"},{"tag":"味","hook":"中が空洞の稲庭うどん","t":"稲庭うどんは、ひねりながら練る独特の製法で麺の内部に気泡が生じ、中空になります。そのため滑らかな食感になります。"},{"tag":"クイズ","q":"1617年にローマで作られた地図にも名が記された、湯沢市の鉱山は？","a":"院内銀山"},{"tag":"歴史","hook":"出羽の都と呼ばれた銀山","t":"最盛期の院内銀山は、人口15,000を擁し、城下町久保田を凌駕する藩内で最も大きな街となり、「出羽の都」と呼ばれました。"},{"tag":"車窓","hook":"「東北のミニアルプス」神室山","t":"神室山を主峰とする神室連峰は、豪雪に磨かれた険しい山容から、別名「東北のミニアルプス」と呼ばれます。"},{"tag":"歴史","hook":"縄文時代の住まいの洞窟","t":"岩井堂洞窟は、全長約80mの凝灰岩の露頭にできた4つの洞窟で、いずれも縄文時代には住まいとして利用されました。"},{"tag":"ゆかり","hook":"小野小町の生誕地の伝説","t":"湯沢市には、歌人・小野小町の、諸説ある生誕地の一つという伝説があります。"},{"tag":"ゆかり","hook":"出身の元横綱と元大関","t":"湯沢市の出身者には、元大相撲横綱の照國万藏、元大相撲大関の清國勝雄がいます。"},{"tag":"クイズ","q":"湯沢市の三関地区で江戸時代から栽培されてきた、根が太く長いセリは？","a":"三関せり"}]},"滝沢市":{"pref":"岩手県","cards":[{"tag":"へえ","hook":"日本一人口が多かった村","t":"滝沢は2000年に人口5万人を超えても村のまま。2002年から日本一人口の多い村でしたが、2014年に市になりました。","teaser":true},{"tag":"数字","hook":"ぎゅっと人が集まる町","t":"1km²あたり約307人。県内33市町村中3位の人口密度です。"},{"tag":"へえ","hook":"おみくじ器は滝沢市の1社だけ","t":"ルーレット式おみくじ器を、2026年現在、滝沢市の北多摩製作所だけが製造しています。本業のかたわら、1983年から作っています。"},{"tag":"出身","hook":"滝沢市出身の有名人","t":"滝沢市出身には、サッカー選手の岩清水梓、タレントの福田萌、女優の加村真美がいます。"},{"tag":"歴史","hook":"チャグチャグ馬コは14キロの行列","t":"チャグチャグ馬コは、鬼越蒼前神社から盛岡八幡宮までの14キロメートルを、100頭ほどの華やかな馬が進みます。"},{"tag":"車窓","hook":"鈴の音が名前になった祭り","t":"チャグチャグ馬コは、馬が歩くたびに鈴が「チャグチャグ」と鳴る音が名前の由来です。1996年に「日本の音風景100選」に選ばれました。"},{"tag":"歴史","hook":"馬を葬った祠が神社の始まり","t":"鬼越蒼前神社の始まりは、暴れ出した馬が峠まで駆けてきて死んだのを、村人が手厚く葬って祠を建てたことといわれます。"},{"tag":"車窓","hook":"岩手山は県のシンボル","t":"岩手山は標高2,038mで、岩手県の最高峰です。「南部富士」とも呼ばれ、県のシンボルの一つです。"},{"tag":"へえ","hook":"日本最大の民間総合牧場","t":"小岩井農場は、総面積約3,000ヘクタールの日本最大の民間総合牧場です。"},{"tag":"ゆかり","hook":"「小岩井」は三人の頭文字","t":"「小岩井」の名は、創業に関わった小野・岩崎・井上の三名の頭文字から付けられました。"},{"tag":"ゆかり","hook":"賢治が歩いた小岩井農場","t":"宮沢賢治は小岩井農場をたびたび散策し、1922年5月の散策が長詩「小岩井農場」のもとになりました。"},{"tag":"車窓","hook":"スイカ柄のガスタンク","t":"盛岡ガス滝沢工場には、全面スイカ柄のガスタンクがあります。特産のスイカのPRのために描かれました。"},{"tag":"クイズ","q":"チャグチャグ馬コの名前は、何の音に由来する？","a":"馬が歩くたびに鳴る鈴の音"}]},"潟上市":{"pref":"秋田県","cards":[{"tag":"へえ","hook":"県内で最小面積の市","t":"潟上市は、市域面積97.72km2で、秋田県内で最小面積の市です。"},{"tag":"数字","hook":"県内で小さい方の町","t":"面積は約97.7km²で、県内25市町村中23位。人口は約31,558人（2021年）です。"},{"tag":"歴史","hook":"日本で初めてのアスファルト舗装","t":"1878年、豊川産の土瀝青を使った東京の昌平橋の工事で、日本で初めてアスファルト舗装が行われました。","teaser":true},{"tag":"出身","hook":"潟上市出身の有名人","t":"潟上市出身には、格闘家の桜庭和志、写真家の中村征夫、プロ野球選手の吉田輝星、フォーク歌手の山平和彦がいます。"},{"tag":"歴史","hook":"縄文から使われた天然アスファルト","t":"豊川油田では天然のアスファルトが産出し、縄文時代早期から利用されていました。"},{"tag":"味","hook":"秋田県最大手の味噌","t":"小玉醸造は味噌製造で秋田県最大手。清酒「太平山」と味噌「ヤマキウ」が広く知られています。"},{"tag":"ゆかり","hook":"坂上田村麻呂が祀った神社","t":"社伝では、801年に坂上田村麻呂が神恩に感謝して祀ったのが、東湖八坂神社の始まりといいます。"},{"tag":"へえ","hook":"牛乗りとくも舞い","t":"東湖八坂神社の例大祭では、毎年7月7日に「牛乗り」と「くも舞い」が行われます。"},{"tag":"ゆかり","hook":"農業指導者・石川理紀之助","t":"石川理紀之助は潟上市の篤農家で、明治から大正期の農業指導者。秋田県種苗交換会の先覚者です。"},{"tag":"車窓","hook":"全高59.8mの天王スカイタワー","t":"道の駅てんのう（天王グリーンランド）には、全高59.8mの天王スカイタワーがあります。"},{"tag":"歴史","hook":"潟上の地名の由来","t":"潟上の地名は、八郎潟の上方（潟の上）に位置することに由来するとされます。"},{"tag":"クイズ","q":"潟上市の豊川産の土瀝青を使った工事で、日本で初めて行われた舗装は？","a":"アスファルト舗装"},{"tag":"クイズ","q":"秋田県内で最小面積の市は？","a":"潟上市"}]},"猪苗代町":{"pref":"福島県","cards":[{"tag":"へえ","hook":"日本海にも太平洋にも注ぐ湖","t":"猪苗代湖は、流出河川が日本海と太平洋の両方に流れる、日本でも珍しい湖です。","teaser":true},{"tag":"数字","hook":"約394.9km²に約13,403人が暮らす町","t":"面積は約394.9km²、人口は約13,403人（2021年）。1km²あたり約34人です。"},{"tag":"ゆかり","hook":"野口英世は猪苗代町の生まれ","t":"野口英世は1876年、三ッ和村（現・猪苗代町）に生まれ、清作と名付けられました。22歳で英世に改名します。"},{"tag":"出身","hook":"猪苗代町出身の有名人","t":"猪苗代町出身には、細菌学者の野口英世、チェアスキー選手の鈴木猛史、女優の逢初夢子がいます。"},{"tag":"ゆかり","hook":"手術費用を集めた募金","t":"1892年、野口英世の作文が教師や同級生の同情を誘い、左手の手術費用を集める募金が行われました。"},{"tag":"歴史","hook":"天鏡閣は李白の詩から","t":"天鏡閣の名は、漢詩を好んだ大正天皇が皇太子時代に滞在した折、李白の詩句「明湖落天鏡」から命名されました。"},{"tag":"車窓","hook":"噴火で5km流された大石","t":"見祢の大石は、もとは磐梯山の火口付近にあった岩。1888年の噴火の泥流で約5km流され、今の場所に辿り着きました。"},{"tag":"へえ","hook":"活火山を3つも抱える町","t":"猪苗代町は、活火山を3つも抱える珍しい自治体です。北西に磐梯山がそびえ、南には猪苗代湖をたたえます。"},{"tag":"ゆかり","hook":"「高原列車は行く」のモデル","t":"歌「高原列車は行く」（作詞：丘灯至夫、作曲：古関裕而）は、沼尻軽便鉄道がモデルとされています。"},{"tag":"へえ","hook":"ウィンタースポーツの聖地","t":"猪苗代町では冬季国体やフリースタイルスキー世界選手権など、ウィンタースポーツの大会が多く開かれ、「聖地」と呼ばれます。"},{"tag":"歴史","hook":"亀ヶ城は例外で存続","t":"猪苗代城は会津領の重要拠点として、一国一城令の際も例外として存続が認められました。別名は亀ヶ城です。"},{"tag":"クイズ","q":"猪苗代湖は、面積で日本で何番目に広い湖?","a":"4番目"},{"tag":"クイズ","q":"天鏡閣の名は、誰の詩句「明湖落天鏡」から付けられた?","a":"李白"}]},"玉川村":{"pref":"福島県","cards":[{"tag":"車窓","hook":"福島県で唯一の空港がある村","t":"福島県で唯一の空港が、玉川村内にあります。あぶくま高原道路が空港へのアクセスとして整備され、高速交通網に接続されています。","teaser":true},{"tag":"数字","hook":"約46.7km²に約6,324人が暮らす町","t":"面積は約46.7km²、人口は約6,324人（2021年）。1km²あたり約136人です。"},{"tag":"歴史","hook":"玉川の名のもとは泉郷川","t":"「玉川」の名は、旧須釜村から旧泉村に流れる玉川（のちに泉郷川へ名称変更）に由来します。"},{"tag":"歴史","hook":"泉と須釜が合わさって川になる","t":"合併当時の記録では、泉が須釜村と合併して川になるという意味が、「玉川」の名に含まれているとされています。"},{"tag":"味","hook":"特産品はサルナシ","t":"玉川村の特産品はサルナシです。2017年1月に玉川大学と包括的な連携協定を結び、サルナシの6次産業化やPR動画作成などを展開しています。"},{"tag":"車窓","hook":"日本の滝百選、乙字ケ滝","t":"玉川村の地理には、日本の滝百選に選ばれた乙字ケ滝があります。ほかに観音岳、阿武隈川、母畑湖があります。"},{"tag":"へえ","hook":"水郡線の「玉川村駅」は別の村","t":"水郡線の玉川村駅は茨城県常陸大宮市（旧那珂郡玉川村）にあり、福島県の玉川村とは関係がありません。"},{"tag":"歴史","hook":"北限域の切石積み石室、宮ノ前古墳","t":"宮ノ前古墳は、古墳時代終末期の7世紀後半頃の築造と推定されます。切石積の横穴式石室としては、北限域に位置します。"},{"tag":"へえ","hook":"さるなしサミットを開いた村","t":"2017年、産地である玉川村が中心となって、産地9市町村が参加する「第1回さるなしサミット」が開かれました。"},{"tag":"へえ","hook":"空港にウルトラシリーズの立像","t":"『ウルトラマン』の生みの親、円谷英二の故郷が須賀川市にあることから、福島空港の施設内外にはウルトラシリーズの立像や関連物が展示されています。"},{"tag":"クイズ","q":"玉川村の特産品は、何という果実？","a":"サルナシ"},{"tag":"クイズ","q":"水郡線の「玉川村駅」があるのは、どこの県？","a":"茨城県"}]},"田子町":{"pref":"青森県","cards":[{"tag":"へえ","hook":"環境庁が認めた星空日本一","t":"田子町は1992年に環境庁から星空日本一に認定されました。","teaser":true},{"tag":"数字","hook":"約242.0km²に約4,782人が暮らす町","t":"面積は約242.0km²、人口は約4,782人（2021年）。1km²あたり約20人です。"},{"tag":"味","hook":"「ニンニクの町」","t":"田子町はニンニクの生産が盛んで、「ニンニクの町」として全国的に知られています。"},{"tag":"出身","hook":"田子町出身の有名人","t":"田子町出身には、漫画家の川三番地がいます。"},{"tag":"ゆかり","hook":"ニンニク祭りが結んだ交流","t":"1987年に田子町職員がギルロイ市のガーリック・フェスティバルを訪れたことが、交流の契機になりました。"},{"tag":"へえ","hook":"地名はアイヌ語で小高い丘","t":"田子の地名は、アイヌ語の「タプコプ」（小高い丘）に由来するとされます。"},{"tag":"車窓","hook":"スヌーピーに似た滝","t":"みろくの滝は形がスヌーピーに似ていて、素麺のように細い流れで「ソーメンの滝」とも呼ばれます。"},{"tag":"車窓","hook":"数万株のヤマツツジ","t":"大黒森の頂上付近には数万株のヤマツツジが広がり、頂上からは360度のパノラマが広がります。"},{"tag":"クイズ","q":"田子町が1992年に環境庁から認定された称号は？","a":"星空日本一"},{"tag":"クイズ","q":"「タプコプ」に由来するといわれる田子の地名。その意味は？","a":"小高い丘"},{"tag":"数字","hook":"八戸まで約35km","t":"田子町から、八戸市まで約35km、盛岡市まで約90km、青森市まで約115kmです。"},{"tag":"へえ","hook":"虫を追う五穀豊穣の祭り","t":"虫追い祭りは、江戸時代より伝わる五穀豊穣を祈願する祭りで、青森県無形民俗文化財に指定されています。"},{"tag":"歴史","hook":"野辺地湊へ続いた交易ルート","t":"江戸時代の田子は、尾去沢鉱山から野辺地湊への交易ルートとして栄えました。"}]},"田村市":{"pref":"福島県","cards":[{"tag":"へえ","hook":"採石中に偶然見つかったあぶくま洞","t":"あぶくま洞は1969年、石灰岩の採掘中に偶然発見されました。旧名は「釜山鍾乳洞」です。","teaser":true},{"tag":"数字","hook":"約458.3km²に約34,921人が暮らす町","t":"面積は約458.3km²、人口は約34,921人（2021年）。1km²あたり約76人です。"},{"tag":"へえ","hook":"鍾乳石の種類と数は東洋一とも","t":"あぶくま洞の洞内は総延長4218.3mに及びます。鍾乳石の種類と数の多さでは東洋一ともされています。"},{"tag":"出身","hook":"田村市出身の有名人","t":"田村市出身には、作家の大野更紗、女優の渡辺由紀、漫画家のよこたとくおがいます。"},{"tag":"味","hook":"洞内は一年中14℃前後","t":"あぶくま洞の洞内の平均気温は14℃前後で、一年を通して大きくは変動しません。この環境を利用して、ワインの貯蔵も行われています。"},{"tag":"へえ","hook":"洞窟のもとは約3億年前の海","t":"あぶくま洞を含む一帯の石灰岩は、約3億年前に有孔虫などの生物の遺骸が海底に堆積してできたものです。"},{"tag":"歴史","hook":"鬼穴に隠された財宝の伝説","t":"鬼穴の「奈落の井戸」には、大多鬼丸という豪族が財宝を隠したという伝説があります。"},{"tag":"歴史","hook":"国天然記念物の入水鍾乳洞","t":"あぶくま洞の北方約4kmにある入水鍾乳洞は、1927年に発見され、1934年12月に国天然記念物に指定されました。"},{"tag":"車窓","hook":"阿武隈高地の最高峰、大滝根山","t":"大滝根山は田村市と川内村の境にそびえる、標高1,192.1mの山です。阿武隈高地の最高峰です。"},{"tag":"へえ","hook":"日本標準時を送る電波の山","t":"田村市都路町と川内村の境、大鷹鳥谷山の山頂付近に、日本標準時のデータを送信する標準電波の送信所があります。"},{"tag":"車窓","hook":"阿武隈の異端児、鎌倉岳","t":"鎌倉岳は、なだらかな山が多い阿武隈高地の中では珍しく、鋭く天を突くような山容から「阿武隈の異端児」と呼ばれます。"},{"tag":"クイズ","q":"あぶくま洞は、何をしている最中に偶然発見された？","a":"石灰岩の採掘"},{"tag":"クイズ","q":"田村市と川内村の境にそびえる大滝根山は、何の最高峰？","a":"阿武隈高地"}]},"田舎館村":{"pref":"青森県","cards":[{"tag":"へえ","hook":"北方稲作の発祥の地とされる村","t":"米づくりで知られ、北方稲作文化発祥の地とされています。"},{"tag":"数字","hook":"県内で小さい方の町","t":"面積は約22.4km²で、県内40市町村中40位。人口は約7,335人（2021年）です。"},{"tag":"車窓","hook":"お城そっくりの村役場","t":"村役場は天守や大手門を備えた城郭風の外観で、プラモデルにもなりました。","teaser":true},{"tag":"出身","hook":"田舎館村出身の有名人","t":"田舎館村出身には、大相撲力士の一ノ矢藤太郎、歌手の佐々木真央がいます。"},{"tag":"車窓","hook":"駅名が「田んぼアート」","t":"弘南鉄道弘南線には「田んぼアート駅」があり、隣は田舎館駅です。"},{"tag":"ゆかり","hook":"第49代横綱の出身地","t":"栃ノ海晃嘉は大相撲第49代横綱で、田舎館村の出身です。"},{"tag":"クイズ","q":"弘南線の「田んぼアート駅」の隣の駅は？","a":"田舎館駅"},{"tag":"数字","hook":"人口密度は県下3位","t":"平成22年の国勢調査で、田舎館村の人口密度は県下3位でした。"},{"tag":"ゆかり","hook":"大関になった一ノ矢","t":"大相撲で大関になった一ノ矢藤太郎は、田舎館村の出身です。"},{"tag":"歴史","hook":"廃止された黒石線の駅","t":"村には、1998年4月1日に廃止された弘南鉄道黒石線の川部駅と前田屋敷駅がありました。"},{"tag":"車窓","hook":"国道102号沿いの道の駅","t":"国道102号沿いに、道の駅いなかだてがあります。"}]},"田野畑村":{"pref":"岩手県","cards":[{"tag":"へえ","hook":"海岸線すべてが国立公園","t":"田野畑村は、村の海岸線がすべて三陸復興国立公園に指定されています。"},{"tag":"数字","hook":"約156.2km²に約3,008人が暮らす町","t":"面積は約156.2km²、人口は約3,008人（2021年）。1km²あたり約19人です。"},{"tag":"へえ","hook":"唯一の特A級・北山崎","t":"北山崎の、海面からの高さ200mの大海食崖が連なる景色は、「自然資源・海岸の部」で唯一の特Ａ級に格付けされました。","teaser":true},{"tag":"車窓","hook":"雲のような霧が海面を覆う","t":"北山崎では、「やませ」と呼ばれる風や濃霧が発生しやすく、雲のような霧が断崖の麓の海面を覆うこともあります。"},{"tag":"へえ","hook":"鵜の巣がある断崖","t":"鵜ノ巣断崖は標高200mにも及ぶ断崖絶壁。名は、中腹にウミウやカワウの営巣地があることにちなむとされます。"},{"tag":"歴史","hook":"全国の支えでよみがえった番屋","t":"机浜番屋群は、全国からの支援による再生プロジェクトで、2014年12月に24棟が完成。番屋料理や塩づくりの体験もできます。"},{"tag":"ゆかり","hook":"畠山重忠の愛馬を祀る神社","t":"畠山神社は、源義経の討伐に向かった畠山重忠の愛馬がこの地で脚を折って倒れ、それを祀った神社とされます。"},{"tag":"へえ","hook":"野生の鹿をかたどった鹿踊","t":"菅窪鹿踊の鹿頭は野生の鹿をかたどり、この特徴は田野畑村と四国宇和島だけと言われます。"},{"tag":"ゆかり","hook":"東北の駅百選・田野畑駅","t":"2002年10月14日、鉄道の日に、田野畑駅が「東北の駅百選」に選ばれました。"},{"tag":"味","hook":"ウニから乳製品まで","t":"田野畑村の特産品は、ウニ、アワビ、ワカメ、マツタケ、山ぶどうのほか、牛乳やヨーグルト、アイスクリームなどです。"},{"tag":"クイズ","q":"田野畑村の海岸線は、すべてどの国立公園に指定されている？","a":"三陸復興国立公園"},{"tag":"クイズ","q":"北山崎の大海食崖は、海面からの高さがおよそ何メートル？","a":"200メートル"}]},"由利本荘市":{"pref":"秋田県","cards":[{"tag":"へえ","hook":"日本で最初のロケット発射場","t":"岩城町の道川海岸に、日本で最初のロケット発射場「秋田ロケット実験場」が開設されました。","teaser":true},{"tag":"数字","hook":"県内で面積1位","t":"面積は約1,209.6km²で、県内25市町村中1位の広さ。人口は約73,840人（2021年）です。"},{"tag":"歴史","hook":"最初の飛翔実験は転げ落ちた","t":"1955年8月6日の最初の飛翔実験は、ロケットが発射台から転げ落ちる失敗。同日2回目は成功し、到達高度は600mでした。"},{"tag":"出身","hook":"由利本荘市出身の有名人","t":"由利本荘市出身には、作曲家の小松耕輔、映画監督の斎藤寅次郎、女優の生駒里奈、俳優の渡部秀がいます。"},{"tag":"クイズ","q":"鳥海山が「出羽富士」とも呼ばれるのは、何が富士山に似ているから？","a":"山頂に雪が積もった姿"},{"tag":"へえ","hook":"晴れれば北アルプスも見える","t":"鳥海山の山頂からは、空気が澄み切れば、約300km先の北アルプスの後立山連峰も見ることができます。"},{"tag":"へえ","hook":"法体の滝は三平のロケ地","t":"法体の滝は、映画版『釣りキチ三平』のロケ地。作品中では「夜鳴き谷」として登場します。"},{"tag":"歴史","hook":"滝の名は空海ゆかり","t":"法体の滝の名は、法体の空海が村を訪れた際に不動明王が現れ、空海が滝に拝礼したことから来ているといいます。"},{"tag":"歴史","hook":"「本城」から「本荘」へ","t":"本荘城は、はじめ「本城」と書かれ、六郷政勝の代に「本荘」と改名。明治維新まで六郷氏11代の居城でした。"},{"tag":"車窓","hook":"まごころ列車が走るろく線","t":"鳥海山ろく線では、午前中の1往復が、秋田おばこ姿のアテンダントが乗務する「まごころ列車」として運転されます。"},{"tag":"味","hook":"稲庭のルーツともされる本荘うどん","t":"本荘うどんは、一説には稲庭うどんのルーツともされ、秋田県で最も古い歴史を持つうどんです。"},{"tag":"味","hook":"昭和40年代に流行ったハムフライ","t":"本荘ハムフライはB級グルメ。昭和40年代にさかんに食べられ、近年は復活して親しまれています。"},{"tag":"へえ","hook":"奥女中が作り始めたまり","t":"本荘ごてんまりは、江戸時代に本荘藩の奥女中が作り始めたとされる工芸品です。"}]},"男鹿市":{"pref":"秋田県","cards":[{"tag":"へえ","hook":"なまはげは鬼ではない","t":"なまはげには角がありますが、鬼ではありません。本来は鬼とは無縁の来訪神です。","teaser":true},{"tag":"数字","hook":"約241.1km²に約24,690人が暮らす町","t":"面積は約241.1km²、人口は約24,690人（2021年）。1km²あたり約102人です。"},{"tag":"歴史","hook":"国の重要無形民俗文化財","t":"なまはげ行事は200年以上の歴史があり、国の重要無形民俗文化財です。ユネスコの無形文化遺産にも登録されています。"},{"tag":"出身","hook":"男鹿市出身の有名人","t":"男鹿市出身には、元プロ野球選手の落合博満、ラグビー選手の吉田義人、アンデス文明研究家の天野芳太郎がいます。"},{"tag":"へえ","hook":"赤面はジジ、青面はババ","t":"なまはげの仮面は、赤面と青面の1対に定型化もされ、赤面がジジナマハゲ、青面がババナマハゲと呼ばれます。"},{"tag":"車窓","hook":"北緯40度線上の入道崎","t":"入道崎は北緯40度線上にあり、それを印した安山岩のモニュメントが置かれています。"},{"tag":"車窓","hook":"白黒の縞の入道埼灯台","t":"入道埼灯台は1898年に運用が始まりました。白黒の縞模様が、岬のシンボルです。"},{"tag":"歴史","hook":"東日本屈指の山城・脇本城","t":"脇本城は、東日本屈指の規模を誇る山城です。広さは150haで、石垣は存在しません。"},{"tag":"車窓","hook":"標高355mの寒風山","t":"寒風山は標高355mの成層火山で、山頂部は滑落で2つに分かれています。"},{"tag":"ゆかり","hook":"落合博満さんの故郷","t":"元プロ野球選手で中日ドラゴンズ元監督の落合博満さんは、男鹿市名誉市民で、旧若美町の出身です。"},{"tag":"ゆかり","hook":"アンデス研究の天野芳太郎","t":"アンデス文明研究家で実業家の天野芳太郎は、旧脇本村の出身です。"},{"tag":"クイズ","q":"なまはげは、鬼ではなく何だとされる？","a":"来訪神"},{"tag":"クイズ","q":"入道崎にモニュメントがある、北緯何度の線？","a":"40度線"}]},"登米市":{"pref":"宮城県","cards":[{"tag":"へえ","hook":"最も古い現存パトカー","t":"登米の警察資料館（旧登米警察署庁舎）には、宮城県警察が使っていたC210型のパトカーが展示されています。現存する警らパトカーとしては最も古いものです。","teaser":true},{"tag":"数字","hook":"約536.1km²に約76,164人が暮らす町","t":"面積は約536.1km²、人口は約76,164人（2021年）。1km²あたり約142人です。"},{"tag":"へえ","hook":"火を防ぐ裸の行事","t":"「米川の水かぶり」は、毎年2月の初午の日に、藁装束の男たちが町を走り抜けて水を屋根にかけ、火伏せを祈る行事です。"},{"tag":"出身","hook":"登米市出身の有名人","t":"登米市出身には、漫画家の石ノ森章太郎、漫画家の大友克洋、ピアニストの及川浩治がいます。"},{"tag":"車窓","hook":"みやぎの明治村","t":"旧登米町周辺には明治時代の建造物が多く、「みやぎの明治村」と呼ばれています。旧水沢県庁庁舎や旧登米高等尋常小学校校舎があります。"},{"tag":"車窓","hook":"隈研吾さん設計の登米懐古館","t":"2019年に移転した登米懐古館の新館は、隈研吾さんの設計です。屋根には、かつて登米特産であったスレート瓦が葺かれています。"},{"tag":"車窓","hook":"マガンの羽音が音風景に","t":"伊豆沼では、早朝や夕方に一斉に飛び立つマガンの羽音と鳴き声が、「日本の音風景100選」に選ばれています。"},{"tag":"へえ","hook":"登米市は「とめ」と読む","t":"市名は「とよま」ではなく、「登米（とめ）郡」の郡名からとって、「登米（とめ）市」となりました。"},{"tag":"味","hook":"米どころ登米は東北地方第2位","t":"登米市は、ササニシキ、ひとめぼれ、コシヒカリなどの有名米の産地で、農業産出額は303億円で東北地方第2位です。"},{"tag":"歴史","hook":"登米伊達氏の始まり","t":"1601年、政宗の部将・白石宗直が政宗から「伊達」の姓を賜り、寺池城に入って登米伊達氏の祖となりました。"},{"tag":"ゆかり","hook":"『おかえりモネ』の舞台","t":"2021年5月から10月に放映されたNHK連続テレビ小説『おかえりモネ』は、登米市と気仙沼市が舞台でした。"},{"tag":"クイズ","q":"登米市東和町の火伏せの行事「米川の水かぶり」が登録された、ユネスコの遺産は何でしょう?","a":"無形文化遺産です。"},{"tag":"クイズ","q":"伊豆沼・内沼が1985年に登録されたラムサール条約は、日本国内で何番目の登録地でしょう?","a":"2番目です。渡り鳥の越冬地として知られます。"}]},"白河市":{"pref":"福島県","cards":[{"tag":"へえ","hook":"優勝旗が白河の関を越えた","t":"2022年の夏の高校野球で仙台育英が優勝し、東北初の甲子園制覇。「優勝旗が白河の関を越えた」と歓喜されました。","teaser":true},{"tag":"数字","hook":"約305.3km²に約59,044人が暮らす町","t":"面積は約305.3km²、人口は約59,044人（2021年）。1km²あたり約193人です。"},{"tag":"歴史","hook":"南湖公園は日本最古の公園","t":"南湖は「日本最古の公園」とよばれます。1801年、藩主の松平定信が身分を越えて庶民が憩える場として開放しました。"},{"tag":"出身","hook":"白河市出身の有名人","t":"白河市出身には、洋画家の関根正二、映画監督のサトウトシキ、マラソン選手の藤田敦史がいます。"},{"tag":"歴史","hook":"小峰城は木造で復元された","t":"戊辰戦争で焼けた白河小峰城は、1991年に御三階櫓が木造で復元されました。各地で進む木造復元の先がけとされています。"},{"tag":"へえ","hook":"白河の関はみちのくの玄関口","t":"白河の関は、古代の日本の関所で「みちのくの玄関口」とされてきました。鼠ヶ関・勿来関とともに奥州三関の一つです。"},{"tag":"歴史","hook":"能因法師も芭蕉も詠んだ関","t":"平安時代の能因法師は「秋風ぞ吹く白河の関」と詠みました。のちに松尾芭蕉も、おくのほそ道で白河到着の情景を詠んでいます。"},{"tag":"へえ","hook":"河北新報の名は白河以北から","t":"宮城県の実業家が1897年に創刊した新聞「河北新報」の名は、「白河以北」の「河北」からとられました。"},{"tag":"味","hook":"白河ラーメンは蕎麦打ちの麺","t":"白河ラーメンは、豚骨や鶏ガラの醤油ベースのスープに、蕎麦打ちの技法で作る縮れ麺が特徴です。"},{"tag":"ゆかり","hook":"小原庄助のモデルの墓","t":"「朝寝朝酒朝湯が大好き」と歌われる小原庄助。モデルと伝わる人物の墓が、白河市の皇徳寺にあります。"},{"tag":"ゆかり","hook":"安珍はこの地の出身といわれる","t":"安珍・清姫伝説の安珍は、この地の出身の僧侶といわれ、市内の萱根根田地区に安珍をまつった堂があります。"},{"tag":"へえ","hook":"ビャッコイは白河市だけに自生","t":"ビャッコイという植物は、日本国内では白河市表郷金山にだけ自生しています。"},{"tag":"クイズ","q":"白河小峰城は盛岡城、若松城と並び、何の1つに数えられる？","a":"東北三名城"}]},"白石市":{"pref":"宮城県","cards":[{"tag":"へえ","hook":"「しらいし」ではなく「しろいし」","t":"白石は、苗字などで一般的な「しらいし」ではなく、「しろいし」と読みます。"},{"tag":"数字","hook":"約286.5km²に約32,570人が暮らす町","t":"面積は約286.5km²、人口は約32,570人（2021年）。1km²あたり約114人です。"},{"tag":"歴史","hook":"一国一城令でも壊されなかった城","t":"一国一城令で全国の城が壊されるなか、白石城は例外的に城として認められ、白石は明治維新までの260余年、片倉氏の城下町として栄えました。"},{"tag":"出身","hook":"白石市出身の有名人","t":"白石市出身には、絵本作家のわたりむつこ、第18代横綱の大砲万右エ門、プロレスラーの遠藤哲哉がいます。"},{"tag":"歴史","hook":"寄付1億円超で復元した白石城","t":"白石城の三階櫓や門は、復元基金に個人や法人から1億円を超す寄付が集まり、1995年に木造で復元されました。"},{"tag":"味","hook":"父のために生まれた白石温麺","t":"江戸時代の初め、白石の鈴木浅右衛門が、胃腸の弱い父のため、旅の僧に教わった油を使わない麺の製法を苦心して会得し、温麺を始めたと伝わります。"},{"tag":"へえ","hook":"鎌の先で掘り当てた温泉","t":"鎌先温泉は1428年、里人が草刈りの最中に鎌の先で温泉を掘り当てたと伝わり、温泉名もそれに由来します。","teaser":true},{"tag":"へえ","hook":"「わすれずの山」と不忘山","t":"「不忘山」を「わすれずのやま」と読むと、蔵王連峰一帯を指す古い呼び名です。清少納言の『枕草子』にも「わすれずの山」が出てきます。"},{"tag":"へえ","hook":"長さ1802mの流し温麺","t":"2006年、白石市のスキー場で流し素麺の世界最長記録を塗り替えるイベントがあり、1802メートルの「流し温麺」が完成しました。"},{"tag":"歴史","hook":"鬼小十郎まつりで合戦を再現","t":"鬼小十郎まつりは2008年に始まり、10月に白石城で行われます。公募の甲冑武者や忍者隊など約120人が合戦を再現します。"},{"tag":"ゆかり","hook":"白石出身の第18代横綱","t":"白石市出身の大砲万右エ門は、第18代横綱の力士です。"},{"tag":"クイズ","q":"白石温麺、白石和紙と合わせて「白石三白」と呼ばれる、もう一つの名産は何?","a":"白石葛"},{"tag":"クイズ","q":"明治初め、片倉家の家臣団が移住した縁で白石市と友好都市になっている、札幌市の区は?","a":"白石区"}]},"白鷹町":{"pref":"山形県","cards":[{"tag":"へえ","hook":"最上川本川で唯一の井堰","t":"1615年に現在の白鷹町に建設された「諏訪堰」は、最上川の本川に建設された唯一の井堰です。","teaser":true},{"tag":"数字","hook":"約157.7km²に約12,663人が暮らす町","t":"面積は約157.7km²、人口は約12,663人（2021年）。1km²あたり約80人です。"},{"tag":"歴史","hook":"荒砥まで船が通った最上川","t":"1693年、米沢藩御用商人の西村久左衛門が最上川の難所を開鑿し、長崎から荒砥(白鷹町)までの通船工事を完成させました。"},{"tag":"出身","hook":"白鷹町出身の有名人","t":"白鷹町出身には、宇宙物理学者の佐藤文隆、歌手の渚ようこ、俳優の矢崎広がいます。"},{"tag":"ゆかり","hook":"上杉鷹山の号は白鷹山から","t":"上杉鷹山の「鷹山」という隠居後の号は、白鷹山から採られたとされます。江戸時代、白鷹山は米沢藩に大切にされました。"},{"tag":"へえ","hook":"白鷹山の名前の由来","t":"白鷹山の名は、行基が訪れたとき白い鷹が飛来したという伝説や、雪を抱いた姿が羽を広げた鷹に見えることに由来するという説があります。"},{"tag":"歴史","hook":"山頂の福満大虚空蔵尊","t":"白鷹山の山頂には、日本五大虚空蔵のひとつとされる「福満大虚空蔵尊」があります。"},{"tag":"へえ","hook":"七進五退三転の獅子舞","t":"鮎貝八幡宮の七五三獅子舞は、「七進五退三転」という独特の足運びが名の由来。「七五三の舞」の元祖とされます。"},{"tag":"歴史","hook":"城跡に建つ鮎貝八幡宮","t":"鮎貝八幡宮は、鮎貝城の本丸跡に祀られています。城の土塁や堀の遺構も確認できます。"},{"tag":"歴史","hook":"境目の城・荒砥城","t":"荒砥城は、最上領と隣接する「境目の城」として重視されました。江戸時代には米沢藩五支城の一つでした。"},{"tag":"クイズ","q":"白鷹町のヤナ公園で、毎年9月頃に開かれるまつりは?","a":"白鷹鮎まつり"},{"tag":"クイズ","q":"白鷹町が産地となっている、植物は?","a":"ホップ"}]},"盛岡市":{"pref":"岩手県","cards":[{"tag":"へえ","hook":"NYタイムズが選んだ盛岡","t":"2023年、盛岡はニューヨーク・タイムズの『2023年に行くべき52カ所』に選ばれました。","teaser":true},{"tag":"数字","hook":"県内で人口1位","t":"人口は約290,553人（2021年）で、県内33市町村中1位。面積は約886.5km²です。"},{"tag":"味","hook":"盛岡は自称「めん都」","t":"冷麺・じゃじゃ麺・わんこそばと、全国的に知られる麺料理が育ったことから、盛岡市は自分で「めん都」と名乗っています。"},{"tag":"へえ","hook":"岩の割れ目から咲く桜","t":"石割桜は、巨大な花崗岩の割れ目から育った桜です。樹齢は360年を越え、見ごろは4月の半ばからです。"},{"tag":"歴史","hook":"「盛岡」の名は連歌から","t":"「盛岡」の名は、1691年に藩主と僧が交わした連歌に由来します。「盛り上がり栄える岡」という意味とされます。"},{"tag":"車窓","hook":"白い石垣が目を引く城跡","t":"盛岡城跡の白い花崗岩の石垣は、高い所で14mに及びます。土塁の多い東北の城の中では異彩を放っています。"},{"tag":"ゆかり","hook":"城跡の公園に啄木の歌碑","t":"盛岡城跡の公園には、石川啄木の「不来方のお城の草に寝ころびて空に吸はれし十五の心」と刻まれた歌碑があります。"},{"tag":"味","hook":"じゃじゃ麺のルーツは満州","t":"盛岡じゃじゃ麺は、旧満州で味わった炸醤麺を元に、終戦後の盛岡の屋台でアレンジを重ねて完成したといわれます。"},{"tag":"車窓","hook":"どこからでも岩手山","t":"盛岡市内のあらゆる地域から岩手山が望まれ、多くの学校の校歌にも歌われています。"},{"tag":"へえ","hook":"薮川は富士山に次ぐ寒さ","t":"盛岡市の薮川は、1月の日最低気温が-13.2℃で、本州の観測所としては富士山に次いで低くなっています。"},{"tag":"クイズ","q":"盛岡じゃじゃ麺を食べ終えた器に、卵と肉味噌を入れ、ゆで汁を注いで作るスープの名前は？","a":"鶏蛋湯（チータンタン）"}]},"相馬市":{"pref":"福島県","cards":[{"tag":"歴史","hook":"野馬追は平将門の軍事訓練から","t":"相馬野馬追の起源は、平将門が野生馬を敵兵に見立てて軍事訓練をしたことに始まると言われています。"},{"tag":"数字","hook":"約197.8km²に約34,645人が暮らす町","t":"面積は約197.8km²、人口は約34,645人（2021年）。1km²あたり約175人です。"},{"tag":"車窓","hook":"東北六大祭りのひとつ","t":"相馬野馬追は国の重要無形民俗文化財。東北の夏祭りのさきがけとされ、東北六大祭りのひとつとして紹介されることもあります。"},{"tag":"出身","hook":"相馬市出身の有名人","t":"相馬市出身には、元プロ野球選手の鈴木尚広、元大相撲関脇力士の栃東知頼、俳人の大須賀乙字がいます。"},{"tag":"へえ","hook":"上から見下ろしてはいけない","t":"相馬野馬追では、上から見下ろすのはいけないとされ、出陣式のときは通り道の歩道橋が封鎖されます。","teaser":true},{"tag":"歴史","hook":"一度消えた野馬追","t":"野馬追は、1872年に野馬がすべて狩り獲られて一度消滅。原町の相馬太田神社が中心となり、1878年に復活しました。"},{"tag":"車窓","hook":"「小松島」と評される松川浦","t":"松川浦は、大小の島や岩が点在する風景が松島になぞらえられて「小松島」とも評され、日本百景の一つです。"},{"tag":"車窓","hook":"市街地に点在する馬の銅像","t":"相馬氏が馬の紋章を用いたことにちなんで、相馬市の市街地には馬の銅像が点在しています。"},{"tag":"ゆかり","hook":"相馬中村藩主に仕えた丹下左膳","t":"小説『新版大岡政談』の登場人物・丹下左膳は、相馬中村藩主に仕えていたという設定です。"},{"tag":"味","hook":"相馬の苺と梨","t":"相馬市は、和田地区を中心に苺が特産です。磯部地区、石上地区を中心に梨の栽培も盛んです。"},{"tag":"へえ","hook":"相馬盆唄は元B面曲","t":"民謡の相馬盆唄は、元は「会津磐梯山」のB面曲でしたが、A面曲を上回る人気になりました。"},{"tag":"クイズ","q":"相馬野馬追の起源とされる、野生馬を使った軍事訓練をしたのは誰?","a":"平将門"},{"tag":"クイズ","q":"相馬市の松川浦は、カタカナの何の字の形をした潟湖?","a":"「フ」"}]},"真室川町":{"pref":"山形県","cards":[{"tag":"車窓","hook":"山形県の北の玄関口","t":"真室川町は山形県の北の玄関口。北部の雄勝峠を通る奥羽本線や国道13号で秋田県と結ばれています。"},{"tag":"数字","hook":"約374.2km²に約7,047人が暮らす町","t":"面積は約374.2km²、人口は約7,047人（2021年）。1km²あたり約19人です。"},{"tag":"車窓","hook":"「森の巨人たち100選」の大カツラ","t":"女甑の大カツラは、及位マタギから崇められてきた御神木。林野庁選定の「森の巨人たち100選」に選ばれています。","teaser":true},{"tag":"出身","hook":"真室川町出身の有名人","t":"真室川町出身には、俳優の佐藤昇、鷹匠の沓沢朝治がいます。"},{"tag":"へえ","hook":"甑とは米を蒸す木桶","t":"甑山は、男甑と女甑という岩峰からなる山。「甑」は米を蒸す木桶のことで、山の形から名付けられたと考えられています。"},{"tag":"ゆかり","hook":"出囃子が結んだ「まむろがわ大使」","t":"桂吉弥さんは、出囃子に「真室川音頭」を使っている縁で、2013年に「まむろがわ大使」に起用されました。"},{"tag":"ゆかり","hook":"映画「老人と鷹」のモデルは町の鷹匠","t":"真室川町出身の沓沢朝治は鷹匠で、映画「老人と鷹」のモデルです。"},{"tag":"歴史","hook":"鮭延城と鮭延秀綱","t":"1563年、鮭延秀綱が、内町の鮭川の高台に鮭延城を築きました。"},{"tag":"歴史","hook":"古河とつながる鮭延寺","t":"古河で亡くなった鮭延秀綱を弔うため、古河に鮭延寺が建立された縁で、真室川町は旧総和町と1988年に姉妹都市になりました。"},{"tag":"へえ","hook":"最上の林業を管理するのは真室川","t":"山形森林管理署最上支署は、最上地方の林業管理を行います。中心都市の新庄市ではなく、真室川町にあります。"},{"tag":"歴史","hook":"歌詞を募集して生まれた「正調」","t":"真室川音頭の今の歌詞は、1952年に真室川町が歌詞を広く募集して織り込んだもの。「正調真室川音頭」と呼ばれ、レコード録音されました。"},{"tag":"へえ","hook":"真室川音頭の元唄は「ナット節」","t":"真室川音頭の元唄は、明治時代に北海道東海岸方面で流行した作業唄「ナット節」だったとされます。"},{"tag":"クイズ","q":"真室川町出身の鷹匠・沓沢朝治がモデルになった映画は？","a":"老人と鷹"}]},"矢吹町":{"pref":"福島県","cards":[{"tag":"へえ","hook":"矢で屋根をふいた社が町名の由来","t":"八幡太郎義家が建てた八幡の社は、矢柄で屋根を葺いたといわれ、古い記録では「屋葺」。矢吹姓の発祥の地とも言われます。","teaser":true},{"tag":"数字","hook":"約60.4km²に約16,823人が暮らす町","t":"面積は約60.4km²、人口は約16,823人（2021年）。1km²あたり約279人です。"},{"tag":"へえ","hook":"日本三大開拓地の一つ","t":"矢吹町は「日本三大開拓地」の一つとされています。"},{"tag":"出身","hook":"矢吹町出身の有名人","t":"矢吹町出身には、演歌歌手の津吹みゆ、陸上選手の千葉麻美、詩人の大滝清雄がいます。"},{"tag":"歴史","hook":"昭和天皇が開墾地を視察","t":"1947年、昭和天皇が戦後巡幸で矢吹町を訪れ、修練農場や開墾事業地を視察しました。"},{"tag":"歴史","hook":"ダム工事で映画館もにぎわった","t":"1950年に着工した羽鳥ダム（現在の天栄村）の建設では、日本中から工夫が集まり、矢吹町は大変賑わって映画館もありました。"},{"tag":"へえ","hook":"あゆり公園の大賀ハス","t":"あゆり公園には、千葉県天然記念物の大賀ハスの生育地があります。千葉市役所から縁あって譲り受けたものです。"},{"tag":"ゆかり","hook":"絶好調男・中畑清さんの出身地","t":"元プロ野球選手の中畑清さんは矢吹町の出身。愛称は「絶好調男」で、のちに横浜DeNAベイスターズの初代監督を務めました。"},{"tag":"車窓","hook":"町の半分以上が農地","t":"矢吹町は東京より北へ約215kmにあり、町の面積の半分以上が農地で形成されています。"},{"tag":"クイズ","q":"矢吹町は、奥州街道とどの街道の追分地点だった？","a":"棚倉街道"}]},"矢巾町":{"pref":"岩手県","cards":[{"tag":"へえ","hook":"国内初の木製の冑が出土","t":"2006年、徳丹城跡の発掘調査で、井戸跡から国内初となる木製の冑（兜）が見つかりました。","teaser":true},{"tag":"数字","hook":"県内で小さい方の町","t":"面積は約67.3km²で、県内33市町村中32位。人口は約27,638人（2021年）です。"},{"tag":"歴史","hook":"水害で引っ越した城","t":"矢巾の徳丹城は、水害を理由に、盛岡の志波城を約10キロメートル南へ移して812年に造られました。"},{"tag":"出身","hook":"矢巾町出身の有名人","t":"矢巾町出身には、参議院議員の横澤高徳、柔道家の川村禎三、カヌーの水本圭治がいます。"},{"tag":"歴史","hook":"毒ケ森が「南昌山」に","t":"南昌山は、1703年に僧・空念の推挙で、「南部の繁昌」を願い、毒ケ森（徳ヶ森）から改名されました。"},{"tag":"車窓","hook":"鐘を伏せたような南昌山","t":"南昌山は標高848.0m。岩の鐘を伏せたような均整のとれた形で、古くから地元の信仰の対象とされてきました。"},{"tag":"ゆかり","hook":"賢治童話に出てくる南昌山","t":"宮沢賢治は、南昌山を童話「鳥をとるやなぎ」に登場させています。"},{"tag":"へえ","hook":"南昌山の名が星になった","t":"2022年8月、小惑星22355に「矢巾・南昌山」、小惑星22352に「藤原健次郎」の名が付くことが国際天文学連合に承認されました。"},{"tag":"へえ","hook":"みちのくプロレスの聖地","t":"みちのくプロレスは、旗揚げの地・矢巾町を聖地とし、旗揚げから30年以上たった今も、矢巾町民総合体育館をビッグマッチ会場にしています。"},{"tag":"へえ","hook":"県内初の本格的音楽ホール","t":"矢巾町文化会館「田園ホール」は、岩手県内初の本格的音楽ホールで、町民手作りの「矢巾町民劇場」が毎年2月に上演されます。"},{"tag":"味","hook":"古くから有名な徳田米","t":"矢巾町は、古くから徳田米の産地として有名です。"},{"tag":"クイズ","q":"岩手県内初の本格的音楽ホールで、愛称が「田園ホール」の矢巾町の施設は？","a":"矢巾町文化会館"}]},"矢祭町":{"pref":"福島県","cards":[{"tag":"へえ","hook":"本を呼びかけたら29万冊","t":"矢祭もったいない図書館は、2006年に3万冊を目標に全国へ本の寄贈を呼びかけ、送料は寄贈者負担でも約29万冊（当時）が集まりました。","teaser":true},{"tag":"数字","hook":"約118.3km²に約5,353人が暮らす町","t":"面積は約118.3km²、人口は約5,353人（2021年）。1km²あたり約45人です。"},{"tag":"歴史","hook":"「合併しない」と宣言した町","t":"2001年10月31日、町議会が「市町村合併をしない矢祭町宣言」を可決しました。"},{"tag":"出身","hook":"矢祭町出身の有名人","t":"矢祭町出身には、お笑い芸人のあばれる君、元矢祭町長の根本良一がいます。"},{"tag":"へえ","hook":"福島県なのに茨城との縁が深い","t":"矢祭町は福島県の最南端。茨城県日立市へは約45kmですが、同じ福島県のいわき市勿来へは約55kmで、茨城県北部との関係が深い町です。"},{"tag":"車窓","hook":"桜と紅葉の名所、矢祭山","t":"矢祭山は標高382.7mで、うつくしま百名山の一つ。南側の矢祭山公園は桜やツツジ、紅葉の名所で、付近は鮎釣りでも知られます。"},{"tag":"車窓","hook":"戸津辺の桜は県の天然記念物","t":"戸津辺の桜は、エドヒガンという桜で、県指定の天然記念物です。"},{"tag":"歴史","hook":"中心部の地名は佐竹氏ゆかり","t":"戦国時代、矢祭は常陸の佐竹氏の領土でした。中心部の地名「東舘」は、その統治下に付けられたものです。"},{"tag":"ゆかり","hook":"あばれる君の出身地","t":"お笑い芸人のあばれる君は、矢祭町の出身です。"},{"tag":"クイズ","q":"矢祭もったいない図書館の建物は、もとは何の施設だった？","a":"町が持っていた古い武道館"}]},"石川町":{"pref":"福島県","cards":[{"tag":"歴史","hook":"ウラン鉱石の採石地だった","t":"石川町は、太平洋戦争中に原子爆弾の材料となるウラン鉱石の採石地として知られました。勤労動員で多くの学生が採掘しましたが、戦後にGHQにより回収されました。","teaser":true},{"tag":"数字","hook":"約115.7km²に約14,222人が暮らす町","t":"面積は約115.7km²、人口は約14,222人（2021年）。1km²あたり約123人です。"},{"tag":"車窓","hook":"八幡山の頂上にある一宮","t":"石都々古和気神社は、八幡山と呼ばれる山の頂上にあります。式内社で、陸奥国一宮を称しています。"},{"tag":"出身","hook":"石川町出身の有名人","t":"石川町出身には、劇作家の谷賢一、歌手の津山洋子、漫画家の深谷かほるがいます。"},{"tag":"歴史","hook":"25代528年続いた石川氏の居城","t":"1063年、石川有光が八幡山山頂の神社の東側に三芦城を築きました。以降25代528年間にわたって石川氏の居城でした。"},{"tag":"へえ","hook":"「飛翔獅子」と呼ばれる狛犬","t":"石都々古和気神社の狛犬は、1930年に石工の小林和平が製作した、「飛翔獅子」と呼ばれる一対の狛犬です。石川町指定文化財です。"},{"tag":"味","hook":"ラジウム含有量は東北一の母畑温泉","t":"母畑温泉は、ラジウム含有量は東北一を誇り、古くから湯治に利用され、打ち身なら母畑へともいわれる温泉です。"},{"tag":"車窓","hook":"町を一望できる石尊山公園","t":"石尊山公園は、石陽社記念碑やライトアップされた「光の塔」などがあり、町を一望できる高台の公園です。"},{"tag":"ゆかり","hook":"『夜廻り猫』の漫画家は石川町出身","t":"石川町出身の深谷かほるさんは漫画家で、代表作は『ハガネの女』『夜廻り猫』です。"},{"tag":"歴史","hook":"源義家の馬の傷を治した湯","t":"開湯伝説では、平安時代、奥州を訪れた八幡太郎義家が戦いで負った馬の傷を谷川の水で洗ったところ、数日で治りました。これが母畑温泉の始まりといわれます。"},{"tag":"クイズ","q":"石川町の三芦城は、何代、何年にわたって石川氏の居城だった？","a":"25代528年間"},{"tag":"クイズ","q":"石川町の母畑湖は、何ダムのダム湖？","a":"千五沢ダム"}]},"石巻市":{"pref":"宮城県","cards":[{"tag":"歴史","hook":"石巻の船乗りが世界一周","t":"1793年に石巻湊を出た千石船「若宮丸」は漂流。乗員のうち4人は約12年後に江戸から故郷へ向かい、日本人として初の世界一周の事例と言われています。","teaser":true},{"tag":"数字","hook":"県内で面積4位","t":"面積は約554.5km²で、県内35市町村中4位の広さ。人口は約138,856人（2021年）です。"},{"tag":"へえ","hook":"国内最古の現役の閘門","t":"石井閘門は日本初の西洋式の本格的な閘門です。現在日本国内で稼動する閘門の中では最古で、2002年に国の重要文化財になりました。"},{"tag":"へえ","hook":"日本最古の木造教会建築","t":"旧石巻ハリストス正教会教会堂は、現存する日本最古の木造教会建築です。今は市が所有し、宗教施設としては使われていません。"},{"tag":"へえ","hook":"暖流と寒流がぶつかる漁場","t":"石巻の沖の金華山沖は、黒潮（暖流）と親潮（寒流）がぶつかる潮目として世界三大漁場の一つで、水産資源の宝庫です。"},{"tag":"味","hook":"200種類を超える水揚げ","t":"石巻漁港などでは、サバ・カツオ・タラ・サンマなど、200種類を超える水産物が水揚げされています。"},{"tag":"歴史","hook":"奥州最大の米の集積港","t":"江戸時代、北上川の改修で舟運が活発になり、石巻港は「奥州最大の米の集積港」として栄えました。"},{"tag":"歴史","hook":"月ノ浦で造られた船","t":"1613年、伊達政宗は月ノ浦でサン・ファン・バウティスタ号を建造。支倉常長を正使とする慶長遣欧使節を派遣しました。"},{"tag":"ゆかり","hook":"芭蕉が訪れた日和山","t":"1689年、松尾芭蕉が日和山を訪れ、同行の曽良が眺望を日記に記しました。山の名は、商船が出航する前に天候を観察したことにちなむといいます。"},{"tag":"ゆかり","hook":"石ノ森章太郎と萬画のまち","t":"1995年に漫画家の石ノ森章太郎さんが「マンガを活かしたまちづくり」を提案。2001年に石ノ森萬画館が開館し、石巻は「萬画のまち」になりました。"},{"tag":"クイズ","q":"江戸中期、仙台藩内で石巻だけが造ることを許されたものは何でしょう?","a":"銭の鋳造です。寛永通宝などが造られ、「鋳銭場」という町名が今も石巻駅前に残っています。"},{"tag":"クイズ","q":"2019年7月に31年ぶりに行われた、牡鹿地区の鮎川浜を中心とする漁は何でしょう?","a":"商業捕鯨です。牡鹿地区の鮎川浜を中心に捕鯨が行われています。"}]},"磐梯町":{"pref":"福島県","cards":[{"tag":"へえ","hook":"世界第3位の発電所が東京へ送電","t":"1914年、日橋川の急流を活用した猪苗代第一発電所が完成し、東京まで200キロメートル超の長距離送電を開始。当時、世界第3位の規模でした。","teaser":true},{"tag":"数字","hook":"約59.8km²に約3,350人が暮らす町","t":"面積は約59.8km²、人口は約3,350人（2021年）。1km²あたり約56人です。"},{"tag":"歴史","hook":"807年、徳一が慧日寺を開く","t":"807年、法相宗の僧・徳一がこの地に下り、慧日寺を開きました。徳一は東大寺と興福寺に学び、空海や最澄とも論争した高僧です。"},{"tag":"歴史","hook":"寺僧300、僧兵3,000の大寺院","t":"慧日寺は平安時代の末期には、寺僧300、僧兵3,000、寺領18万石という大寺院に発展し、会津一円を支配していました。"},{"tag":"歴史","hook":"駅名はもと「大寺駅」","t":"磐梯町駅周辺は慧日寺の門前町が起源で、古くから「大寺（おおてら）」と呼ばれました。駅も1965年までは大寺駅でした。"},{"tag":"車窓","hook":"町の最高点は磐梯山の山頂","t":"磐梯町の最高点は磐梯山の山頂で標高1816m、最低点は会津盆地の一端で標高200mです。"},{"tag":"車窓","hook":"ゴールドラインは冬季閉鎖","t":"磐梯山ゴールドラインはアルツ磐梯スキー場のゲレンデの中を通るため、冬季は11月上旬から翌年4月下旬まで全面閉鎖されます。"},{"tag":"へえ","hook":"ゴールドラインの名は民謡から","t":"通称の「磐梯山ゴールドライン」の名称は、会津の宝の山と唄った地元の民謡『会津磐梯山』を由来とします。"},{"tag":"へえ","hook":"磐梯山は地質百選とジオパーク","t":"磐梯山は、2007年に日本の地質百選に選定され、2011年には日本ジオパークに認定されました。"},{"tag":"クイズ","q":"磐梯町駅は1965年まで、何駅という名前だった?","a":"大寺駅"},{"tag":"クイズ","q":"磐梯山ゴールドラインの名称は、どんな民謡に由来する?","a":"会津磐梯山"}]},"福島市":{"pref":"福島県","cards":[{"tag":"味","hook":"梨は市町村別で日本一","t":"福島市の梨の生産数は、市町村別で日本一です。桃も全国有数の収穫量で、「果物王国」と呼ばれます。"},{"tag":"数字","hook":"県内で面積3位","t":"面積は約767.7km²で、県内53市町村中3位の広さ。人口は約284,282人（2021年）です。"},{"tag":"味","hook":"ラヂウム玉子","t":"飯坂温泉の温泉卵「ラヂウム玉子」。日本国内で初めてラジウムの存在が確認されたことにちなむ名前で、成分は含まれません。"},{"tag":"出身","hook":"福島市出身の有名人","t":"福島市出身には、作曲家の古関裕而、俳優の佐藤B作、俳優の梅沢富美男、お笑い芸人のなすびがいます。"},{"tag":"歴史","hook":"福島の地名は縁起もの","t":"福島の地名は、安土桃山時代に縁起の良さそうな「福島」へ杉妻を改名したという説が有力です。"},{"tag":"歴史","hook":"幻の県庁移転","t":"かつて郡山市への県庁移転が県議会で賛成多数で可決されたことがありますが、実現しませんでした。"},{"tag":"ゆかり","hook":"古関裕而の出身地","t":"令和初期の時点で福島市唯一の名誉市民は、行進曲や校歌を数多く手掛けた作曲家・古関裕而。福島市の出身です。"},{"tag":"ゆかり","hook":"「さんぽ」は信夫山のイメージ","t":"『となりのトトロ』の「さんぽ」は、作詞家の中川李枝子さんが幼いころ遊んだ信夫山を歩いたイメージで作ったと語っています。","teaser":true},{"tag":"車窓","hook":"長さ12メートルの大わらじ","t":"信夫山の羽黒神社に奉納される大わらじは長さ12メートル。毎年2月の「信夫三山暁参り」で奉納されます。"},{"tag":"車窓","hook":"吾妻の雪うさぎ","t":"早春、吾妻小富士の山肌に残る雪がうさぎの形に見えます。「雪うさぎ」と呼ばれ、春の訪れを知らせる風物詩です。"},{"tag":"へえ","hook":"日本一高い公開天文台","t":"浄土平天文台は、日本一高い場所に位置する公開天文台とされています。"},{"tag":"クイズ","q":"花見山に幾度も通い「福島に桃源郷あり」と讃えた人物は?","a":"秋山庄太郎"},{"tag":"クイズ","q":"信夫山の外周は1周7キロメートル。これと同じ大きさの場所は?","a":"皇居(外苑も含む)"}]},"秋田市":{"pref":"秋田県","cards":[{"tag":"へえ","hook":"国内最大の油田が市内に","t":"八橋油田は、昭和20年代後半から30年代にかけて国内最大の油田で、現在までの累積産油量も国内最大です。","teaser":true},{"tag":"数字","hook":"県内で人口1位","t":"人口は約302,984人（2021年）で、県内25市町村中1位。面積は約906.1km²です。"},{"tag":"クイズ","q":"竿燈まつりで、連なる提灯は何に見立てられている？","a":"米俵"},{"tag":"出身","hook":"秋田市出身の有名人","t":"秋田市出身には、脚本家の内館牧子、歌手の桜田淳子、タレントの佐々木希、ミュージシャンの藤原基央がいます。"},{"tag":"へえ","hook":"夜空に10000個超の提灯","t":"竿燈の本番では、10000個を超える提灯が夜空に輝きます。提灯は職人がすべて手作業で作っています。"},{"tag":"へえ","hook":"竿燈で一番難しい技は腰","t":"竿燈の基本技は流し・平手・額・肩・腰の五つ。中でも腰の技が一番難しいとされています。"},{"tag":"歴史","hook":"朝廷が置いた最北の城柵","t":"秋田城は、朝廷が設置した城柵の中でも最北にある古代の城です。国の史跡になっています。"},{"tag":"歴史","hook":"秋田城と渤海使の交流","t":"秋田城の発掘調査では、渤海との交流をうかがわせる複数の事実が指摘されています。"},{"tag":"歴史","hook":"天守のない久保田城","t":"久保田城には天守がなく、塁上の「出し御書院」という櫓座敷が代わりでした。他に8棟の櫓が並んでいました。"},{"tag":"車窓","hook":"千秋公園は日本100名城","t":"千秋公園（久保田城跡）は、市の指定名勝です。日本100名城の第9番にも選ばれています。"},{"tag":"へえ","hook":"自治体歌の代替わり最多","t":"秋田市民歌は、1928年の初代から数えて5代目。4回も代替わりしたのは、日本の自治体歌では最多です。"},{"tag":"歴史","hook":"金足農が全国大会で準優勝","t":"秋田市の秋田県立金足農業高等学校硬式野球部は、第100回全国高等学校野球選手権記念大会で準優勝を果たしました。"},{"tag":"クイズ","q":"秋田市は、日本で最初に市制施行された31都市のひとつです。それは何年？","a":"1889年"}]},"米沢市":{"pref":"山形県","cards":[{"tag":"味","hook":"米沢牛は英語教師の一皿から","t":"当時の米沢では四つ足の動物を食べないとされていました。英語教師ダラスがコックに牛肉を調理させたのが、米沢牛の始まりです。","teaser":true},{"tag":"数字","hook":"県内で面積4位","t":"面積は約548.5km²で、県内35市町村中4位の広さ。人口は約80,795人（2021年）です。"},{"tag":"ゆかり","hook":"政宗が生まれた米沢城","t":"「独眼竜」こと伊達政宗は、米沢城で生まれました。岩出山城へ移るまで米沢を支配していました。"},{"tag":"出身","hook":"米沢市出身の有名人","t":"米沢市出身には、戦国大名の伊達政宗、民法学者の我妻榮、漫画家のますむらひろし、俳優の伴淳三郎がいます。"},{"tag":"歴史","hook":"借金20万両の上杉家","t":"18世紀中頃の上杉家は、借財が20万両(いまの約150億〜200億円)にふくらんでいました。"},{"tag":"へえ","hook":"ウコギの垣根は食べられる","t":"鷹山が復活させたウコギの垣根は、もとは直江兼続が始めたもの。若葉は湯や油で調理して食べられます。"},{"tag":"歴史","hook":"「鷹山」の号は白鷹山から","t":"上杉治憲の号「鷹山」は、白鷹町にある白鷹山からとったと言われています。"},{"tag":"へえ","hook":"滝百選に選ばれた滑川大滝","t":"日本の滝百選に、市は白布大滝を推薦していました。でもスケールが数段上の滑川大滝が選ばれました。"},{"tag":"ゆかり","hook":"沖縄に並ぶ上杉茂憲の碑","t":"14代藩主・上杉茂憲は沖縄県令としての功績をたたえられ、沖縄県民有志の記念碑が廟所に並んでいます。"},{"tag":"車窓","hook":"天守のない米沢城","t":"米沢城に天守はなく、本丸の2基の三階櫓を「御三階」と呼び、天守の代わりにしていました。"},{"tag":"歴史","hook":"帝人の前身は米沢で生まれた","t":"大正時代、米沢高等工業学校の教授・秦逸三によって、帝国人造絹絲(帝人の前身)が興されました。"},{"tag":"クイズ","q":"1889年に全国で最初に市制施行した市は、全部で何市?","a":"31市(米沢市もその1つ)"},{"tag":"クイズ","q":"米沢の鯉は、何を補うため上杉鷹山が飼育を始めた?","a":"たんぱく質"}]},"紫波町":{"pref":"岩手県","cards":[{"tag":"ゆかり","hook":"銭形平次の投げ銭は水滸伝から","t":"紫波町出身の野村胡堂は、小学生のころ読んだ『水滸伝』の石投げの名手を、のちに銭形平次の投げ銭のヒントにしました。","teaser":true},{"tag":"数字","hook":"約239.0km²に約32,036人が暮らす町","t":"面積は約239.0km²、人口は約32,036人（2021年）。1km²あたり約134人です。"},{"tag":"ゆかり","hook":"「たきび」の作詞者は紫波の人","t":"童謡「たきび」の作詞者・巽聖歌の出生地は紫波町で、晩年を過ごした東京都日野市とは、その縁で姉妹都市になりました。"},{"tag":"出身","hook":"紫波町出身の有名人","t":"紫波町出身には、作家の野村胡堂、児童文学者の巽聖歌がいます。"},{"tag":"へえ","hook":"官民が組むまちづくりで注目","t":"紫波町は、役所と民間が手を組む「公民連携」を全国に先駆けて導入し、そのまちづくりが全国的に注目されています。"},{"tag":"歴史","hook":"「紫波」の字はいろいろ","t":"「紫波」の地名には由来の説がいくつもあり、歴史書には「子波」「斯波」「志和」とも書かれています。"},{"tag":"へえ","hook":"三大稲荷とされることも","t":"紫波町の志和稲荷神社は、地元では日本三大稲荷や日本五大稲荷の一つとされることがあります。"},{"tag":"歴史","hook":"千年超えの神木「稲荷山大杉」","t":"志和稲荷神社の境内には樹齢千年を超える「稲荷山大杉」があり、長寿を願って根本から白狐の毛を探す風習があります。"},{"tag":"歴史","hook":"宿場町と港町で栄えた日詰","t":"江戸時代の日詰町は、奥州街道の宿場町として栄え、北上川舟運の港町としても発展しました。"},{"tag":"味","hook":"南部杜氏の発祥地","t":"紫波町は、日本三大杜氏のひとつ「南部杜氏」の発祥地とされ、2022年時点で日本酒の酒蔵が4蔵あります。"},{"tag":"車窓","hook":"日本初のバレーボール専用体育館","t":"紫波町のオガールベースには、日本初のバレーボール専用体育館「オガールアリーナ」があります。"},{"tag":"歴史","hook":"義経が馬術を磨いた赤沢","t":"紫波町の赤沢地区には、源義経が馬術の修業を積んだという伝説が残っています。"},{"tag":"クイズ","q":"紫波町出身の作家・野村胡堂が書いた、投げ銭で有名な捕物帳の題名は？","a":"『銭形平次捕物控』"}]},"美郷町":{"pref":"秋田県","cards":[{"tag":"へえ","hook":"奇祭「竹打ち」","t":"「六郷のカマクラ行事」は、一般的には「竹打ち」と呼ばれる、奇祭とも言われる小正月の神事。国の重要無形民俗文化財です。","teaser":true},{"tag":"数字","hook":"県内で小さい方の町","t":"面積は約168.3km²で、県内25市町村中22位。人口は約18,493人（2021年）です。"},{"tag":"へえ","hook":"町のあちこちで水が自噴","t":"美郷町は、町内各所で地下水が自噴する土地。美郷町六郷は「水の郷百選」に選ばれています。"},{"tag":"出身","hook":"美郷町出身の有名人","t":"美郷町出身には、日本画家の佐々木久実、パイロットの佐藤章がいます。"},{"tag":"へえ","hook":"名水百選の六郷湧水群","t":"六郷湧水群は1985年に名水百選のひとつに選ばれました。旧六郷市街地とその周辺に、大小合わせて約60箇所あります。"},{"tag":"クイズ","q":"1896年の陸羽地震で一部が地表に現れた、美郷町の断層は？","a":"千屋断層"},{"tag":"歴史","hook":"断層で川の流れが変わった","t":"陸羽地震の断層の変動で、丸子川は流路が変わり、高梨で堤防を壊して田の中を1キロほど流れるようになりました。"},{"tag":"車窓","hook":"昼頃に着いた真昼岳","t":"真昼岳の山名は、伝説の坂上田村麻呂が東征のとき、昼頃に山頂に着いたからとされています。"},{"tag":"へえ","hook":"町の魚はハリザッコ","t":"美郷町の木はアカマツ、花はラベンダー、鳥は雁、魚はハリザッコ（イバラトミヨ）です。"},{"tag":"へえ","hook":"面積が同じ栃木の町と交流","t":"旧仙南村と栃木県の旧小川町は、面積がともに41.16平方キロメートルとほとんど同じだったことから交流が始まりました。"},{"tag":"味","hook":"500軒中19軒が酒屋","t":"享保年間には、六郷川内池・高野の500軒中19軒が酒屋だったと記録されています。名水と秋田米を利用した日本酒醸造業が古くから盛んでした。"},{"tag":"ゆかり","hook":"ジャーナリストのむのたけじ","t":"ジャーナリストのむのたけじは、旧六郷町の出身です。"},{"tag":"味","hook":"ニテコ清水の流しそうめん","t":"美郷町の名物に、ニテコ清水の流しそうめんがあります。"}]},"美里町":{"pref":"宮城県","cards":[{"tag":"へえ","hook":"国内最大級の植物工場","t":"美里町には、レタスを栽培する国内最大級の太陽光利用型植物工場「美里グリーンベース」が建設されました。","teaser":true},{"tag":"数字","hook":"約75.0km²に約23,796人が暮らす町","t":"面積は約75.0km²、人口は約23,796人（2021年）。1km²あたり約317人です。"},{"tag":"歴史","hook":"鉄道を説得した小牛田村長","t":"1890年に小牛田駅が開業。当時の村長・鎌田整一郎は、山神社があるから鉄道が通れば人が集まると、説得に回ったという話が残ります。"},{"tag":"出身","hook":"美里町出身の有名人","t":"美里町出身には、国際政治学者の袖井林二郎、ジャーナリストの千葉亀雄がいます。"},{"tag":"へえ","hook":"お殿様の奥方も安産祈願","t":"小牛田の山神社は子授け・安産・子育ての神として信仰され、白石片倉家など藩の奥方の御産の際は、家臣が代参して神札を受けたといいます。"},{"tag":"味","hook":"参道名物・山の神まんじゅう","t":"山神社の参道には、小牛田名物の「山の神まんじゅう」の売店などがあります。"},{"tag":"歴史","hook":"縄文から平安までの集落跡","t":"山前遺跡は、縄文時代と、古墳時代から平安時代にかけての集落跡からなる複合遺跡で、1976年に国の史跡に指定されました。"},{"tag":"車窓","hook":"町の約70%が水田や畑","t":"美里町は、江合川と鳴瀬川が貫流して水利に恵まれ、土地も平坦。町の面積の約70%が水田や畑です。"},{"tag":"車窓","hook":"樹齢750年余りの槻の木","t":"木間塚十王山公園には、樹齢750年余りと言い伝えられる槻の木が立っています。"},{"tag":"ゆかり","hook":"知事や評論家を生んだ町","t":"秋田県知事と石川県知事を務めた鈴木大亮、国際政治学者の袖井林二郎、ジャーナリストの千葉亀雄は、いずれも美里町の出身です。"},{"tag":"クイズ","q":"美里町が東北地方屈指の産地になっている花は何でしょう?","a":"バラです。栽培面積は約4haです。"},{"tag":"クイズ","q":"小牛田駅に乗り入れる3路線は、東北本線、陸羽東線と、あと一つは何線でしょう?","a":"石巻線です。3路線が乗り入れる接続駅です。"}]},"羽後町":{"pref":"秋田県","cards":[{"tag":"へえ","hook":"亡霊に扮して踊る盆踊","t":"西馬音内の盆踊は、道路沿いに焚き火を点け、それを囲うように、亡霊に扮した踊り子たちが踊ります。","teaser":true},{"tag":"数字","hook":"約230.8km²に約13,547人が暮らす町","t":"面積は約230.8km²、人口は約13,547人（2021年）。1km²あたり約59人です。"},{"tag":"へえ","hook":"顔を隠すのは死者の表現","t":"踊り子の女性は半月型の編み笠をかぶり、複数の布を継ぎ合わせた端縫い衣装をまといます。顔を隠す様子は死者を表現するとされます。"},{"tag":"出身","hook":"羽後町出身の有名人","t":"羽後町出身には、国学者の佐藤信淵、将棋名誉九段の金易二郎、歌手の岩本公水がいます。"},{"tag":"歴史","hook":"8月16日から18日の盆踊","t":"西馬音内の盆踊は、国の重要無形民俗文化財でユネスコ無形文化遺産。毎年8月16日から18日まで、西馬音内本町通りで行われます。"},{"tag":"車窓","hook":"居住する家で東北最古","t":"鈴木家住宅は江戸時代前期頃の農家の住宅。現在も所有者家族が居住している住宅としては東北最古です。"},{"tag":"車窓","hook":"茅葺きの古民家が100棟以上","t":"羽後町は、茅葺き屋根の古民家が秋田県内で最も多く残されている町として知られ、その数は100棟以上です。"},{"tag":"ゆかり","hook":"思想家・佐藤信淵の故郷","t":"江戸時代後期の思想家・佐藤信淵は、西馬音内前郷村または郡山村（現在の羽後町）の出身です。"},{"tag":"味","hook":"蕎麦屋が多い西馬音内","t":"羽後町には蕎麦屋が多く、ガイドマップなどで「西馬音内そば」として取り上げられています。「弥助そば」がその代表格です。"},{"tag":"クイズ","q":"羽後町のキャッチフレーズは何？","a":"「緑と踊りと雪の町」"},{"tag":"歴史","hook":"白井晟一が初めて設計","t":"羽後病院の旧病棟（1948年完成）は、建築家・白井晟一が初めて設計した公共建築でした。現存していません。"},{"tag":"へえ","hook":"三重櫓の鎌鼬美術館","t":"旧長谷山邸の三重櫓は、現在、細江英公が撮影した土方巽の写真パネルなどを展示する鎌鼬美術館になっています。"},{"tag":"ゆかり","hook":"矢口高雄が初めて赴任した支店","t":"漫画家・矢口高雄が羽後銀行（現・北都銀行）の社員として初めて赴任したのが、西馬音内支店でした。"}]},"能代市":{"pref":"秋田県","cards":[{"tag":"車窓","hook":"700万本のクロマツ林","t":"風の松原は、約700万本のクロマツが広がる、日本最大級の松林です。","teaser":true},{"tag":"数字","hook":"約426.9km²に約49,625人が暮らす町","t":"面積は約426.9km²、人口は約49,625人（2021年）。1km²あたり約116人です。"},{"tag":"歴史","hook":"松原は私財で始まった","t":"風の松原の植林は、1711年に廻船問屋と庄屋が私財を投じて始めたのが出発点です。"},{"tag":"出身","hook":"能代市出身の有名人","t":"能代市出身には、元プロ野球選手の山田久志、体操選手の小野喬、声優の浅野真澄、俳優の大坂志郎がいます。"},{"tag":"へえ","hook":"鯱を川に流す七夕","t":"能代役七夕は8月6日・7日。7日夜は、鯱飾りを米代川に浮かべて火をつけ、送り流します。"},{"tag":"歴史","hook":"「恋文のまち」のはじまり","t":"二ツ井町は「恋文のまち」。1881年、東北巡幸で訪れた明治天皇に皇后からの手紙が届いたのが由来です。"},{"tag":"へえ","hook":"縄文の超大型建物の跡","t":"杉沢台遺跡には、長径31m、面積222平方メートルの日本最大級の超大型建物の跡があります。"},{"tag":"へえ","hook":"北海道の石でできた斧","t":"杉沢台遺跡の縄文前期の磨製石斧は、北海道日高地方の「アオトラ石」と分かりました。"},{"tag":"歴史","hook":"安東氏が5代の山城","t":"檜山城は、檜山安東氏が5代にわたって居城とした山城です。"},{"tag":"車窓","hook":"東西1500mの大きな山城","t":"檜山城は東西1500m、南北900mの大規模な山城で、西には羽州街道が通っています。"},{"tag":"歴史","hook":"658年に登場する「渟代」","t":"能代の地名は、658年に阿倍比羅夫が上陸した「渟代」として日本書紀に記されています。"},{"tag":"へえ","hook":"バスケの街づくり","t":"能代市は、1989年度からバスケットボールの街づくり事業に取り組んでいます。"},{"tag":"クイズ","q":"能代市で8月に行われ、鯱飾りを米代川に流す祭りは？","a":"能代役七夕"}]},"舟形町":{"pref":"山形県","cards":[{"tag":"へえ","hook":"国宝の土偶「縄文の女神」","t":"「縄文の女神」は、舟形町の西ノ前遺跡から出土した縄文時代中期頃の土偶です。国宝に指定されています。","teaser":true},{"tag":"数字","hook":"約119.0km²に約4,988人が暮らす町","t":"面積は約119.0km²、人口は約4,988人（2021年）。1km²あたり約42人です。"},{"tag":"歴史","hook":"日本三大亜炭田の一つ「最上炭田」","t":"明治時代、舟形町・最上町・尾花沢市を中心に最上炭田が発見されました。岐阜県・宮城県と並び、「日本三大亜炭田」と呼ばれました。"},{"tag":"出身","hook":"舟形町出身の有名人","t":"舟形町出身には、元運輸大臣の伊藤茂、大相撲力士の栃櫻光輝がいます。"},{"tag":"へえ","hook":"壊れていない完全な土偶","t":"故意に壊された状態で見つかり復元できない土偶が多い中、完全な形の「縄文の女神」は日本国内では珍しいとされます。"},{"tag":"歴史","hook":"大英博物館にも出展","t":"「縄文の女神」の本物は山形県立博物館に保管され、レプリカは舟形町歴史民俗資料館に。2009年にはイギリスの大英博物館の土偶展にも展示されました。"},{"tag":"歴史","hook":"交通の交差点だった羽州街道の宿場","t":"江戸時代の舟形は、参勤交代路でもあった羽州街道の宿場町。東は仙台藩へ、西は庄内藩・出羽三山へ通じる交差点でした。"},{"tag":"へえ","hook":"猿羽根山の「日本三大地蔵」","t":"猿羽根峠の頂上にある猿羽根山地蔵尊堂は、「日本三大地蔵」の一つ。千年の歴史があるといわれ、良縁・子宝・長寿にご利益があるとされます。"},{"tag":"車窓","hook":"峠の下をくぐる猿羽根隧道","t":"猿羽根峠の下には、1961年に国道13号の猿羽根隧道（全長433m）ができました。東北中央自動車道の舟形トンネル（全長1,368m）は勾配すらなく越えられます。"},{"tag":"ゆかり","hook":"バードが絶賛した峠の最上川","t":"1878年に猿羽根新道が開通した翌年、イザベラ・バードが訪れ、峠の麓から見た最上川の風景を『日本奥地紀行』の中で絶賛しました。"},{"tag":"歴史","hook":"観覧車もあった猿羽根山遊園地","t":"猿羽根山は、かつて観覧車やミニ鉄道、遊具を備えた猿羽根山遊園地でしたが、1988年ごろに閉園しました。今はスキー場や展望台に流用されています。"},{"tag":"クイズ","q":"舟形町の西ノ前遺跡から出土し、2012年に国宝に指定された土偶の愛称は？","a":"縄文の女神"},{"tag":"クイズ","q":"最上炭田は、岐阜県・宮城県と並んで「日本三大」何田と呼ばれた？","a":"亜炭田"}]},"色麻町":{"pref":"宮城県","cards":[{"tag":"へえ","hook":"「河童のふるさと」の町","t":"色麻町は「河童のふるさと」をキャッチフレーズに、町内に河童のモニュメントがあり、町のテーマソングは「カッパブギ色麻」です。","teaser":true},{"tag":"数字","hook":"約109.3km²に約6,580人が暮らす町","t":"面積は約109.3km²、人口は約6,580人（2021年）。1km²あたり約60人です。"},{"tag":"ゆかり","hook":"磯良神社のカッパ像","t":"磯良神社では、御神体として木彫りのカッパ像が祀られていて、60年ごとに開帳されます。"},{"tag":"出身","hook":"色麻町出身の有名人","t":"色麻町出身には、実業家の小嶋進、バレーボール選手の早坂心之介がいます。"},{"tag":"へえ","hook":"初物のキュウリを川に流す","t":"磯良神と河童に本来は関わりがありませんが、当地では初物のキュウリをお供えとして川に流すなど、河童のイメージと結びついています。"},{"tag":"車窓","hook":"春は一直線に落ちる色麻大滝","t":"色麻大滝は落差41mの滝で、普段は2段に分かれていますが、春の雪解け時には一直線に落下します。"},{"tag":"車窓","hook":"東京ドーム909個分の演習場","t":"色麻町などにまたがる王城寺原演習場は、東京ドーム909個分の広さがあり、全国で5番目に広い演習場です。"},{"tag":"歴史","hook":"715年に十郡が置かれた","t":"715年、関東から富民千戸を陸奥国北部に移し、色麻を含む黒川以北十郡が設けられました。"},{"tag":"味","hook":"米作の町で育つえごま","t":"色麻町は農業の町で、米作が中心ですが、転作作物としてえごまが栽培されています。"},{"tag":"クイズ","q":"色麻町の磯良神社は、地元で何という愛称でも呼ばれているでしょう?","a":"「おかっぱ様」です。水難よけ・縁結び・安産などの御利益があるとされます。"},{"tag":"クイズ","q":"奈良時代の737年、『続日本紀』に記述が出てくる、色麻にあった城柵の名前は何でしょう?","a":"色麻柵です。"}]},"花巻市":{"pref":"岩手県","cards":[{"tag":"味","hook":"わんこそばは殿様への一口から","t":"花巻起源説では、南部利直が花巻城に立ち寄った際、失礼のないよう漆器のお椀に一口だけのそばを出したのが始まりとされます。","teaser":true},{"tag":"数字","hook":"県内で人口4位","t":"人口は約92,815人（2021年）で、県内33市町村中4位。面積は約908.4km²です。"},{"tag":"へえ","hook":"大晦日は年越しわんこそば","t":"花巻では、歳の数だけ食べると長生きすると伝えられる「年越しわんこそば」が、かつて大晦日の家族行事でした。"},{"tag":"出身","hook":"花巻市出身の有名人","t":"花巻市出身には、詩人の宮沢賢治、洋画家の松本竣介、漫画家の池野恋、プロ野球選手の畠山和洋がいます。"},{"tag":"歴史","hook":"「花巻」の名の由来は諸説","t":"地名の由来には諸説あります。名馬を産した「花の牧」の牧場や、春に花びらが北上川に浮かぶ風景からなどです。"},{"tag":"ゆかり","hook":"「修悦体」の生みの親は花巻出身","t":"花巻市出身の佐藤修悦さんは、警備員であり、「修悦体」というフォントの考案者です。"},{"tag":"歴史","hook":"花巻温泉に日本初のナイタースキー場","t":"花巻温泉は昭和初期に「東北の宝塚」を目指し、動物園や日本初となるナイタースキー場などが造られた行楽地でした。"},{"tag":"車窓","hook":"玉すだれのように流れる釜淵の滝","t":"釜淵の滝は、高さ8.5m、幅30mの岩の上を、水が玉すだれのように幾筋にも分かれて流れ落ちます。"},{"tag":"ゆかり","hook":"賢治記念館の近くに「山猫軒」","t":"胡四王山の九合目あたりに宮沢賢治記念館があり、童話「注文の多い料理店」にちなんだレストラン「山猫軒」もあります。"},{"tag":"へえ","hook":"本州で唯一のアカエゾマツの山","t":"早池峰山は、本州で唯一、アカエゾマツが自生している山です。山頂は宮古市・遠野市・花巻市の境です。"},{"tag":"車窓","hook":"岩手県内唯一の空港","t":"花巻市にある花巻空港は、岩手県内唯一の空港です。"},{"tag":"クイズ","q":"花巻で毎年わんこそば全日本大会が開かれる、わんこそば記念日は何月何日?","a":"2月11日"},{"tag":"クイズ","q":"宮沢賢治が設計した花壇の跡にある、花巻温泉の名所は?","a":"花巻温泉バラ園"}]},"葛尾村":{"pref":"福島県","cards":[{"tag":"へえ","hook":"交通死亡事故ゼロ13,261日","t":"葛尾村は2001年まで36年間、交通死亡事故ゼロの13,261日を達成。単独の自治体では国内最長でしたが、2022年に途絶えました。","teaser":true},{"tag":"車窓","hook":"標高450mの高原の村","t":"葛尾村は阿武隈高地にあり、村の中心部は標高約450m。最も高い集落は約700mの高さにあります。"},{"tag":"味","hook":"ゆるキャラ「しみちゃん」","t":"2016年に誕生した葛尾村初のゆるキャラ「しみちゃん」は、郷土料理「凍み餅」がモチーフです。"},{"tag":"へえ","hook":"再生可能エネルギーで村の再生","t":"葛尾村は、太陽光発電などの再生可能エネルギーと蓄電池、電気自動車を組み合わせたスマートコミュニティをめざしています。"},{"tag":"歴史","hook":"役場は2016年に村へ戻る","t":"仮役場を会津坂下町、次いで三春町に置いた後、2016年4月1日から全業務を村の役場で再開しました。"},{"tag":"車窓","hook":"日山・手倉山・五十人山","t":"葛尾村の山には、日山・竜子山・中ノ森山・手倉山・五十人山・蟹山があります。"},{"tag":"クイズ","q":"葛尾村の郷土料理「凍み餅」をモチーフにしたゆるキャラの名前は?","a":"しみちゃん"},{"tag":"クイズ","q":"葛尾村の交通死亡事故ゼロは、2001年まで何年間続いた?","a":"36年間"}]},"葛巻町":{"pref":"岩手県","cards":[{"tag":"へえ","hook":"ミルクとワインと風の町","t":"葛巻町は「北緯40度 ミルクとワインとクリーンエネルギーの町」を掲げ、風力発電や太陽光発電、バイオマス発電を進めています。"},{"tag":"数字","hook":"人より自然が多い町","t":"1km²あたり約13人。県内で下から3番目の人口密度です。"},{"tag":"へえ","hook":"町の86%が森林","t":"葛巻町の中心部は標高約400m。周囲は1,000mを超える山々に囲まれ、森林が町の86%を占めます。"},{"tag":"歴史","hook":"塩を運んだ野田街道の宿場町","t":"江戸時代の葛巻は八戸藩に属し、盛岡へ塩を運ぶ野田街道の宿場町として栄えました。"},{"tag":"へえ","hook":"鉄道も高速も温泉もない町","t":"鉄道も高速道路もない葛巻町。町の第三セクター（官民共同の会社）3社が、2007年に16億7000万円を売り上げました。"},{"tag":"味","hook":"縄文時代からヤマブドウの酒？","t":"葛巻町内の縄文時代の遺跡からは、ヤマブドウの大量の種や、果汁を発酵させ酒にしていたとみられる土器が出土しています。","teaser":true},{"tag":"味","hook":"ヤマブドウのくずまきワイン","t":"くずまきワインは、葛巻町特産のヤマブドウを使ったワインが中心で、岩手県を代表するワインブランドの一つです。"},{"tag":"へえ","hook":"山車の人形は借り物","t":"葛巻町の秋まつりには山車が4台出ます。山車人形は、一戸町や盛岡市から借り上げているそうです。"},{"tag":"へえ","hook":"町営のワンセグ放送だった","t":"葛巻町は2013年にワンセグエリア放送を始め、市町村では三沢市と並ぶ国内初の事例でしたが、2023年に廃止されました。"},{"tag":"ゆかり","hook":"沖縄の北中城村と姉妹都市","t":"葛巻町は、沖縄県中頭郡の北中城村と、1989年に姉妹都市提携を結びました。"},{"tag":"車窓","hook":"急カーブが続く平庭峠","t":"葛巻町と久慈市の境の平庭峠は、前後に急勾配・急カーブが続きます。周辺には平庭高原が広がっています。"},{"tag":"クイズ","q":"葛巻町の森林は、町全体のおよそ何%を占めている？","a":"86%"}]},"蓬田村":{"pref":"青森県","cards":[{"tag":"へえ","hook":"新幹線は通るが駅はない","t":"北海道新幹線は村内を経由していますが、駅や信号場は設置されていません。","teaser":true},{"tag":"数字","hook":"約80.8km²に約2,591人が暮らす町","t":"面積は約80.8km²、人口は約2,591人（2021年）。1km²あたり約32人です。"},{"tag":"へえ","hook":"飛び地が3組ある自治体と隣り合う村","t":"蓬田村は、3組の飛び地を有する自治体と接している村です。"},{"tag":"出身","hook":"蓬田村出身の有名人","t":"蓬田村出身には、漫画家の武井宏之がいます。"},{"tag":"味","hook":"トマトの名前がかわいい","t":"蓬田村のトマトには、桃太郎、津軽の雫、北の雅、よもぎたbaby babyがあります。"},{"tag":"味","hook":"寒じめちぢみほうれん草","t":"蓬田村では、寒じめちぢみほうれん草が作られています。"},{"tag":"車窓","hook":"村の西にそびえる大倉岳","t":"村の西にある大倉岳が、北津軽郡との境になっています。"},{"tag":"クイズ","q":"蓬田村を経由している新幹線は？","a":"北海道新幹線（村内に駅はない）"},{"tag":"味","hook":"ホタテの養殖が盛ん","t":"蓬田村の漁港には蓬田漁港と瀬辺地漁港があり、ホタテガイの養殖が盛んです。"},{"tag":"味","hook":"村の名がつく蓬田牛","t":"蓬田村の畜産には、蓬田牛や採卵養鶏があります。"},{"tag":"車窓","hook":"玉松海水浴場と海まつり","t":"蓬田村の見どころには、玉松海水浴場、玉松海まつり、たままつ海の情報館があります。"},{"tag":"歴史","hook":"2025年に新庁舎へ","t":"蓬田村役場は、2025年8月12日に新庁舎へ移転しました。"}]},"蔵王町":{"pref":"宮城県","cards":[{"tag":"歴史","hook":"「北のパラオ」と名づけた地区","t":"戦後、パラオからの引揚者が入植した地区は「北原尾（きたはらお）」と名づけられました。「北のパラオ」の意味です。","teaser":true},{"tag":"数字","hook":"約152.8km²に約11,360人が暮らす町","t":"面積は約152.8km²、人口は約11,360人（2021年）。1km²あたり約74人です。"},{"tag":"車窓","hook":"落差181mを三段に落ちる三階の滝","t":"三階の滝は、落差181mを三段に落ちる東北屈指の段瀑です。日本の滝百選の一つで、紅葉の名所です。"},{"tag":"出身","hook":"蔵王町出身の有名人","t":"蔵王町出身には、プロ野球選手の船迫大雅がいます。"},{"tag":"車窓","hook":"エコーラインの「雪の回廊」","t":"蔵王エコーラインは、春の冬季閉鎖が解けた直後、道路横に車高を超える雪の壁がそびえ「雪の回廊」になります。"},{"tag":"車窓","hook":"エコーラインは約半年お休み","t":"蔵王エコーラインは豪雪地帯のため、すみかわスノーパーク入口から上山市坊平間の約16.5kmが、11月上旬から4月下旬まで閉鎖されます。"},{"tag":"へえ","hook":"遠刈田は三大こけし発祥の地","t":"遠刈田温泉は、土湯温泉や鳴子温泉と並ぶ三大こけし発祥の地。遠刈田こけしは、頭に赤い放射線状の飾りを描くのが特徴です。"},{"tag":"へえ","hook":"「遠刈田」は読み方が2つ","t":"遠刈田は古くは「湯刈田」と書き、「とうがった」と読みました。今も「とおがった」「とうがった」の2通りの読みがあります。"},{"tag":"歴史","hook":"遠刈田温泉の開湯は約400年前","t":"遠刈田温泉の開湯は1601年とされますが、平安時代末に金商人の金売吉次が開いていたとも伝えられます。"},{"tag":"味","hook":"梨の生産量は宮城県内一","t":"蔵王町は梨の生産量が宮城県内一で、利府町と並ぶ産地です。モモやブルーベリーも名産です。"},{"tag":"へえ","hook":"御釜は境界未定地域にある","t":"御釜は、蔵王町と川崎町の境界未定地域にある火口湖で、五色沼（ごしきぬま）とも呼ばれます。しばしば蔵王連峰の象徴として見られます。"},{"tag":"へえ","hook":"御釜は火山の様子で色が変わる","t":"御釜の水は、火山活動がない時期は澄んだ瑠璃色です。火山活動があると、湖底の沈殿物が舞い上がって白っぽく濁ります。"},{"tag":"クイズ","q":"蔵王町で、ビニールハウスなどの施設栽培の出荷高が日本一の野菜は?","a":"ツルムラサキ"}]},"藤崎町":{"pref":"青森県","cards":[{"tag":"へえ","hook":"リンゴ「ふじ」の故郷","t":"リンゴの品種「ふじ」が育成され、その名の由来となった町です。","teaser":true},{"tag":"数字","hook":"県内で小さい方の町","t":"面積は約37.3km²で、県内40市町村中39位。人口は約14,478人（2021年）です。"},{"tag":"歴史","hook":"「東北7号」が名を変えた","t":"1962年、東北7号が「ふじ」と命名され、品種登録されました。"},{"tag":"出身","hook":"藤崎町出身の有名人","t":"藤崎町出身には、元青森県知事の木村守男、プロレスラーのケンドー・カシン、女優の東さくらがいます。"},{"tag":"へえ","hook":"津軽弁だと「ふんちゃぎ」","t":"藤崎町は津軽弁で「ふんちゃぎ」と呼ばれます。"},{"tag":"味","hook":"麺に海苔を練りこんだ中華","t":"アンペそばは、麺に海苔が練りこまれている中華ソバです。"},{"tag":"車窓","hook":"夜空に約4000発","t":"津軽花火大会は、打ち上げ数が約4000発です。"},{"tag":"ゆかり","hook":"祖母の昔話を方言のまま","t":"民話研究家の川合勇太郎は、藤崎町出身の祖母から聞いた昔話を方言のまま記録し、『津軽むがしこ集』（1930年）にまとめました。"},{"tag":"クイズ","q":"アンペそばの麺に練りこまれているものは？","a":"海苔"},{"tag":"味","hook":"リンゴだけじゃない藤崎の農産物","t":"藤崎町では、リンゴや米のほか、ニンニク、トマト、アスパラガス、アルストロメリアも作られています。"},{"tag":"車窓","hook":"白鳥観察施設こーやまるくん","t":"藤崎町には、白鳥ふれあい広場や、白鳥観察施設「こーやまるくん」があります。"},{"tag":"ゆかり","hook":"プロレスラーのケンドー・カシン","t":"プロレスラーのケンドー・カシンは、藤崎町の出身です。"}]},"藤里町":{"pref":"秋田県","cards":[{"tag":"車窓","hook":"白神山地の秋田県側はすべて藤里","t":"白神山地の世界遺産の登録区域の約4分の1、秋田県側のすべてが、藤里町の町域内にあります。"},{"tag":"数字","hook":"人より自然が多い町","t":"1km²あたり約10人。県内で下から2番目の人口密度です。"},{"tag":"歴史","hook":"茅葺き屋根をトタンに替えた町","t":"1959年、藤里町は火災防止のため、無償でトタン板を提供する代わりに萱山を町に返してもらう条例を制定しました。","teaser":true},{"tag":"出身","hook":"藤里町出身の有名人","t":"藤里町出身には、大相撲力士の能代潟錦作、作家の簾内敬司がいます。"},{"tag":"へえ","hook":"町名は藤琴と素波里から","t":"藤里町の名は、藤琴村の「藤」と、粕毛村の景勝地だった素波里の「里」を合わせたものです。"},{"tag":"味","hook":"町内で育てて造る白神山地ワイン","t":"白神山地ワインは、2021年から町内のワイナリーで、ブドウ栽培から醸造まで一貫して行われています。"},{"tag":"歴史","hook":"幕末から続く市日","t":"藤里町の市日は、1のつく日に開かれます。幕末にはすでに行われていたといわれます。"},{"tag":"へえ","hook":"藤琴豊作踊り","t":"藤琴豊作踊りは、駒踊りや獅子舞などから成る県の無形民俗文化財で、毎年9月の祭典で披露されます。"},{"tag":"車窓","hook":"馬の雪形の藤里駒ヶ岳","t":"藤里駒ヶ岳の名は、残雪期に馬の形に見える雪形に由来します。農民はこの雪形で田植えの季節を知ったといいます。"},{"tag":"へえ","hook":"蓑の「笹ゲラ」","t":"昭和期までは「笹ゲラ」と呼ばれる蓑が雨具として使われ、町の有形民俗文化財になっています。"},{"tag":"味","hook":"もひと粕毛そば","t":"藤里町の名物には、牛のなんこ鍋（通称・もひ）や、つなぎに豆粉を使う粕毛そばがあります。"},{"tag":"クイズ","q":"白神山地の世界遺産登録区域のうち、藤里町の町域内にある割合は？","a":"約4分の1"},{"tag":"クイズ","q":"藤里町の名は、藤琴村の「藤」と、どこの景勝地の「里」を合わせた？","a":"素波里"}]},"西会津町":{"pref":"福島県","cards":[{"tag":"へえ","hook":"舟運の最大の難所、銚子の口","t":"銚子の口は、幅広だった川が急に十数メートルに狭まる景勝地。江戸時代の大坂廻米舟運では最大の難所と呼ばれました。","teaser":true},{"tag":"数字","hook":"約298.2km²に約5,597人が暮らす町","t":"面積は約298.2km²、人口は約5,597人（2021年）。1km²あたり約19人です。"},{"tag":"へえ","hook":"「3年続けて」お詣りする神社","t":"大山祇神社は「3年続けてお詣りすれば、なじょな（どんな）願いもききなさる」とされ、信仰を集めています。"},{"tag":"出身","hook":"西会津町出身の有名人","t":"西会津町出身には、漫画家の佐藤夕子、歌手のものえ和恵がいます。"},{"tag":"車窓","hook":"樹齢400年超の杉並木と202段","t":"大山祇神社の参道には、滝や樹齢400年超の杉並木、202段の石段があります。「ふくしまの遊歩道50選」の推奨遊歩道に選定されています。"},{"tag":"車窓","hook":"廃校の木造校舎が芸術村に","t":"西会津国際芸術村は、2002年春に廃校となった旧新郷中学校の木造校舎を活用。2004年にはリトアニアから2名のアーティストが招かれました。"},{"tag":"歴史","hook":"宿駅が置かれた越後街道","t":"西会津町は会津五街道のひとつ越後街道が通り、野沢、上野尻、白坂、宝川などの宿駅がおかれ、野沢は規模が大きく六斎市が行われました。"},{"tag":"へえ","hook":"長寿の里・大宜味村と交流","t":"西会津町は「百歳への挑戦」をテーマに1993年から健康のまちづくりを進め、「長寿の里」を掲げる沖縄県大宜味村と交流しています。"},{"tag":"味","hook":"完熟させて甘みを付ける縞瓜","t":"縞瓜は西会津町から喜多方市山都町にかけて栽培される瓜。白瓜系ながら未熟果用ではなく、完熟させて甘みを付けます。"},{"tag":"味","hook":"海藻でつくる寒天状の「いご」","t":"盆や彼岸などには、海藻を使った「いご」（えご）という寒天状の料理を作ります。"},{"tag":"車窓","hook":"観音堂は東口から西口へ","t":"如法寺の観音堂は東口から入って西口に抜ける珍しい作り。左甚五郎作「隠れ三猿」を見つけると「福まさる」といいます。"},{"tag":"クイズ","q":"西会津町の銚子の口は、何川の峡谷にある景勝地?","a":"阿賀川"},{"tag":"クイズ","q":"西会津町が交流している、「長寿の里」を掲げる沖縄県の村は?","a":"大宜味村"}]},"西和賀町":{"pref":"岩手県","cards":[{"tag":"へえ","hook":"冬の累積降雪量は10m以上","t":"三方を標高1,000m級の山に囲まれた地形のため、西和賀町の冬の累積降雪量は10m以上になります。"},{"tag":"数字","hook":"人より自然が多い町","t":"1km²あたり約9人。県内で下から1番目の人口密度です。"},{"tag":"へえ","hook":"岩手なのに秋田弁の町","t":"天気予報は秋田県南地方の範囲に入り、言葉も南部弁ではなく秋田弁が主体です。"},{"tag":"出身","hook":"西和賀町出身の有名人","t":"西和賀町出身には、プロレタリア作家の古沢元、尺八演奏者の菊池淡水、政治家の深沢晟雄がいます。"},{"tag":"歴史","hook":"乳児死亡率ゼロの村があった","t":"旧沢内村の深沢晟雄村長は、全国に先駆けて1歳未満と60歳以上の医療費を無料にし、1962年に乳児死亡率ゼロを達成しました。","teaser":true},{"tag":"ゆかり","hook":"年貢米の身代わりになった娘","t":"「およねの像」は、飢饉のとき年貢米の身代わりに城へ上がったお米を偲んだ石像で、沢内甚句に歌われています。"},{"tag":"味","hook":"ビスケットの天ぷら","t":"町の名産はビスケットの天ぷら。ビスケットを、小麦粉・もち米の粉・砂糖を合わせた生地で揚げます。"},{"tag":"味","hook":"温泉の熱で育てるスッポン","t":"温泉熱を利用してスッポンを養殖し、町内の旅館や飲食店に出荷しています。スープやラーメンもあります。"},{"tag":"へえ","hook":"湯川沼に浮かぶ浮草の島","t":"湯川沼には、直径1〜5mの浮草が集まって浮いている島があります。"},{"tag":"へえ","hook":"根雪になる日がわかる大銀杏","t":"沢内の大銀杏は、葉が落ちてから21日目に根雪になると言われています。高さ28m、周囲7mです。"},{"tag":"歴史","hook":"雪の川で禊をする裸祭り","t":"長松垢離とりは約380年前から続く行事です。若者がふんどし一本で、雪の積もる湯之沢川で禊払いをします。"},{"tag":"クイズ","q":"沢内の大銀杏は、葉が落ちて何日目に根雪になると言われる?","a":"21日目"},{"tag":"クイズ","q":"西和賀町で温泉熱を使って養殖している、ある水辺の生き物は?","a":"スッポン"}]},"西川町":{"pref":"山形県","cards":[{"tag":"味","hook":"酒・ワイン・ビールがそろう町","t":"西川町には日本酒・ワイン・ビールの醸造元があり、3種類がそろう自治体は山形県で唯一です。","teaser":true},{"tag":"数字","hook":"人より自然が多い町","t":"1km²あたり約12人。県内で下から2番目の人口密度です。"},{"tag":"へえ","hook":"月山は夏もスキーができる","t":"月山は豊富な残雪のため、国内では乗鞍岳や立山と共に夏スキーが可能な山としても知られます。"},{"tag":"出身","hook":"西川町出身の有名人","t":"西川町出身には、人工知能学者の飯田弘之、女医の志田周子、哲学者の山内志朗がいます。"},{"tag":"車窓","hook":"100m超に噴き上がる月山湖大噴水","t":"月山湖には、100mを越える高さまで水を噴き出す巨大な噴水「月山湖大噴水」があり、観光名所になっています。"},{"tag":"味","hook":"全国でも有数の山菜王国","t":"西川町はキノコ・山菜の生産額が全国でも有数の「山菜王国」。間沢には山菜料理専門の店が2店舗あります。"},{"tag":"歴史","hook":"消えた三山線と自転車道","t":"かつて三山線が間沢駅まで走っていましたが、1974年に廃止。跡地は間沢〜山寺を結ぶ37.8kmの自転車道になっています。"},{"tag":"味","hook":"岩根沢の秘伝「六浄豆腐」","t":"岩根沢では、出羽三山の行者が伝えたとされる秘伝の豆腐「六浄豆腐」が作られ、全国でも岩根沢でしか見られません。"},{"tag":"ゆかり","hook":"無医村に戻った女医・志田周子","t":"女医・志田周子は1935年、父に請われて無医村だった大井沢村に戻り、唯一の村医に。20年以上、地域医療に尽力しました。"},{"tag":"へえ","hook":"大井沢の大栗","t":"大井沢の大栗は、幹回りの長さが日本一の栗の巨樹です。"},{"tag":"へえ","hook":"水の郷百選と月山自然水","t":"西川町は「水の郷百選」に認定され、名水百選「月山山麓湧水群」の「月山自然水」は1983年から販売されています。"},{"tag":"クイズ","q":"西川町の月山スキー場は、4月上旬から何月頃まで滑れる?","a":"7月頃"},{"tag":"クイズ","q":"西川町の南端と北端にある、月山ともう一つの山は?","a":"朝日岳"}]},"西目屋村":{"pref":"青森県","cards":[{"tag":"へえ","hook":"防災無線で吉幾三が流れる","t":"防災無線では15時に吉幾三の掛け声入りラジオ体操、17時に「白神が故郷」が放送されます。","teaser":true},{"tag":"数字","hook":"人より自然が多い町","t":"1km²あたり約5人。県内で下から1番目の人口密度です。"},{"tag":"へえ","hook":"鉄道が村内を走らない","t":"村内に鉄道は走っていません。鉄道で来るなら、最寄り駅はJR奥羽本線と弘南鉄道弘南線の弘前駅です。"},{"tag":"出身","hook":"西目屋村出身の有名人","t":"西目屋村出身には、歌手の桂ゆり、ボクサーの熊谷二郎、劇団四季俳優の吉谷昭雄がいます。"},{"tag":"歴史","hook":"湖の底に沈んだダム","t":"津軽ダム（津軽白神湖）ができ、目屋ダム（旧・美山湖）は水没しました。"},{"tag":"歴史","hook":"定額給付金の現金支給は全国最初組","t":"2009年3月6日、北海道西興部村と並び、全国で最初に定額給付金の現金支給が始まりました。"},{"tag":"ゆかり","hook":"世界遺産の山がある村","t":"村内には世界遺産の白神山地が広がっています。"},{"tag":"へえ","hook":"伝統的工芸品の目屋人形","t":"目屋人形は経済産業大臣指定の伝統的工芸品です。"},{"tag":"クイズ","q":"西目屋村の南側で県境を成すのはどこの県？","a":"秋田県"},{"tag":"歴史","hook":"尾太鉱山が支えた村","t":"西目屋村は、尾太鉱山が基幹産業でしたが、1978年に閉山しました。"},{"tag":"へえ","hook":"役場はダム工事事務所の建物","t":"2020年11月30日、西目屋村は庁舎を、旧津軽ダム工事事務所の建物に移しました。"},{"tag":"ゆかり","hook":"村のPRガールズはライスボール","t":"弘前市のボーカルユニット、ライスボールは、2022年から「にしめやPRガールズ」を務めています。"}]},"西郷村":{"pref":"福島県","cards":[{"tag":"へえ","hook":"村で唯一、新幹線が止まる","t":"西郷村には新白河駅があり、日本の村で唯一、新幹線が停車します。首都圏への新幹線通勤の人も多い村です。","teaser":true},{"tag":"数字","hook":"約192.1km²に約20,508人が暮らす町","t":"面積は約192.1km²、人口は約20,508人（2021年）。1km²あたり約107人です。"},{"tag":"歴史","hook":"新白河駅の前の名は磐城西郷","t":"東北新幹線ができる前、新白河駅は村名に由来する「磐城西郷駅」という駅名でした。1982年に改称されました。"},{"tag":"出身","hook":"西郷村出身の有名人","t":"西郷村出身には、タレントの野村沙知代、プロ野球選手の遠藤一彦がいます。"},{"tag":"へえ","hook":"村の工場は内視鏡の世界","t":"村内の白河オリンパスは、世界シェア80%を持つ医療用内視鏡の基幹工場と紹介されています。"},{"tag":"車窓","hook":"雪割橋の名は冬景色から","t":"阿武隈川の源流域にかかる雪割橋。「雪割」は、一面の銀世界を割るように阿武隈川が流れることに由来します。"},{"tag":"歴史","hook":"雪割橋は縄梯子から始まった","t":"1946年、開拓のため雪割渓谷を渡る必要があり、初めは縄梯子で命がけで渡りました。同じ年に初代の吊橋が架けられました。"},{"tag":"へえ","hook":"三本槍の名は3つの藩の槍？","t":"三本槍岳の名は、3つの藩が領地を確かめるため槍を立てた故事に由来するという説明があります。ただし裏付ける資料は確認されていません。"},{"tag":"へえ","hook":"分水嶺の山、三本槍岳","t":"三本槍岳の山頂から約400m北のピークは、日本の中央分水嶺です。阿武隈川と那珂川の源流部にもあたります。"},{"tag":"歴史","hook":"甲子温泉の甲子は干支","t":"甲子温泉は1384年に発見されたといわれます。名前は、この年の干支が「甲子（きのえね）」だったことに因みます。"},{"tag":"車窓","hook":"かつての登山道国道","t":"甲子峠には、かつて登山道のまま国道とされた区間があり、「登山道国道」と言われて国道標識が知られていました。"},{"tag":"クイズ","q":"西郷村の「西郷」という村名は、何に由来する？","a":"白河の西に位置する郷"}]},"角田市":{"pref":"宮城県","cards":[{"tag":"歴史","hook":"かつて「角田県」があった","t":"明治2年（1869年）、白石県が角田県に改称され、角田城に県庁が置かれました。2年後に仙台県へ統合され、仙台県は翌年、宮城県に改称されました。","teaser":true},{"tag":"数字","hook":"約147.5km²に約27,848人が暮らす町","t":"面積は約147.5km²、人口は約27,848人（2021年）。1km²あたり約189人です。"},{"tag":"歴史","hook":"県内最古の寺社建築、高蔵寺","t":"高蔵寺の阿弥陀堂は県内最古の寺社建築とされます。東北地方に現存する平安時代の建築は、中尊寺金色堂、白水阿弥陀堂とこの堂の3か所だけです。"},{"tag":"出身","hook":"角田市出身の有名人","t":"角田市出身には、物理学者の大槻義彦、作家の鎌田樹、オートバイレーサーの伊藤真一がいます。"},{"tag":"へえ","hook":"ロケットエンジンを開発する町","t":"角田宇宙センターでは、LE-5やLE-7などの液体ロケットエンジンが開発されてきました。"},{"tag":"へえ","hook":"世界でも最大規模の高温衝撃風洞","t":"1999年3月に完成した角田宇宙センターの高温衝撃風洞は、世界でも最大規模の大きさです。"},{"tag":"へえ","hook":"海底から上がったロケットエンジン","t":"角田宇宙センターの展示室には、海底から引き上げられたH-IIロケット8号機のLE-7エンジンが展示されています。入館料は無料です。"},{"tag":"へえ","hook":"公園にH-IIロケットの模型","t":"台山公園には、市内にJAXAがある関係で、H-IIロケットの模型が展示されています。"},{"tag":"へえ","hook":"JAXAの町どうしで「銀河連邦」","t":"角田市は、JAXAの施設がある市町による友好都市「銀河連邦」の一員で、2016年に提携しました。"},{"tag":"歴史","hook":"養蚕から電機・自動車部品へ","t":"角田市は古くから養蚕が盛んでしたが、高度経済成長期以降は、電機メーカーや自動車部品メーカーの進出が相次ぎました。"},{"tag":"クイズ","q":"角田城主・石川氏の発祥の地として、1978年に角田市と姉妹都市になった福島県の町は?","a":"石川町"}]},"軽米町":{"pref":"岩手県","cards":[{"tag":"ゆかり","hook":"乃木将軍の愛馬の墓","t":"軽米町西里の駒形神社には、乃木希典の愛馬「雷号」の墓があります。雷号は晩年を軽米で過ごしました。","teaser":true},{"tag":"数字","hook":"約245.8km²に約8,224人が暮らす町","t":"面積は約245.8km²、人口は約8,224人（2021年）。1km²あたり約33人です。"},{"tag":"歴史","hook":"九戸方の大将格の城跡","t":"晴山地区の晴山館址は、九戸政実の乱で九戸方の大将格だった晴山治部少輔の居城とされます。"},{"tag":"出身","hook":"軽米町出身の有名人","t":"軽米町出身には、小説家の北上秋彦、大相撲力士の福ノ里邦男、漫画家の古舘春一がいます。"},{"tag":"車窓","hook":"岩手山も望む折爪岳","t":"折爪岳（標高852.2m）は軽米町・二戸市・九戸村にまたがる山。展望台から遠く岩手山や八戸市を望めます。"},{"tag":"へえ","hook":"欄間に彫刻370カ所の寺","t":"徳楽寺の本堂の欄間には、昭和20年代に津軽の彫師が手掛けた彫刻が370カ所に及びます。"},{"tag":"歴史","hook":"5月8日に公開される薬師堂","t":"曹洞宗・徳楽寺の薬師堂には、文化財指定を受けた彫刻が安置され、5月8日に公開されます。"},{"tag":"へえ","hook":"冬は氷点下20度近くに","t":"軽米町では冬、近年でも-20℃付近の気温が観測され、2013年1月18日には-19.5℃を記録しています。"},{"tag":"ゆかり","hook":"北海道の音更町と姉妹都市","t":"軽米町は、北海道河東郡の音更町と、1985年10月31日に姉妹都市提携を結びました。"},{"tag":"へえ","hook":"町内に鉄道が走っていない","t":"軽米町には鉄道路線がなく、鉄道を使うときは二戸駅か八戸駅まで路線バスで向かいます。"},{"tag":"クイズ","q":"乃木希典の愛馬「雷号」が晩年を過ごした岩手の町は？","a":"軽米町"},{"tag":"クイズ","q":"折爪岳の展望台から、遠くに見えるとされる岩手の山は？","a":"岩手山"}]},"遊佐町":{"pref":"山形県","cards":[{"tag":"へえ","hook":"千年以上変わらない「遊佐」","t":"遊佐の地名は『延喜式』（927年）に「遊佐 十疋」と登場。千年以上、文字も音もそのまま伝えられている珍しい例とされます。","teaser":true},{"tag":"数字","hook":"約208.4km²に約12,895人が暮らす町","t":"面積は約208.4km²、人口は約12,895人（2021年）。1km²あたり約62人です。"},{"tag":"車窓","hook":"湧水の町・水の郷百選","t":"遊佐町は湧水や自噴井戸が多く、1996年に「水の郷百選」に認定されています。"},{"tag":"出身","hook":"遊佐町出身の有名人","t":"遊佐町出身には、女優の阿部祐見子、プロ野球選手の伊藤海斗、書体設計士の鳥海修がいます。"},{"tag":"車窓","hook":"海辺に彫られた22体の磨崖仏","t":"十六羅漢岩は、遊佐町にある22体の磨崖仏。事故死した漁師の供養と海上安全を願い、1864年から5年かけて1868年に完成しました。"},{"tag":"へえ","hook":"郵便番号の数字が最大の町","t":"遊佐町の郵便番号は999-83XXなど。数字が最大の市町村で、菅里（999-8531）がもっとも大きい番号です。"},{"tag":"歴史","hook":"年貢の窮状を幕府へ直訴","t":"1634年、遊佐郷の大肝煎・高橋太郎左衛門は、年貢が二倍近くに増えた窮状を訴える直訴状を幕府に出し、受理されました。"},{"tag":"ゆかり","hook":"鰊御殿を残した青山留吉","t":"青山留吉は遊佐郷の青塚に生まれ、後志国に渡って道内有数の漁業家に成長。旧青山本邸は鰊御殿とも呼ばれ、今も残ります。"},{"tag":"へえ","hook":"山形県側にも「ナマハゲ」に似た風習","t":"三崎の山形県側にある女鹿の集落には、「ナマハゲ」に酷似した「アマハゲ」という風習が伝わっています。"},{"tag":"車窓","hook":"山頂は遊佐町、「出羽富士」","t":"鳥海山の山頂（標高2,236m）は遊佐町にあります。雪が積もった姿が富士山に似ているため、出羽富士とも呼ばれます。"},{"tag":"へえ","hook":"中高生が選ぶ少年町長","t":"遊佐町では2003年から、町の中高生が投票で「少年町長」と「少年議員」を選ぶ少年議会が行われています。"},{"tag":"クイズ","q":"遊佐町が1996年に認定された、湧水の多さを評価する百選は何？","a":"水の郷百選"},{"tag":"クイズ","q":"遊佐町の北にそびえる、東北地方第二の標高を誇る山は？","a":"鳥海山"}]},"遠野市":{"pref":"岩手県","cards":[{"tag":"ゆかり","hook":"河童や座敷童子の民話の町","t":"遠野は柳田國男の『遠野物語』の舞台で、河童や座敷童子などが登場する「遠野民話」が伝わります。"},{"tag":"数字","hook":"約826.0km²に約25,181人が暮らす町","t":"面積は約826.0km²、人口は約25,181人（2021年）。1km²あたり約30人です。"},{"tag":"へえ","hook":"河童を捕るには許可証がいる","t":"遠野のカッパ淵では、河童を捕まえるには「カッパ捕獲許可証」が必要とされています。","teaser":true},{"tag":"出身","hook":"遠野市出身の有名人","t":"遠野市出身には、人類学者の伊能嘉矩、漫画家の奥友志津子、作家の若竹千佐子がいます。"},{"tag":"車窓","hook":"全国唯一のカッパ狛犬","t":"カッパ淵は、全国唯一のカッパ狛犬で知られる常堅寺の裏手を流れる小川の淵です。"},{"tag":"へえ","hook":"オシラサマ1000体の御蚕神堂","t":"伝承園の御蚕神堂には、養蚕の神「オシラサマ」が1000体も安置されています。"},{"tag":"歴史","hook":"商人1000人が集まった市","t":"『遠野物語』によると、遠野では月に6度の市が開かれ、商人1,000人、馬1,000頭が集まる賑わいでした。"},{"tag":"味","hook":"ジンギスカンはバケツで焼く","t":"遠野はジンギスカンの人気が高く、固形燃料を入れた「ジンギスカンバケツ」に鍋をのせて焼くのが一般的です。"},{"tag":"味","hook":"ホップとどぶろくの町","t":"遠野は酒との関わりも深く、ビールの原料ホップやどぶろくの生産にも力を入れています。"},{"tag":"へえ","hook":"全世帯の約2割が菊池さん","t":"肥後国の菊池氏の一族が移ってきたことから、遠野では今も菊池姓が全世帯の約2割を占めます。"},{"tag":"歴史","hook":"約240年続いた城下町","t":"1627年に八戸直義が遠野鍋倉城主となり、以後約240年間、遠野は遠野南部氏の城下町として続きました。"},{"tag":"クイズ","q":"遠野のカッパ淵で、河童を捕まえるのに必要なものは?","a":"カッパ捕獲許可証"},{"tag":"クイズ","q":"遠野でジンギスカンを焼くとき、固形燃料を入れる金属製の容器は?","a":"ジンギスカンバケツ"}]},"郡山市":{"pref":"福島県","cards":[{"tag":"歴史","hook":"原野を変えた安積疏水","t":"江戸時代の郡山宿の人口は約5,000人で、周辺は水不足の原野でした。猪苗代湖の水を引く安積疏水が、開拓と都市化を進めました。"},{"tag":"数字","hook":"県内で面積4位","t":"面積は約757.2km²で、県内53市町村中4位の広さ。人口は約327,040人（2021年）です。"},{"tag":"へえ","hook":"疏水の落差を生かした高圧送電","t":"猪苗代湖と疏水の落差約300mを使った沼上発電所から、日本で初めての高圧送電が郡山市内まで行われ、紡績・繊維産業が発展しました。"},{"tag":"出身","hook":"郡山市出身の有名人","t":"郡山市出身には、俳優の西田敏行、漫画家の弐瓶勉、フィギュアスケート選手の本田武史がいます。"},{"tag":"歴史","hook":"東北最大の前方後方墳","t":"大安場古墳は、全長が約83メートルと推定される前方後方墳です。前方後方墳としては、東北地方最大の規模です。"},{"tag":"へえ","hook":"駅前ビルに世界一高いプラネタリウム","t":"郡山駅前のビッグアイにある郡山市ふれあい科学館のプラネタリウムは、地上から数えて世界で最も高い場所にあり、ギネス世界記録に認定されています。","teaser":true},{"tag":"へえ","hook":"24時間営業の第1号店","t":"郡山虎丸店（1975年開店）は、日本のセブン-イレブンで最初に24時間営業を行った店舗です。"},{"tag":"味","hook":"ラーメン店は約600軒","t":"郡山市内にはラーメン店が約600軒あり、個性的なラーメンで競い合う激戦区になっています。"},{"tag":"歴史","hook":"高柴デコ屋敷の工人の里","t":"高柴デコ屋敷は、三春駒や三春張子人形の発祥の地です。江戸時代から300年以上の歴史を持つ工人の里で、4軒の工房が郷土民芸品を作っています。"},{"tag":"へえ","hook":"磐越三美人湯の磐梯熱海","t":"磐梯熱海温泉は、月岡温泉、いわき湯本温泉とともに「磐越三美人湯」に数えられる温泉です。"},{"tag":"車窓","hook":"風の高原・布引高原","t":"標高約1,000mの布引高原には風力発電用の風車33基が立ち並び、磐梯山や猪苗代湖が一望できます。"},{"tag":"クイズ","q":"郡山市の鯉の養殖生産量（2014年）は、市町村別で全国何位？","a":"1位"},{"tag":"クイズ","q":"日本の滝百選に数えられる、郡山市の銚子ケ滝の高さは？","a":"48m"}]},"酒田市":{"pref":"山形県","cards":[{"tag":"へえ","hook":"日本最古級といわれる六角灯台","t":"日和山公園には、日本最古級といわれる木造の六角灯台（1895年築）があります。桜の名所でもあります。","teaser":true},{"tag":"数字","hook":"県内で面積3位","t":"面積は約603.0km²で、県内35市町村中3位の広さ。人口は約99,235人（2021年）です。"},{"tag":"歴史","hook":"「西の堺、東の酒田」","t":"1672年に河村瑞賢が西廻り航路を確立すると、酒田は北前船の寄港地として栄え、「西の堺、東の酒田」ともいわれました。"},{"tag":"出身","hook":"酒田市出身の有名人","t":"酒田市出身には、哲学者の阿部次郎、写真家の土門拳、詩人の吉野弘、俳優の成田三樹夫がいます。"},{"tag":"歴史","hook":"日本一の地主・本間家の街","t":"酒田には、戦後の農地改革まで日本一の地主だった本間家などの豪商が活躍し、街は三十六人衆という自治組織で運営されました。"},{"tag":"車窓","hook":"山居倉庫の屋根と土間の工夫","t":"山居倉庫の屋根は断熱を考えた二重構造。土間はにがりで練り固めて塩を敷き、庫内の温度・湿度を一定に保ちます。"},{"tag":"ゆかり","hook":"「おしん」は山居倉庫から","t":"『おしん』の脚本を手掛けた橋田壽賀子は、シナリオハンティングで酒田を訪れ、山居倉庫を見た瞬間、これでドラマができると確信しました。"},{"tag":"へえ","hook":"日本初の写真専門の美術館","t":"土門拳記念館は、日本初の写真専門の美術館。約13万5千点の土門作品のすべてを所蔵しています。"},{"tag":"車窓","hook":"玉簾の滝は県内一の直瀑","t":"玉簾の滝は落差63メートル。段差のない直瀑の滝としては山形県内一の高さです。"},{"tag":"味","hook":"自家製麺と極薄ワンタンの酒田ラーメン","t":"酒田ラーメンの特徴は、自家製麺と極薄ワンタン。地元の食材を使った「酒田フレンチ」も名物です。"},{"tag":"歴史","hook":"日本最初の女性消防組織","t":"1910年、酒田で日本最初の女性消防組織「婦人火防組」が編成されました。"},{"tag":"クイズ","q":"1672年に西廻り航路を確立し、酒田を北前船の寄港地として栄えさせた人物は？","a":"河村瑞賢"},{"tag":"クイズ","q":"山居倉庫の西側に41本植えられ、冬の強い季節風から建物を守る木は？","a":"けやき（欅）"}]},"野田村":{"pref":"岩手県","cards":[{"tag":"へえ","hook":"日本で唯一バラ輝石が採れた鉱山","t":"野田玉川鉱山は、日本で唯一バラ輝石が産出される鉱山。閉山後は観光坑道として一部を公開しています。","teaser":true},{"tag":"数字","hook":"県内で小さい方の町","t":"面積は約80.8km²で、県内33市町村中30位。人口は約3,852人（2021年）です。"},{"tag":"へえ","hook":"坑道は総延長およそ28キロ","t":"地下420m、総延長約28kmの坑道のうち、1.5kmが観光坑道として公開されています。"},{"tag":"出身","hook":"野田村出身の有名人","t":"野田村出身には、日本画家の佐藤圀夫、プロ野球選手の鈴木正幸がいます。"},{"tag":"へえ","hook":"坑道に並ぶ37体のマネキン","t":"観光坑道には37体のマネキンが配置され、2021年に人気投票が行われました。"},{"tag":"歴史","hook":"戦時中に盛んだった自家製塩","t":"野田村では、1945年に戦時特例で自家製塩が盛んになりました。"},{"tag":"歴史","hook":"製塩の廃止とサケふ化施設","t":"1949年、野田浜での自由製塩が廃止され、下安家にサケふ化施設が完成しました。"},{"tag":"歴史","hook":"三陸鉄道が久慈線を引き受け","t":"1984年、国鉄久慈線を第三セクター鉄道（官民共同の鉄道会社）の三陸鉄道が引き受けて営業を始めました。"},{"tag":"車窓","hook":"久慈市境の男和佐羅比山","t":"男和佐羅比山（標高814m）は、野田村と久慈市の境界付近にある山です。"},{"tag":"ゆかり","hook":"北海道の様似町と姉妹都市","t":"野田村は、北海道日高振興局様似郡の様似町と姉妹都市です。"},{"tag":"クイズ","q":"野田村の野田玉川鉱山で、日本で唯一産出される鉱物は？","a":"バラ輝石（ロードナイト）"}]},"野辺地町":{"pref":"青森県","cards":[{"tag":"歴史","hook":"現存日本最古の常夜灯","t":"浜町の常夜燈は1827年、野辺地湊への夜間入港のため設置された現存日本最古の常夜灯です。旧暦3月10日から10月10日まで点灯されました。","teaser":true},{"tag":"数字","hook":"約81.7km²に約12,352人が暮らす町","t":"面積は約81.7km²、人口は約12,352人（2021年）。1km²あたり約151人です。"},{"tag":"車窓","hook":"駅にある国内最古の防雪林","t":"野辺地駅には、国内最古の鉄道防雪林「野辺地防雪原林」があります。鉄道記念物14号に指定されています。"},{"tag":"出身","hook":"野辺地町出身の有名人","t":"野辺地町出身には、スキージャンプ選手の一戸剛、国史学者の松本彦次郎、サッカー選手の柴崎岳がいます。"},{"tag":"へえ","hook":"到着と同時に亡くなった馬","t":"明治天皇の行幸のお供をした馬・花鳥号は、1876年、野辺地の宿泊所に着くと同時に死に、翌日となりの常光寺に葬られました。"},{"tag":"へえ","hook":"北限のエドヒガン桜","t":"愛宕公園のエドヒガン桜は樹齢300年で、北限のエドヒガンとされ、町指定天然記念物です。"},{"tag":"歴史","hook":"本州最北の戊辰戦争史跡","t":"野辺地戦争戦死者の墓所は、戊辰戦争にかかる本州最北、県内唯一の史跡です。新政府軍の戦死者のうち27名の名を刻む4基の墓石があります。"},{"tag":"味","hook":"葉つきこかぶが名物","t":"「野辺地葉つきこかぶ」は地域団体商標に登録されている町の名物で、農業で盛んに作られています。"},{"tag":"ゆかり","hook":"司馬遼太郎が描いた湊町","t":"司馬遼太郎の『菜の花の沖』では、主人公の高田屋嘉兵衛が野辺地湊に逗留し、野辺地に高田屋の支店を置きます。"},{"tag":"クイズ","q":"野辺地町ゆかりの国の重要文化財・板状立脚土偶は、何時代のもの？","a":"縄文時代後期"},{"tag":"歴史","hook":"函館へ渡った野辺地のフェリー","t":"野辺地と函館を結んだ東日本フェリーは、1969年に運航を始め、1995年4月に廃止されました。"},{"tag":"歴史","hook":"駅に昭和天皇のお召し列車","t":"1947年8月11日、野辺地駅に昭和天皇の戦後巡幸のお召し列車が停車しました。"},{"tag":"へえ","hook":"人口の割に店が多い理由","t":"野辺地町は人口の割に商業施設が多く、東北町千曳や横浜町、六ヶ所村などの周辺地域からの需要があります。"},{"tag":"へえ","hook":"北前船が運んだ祇園祭","t":"野辺地祇園祭は、起源が上方にあるとされ、北前船交易とともに運ばれてきた祭事です。"}]},"金ケ崎町":{"pref":"岩手県","cards":[{"tag":"へえ","hook":"県内トップの工業の町","t":"金ケ崎町は、2018年の製造品出荷額が約6,123億円で岩手県内第1位です。県内最大の工業団地があります。","teaser":true},{"tag":"数字","hook":"約179.8km²に約15,337人が暮らす町","t":"面積は約179.8km²、人口は約15,337人（2021年）。1km²あたり約85人です。"},{"tag":"車窓","hook":"ナンバープレートは「平泉」","t":"金ケ崎町の車のナンバープレートは、ご当地ナンバーの「平泉」ナンバーで登録されます。"},{"tag":"出身","hook":"金ケ崎町出身の有名人","t":"金ケ崎町出身には、声優の桑島法子、小説家の平谷美樹、漫画家の千田純生がいます。"},{"tag":"歴史","hook":"伊達藩北限の町","t":"金ケ崎町は、江戸時代には伊達藩北限の町として、南部藩と国境を接していました。"},{"tag":"歴史","hook":"安倍氏の中心の柵・鳥海柵","t":"『陸奥話記』には安倍氏が設けた12の柵が記され、その中心的な柵が鳥海柵です。"},{"tag":"ゆかり","hook":"名誉町民は岩手県知事を4期","t":"金ケ崎町名誉町民の千田正は、参議院議員を3期、岩手県知事を4期務めました。"},{"tag":"車窓","hook":"江戸のままの武家町の小路","t":"城内諏訪小路は、江戸時代のままの小路が残る武家町です。各屋敷地はサワラヒバの生垣で区画されています。"},{"tag":"へえ","hook":"人柱伝説の千貫石ため池","t":"千貫石ため池は、ため池百選に選ばれています。江戸の元禄初期から伝わる「人柱伝説」があります。"},{"tag":"クイズ","q":"金ケ崎町の車のナンバープレートは、どこの地名?","a":"平泉ナンバー"},{"tag":"クイズ","q":"金ケ崎町の鳥海柵は、平安時代のどの豪族の城柵?","a":"安倍氏"}]},"金山町（山形県）":{"pref":"山形県","cards":[{"tag":"車窓","hook":"「美しく古びる」を目指す町並み","t":"金山町は、町域の4分の3が森林。金山杉と、白壁の金山型住宅で「美しく古びる」景観づくりに意欲的な町です。"},{"tag":"数字","hook":"約161.7km²に約5,045人が暮らす町","t":"面積は約161.7km²、人口は約5,045人（2021年）。1km²あたり約31人です。"},{"tag":"へえ","hook":"自治体で初の情報公開条例","t":"金山町は1982年、日本の地方公共団体で初となる情報公開条例を制定、施行しました。","teaser":true},{"tag":"出身","hook":"金山町出身の有名人","t":"金山町出身には、参議院議員の岸宏一、プロ野球選手の佐藤賢がいます。"},{"tag":"へえ","hook":"合併しなかったことが誇り","t":"金山町は村制施行以来、町域の変更がありません。幾度もあった合併の流れに加わらなかったことを、町の誇りとしています。"},{"tag":"歴史","hook":"諸大名が必ず泊まる金山宿","t":"金山宿から先は厳しい峠が続くため、参勤交代をする秋田・津軽の諸大名が必ず泊まる宿場で、本陣・脇本陣が置かれていました。"},{"tag":"ゆかり","hook":"イザベラ・バードの足を癒やした町","t":"1878年に金山を訪れたイザベラ・バードは、足の治療で逗留。東洋医学で足が回復し、認識を改めたと好意的に記しています。"},{"tag":"へえ","hook":"年平均降雪量は813cm","t":"金山町は特別豪雪地帯。年平均降雪量は813cmで、気温の年較差も大きい大陸性気候です。"},{"tag":"歴史","hook":"楯山城と金山の街割り","t":"戦国時代、最上義光が楯山城を築き、小野寺氏攻めの最前線に。今の金山町中心部の街割は、このころに作られたといわれます。"},{"tag":"車窓","hook":"秋田との県境は神室連峰","t":"町の北東部は神室連峰の1,000m級の尾根で、秋田県との県境になっています。"},{"tag":"車窓","hook":"上台峠から望む金山三峰","t":"上台峠から見える薬師山・中ノ森・熊鷹森は金山三峰と呼ばれ、イザベラ・バードが「日本のピラミッドである」と著しました。"},{"tag":"クイズ","q":"金山町の石造りの大堰（農業用水路）には、何が放流されている？","a":"錦鯉"}],"label":"金山町"},"金山町（福島県）":{"pref":"福島県","cards":[{"tag":"車窓","hook":"タイヤの音で曲が聞こえる道","t":"金山町の大字水沼にあるシンフォニーロードは、自動車で走るとタイヤと路面の摩擦音で、車内の人に楽曲が聞こえます。","teaser":true},{"tag":"数字","hook":"約293.9km²に約1,875人が暮らす町","t":"面積は約293.9km²、人口は約1,875人（2021年）。1km²あたり約6人です。"},{"tag":"へえ","hook":"ヒメマスがすむ沼沢湖","t":"金山町の沼沢湖は、福島県内で唯一、ヒメマスが生息する湖です。"},{"tag":"へえ","hook":"新しいカルデラ湖・沼沢湖","t":"沼沢湖は、約4万5千年前と約5400年前の大規模な噴火で誕生した新しいカルデラ湖で、水深は約96mです。"},{"tag":"へえ","hook":"青白く濁る炭酸の湯","t":"大塩温泉の源泉は湯船で青白く濁ります。炭酸成分が日本でも有数の多さなのが特徴です。"},{"tag":"味","hook":"首脳会合に出た大塩炭酸泉","t":"大塩炭酸泉は、2019年に開催された第14回20か国・地域首脳会合にミネラルウォーターとして提供されました。"},{"tag":"歴史","hook":"烏山の山頂にあった玉縄城","t":"玉縄城は標高484メートルの烏山の山頂部に築かれた山城で、1544年に築城されたと伝わります。"},{"tag":"歴史","hook":"渡し舟が足だった三更集落","t":"金山町の三更集落では10戸全戸が渡し舟を持ち、対岸の早戸集落との間を住民自らが船頭となって行き来していました。"},{"tag":"歴史","hook":"室町時代の山ノ内氏勝","t":"室町時代、金山町には会津四家に数えられる山ノ内氏勝がおり、横田中丸城などの史跡が今も残っています。"},{"tag":"車窓","hook":"全域が特別豪雪地帯","t":"金山町は全域が特別豪雪地帯に指定されていて、年平均降雪量は975cmです。"},{"tag":"ゆかり","hook":"ドラマ『未成年』のロケ地","t":"金山町は、テレビドラマ『未成年』のロケ地でした。"},{"tag":"クイズ","q":"福島県内で唯一、ヒメマスが生息する金山町の湖は?","a":"沼沢湖"}],"label":"金山町"},"釜石市":{"pref":"岩手県","cards":[{"tag":"歴史","hook":"近代製鉄発祥の地・釜石","t":"釜石は、幕末に盛岡藩士の大島高任が日本初の商用高炉を成功させ、日本の近代製鉄発祥の地となりました。","teaser":true},{"tag":"数字","hook":"約440.4km²に約33,061人が暮らす町","t":"面積は約440.4km²、人口は約33,061人（2021年）。1km²あたり約75人です。"},{"tag":"車窓","hook":"橋野高炉跡が世界遺産に","t":"2015年7月5日、橋野高炉跡を含む「明治日本の産業革命遺産」が世界遺産に登録されました。"},{"tag":"出身","hook":"釜石市出身の有名人","t":"釜石市出身には、作家の高橋克彦、小説家の柚月裕子、ゲームクリエイターの鈴木裕がいます。"},{"tag":"車窓","hook":"胎内に七福神の釜石大観音","t":"釜石大観音は高さ48.5メートルの魚籃観音像で、胎内に七福神が配置され、釜石湾を一望できる展望台があります。"},{"tag":"へえ","hook":"日本の海図第1号は釜石港","t":"釜石港では、日本の海図の第1号が作成されました。"},{"tag":"へえ","hook":"7連覇した「北の鉄人」","t":"新日鉄釜石ラグビー部は、1978年から1984年にかけて日本選手権7連覇を達成し、「北の鉄人」と呼ばれました。"},{"tag":"歴史","hook":"ラグビーの価値を高めた釜石","t":"2019年11月、釜石市は、復興を通じてラグビーの価値を高めたとして、ワールドラグビーの「キャラクター賞」に選ばれました。"},{"tag":"へえ","hook":"釜石市の花は「はまゆり」","t":"釜石市の花は「はまゆり」（正式名はスカシユリ）、木はタブノキ、鳥はオオミズナギドリです。"},{"tag":"味","hook":"映画になった釜石ラーメン","t":"2023年には、釜石ラーメンをめぐる映画『釜石ラーメン物語』が公開されました。"},{"tag":"へえ","hook":"海鳥の繁殖地・三貫島","t":"釜石市の三貫島は、オオミズナギドリとヒメクロウミツバメの繁殖地として、国の天然記念物に指定されています。"},{"tag":"ゆかり","hook":"『釣りバカ日誌6』の舞台","t":"映画『釣りバカ日誌6』（1993年公開）は、釜石市が舞台になりました。"},{"tag":"クイズ","q":"釜石市の花で、正式名を「スカシユリ」という花の通称は？","a":"はまゆり"}]},"鏡石町":{"pref":"福島県","cards":[{"tag":"へえ","hook":"日本初の西欧式牧場、岩瀬牧場","t":"岩瀬牧場は日本初の西欧式牧場で、唱歌「牧場の朝」のモデルとなりました。","teaser":true},{"tag":"数字","hook":"県内で小さい方の町","t":"面積は約31.3km²で、県内53市町村中51位。人口は約12,282人（2021年）です。"},{"tag":"へえ","hook":"町歌に相当する「牧場の朝」","t":"唱歌「牧場の朝」の舞台は、鏡石町の岩瀬牧場とされています。町では、この曲を町歌に相当する「町のシンボルソング」と定めています。"},{"tag":"出身","hook":"鏡石町出身の有名人","t":"鏡石町出身には、参議院議員の鈴木省吾、プロ野球選手の吉田康夫がいます。"},{"tag":"へえ","hook":"「日本の歌百選」に選ばれた唱歌","t":"唱歌「牧場の朝」は、2006年に文化庁と日本PTA全国協議会が「日本の歌百選」に選びました。"},{"tag":"歴史","hook":"朝日新聞記者が書いた牧場の情景","t":"1910年、朝日新聞記者の杉村楚人冠が牧場長の招待で牧場を訪れ、その情景をもとに「牧場の朝」を書いたとされています。"},{"tag":"歴史","hook":"オランダから牛を13頭購入","t":"1908年、岩瀬牧場はオランダから血統書付きのホルスタイン種牛13頭を購入しました。"},{"tag":"へえ","hook":"牧場そのものは須賀川市にある","t":"岩瀬牧場の観光化された公園や事務所は鏡石町ですが、歴史ある牧場そのものは、正確に言うと須賀川市の領域にあります。"},{"tag":"車窓","hook":"標高280m台の平坦な台地","t":"鏡石町は、西に釈迦堂川、東に阿武隈川が流れ、標高280ｍ台の平坦な台地にあります。"},{"tag":"ゆかり","hook":"モントリオール五輪に出場した町出身者","t":"鏡石町出身の町島洋一さんは、元競輪選手で、モントリオールオリンピックに出場しました。"},{"tag":"クイズ","q":"鏡石町の岩瀬牧場の情景が舞台とされる、文部省唱歌の曲名は？","a":"牧場の朝"},{"tag":"クイズ","q":"1908年に岩瀬牧場がオランダから購入したホルスタイン種牛は何頭？","a":"13頭"}]},"長井市":{"pref":"山形県","cards":[{"tag":"へえ","hook":"けん玉が「市技」のまち","t":"長井市には競技用けん玉の生産量日本一の工場があり、2020年9月にはけん玉を「市技」と定める条例もできました。","teaser":true},{"tag":"数字","hook":"約214.7km²に約25,836人が暮らす町","t":"面積は約214.7km²、人口は約25,836人（2021年）。1km²あたり約120人です。"},{"tag":"車窓","hook":"500種100万本の花菖蒲","t":"長井あやめ公園には500種100万本の花菖蒲が植えられています。名前は「あやめ」でも、厳密には花菖蒲です。"},{"tag":"出身","hook":"長井市出身の有名人","t":"長井市出身には、戦国時代の武将の片倉景綱、画家の菅原白龍、男子プロゴルファーの遠藤彰がいます。"},{"tag":"歴史","hook":"あやめ公園で見つかった長井古種","t":"1962年、江戸系・肥後系・伊勢系のどれにも属さない品種があやめ公園で見つかり、「長井古種」と名づけられました。"},{"tag":"歴史","hook":"最上川舟運の終着港","t":"江戸時代まで、酒田から最上川をさかのぼる舟運ルートの終着港が長井でした。米沢藩の交易港でした。"},{"tag":"へえ","hook":"県で1番古い郡役所「小桜館」","t":"小桜館は1878年建築の旧西置賜郡役所。現存する郡役所では山形県で1番古く、全国でも2番目です。"},{"tag":"車窓","hook":"市街地に残る茅葺屋根","t":"市街地に珍しい茅葺屋根の民家が残り、2018年に重要文化的景観「長井の町場景観」に選定されました。"},{"tag":"へえ","hook":"ロボットの迷路競技を長井で","t":"2006年、マイクロマウス全国大会が初めて都内を離れ、長井市で開かれました。ロボットが迷路の最短時間を競います。"},{"tag":"車窓","hook":"映画の舞台になった長井線","t":"映画『スウィングガールズ』(2004年)は長井市を含む置賜地方で撮影され、フラワー長井線の列車も登場します。"},{"tag":"歴史","hook":"ダムの下に沈んだ管野ダム","t":"2011年に竣工した長井ダムの湖は「ながい百秋湖」。すぐ下流にあった管野ダムは、完全に水没しました。"},{"tag":"クイズ","q":"フラワー長井線の「フラワー」は、何が多いことからついた名?","a":"沿線に花の名所が多いこと"},{"tag":"クイズ","q":"長井市が戦前に自治体を挙げて誘致し、成功させた会社は?","a":"東京芝浦電気(現・東芝)"}]},"陸前高田市":{"pref":"岩手県","cards":[{"tag":"へえ","hook":"市名の読み方が地元では違う","t":"市の読み方は「りくぜんたかた」ですが、地元の方言では「たがだ」や「たかだ」と発音されます。","teaser":true},{"tag":"数字","hook":"約231.9km²に約18,182人が暮らす町","t":"面積は約231.9km²、人口は約18,182人（2021年）。1km²あたり約78人です。"},{"tag":"へえ","hook":"日本最大の石質隕石が落ちた","t":"1850年、長圓寺の前に落ちた「気仙隕石」は、日本最大の石質隕石として今に伝わります。"},{"tag":"出身","hook":"陸前高田市出身の有名人","t":"陸前高田市出身には、剣術家の千葉周作、演歌歌手の千昌夫、俳優の村上弘明、プロ野球選手の佐々木朗希がいます。"},{"tag":"車窓","hook":"津波に耐えた奇跡の一本松","t":"高田松原の松の高木が津波に耐えて残り、「奇跡の一本松」と呼ばれて全国的に注目されました。枯死後も保存されています。"},{"tag":"車窓","hook":"高田松原は約7万本の松が茂った浜","t":"高田松原は、かつて約7万本の松が2kmの砂浜に茂っていました。植樹による再生が4万本を目指して進められ、2021年5月に完了しました。"},{"tag":"味","hook":"海辺の町のりんごと北限のユズ","t":"米崎りんごは、三陸沿岸では数少ない果物の産地の名物です。ほかに「北限のユズ」もあります。"},{"tag":"ゆかり","hook":"山車が正面衝突するけんか七夕","t":"気仙町のけんか七夕まつりは、向かい合った山車のロープを引き合って正面衝突させます。総重量は4トンを超えます。"},{"tag":"ゆかり","hook":"12台の山車が動くうごく七夕","t":"高田町では毎年8月7日に、七夕飾りの山車12台が笛と和太鼓の囃子で町内を練り歩きます。"},{"tag":"歴史","hook":"平泉ゆかりの金山あと","t":"玉山金山址は、平泉ゆかりの産金地帯であった可能性が指摘される金山のあとです。"},{"tag":"歴史","hook":"高台と伝承館がつなぐ復興","t":"復興で、氷上山の麓の高台に消防署や県立病院が移り、浸水域には東日本大震災津波伝承館が整備されました。"},{"tag":"クイズ","q":"1850年に陸前高田へ落ちた、日本最大の石質隕石の名前は?","a":"気仙隕石"},{"tag":"クイズ","q":"うごく七夕まつりが開かれる高田町では、山車は何台?","a":"12台"}]},"階上町":{"pref":"青森県","cards":[{"tag":"へえ","hook":"青森県でいちばん早い日の出","t":"小舟渡海岸は、山間部を除くと青森県で一番早く日の出が拝める場所です。","teaser":true},{"tag":"数字","hook":"約94.0km²に約13,176人が暮らす町","t":"面積は約94.0km²、人口は約13,176人（2021年）。1km²あたり約140人です。"},{"tag":"歴史","hook":"724年に開かれた観音堂","t":"寺下観音堂は724年に行基によって開山され、奥州糠部三十三観音の一番札所になっています。"},{"tag":"出身","hook":"階上町出身の有名人","t":"階上町出身には、大相撲力士の十文字友和、競輪選手の小原佑太がいます。"},{"tag":"車窓","hook":"階上岳はツツジの山","t":"階上岳はツツジの群生地で、毎年5月下旬から6月上旬にかけて咲き乱れます。"},{"tag":"味","hook":"海藻ラーメンって？","t":"階上町の特産品は海の幸を生かしたものが多く、いちご煮や塩うに、海藻ラーメンなどが美味とされています。"},{"tag":"へえ","hook":"「はしかみ」の由来は諸説","t":"「はしかみ」の町名には、明治の8村合併のとき階上岳をとって村名にしたという説があります。"},{"tag":"クイズ","q":"階上町の寺下観音堂を開山したのは誰？","a":"行基"},{"tag":"クイズ","q":"小舟渡海岸は、山間部を除いて青森県で何が一番早く拝める？","a":"日の出"},{"tag":"歴史","hook":"単独で町になったのは県内最後","t":"階上町は1980年に村から町になりました。合併を除く単独での昇格は、青森県内で最後です。"},{"tag":"数字","hook":"19〜22歳の人口比率が突出","t":"階上町は、八戸工業大学に通う学生が多く住むため、19歳から22歳の人口比率が突出して多い町です。"},{"tag":"数字","hook":"農業産出額の約半分は鶏","t":"階上町の農業産出額は、49%を鶏、22%を豚が占めています。"}]},"雫石町":{"pref":"岩手県","cards":[{"tag":"へえ","hook":"「雫石」はタンタンという音から","t":"雫石の名は、老杉の根元の清水の滴が岩に落ちて「タンタン」と鳴るのを村人が見つけ、水神として祀った「滴石たんたん」が由来です。","teaser":true},{"tag":"数字","hook":"約608.8km²に約15,589人が暮らす町","t":"面積は約608.8km²、人口は約15,589人（2021年）。1km²あたり約26人です。"},{"tag":"歴史","hook":"雫石神社と町の文化財の老杉","t":"「滴石たんたん」の地には雫石神社が建てられ、老杉は1994年に町の文化財に指定されました。"},{"tag":"出身","hook":"雫石町出身の有名人","t":"雫石町出身には、小説家の楢山芙二夫、漫画家のそのだつくし、演歌歌手の福田こうへいがいます。"},{"tag":"ゆかり","hook":"賢治童話の森は雫石にある","t":"宮沢賢治は町内の七ツ森や小岩井農場にたびたび立ち寄り、狼森や笊森が童話「狼森と笊森、盗森」のモチーフになりました。"},{"tag":"へえ","hook":"アルペンスキーの世界選手権","t":"1993年には、雫石スキー場でアルペンスキー世界選手権雫石大会が開かれました。"},{"tag":"車窓","hook":"国の天然記念物の高山植物","t":"秋田駒ヶ岳の山頂一帯の高山植物は、1926年に「秋田駒ヶ岳高山植物帯」として国の天然記念物に指定されました。"},{"tag":"歴史","hook":"仙岩峠の名づけ親は大久保利通","t":"仙岩峠の名は、秋田の仙北郡と岩手の岩手郡から一字ずつ取ったもので、命名者は大久保利通だとされます。"},{"tag":"味","hook":"ジェラートとチーズの町","t":"雫石町は、岩手三大ジェラートのうち2店舗が所在するなど、ジェラートやチーズなどの乳製品が有名な町です。"},{"tag":"へえ","hook":"グランドセイコーを作る町","t":"雫石には盛岡セイコー工業の雫石高級時計工房があり、グランドセイコーなどを製造しています。"},{"tag":"ゆかり","hook":"ウグイスが見つけた鶯宿温泉","t":"鶯宿温泉は、ウグイスが川床で傷を癒しているのを木樵が見つけたという伝説から、その名が付いたといわれます。"},{"tag":"クイズ","q":"雫石の名のもとになった、清水の滴が岩に落ちて立てる音は？","a":"タンタン"}]},"青森市":{"pref":"青森県","cards":[{"tag":"歴史","hook":"町の名は目印の小さな丘","t":"青森の名は、海岸にあった「青森」と呼ばれる小丘に由来します。漁船が帰るときの目標物だったため、開港の際にその名が採られました。"},{"tag":"数字","hook":"県内で面積2位","t":"面積は約824.6km²で、県内40市町村中2位の広さ。人口は約425,962人（2021年）です。"},{"tag":"車窓","hook":"陸上複線トンネルで世界最長","t":"市内の八甲田トンネルは全長26,455mで、陸上複線トンネルとして世界最長だそうです。","teaser":true},{"tag":"出身","hook":"青森市出身の有名人","t":"青森市出身には、アミューズ創業者の大里洋吉、「森のイスキア」主宰の佐藤初女がいます。"},{"tag":"へえ","hook":"カシスの国内生産の9割","t":"青森市のカシス（クロスグリ）は、国内生産量の約9割を占めるとされます。気候に適した作物として特産品化が進められています。"},{"tag":"味","hook":"浪岡のリンゴ、平成17年は全国3位","t":"浪岡地区はリンゴの生産が盛んで、平成17年の市町村別出荷量は全国第3位でした。"},{"tag":"車窓","hook":"建設時最長だった鋼アーチ橋","t":"城ヶ倉大橋は支間長255mの上路式鋼アーチ橋で、建設時には日本最長でした。"},{"tag":"歴史","hook":"5500年前の縄文の村","t":"三内丸山遺跡は特別史跡で、約5500年から4000年前の縄文時代に集落が繁栄しました。"},{"tag":"ゆかり","hook":"ねぶたは東北三大祭りの一つ","t":"青森ねぶた祭は8月2日から7日まで開かれ、重要無形民俗文化財です。東北三大祭りの1つにも数えられます。"},{"tag":"クイズ","q":"青森という地名は、海岸にあった何を目印にした名前から採られた？","a":"ハイネズが茂る小丘"},{"tag":"へえ","hook":"青森に隕石が落ちた","t":"1984年6月30日、青森市に青森隕石が落下しました。"},{"tag":"数字","hook":"酸ケ湯の雪は年に1706cm","t":"青森市の酸ケ湯では、年平均降雪量が1706cmに達します。"},{"tag":"歴史","hook":"約4000年前の環状列石","t":"小牧野遺跡(国の史跡)の環状列石は、約4000年前の縄文時代後期前半に作られました。"},{"tag":"歴史","hook":"アジア冬季競技大会の開催地","t":"2003年2月1日から8日、青森市でアジア冬季競技大会が開かれ、フィギュアスケートとカーリングの競技が行われました。"}]},"須賀川市":{"pref":"福島県","cards":[{"tag":"歴史","hook":"430年続く火祭り、松明あかし","t":"松明あかしは須賀川市で430年続く火祭りで、日本三大火祭りの一つに数えられることがあります。毎年11月の第2土曜日に開かれます。"},{"tag":"数字","hook":"約279.4km²に約74,778人が暮らす町","t":"面積は約279.4km²、人口は約74,778人（2021年）。1km²あたり約268人です。"},{"tag":"歴史","hook":"松明をともして城を守ると決めた夜","t":"1589年、伊達政宗に降伏を迫られた家臣や領民が、10月10日の夜に松明をともして十日山に集まり、城を守ると決議しました。これが祭りの元です。"},{"tag":"出身","hook":"須賀川市出身の有名人","t":"須賀川市出身には、映画特撮監督の円谷英二、マラソン選手の円谷幸吉、漫画家の鈴木央、陸上競技選手の相澤晃がいます。"},{"tag":"へえ","hook":"牡丹園で唯一の国指定名勝","t":"須賀川牡丹園は、牡丹園としては全国で唯一の国指定名勝です。"},{"tag":"へえ","hook":"東京ドーム約三倍に7000株の牡丹","t":"須賀川牡丹園は総面積10ha、東京ドームの約三倍の広さです。290種類、7000株もの牡丹を楽しめる庭園です。","teaser":true},{"tag":"歴史","hook":"牡丹は薬のために植えられた","t":"1766年、この地で薬種業を営んでいた伊藤祐倫が、牡丹の根を薬用にするため苗木を持ち帰って栽培したのが、牡丹園の始まりといわれています。"},{"tag":"車窓","hook":"奥州街道唯一の保存状態、一里塚","t":"須賀川一里塚は、奥州街道で江戸から数えて59番目と考えられます。2基ともよく保存されているものは奥州街道唯一とされ、国の史跡です。"},{"tag":"ゆかり","hook":"芭蕉は須賀川に8日間も滞在","t":"江戸中期は俳諧が盛んで、松尾芭蕉は『奥の細道』の旅で須賀川宿に8日間も滞在しました。"},{"tag":"ゆかり","hook":"ウルトラの星と姉妹都市","t":"須賀川は円谷英二の出身地です。2013年5月5日、ウルトラ一族が住むとされる「M78星雲 光の国」との姉妹都市提携を発表しました。"},{"tag":"へえ","hook":"乙字ケ滝のそばにゴジラの卵","t":"1980年代、青年会議所が中心となって「ゴジラの里構想」を立ち上げ、乙字ケ滝付近に「ゴジラの卵」と称する造形物が設置されたこともありました。"},{"tag":"クイズ","q":"松尾芭蕉は『奥の細道』の旅で、須賀川宿に何日間滞在した？","a":"8日間"},{"tag":"クイズ","q":"須賀川市の松明あかしは、毎年11月の第何土曜日に開かれる？","a":"第2土曜日"}]},"風間浦村":{"pref":"青森県","cards":[{"tag":"へえ","hook":"村名は各村から一文字ずつ","t":"設置前の各村から一文字ずつ取って、風間浦村と名付けられました。"},{"tag":"数字","hook":"約69.5km²に約1,644人が暮らす町","t":"面積は約69.5km²、人口は約1,644人（2021年）。1km²あたり約24人です。"},{"tag":"へえ","hook":"道知事は知っている村","t":"北海道のテレビ局が映ったため、『青森の県知事は知らないが、北海道の道知事は知っている』という現象もありました。","teaser":true},{"tag":"出身","hook":"風間浦村出身の有名人","t":"風間浦村出身には、シンガーソングライターのサガユウキがいます。"},{"tag":"へえ","hook":"その名も『烏賊様レース』","t":"『元祖 烏賊様レース』が7月から11月の週2回、常設コースで開かれます。"},{"tag":"味","hook":"アンコウの好漁場","t":"付近の海底地形は急峻で、アンコウの好漁場になっています。"},{"tag":"ゆかり","hook":"藩政時代からの下風呂温泉","t":"下風呂温泉は藩政時代からの湯治場です。"},{"tag":"車窓","hook":"対岸の北海道を一望する公園","t":"海峡いさりび公園には、北海道を一望できる展望台や井上靖の文学碑、新島襄の寄港記念碑があります。"},{"tag":"歴史","hook":"大間鉄道の線路跡が残る下風呂","t":"下風呂地区に大間鉄道の線路跡が見られ、その一部が観光地として整備されました。"},{"tag":"クイズ","q":"下風呂地区は古くから何の場として知られる？","a":"湯治場"},{"tag":"数字","hook":"村の約96%は山林や原野","t":"風間浦村は、村の総面積の約96%が山林や原野です。"},{"tag":"へえ","hook":"北海道の旧椴法華村と友好","t":"風間浦村は、北海道の旧椴法華村(現・函館市)と、1991年に友好都市になりました。"},{"tag":"へえ","hook":"漁業・観光・林業の村","t":"風間浦村の主要産業は、漁業、観光、林業です。"}]},"飯舘村":{"pref":"福島県","cards":[{"tag":"へえ","hook":"浜通りで唯一の「96」","t":"飯舘村は標高500m前後。浜通りでは唯一、郵便番号の上二桁が「96」に属する自治体です。","teaser":true},{"tag":"歴史","hook":"山津見神社は1051年に創建","t":"虎捕山のふもとに山津見神社が創建されたのは、1051年(永承6年)です。"},{"tag":"出身","hook":"飯舘村出身の有名人","t":"飯舘村出身には、漫画家の国広あづさ、元福島市長の木幡浩がいます。"},{"tag":"歴史","hook":"「白狼の足跡を追え」","t":"由緒書によると、源頼義の夢に山の神が現れ、「白狼の足跡を踏み追うといい」と告げたといいます。"},{"tag":"車窓","hook":"天井にオオカミの絵","t":"山津見神社の拝殿の天井には、眷属とされる白狼や狼の絵が描かれています。"},{"tag":"歴史","hook":"村名は一字ずつ採った合成地名","t":"飯舘村の名は、旧村名の大舘村と飯曽村から一字ずつ採って合成した地名です。"},{"tag":"へえ","hook":"間に相馬市をはさむ相馬郡","t":"飯舘村は新地町とともに相馬郡を形成しますが、間に相馬市があって地理的に隔てられています。"},{"tag":"車窓","hook":"冬は-15℃を下回ることも","t":"飯舘村では冬、近年でも-15℃を下回ることがあり、2022年2月24日には-16.0℃を観測しています。"},{"tag":"へえ","hook":"7年がかりで撮った富士山","t":"花塚山から富士山を撮るため、地元の登山愛好家3人が7年がかりで挑戦し、2017年に正式に認定されました。"},{"tag":"へえ","hook":"木星の電波を受ける望遠鏡","t":"飯舘村には東北大学が運用する電波望遠鏡があり、木星周辺の放射線帯から出る電波などを観測しています。"},{"tag":"クイズ","q":"飯舘村と相馬郡をつくる、もうひとつの町は?","a":"新地町"},{"tag":"クイズ","q":"山津見神社で信仰される、山神の眷属とされる動物は?","a":"狼(白狼)"}]},"飯豊町":{"pref":"山形県","cards":[{"tag":"味","hook":"米沢牛の約半数は飯豊町産","t":"米沢牛の約半数は飯豊町から出荷。体脂肪率を計り、基準を超えた牛だけが米沢牛になります。","teaser":true},{"tag":"数字","hook":"約329.4km²に約6,517人が暮らす町","t":"面積は約329.4km²、人口は約6,517人（2021年）。1km²あたり約20人です。"},{"tag":"車窓","hook":"ひと月だけ現れる水没林","t":"白川湖は4月下旬に満水になると白柳が水に浸かり水没林に。5月中旬には水が抜かれ、およそひと月しか見られません。"},{"tag":"出身","hook":"飯豊町出身の有名人","t":"飯豊町出身には、脚本家の髙橋幹子がいます。"},{"tag":"車窓","hook":"田園に浮かぶ散居集落","t":"散居集落の家は、北風を避けて北西に杉、暑さを遮る南東に落葉樹を植え、冬は日差しが入るよう工夫されています。"},{"tag":"歴史","hook":"15歳で登る飯豊山","t":"太平洋戦争前まで、飯豊山への登頂は少年の成人儀式でした。15歳までに登らないと一人前と認められませんでした。"},{"tag":"へえ","hook":"「飯が豊かに食える村」","t":"飯豊の名は、飯豊山の麓の町として「飯が豊かに食える村」という意味を込めて付けられました。"},{"tag":"へえ","hook":"小正月の火祭り「ヤハハエロ」","t":"小正月の「ヤハハエロ」は、門松やお札を円錐形に積んだ藁に入れて火をつける行事。「ヤハハエロー」の掛け声が特徴です。"},{"tag":"へえ","hook":"すべて「むかで獅子」の獅子祭り","t":"飯豊町の獅子祭りはすべて「むかで獅子」。警固と獅子の力比べが見どころで、8月に集中します。"},{"tag":"へえ","hook":"真夏に雪遊びができる祭り","t":"白川ダムSHOWえっぐフェスティバルは、真夏に中津川で行われる雪祭り。雪室から取り出した雪で雪遊びができます。"},{"tag":"ゆかり","hook":"直江兼続の末弟の子孫","t":"直江兼続(樋口与六)の末弟・与八の子孫が、飯豊町内に住んでいます。"},{"tag":"クイズ","q":"どんでん平ゆり園の「どんでん」は、何が由来?","a":"どんと転んで、でんと尻をつく丘"},{"tag":"クイズ","q":"飯豊山の山頂は、どこにある?","a":"福島県喜多方市"}]},"高畠町":{"pref":"山形県","cards":[{"tag":"味","hook":"ラ・フランス発祥の地","t":"高畠町はデラウエアの生産量が日本一。三条目地区は、ラ・フランスの発祥の地です。","teaser":true},{"tag":"数字","hook":"約180.3km²に約22,242人が暮らす町","t":"面積は約180.3km²、人口は約22,242人（2021年）。1km²あたり約123人です。"},{"tag":"へえ","hook":"犬と猫を祀る珍しい神社","t":"犬の宮・猫の宮は、日本でも珍しい、犬と猫を祀る神社。愛犬・愛猫の供養と健康祈願の参拝者が多く訪れます。"},{"tag":"出身","hook":"高畠町出身の有名人","t":"高畠町出身には、童話作家の浜田広介、タレントの青木裕子、お笑い芸人のナダルがいます。"},{"tag":"へえ","hook":"幻の日本犬「高安犬」","t":"高安犬は、高安地区でかつて飼われていた日本犬。優秀なマタギ犬でしたが、昭和初期に絶滅しました。"},{"tag":"歴史","hook":"洞窟遺跡が密集する日向洞窟","t":"日向洞窟の周辺には14地点の洞窟遺跡があり、これだけ同じ地域に密集しているのは全国的に稀とされます。"},{"tag":"ゆかり","hook":"直江兼続の亀岡百首","t":"関ヶ原の戦いの直後の1602年、直江兼続が亀岡文殊で詩歌会を主催。上杉家主従27名が100首を奉納しました。"},{"tag":"ゆかり","hook":"童話作家・浜田広介の故郷","t":"童話作家・浜田広介は、高畠町の農家に生まれました。米沢中学、早稲田大学英文科を卒業しています。"},{"tag":"へえ","hook":"「まほろば」の意味","t":"「まほろば」は古語「まほら」に由来し、「丘、山に囲まれた稔豊かな住みよいところ」という意味です。"},{"tag":"歴史","hook":"政宗が幼少に学んだ資福寺跡","t":"資福寺跡は、伊達政宗が幼いころの学問所。境内に伊達輝宗と遠藤基信の墓があります。"},{"tag":"車窓","hook":"駅の中に温泉がある高畠駅","t":"高畠駅の「太陽館」には、駅構内に温泉があります。"},{"tag":"クイズ","q":"高畠町の亀岡文殊は、日本三何のひとつ?","a":"日本三文殊"},{"tag":"クイズ","q":"犬の宮の前で、毎年7月に行われる行事は?","a":"全国ペット供養祭"}]},"鮫川村":{"pref":"福島県","cards":[{"tag":"へえ","hook":"東京の地名が3つ並ぶ字","t":"鮫川村には、東京23区の三か所の地名を一か所の地名とする「赤坂 中野 新宿」があります。","teaser":true},{"tag":"数字","hook":"約131.3km²に約2,984人が暮らす町","t":"面積は約131.3km²、人口は約2,984人（2021年）。1km²あたり約23人です。"},{"tag":"歴史","hook":"下流にも鮫川村があった","t":"鮫川村は鮫川の上流にある村ですが、元々は下流にも鮫川村がありました。"},{"tag":"出身","hook":"鮫川村出身の有名人","t":"鮫川村出身には、競輪選手の遠藤貴人、女子プロゴルファーの蛭田みな美がいます。"},{"tag":"車窓","hook":"鮫川の水源は村の山","t":"鮫川は鮫川村の松曾根山を水源に、いわき市錦町で太平洋に注ぐ二級河川です。"},{"tag":"車窓","hook":"標高400mから650mの高地","t":"鮫川村は福島県の南端にあり、村の大部分が標高400mから650mの高地です。全体の約58%が山林です。"},{"tag":"へえ","hook":"江竜田の滝は滝の総称","t":"江竜田の滝は、二見ヶ滝、そうめんの滝、虹ヶ滝などの総称です。2019年の台風で遊歩道の一部が倒壊し、記事の時点では一部の滝に入れませんでした。"},{"tag":"車窓","hook":"村に鉄道は通っていない","t":"鮫川村には鉄道が通っていません。最寄りは水郡線の磐城石川駅、磐城浅川駅、磐城棚倉駅、磐城塙駅などです。"},{"tag":"ゆかり","hook":"女子プロゴルファーの出身地","t":"女子プロゴルファーの蛭田みな美さんは、鮫川村の出身です。"},{"tag":"クイズ","q":"鮫川村の面積のうち、約何%が山林？","a":"約58%"}]},"鮭川村":{"pref":"山形県","cards":[{"tag":"へえ","hook":"鮭にまつわる話題が多い村","t":"村名の語源は村内を流れる鮭川。「鮭石」などの史跡や、郷土料理「鮭の新切り（ようのじんぎり）」など、鮭にまつわる話題が多い村です。","teaser":true},{"tag":"数字","hook":"約122.1km²に約3,791人が暮らす町","t":"面積は約122.1km²、人口は約3,791人（2021年）。1km²あたり約31人です。"},{"tag":"歴史","hook":"鮭・鱒を「天の恵み」と感謝する習俗","t":"郷土史家の大友儀助によると、鮭川村には太古の自然崇拝の一種として、鮭・鱒を「天の恵み」として感謝する習俗が見られるそうです。"},{"tag":"出身","hook":"鮭川村出身の有名人","t":"鮭川村出身には、アナウンサーの熊谷瞳、テレビディレクターのマッコイ斎藤がいます。"},{"tag":"車窓","hook":"「トトロの木」小杉の大杉","t":"小杉の大杉は、『となりのトトロ』のトトロに似た樹形から「トトロの木」とも呼ばれます。推定樹齢は700年から800年以上です。"},{"tag":"歴史","hook":"殿様が吹雪を避けた大杉","t":"その昔、新庄の殿様が鹿狩りの最中に猛吹雪に襲われ、この木の下で風雪を避けたという伝説があります。"},{"tag":"味","hook":"なめこ栽培が盛んな村","t":"鮭川村の主要産業は農業と羽根沢温泉への観光で、特に、なめこ栽培が盛んです。"},{"tag":"へえ","hook":"鮭の子館とエコパーク","t":"鮭川村はグリーンツーリズムを掲げ、国道458号沿いに川遊びや産地直売所の機能をもつ「鮭の子館」などを整備しました。"},{"tag":"へえ","hook":"東日本随一の灯籠流し・庭月観音","t":"庭月観音は鮭川河畔にあり、最上三十三観音霊場の打ち止めの地。8月18日の灯籠流しは、仏式としては東日本随一と言われます。"},{"tag":"歴史","hook":"「おかげ様門」の名の由来","t":"庭月観音の山門は「おかげ様門」。「自分が生きているのは数多くのお蔭さまを受けているからである」という教えから名づけられました。"},{"tag":"へえ","hook":"石油を探していたら温泉が出た","t":"羽根沢温泉は、1919年に始まった日本石油の石油試掘中、地下約600mから湧き出しました。石油採掘は失敗で、1921年に廃坑になりました。"},{"tag":"へえ","hook":"羽根沢の名は鷹の羽根から","t":"羽根沢の名は、このあたりの住民が新庄藩の藩主に鷹の羽根を献上したことから名づけられたといいます。"},{"tag":"クイズ","q":"鮭川村で「トトロの木」と呼ばれる巨木は、何の木？","a":"杉（小杉の大杉）"}]},"鰺ヶ沢町":{"pref":"青森県","cards":[{"tag":"へえ","hook":"作品に描かれた床屋の多い町","t":"つげ義春の『リアリズムの宿』には、「鰺ヶ沢は漁港の町でやたら床屋が多い」と書かれています。","teaser":true},{"tag":"数字","hook":"約343.1km²に約8,730人が暮らす町","t":"面積は約343.1km²、人口は約8,730人（2021年）。1km²あたり約25人です。"},{"tag":"ゆかり","hook":"もののけ姫の取材地","t":"美術監督の男鹿和雄は、『もののけ姫』のエミシの村を描くため、1995年に白神山地を取材に訪れました。"},{"tag":"出身","hook":"鰺ヶ沢町出身の有名人","t":"鰺ヶ沢町出身には、大相撲力士の舞の海秀平がいます。"},{"tag":"車窓","hook":"日本の滝百選・くろくまの滝","t":"くろくまの滝は、日本の滝百選に選ばれています。"},{"tag":"歴史","hook":"国の史跡・種里城址","t":"種里城址は国の史跡で、大浦光信公の館です。"},{"tag":"へえ","hook":"南北に40キロの細長い町","t":"鰺ヶ沢町は南北が40キロメートルと長く、北は日本海に面し、南は白神山地で秋田県と接します。"},{"tag":"ゆかり","hook":"『赤い靴』ゆかりの町","t":"鰺ヶ沢町出身の鈴木志郎は、童謡『赤い靴』のモデルとなった少女きみの義父です。"},{"tag":"ゆかり","hook":"映画のロケ地になった町","t":"1971年には、映画『男はつらいよ 奮闘篇』のロケ地となりました。"},{"tag":"クイズ","q":"鰺ヶ沢町の南で秋田県と県境を接する山地は？","a":"白神山地"},{"tag":"車窓","hook":"弘前から一番近い海水浴場","t":"鰺ヶ沢海水浴場は、弘前市から一番近い海水浴場で、車で30分ほどです。"},{"tag":"ゆかり","hook":"舞の海さんの出身地","t":"相撲解説者の舞の海秀平さんは鰺ヶ沢町の出身で、大相撲での最高位は小結でした。"},{"tag":"へえ","hook":"ドラマの主人公が鰺ヶ沢出身","t":"「世にも奇妙な物語」の「言葉のない部屋」では、木村拓哉さん演じる主人公が鰺ヶ沢出身でした。"}]},"鶴岡市":{"pref":"山形県","cards":[{"tag":"へえ","hook":"クラゲ展示でギネス認定","t":"加茂水族館のクラゲは50種類以上。2012年には、展示する種類数でギネス世界記録に認定されました。","teaser":true},{"tag":"数字","hook":"県内で面積1位","t":"面積は約1,311.5km²で、県内35市町村中1位の広さ。人口は約121,371人（2021年）です。"},{"tag":"歴史","hook":"最低の入館者から反転攻勢","t":"1997年度の入館者は過去最低の9万2183人。サンゴの水槽で偶然クラゲが発生し、反転攻勢が始まりました。"},{"tag":"歴史","hook":"鶴岡は「亀」の対になった名","t":"1603年、酒田の東禅寺城を「亀ヶ崎城」と改め、「鶴と亀」の対比で大宝寺城を鶴ヶ岡城と改称したのが鶴岡の名の元です。"},{"tag":"へえ","hook":"給食もバンジーもサーフィンも","t":"鶴岡は学校給食発祥の地、バンジージャンプ発祥の地、サーフィン発祥の地。東北地方に唯一現存する藩校・致道館もあります。"},{"tag":"味","hook":"日本で初めてユネスコ食文化創造都市","t":"鶴岡は2014年に日本で初めてユネスコ食文化創造都市に認定されました。代表的な食文化は「つるおか伝統菓子」です。"},{"tag":"味","hook":"「だだちゃ」ってどういう意味？","t":"「だだちゃ」は庄内の方言で「おやじ」「お父さん」のこと。殿様が「どごのだだちゃの作った豆だや?」と尋ねたのが由来という説があります。"},{"tag":"車窓","hook":"羽黒山の五重塔は東北地方で最古","t":"羽黒山の五重塔は、平将門の創建とされ、塔としては東北地方で最古とされます。現在のものは15世紀ごろの再建で、国宝です。"},{"tag":"へえ","hook":"黒川能は「とうふ祭り」","t":"黒川能の王祗祭では、能の幕あいに黒川地区の住民が総出で作った凍み豆腐が振る舞われ、地元では「とうふ祭り」とも呼ばれます。"},{"tag":"ゆかり","hook":"「おくりびと」の銭湯は今は廃業","t":"映画『おくりびと』の撮影で有名な銭湯「鶴乃湯」は、市内で唯一の銭湯でしたが、2009年9月1日に廃業しました。"},{"tag":"クイズ","q":"鶴岡の「鶴」は、酒田の「亀ヶ崎城」の「亀」と対にして付けられました。鶴岡の元の城の名は？","a":"鶴ヶ岡城"},{"tag":"クイズ","q":"出羽三山は、羽黒山、月山とあと一つは？","a":"湯殿山"}]},"鶴田町":{"pref":"青森県","cards":[{"tag":"味","hook":"スチューベン生産日本一","t":"鶴田町ではリンゴ栽培が盛んですが、ブドウの品種「スチューベン」の生産量は日本一とされます。"},{"tag":"数字","hook":"県内で小さい方の町","t":"面積は約46.4km²で、県内40市町村中37位。人口は約12,211人（2021年）です。"},{"tag":"へえ","hook":"町おこしは「ハゲ」で","t":"町名と「ツルツル」をかけ、1989年に「ツル多はげます会」が発足して町おこしに生かしています。","teaser":true},{"tag":"出身","hook":"鶴田町出身の有名人","t":"鶴田町出身には、版画家の藤田健次がいます。"},{"tag":"へえ","hook":"頭に吸盤で綱引き大会","t":"ツル多はげます会は、頭につけた吸盤による綱引き大会や「ハゲアワード」などに取り組んでいます。"},{"tag":"へえ","hook":"町に朝ごはん条例がある","t":"鶴田町には「朝ごはん条例」があります。"},{"tag":"車窓","hook":"水の郷百選の津軽富士見湖","t":"津軽富士見湖（廻堰大溜池）は、「水の郷百選」に認定されています。"},{"tag":"へえ","hook":"樹齢350年のトド松","t":"妙堂崎の「トドロッポの木」はトド松で、県天然記念物。推定樹齢は350年です。"},{"tag":"歴史","hook":"津軽で初のご当地ナンバー","t":"2014年7月1日、原付バイクのナンバープレートに、津軽地方では初めてご当地ナンバーが導入されました。"},{"tag":"クイズ","q":"鶴田町で生産量が日本一とされるブドウの品種は？","a":"スチューベン"},{"tag":"へえ","hook":"さつま町は昔「鶴田町」","t":"鹿児島県の現さつま町は、もとの名が同じ鶴田町で、1997年に姉妹都市になりました。"},{"tag":"へえ","hook":"りんごの産地オレゴンと姉妹","t":"鶴田町は、りんごの主産地であるオレゴン州のフッドリバー市と、1977年に姉妹都市になりました。"},{"tag":"車窓","hook":"鶴の舞橋と丹頂鶴自然公園","t":"鶴田町には、鶴の舞橋、鶴の里ふるさと館、丹頂鶴自然公園があります。"}]},"鹿角市":{"pref":"秋田県","cards":[{"tag":"へえ","hook":"日本で最大のストーンサークル","t":"大湯環状列石の万座遺跡は、環状の直径が最大52mで、日本で最大のストーンサークルです。"},{"tag":"数字","hook":"約707.5km²に約28,929人が暮らす町","t":"面積は約707.5km²、人口は約28,929人（2021年）。1km²あたり約41人です。"},{"tag":"歴史","hook":"石で描いた「日時計」","t":"大湯環状列石には、立石を中心に石を放射状に並べた、「日時計」といわれる組石があります。"},{"tag":"出身","hook":"鹿角市出身の有名人","t":"鹿角市出身には、サッカー選手の奥寺康彦、東洋史学者の内藤湖南、作家の阿部牧郎がいます。"},{"tag":"歴史","hook":"1月2日の大日堂舞楽","t":"大日堂舞楽は毎年1月2日に奉納されます。1959年までは旧暦で行われていました。"},{"tag":"へえ","hook":"花輪ばやしは日本三大ばやし","t":"花輪ばやしは毎年8月19日・20日の祭り。日本三大ばやしの一つで、鹿角の夏の終わりを告げます。"},{"tag":"へえ","hook":"行き着くのが難しい滝","t":"茶釜の滝は、滝百選の中でも「三大難攻滝」の一つといわれ、行き着くのが難しい滝です。"},{"tag":"味","hook":"「北限の桃」の北限とは","t":"「かづの北限の桃」の北限は場所のことではなく、「日本で最も出荷時期が遅い」という意味です。","teaser":true},{"tag":"味","hook":"きりたんぽの発祥の地","t":"鹿角市は、きりたんぽが発祥した場所とされています。"},{"tag":"歴史","hook":"銅山の跡、坑道は約800km","t":"尾去沢鉱山は、坑道の全長が約800kmに及ぶ日本最大最古の銅鉱脈群の採掘跡で、1978年に閉山しました。"},{"tag":"車窓","hook":"十和田湖には面していない","t":"鹿角市は十和田湖に近いものの、市域は十和田湖には面していません。"},{"tag":"クイズ","q":"鹿角市の大湯環状列石で、環状の直径が最大52mある大きい方の遺跡は？","a":"万座遺跡"},{"tag":"クイズ","q":"西馬音内、一日市とともに秋田県の三大盆踊りに数えられる、鹿角市の盆踊りは？","a":"毛馬内の盆踊"}]},"黒石市":{"pref":"青森県","cards":[{"tag":"へえ","hook":"日本の道100選のこみせ通り","t":"中町のこみせ通りは、日本の道100選にも選ばれた路線です。"},{"tag":"数字","hook":"約217.1km²に約31,604人が暮らす町","t":"面積は約217.1km²、人口は約31,604人（2021年）。1km²あたり約146人です。"},{"tag":"味","hook":"黒石焼きそばは平麺","t":"黒石焼きそばは平麺を使うのが特徴です。つゆ焼きそばという食べ方もあります。"},{"tag":"出身","hook":"黒石市出身の有名人","t":"黒石市出身には、詩人の秋田雨雀、漫画家の筒井旭、卓球選手の神巧也がいます。"},{"tag":"車窓","hook":"推定樹齢500年のカヤの木","t":"妙経寺のカヤの木は県天然記念物で、推定樹齢500年です。1652年の寺の創建前から大きかったと伝えられています。"},{"tag":"ゆかり","hook":"美空ひばりが来た黒石","t":"1952年公開の映画「りんご園の少女」は黒石でもロケが行われ、美空ひばりが黒石を訪れました。","teaser":true},{"tag":"歴史","hook":"1万石の小さな藩があった","t":"1809年に黒石藩（1万石）が設置されました。"},{"tag":"へえ","hook":"特別豪雪地帯の黒石市","t":"黒石市は降雪量が多く、特別豪雪地帯に指定されています。"},{"tag":"クイズ","q":"黒石焼きそばは、どんな麺を使う？","a":"平麺"},{"tag":"クイズ","q":"黒石の中町こみせ通りは「日本の道何選」に選ばれた？","a":"100選"},{"tag":"へえ","hook":"ワシントン州ウェナッチ市と姉妹","t":"黒石市は、アメリカ・ワシントン州のウェナッチ市と、1971年に姉妹都市になりました。"},{"tag":"ゆかり","hook":"リンゴ栽培の神様","t":"渋川傳次郎は「リンゴ復興の祖」「リンゴ栽培の神様」とされ、1988年に黒石市名誉市民になりました。"},{"tag":"へえ","hook":"ドラマーのマスコット","t":"黒石市出身の「にゃんごすたー」は、マスコットキャラクターで、ドラマーでもあります。"},{"tag":"へえ","hook":"ねぷたとよされの祭り","t":"黒石の祭りには、黒石ねぷたまつり、黒石よされ、黒石こみせまつり、旧正マッコ市などがあります。"}]}};
